# ── CSRF protection (audit H8, 2026-07-20) ─────────────────────────────────
# Session-synchronizer token: {{ csrf_token() }} (meta tag + hidden form
# inputs) must round-trip on every mutating request as the X-CSRFToken header
# (static/csrf.js patches fetch + form submits) or a csrf_token form field.
# Public capability-token routes and machine endpoints are exempt — they are
# authenticated by their own tokens, not by a browser session.
# ── Upload allowlist + magic-byte validation (audit M6, 2026-07-20) ────────
_UPLOAD_ALLOW = {
    'document': {'pdf', 'jpg', 'jpeg', 'png', 'heic', 'heif', 'webp', 'tif',
                 'tiff', 'bmp', 'gif', 'docx', 'xlsx', 'csv', 'txt', 'eml'},
    'image':    {'png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp'},
    'csv':      {'csv', 'txt', 'tsv'},
}


def _validate_upload_file(fs, kind='document'):
    """Extension allowlist + magic-byte check for user uploads. Returns an
    error STRING (reject with 400) or None (accept). Reads the head of the
    stream and seeks back, so downstream .read()/.save() see the full file.
    Text types skip magic but are rejected if they smell like HTML — an
    uploaded HTML file must never enter the doc store (M6)."""
    try:
        name = (fs.filename or '')
        ext = name.rsplit('.', 1)[-1].lower() if '.' in name else ''
        allowed = _UPLOAD_ALLOW.get(kind, _UPLOAD_ALLOW['document'])
        if ext not in allowed:
            return (f"File type '.{ext or '?'}' isn't accepted here. "
                    f"Allowed: {', '.join(sorted(allowed))}.")
        head = fs.stream.read(16)
        fs.stream.seek(0)
        if ext in ('csv', 'txt', 'tsv', 'eml'):
            low = (head or b'').lstrip().lower()
            if low.startswith(b'<!doct') or low.startswith(b'<html')                or low.startswith(b'<script') or low.startswith(b'<svg'):
                return "This file looks like HTML/SVG, which isn't accepted."
            return None
        ok = False
        if ext == 'pdf':
            ok = head[:4] == b'%PDF'
        elif ext in ('jpg', 'jpeg'):
            ok = head[:3] == b'\xff\xd8\xff'
        elif ext == 'png':
            ok = head[:8] == b'\x89PNG\r\n\x1a\n'
        elif ext == 'gif':
            ok = head[:6] in (b'GIF87a', b'GIF89a')
        elif ext == 'webp':
            ok = head[:4] == b'RIFF' and head[8:12] == b'WEBP'
        elif ext in ('tif', 'tiff'):
            ok = head[:2] in (b'II', b'MM')
        elif ext == 'bmp':
            ok = head[:2] == b'BM'
        elif ext in ('heic', 'heif'):
            ok = head[4:8] == b'ftyp'
        elif ext in ('docx', 'xlsx'):
            ok = head[:4] == b'PK\x03\x04'
        if not ok:
            return (f"The file's contents don't match '.{ext}' — it may be "
                    "renamed or corrupted. Upload the original file.")
        return None
    except Exception as _ve:
        logging.warning(f"[upload-validate] check failed (accepting): {_ve}")
        return None   # fail-open: validation bugs must never block real work


_CSRF_EXEMPT_PREFIXES = (
    "/cron/", "/callsheet/confirm/", "/e/", "/qbo/oauth",
    "/health", "/readyz", "/webhook",
    # /api/v1/ is bearer-token auth (Authorization header, never cookies) —
    # cross-site pages can't set that header, so CSRF doesn't apply. The
    # api_auth_required decorator rejects cookie-only sessions on these
    # routes, so this exemption never opens a cookie-authed mutation path.
    # Deliberately NOT the bare "/api/" prefix: the legacy /api/catalog,
    # /api/quote, /api/role-mapping routes are cookie-session GETs.
    "/api/v1/",
)


@app.after_request
def _security_headers(resp):
    # M6 (2026-07-20): never let browsers MIME-sniff a served file into HTML.
    resp.headers.setdefault("X-Content-Type-Options", "nosniff")
    return resp


@app.context_processor
def _csrf_context():
    def csrf_token():
        from flask import session as _s
        if not _s.get("_csrf"):
            import secrets as _sec
            _s["_csrf"] = _sec.token_urlsafe(32)
        return _s["_csrf"]
    return {"csrf_token": csrf_token}


@app.before_request
def _csrf_protect():
    if request.method not in ("POST", "PUT", "PATCH", "DELETE"):
        return
    p = request.path or ""
    if any(p.startswith(x) for x in _CSRF_EXEMPT_PREFIXES):
        return
    from flask import session as _s
    expected = _s.get("_csrf")
    if not expected:
        # Transition path: sessions minted before this deploy carry no token
        # yet. Seed one now; the next page load embeds it. (Blocking here
        # would 403 every logged-in user mid-session at rollout.)
        import secrets as _sec
        _s["_csrf"] = _sec.token_urlsafe(32)
        return
    sent = (request.headers.get("X-CSRFToken")
            or request.form.get("csrf_token")
            or ((request.get_json(silent=True) or {}).get("csrf_token")
                if request.is_json else None))
    import hmac as _hmac
    if not (sent and _hmac.compare_digest(str(sent), str(expected))):
        return jsonify({"error": "CSRF token missing or invalid — reload the "
                                 "page and try again."}), 403

# ── Budget write-gate (owner 2026-07-22) ─────────────────────────────────────
# One chokepoint for every budget-content mutation:
#   1. LOCKED versions are fully READ-ONLY (the lock lives on the version's
#      Estimated anchor and covers the whole Estimated+Working pair).
#   2. ESTIMATED budgets are only editable by admins or a project OWNER (the
#      LP role an admin grants in Share). Working budgets stay open to editors.
# Enforced via before_request on the endpoints below so every guarded route
# gets identical behavior without per-handler edits.
_BUDGET_WRITE_ENDPOINTS = {
    'upsert_line', 'add_kit_fee', 'line_insert', 'line_duplicate',
    'line_reorder', 'line_set_group', 'remove_schedule_instance',
    'schedule_purge_tag', 'schedule_purge_all', 'travel_apply_doc',
    'toggle_sync_omit', 'import_csv_apply', 'budget_from_template',
    'budget_settings', 'budget_fee_update', 'pull_budget_lines', 'set_gantt_day',
    'set_gantt_days_batch', 'gantt_assign_crew', 'set_gantt_meal',
    'expand_gantt', 'set_schedule_label',
    'schedule_waypoint_restore', 'schedule_waypoint_copy_version',
}


@app.before_request
def _budget_write_gate():
    if request.method not in ("POST", "PUT", "PATCH", "DELETE"):
        return
    if request.endpoint not in _BUDGET_WRITE_ENDPOINTS:
        return
    _bid = (request.view_args or {}).get('bid')
    if not _bid:
        return
    budget = Budget.query.get(_bid)
    if budget is None:
        return   # the handler's own 404 will fire
    _locked = bool(getattr(budget, 'locked', False))
    if not _locked and budget.version_number is not None:
        _anchor = Budget.query.filter_by(project_id=budget.project_id,
                                         version_number=budget.version_number,
                                         budget_mode='estimated').first()
        _locked = bool(_anchor is not None and getattr(_anchor, 'locked', False))
    if _locked:
        return jsonify({"error": "This version is locked (read-only). "
                                 "Unlock it via ✎ in the version menu first."}), 403
    if budget.budget_mode == 'estimated' and not budget.is_actual:
        from flask_login import current_user as _cu
        if getattr(_cu, 'role', None) in ('super_admin', 'admin'):
            return
        _acc = None
        try:
            if getattr(_cu, 'is_authenticated', False):
                _acc = ProjectAccess.query.filter_by(
                    project_id=budget.project_id, user_id=_cu.id).first()
        except Exception:
            _acc = None
        if not _acc or _acc.role != 'owner':
            return jsonify({"error": "Estimated budgets can only be changed by "
                                     "an admin or the project owner/LP."}), 403


