@app.route("/projects/<int:pid>/budget/<int:bid>/line", methods=["POST"])
@login_required
def upsert_line(pid, bid):
    """AJAX: create or update a budget line. Returns updated line totals."""
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    data   = request.get_json(force=True)
    lid    = data.get("id")

    # Estimated edit protection: require explicit override when a Working budget exists
    if _budget_type(budget.budget_mode) == 'estimated' and not data.get('override_estimated'):
        has_working = Budget.query.filter(
            Budget.project_id == pid,
            Budget.version_status != 'archived',
        ).filter(
            Budget.budget_mode.in_(('working', 'actual'))
        ).first()
        if has_working:
            return jsonify({
                "estimated_protected": True,
                "message": "A Working budget exists. Editing Estimated will not affect Working. Confirm to proceed."
            }), 409

    if lid:
        ln = BudgetLine.query.filter_by(id=lid, budget_id=bid).first_or_404()
        _act_before = _budget_line_snapshot(ln)
        _act_is_create = False
    else:
        ln = BudgetLine(budget_id=bid)
        db.session.add(ln)
        _act_before = None
        _act_is_create = True
        # Default sort_order for newly-created lines = MAX(sort_order)+10
        # in the SAME (budget, account_code) section. Without this, new
        # rows defaulted to 0 and showed up at the TOP of the section,
        # ahead of every existing line — which is what the user reported
        # as "jumps me to the top" / "lands in the middle". Only applied
        # when the client didn't explicitly pass a sort_order; existing
        # batch flows that compute their own ordering (drag-reorder,
        # kit-fee insert, schedule split) still win.
        if not data.get("sort_order"):
            _new_code = data.get("account_code")
            if _new_code is not None:
                # no_autoflush: the half-built ln (account_code still NULL)
                # is in the session. Without this guard, the MAX query
                # triggers an autoflush that tries to INSERT ln before its
                # account_code is set — NotNullViolation, HTTP 500.
                with db.session.no_autoflush:
                    _max = (db.session.query(db.func.max(BudgetLine.sort_order))
                            .filter(BudgetLine.budget_id == bid,
                                    BudgetLine.account_code == int(_new_code))
                            .scalar())
                ln.sort_order = (int(_max or 0)) + 10
                # Strip a falsy sort_order from the incoming payload so
                # the field-assignment loop below doesn't overwrite our
                # computed value back to 0.
                data.pop("sort_order", None)

    # Quantity-reduce conflict check: when reducing quantity on a scheduled labor line,
    # the caller must confirm which schedule instances to remove first.
    if lid and "quantity" in data and ln.is_labor and ln.use_schedule and not data.get('skip_qty_check'):
        new_qty = int(float(data["quantity"] or 1))
        old_qty = int(float(ln.quantity or 1))
        if new_qty < old_qty:
            _sm = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'
            _instances = db.session.query(ScheduleDay.crew_instance).filter_by(
                budget_line_id=ln.id, schedule_mode=_sm
            ).distinct().all()
            existing_instances = sorted(set(r[0] or 1 for r in _instances))
            if len(existing_instances) > new_qty:
                # Build instance info from crew assignments
                _cas = {ca.instance or 1: ca for ca in ln.crew_assignments}
                instance_info = []
                for inst in existing_instances:
                    ca = _cas.get(inst)
                    name = None
                    if ca:
                        if ca.crew_member:
                            name = ca.crew_member.name
                        elif ca.name_override:
                            name = ca.name_override
                    day_count = ScheduleDay.query.filter_by(
                        budget_line_id=ln.id, crew_instance=inst, schedule_mode=_sm
                    ).count()
                    instance_info.append({
                        "instance": inst,
                        "name": name or f"Instance {inst}",
                        "days": day_count,
                    })
                return jsonify({
                    "schedule_conflict": True,
                    "line_id": ln.id,
                    "old_qty": old_qty,
                    "new_qty": new_qty,
                    "instances": instance_info,
                    "remove_count": old_qty - new_qty,
                    "message": f"This line has {len(existing_instances)} schedule instances. Reducing to {new_qty} requires removing {old_qty - new_qty}. Select which to remove."
                }), 409

    # Allowed fields
    fields = ["account_code", "account_name", "description", "is_labor", "sort_order",
              "estimated_total", "payroll_co", "quantity", "days", "rate", "rate_type",
              "est_ot", "fringe_type", "agent_pct", "note", "use_schedule",
              "parent_line_id", "line_tag", "role_group", "unit_rate",
              "days_unit", "days_per_week",
              "working_total", "manual_actual",
              # Task 2: catalog linkage for exports
              "catalog_item_id"]
    # Schedule-driven lines (Flights, Per Diem, Hotel, Meals, etc.) get
    # auto-recomputed by sync_schedule_driven_lines on every page load.
    # If the user manually edits qty/days/rate/estimated_total, treat
    # that as an explicit override and set sync_omit=True so subsequent
    # page loads stop clobbering their value. Without this, zeroing
    # Flights in Working "comes back" to its computed value as soon as
    # the user navigates away. User report 2026-05-07.
    _AUTO_OVERRIDE_FIELDS = {"quantity", "days", "rate", "estimated_total",
                             "rate_type", "fringe_type"}
    _has_line_tag = bool(getattr(ln, 'line_tag', None))
    _user_touched_auto_field = _has_line_tag and any(
        f in data for f in _AUTO_OVERRIDE_FIELDS
    )
    # Numeric fields where "blank" should mean ZERO, not NULL. Otherwise
    # calc_line falls back to its default (often 1.0 for qty/days),
    # which silently turns a user-cleared field into a partial value.
    # See budget_calc.calc_line() docstring for the related fix.
    _ZERO_ON_BLANK = {"quantity", "days", "rate", "estimated_total",
                      "est_ot", "agent_pct", "working_total",
                      "manual_actual", "unit_rate", "days_per_week"}
    for f in fields:
        if f in data:
            val = data[f]
            if val == "" or val is None:
                if f in ("account_code", "sort_order") or f in _ZERO_ON_BLANK:
                    setattr(ln, f, 0)
                else:
                    setattr(ln, f, None)
            else:
                setattr(ln, f, val)
    # Apply the auto-override AFTER the field loop so an explicit
    # sync_omit in the payload still wins.
    if _user_touched_auto_field and not getattr(ln, 'sync_omit', False):
        ln.sync_omit = True
        logging.info(
            "[upsert_line] auto-set sync_omit=True on schedule-driven "
            "line id=%s tag=%s — user manually edited %s",
            ln.id, ln.line_tag,
            sorted(set(data.keys()) & _AUTO_OVERRIDE_FIELDS))

    # Labor-line invariant: quantity is always 1 person per line. Multi-
    # person hires use Duplicate Row or Quick Entry's qty splitter (which
    # creates separate A/B/C lines, each qty=1). Per user 2026-05-04:
    # legacy data + edge cases left some labor rows with qty=2,3,…
    # silently multiplying their subtotals (qty × days × rate). Force
    # qty=1 on every labor save so corruption can't recur.
    if ln.is_labor:
        ln.quantity = 1
    else:
        # Non-labor defaults (per user 2026-05-04). The BudgetLine model
        # defaults rate_type='day_10' and days_unit='days' which are
        # both labor concepts. For a fresh non-labor row, default
        # rate_type='x' (Type column) and leave days_unit='days'.
        # Don't overwrite existing non-default values — only set if the
        # field landed on the labor default OR is null.
        _LABOR_RT_VALUES = {'day_10', 'day_8', 'day_12', 'flat_day',
                             'flat_project', 'hourly', 'week', 'custom'}
        if (ln.rate_type or '') in _LABOR_RT_VALUES or not ln.rate_type:
            ln.rate_type = 'x'
        if not ln.days_unit:
            ln.days_unit = 'days'

    # Backfill role_group from the linked CatalogItem when the line has a
    # catalog_item_id but no role_group set. Fixes cases where QE adds a new
    # custom role (e.g. admin-added "Utility" under Grip & Electric) and the
    # client didn't forward group_name on the save payload — without this
    # backfill the budget page falls through to the keyword-based subgroup
    # guesser which doesn't know custom labels and places them under the
    # wrong sub-header (Utility would fall into Sound by proximity of sort
    # order). Safe: only runs when role_group is missing AND a catalog link
    # exists AND that catalog row has a non-empty group_name.
    try:
        if getattr(ln, 'catalog_item_id', None) and not (getattr(ln, 'role_group', None) or '').strip():
            _ci = db.session.get(CatalogItem, ln.catalog_item_id)
            if _ci and (_ci.group_name or '').strip():
                ln.role_group = _ci.group_name
    except Exception:
        # Don't break line save over a subgroup backfill lookup.
        pass

    # Auto-compute estimated_total for non-labor lines (rate × qty × days, less discount)
    if not ln.is_labor:
        r        = float(ln.rate or 0)
        q        = float(ln.quantity or 1)
        d        = float(ln.days or 1)
        discount = float(ln.agent_pct or 0)   # stored as fraction (0.15 = 15%)
        if "rate" in data:
            # User explicitly set the rate (including to 0) → always recompute total
            pre_discount = round(r * q * d, 2)
            ln.estimated_total = round(pre_discount * (1 - discount), 2)
        elif r > 0:
            # Rate wasn't in this payload but is still positive → recompute total
            # (qty / days / discount may have changed)
            pre_discount = round(r * q * d, 2)
            ln.estimated_total = round(pre_discount * (1 - discount), 2)
        elif float(ln.estimated_total or 0) > 0 and ("quantity" in data or "days" in data):
            # Rate is 0 but we have a flat total + qty/days changed → back-derive unit rate
            derived_rate = round(float(ln.estimated_total) / max(q * d, 1), 2)
            ln.rate = derived_rate
            ln.estimated_total = round(derived_rate * q * d * (1 - discount), 2)

    db.session.commit()
    _touch_budget(bid)
    db.session.commit()

    # Activity log: record the create or update. _log_activity owns its
    # own commit + rollback so it can never break this route.
    try:
        _act_after = _budget_line_snapshot(ln)
        if _act_is_create:
            _log_activity(
                action='create', entity_type='budget_line',
                entity_id=ln.id, entity_label=ln.description or ln.account_name,
                budget_id=bid, project_id=pid,
                before=None, after=_act_after,
            )
        elif _act_before != _act_after:
            _log_activity(
                action='update', entity_type='budget_line',
                entity_id=ln.id, entity_label=ln.description or ln.account_name,
                budget_id=bid, project_id=pid,
                before=_act_before, after=_act_after,
            )
    except Exception as _e:
        logging.warning(f"[activity] upsert_line snapshot failed: {_e}")
        try: db.session.rollback()
        except Exception: pass

    fringe_cfgs = get_fringe_configs(db.session, pid)
    if ln.use_schedule:
        _sm = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'
        sched = ScheduleDay.query.filter_by(budget_line_id=ln.id, schedule_mode=_sm).all()
        result = calc_line_from_schedule(ln, sched, fringe_cfgs)
    else:
        result = calc_line(ln, fringe_cfgs)

    resp = {"id": ln.id, **result}
    # Include the editable input fields in the response so other clients can
    # patch their visible Rate / Duration / Qty / Type / Fringe / Agent% /
    # Payroll Co. cells in real time. Without these, the WS broadcast only
    # updated computed totals and remote users saw stale rate displays.
    resp["fields"] = {
        "rate":         float(ln.rate or 0),
        "days":         float(ln.days or 0),
        "quantity":     float(ln.quantity or 0),
        "agent_pct":    float(ln.agent_pct or 0),
        "fringe_type":  ln.fringe_type or 'N',
        "rate_type":    ln.rate_type or 'day_10',
        "payroll_co":   ln.payroll_co or '',
        "description":  ln.description or '',
        "is_labor":     bool(ln.is_labor),
        "days_unit":    getattr(ln, 'days_unit', None) or 'days',
    }
    # Conflict detection: check if another user edited the same field within 2 seconds
    _check_and_emit_conflicts(bid, ln.id, data)
    print(f"[WS] POST /line saved line={ln.id}, emitting to room budget_{bid}")
    _ws_emit_field_change(bid, ln.id, resp)
    return jsonify(resp)


@app.route("/projects/<int:pid>/budget/<int:bid>/line/<int:lid>/kit-fee", methods=["POST"])
@login_required
def add_kit_fee(pid, bid, lid):
    """Add a kit fee child row to an existing labor line."""
    Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    parent = BudgetLine.query.filter_by(id=lid, budget_id=bid).first_or_404()
    data   = request.get_json(force=True) or {}

    desc      = data.get("description") or f"Kit Fee — {parent.description or parent.account_name}"
    rate      = _bc_float(data.get("rate", 0))
    qty       = _bc_float(data.get("quantity", 1), 1)
    days_val  = _bc_float(data.get("days", 1), 1)
    days_unit = (data.get("days_unit") or "days").strip().lower()[:20] or "days"
    estimated = rate * qty * days_val if rate > 0 else 0

    ln = BudgetLine(
        budget_id      = bid,
        account_code   = parent.account_code,
        account_name   = parent.account_name,
        description    = desc,
        is_labor       = False,
        line_tag       = "kit_fee",
        parent_line_id = parent.id,
        sort_order     = parent.sort_order,
        quantity       = qty,
        days           = days_val,
        days_unit      = days_unit,
        rate           = rate,
        unit_rate      = rate if rate > 0 else None,
        estimated_total= estimated,
    )
    db.session.add(ln)
    db.session.commit()
    return jsonify({"ok": True, "id": ln.id, "description": ln.description,
                    "estimated_total": float(ln.estimated_total or 0),
                    "account_code": ln.account_code})


@app.route("/projects/<int:pid>/budget/<int:bid>/line/insert", methods=["POST"])
@login_required
def line_insert(pid, bid):
    """Insert a blank line above or below a reference line within the same section."""
    Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    data     = request.get_json(force=True) or {}
    ref_id   = int(data.get("reference_id") or 0)
    position = data.get("position", "below")   # "above" | "below"

    ref = BudgetLine.query.filter_by(id=ref_id, budget_id=bid).first_or_404()
    # line_kind controls what kind of row is inserted:
    #   'normal' (default) — a blank editable budget line
    #   'spacer'           — a visual divider with no financial values; description always blank
    #   'header'           — a sub-header label inside the section, click-to-edit text
    # Both spacer/header carry line_tag='spacer'|'header' so the template
    # can render them specially. Empty headers are filtered out on
    # render so unfinished placeholders never persist visually.
    line_kind = (data.get("line_kind") or "normal").lower()
    if line_kind not in ("normal", "spacer", "header"):
        line_kind = "normal"

    # All lines in the same section, ordered by sort_order then id (stable tiebreak)
    section_lines = BudgetLine.query.filter_by(
        budget_id=bid, account_code=ref.account_code
    ).order_by(BudgetLine.sort_order, BudgetLine.id).all()

    ref_idx = next((i for i, ln in enumerate(section_lines) if ln.id == ref_id), 0)
    insert_idx = ref_idx if position == "above" else ref_idx + 1

    if line_kind in ("spacer", "header"):
        # Header may carry a user-entered label from the insert payload
        # (see lineInsert in templates/budget.html — prompts the user
        # before POST so empty headers never persist).
        _initial_desc = (data.get("description") or "").strip()[:200]
        new_ln = BudgetLine(
            budget_id    = bid,
            account_code = ref.account_code,
            account_name = ref.account_name,
            description  = _initial_desc,
            is_labor     = False,
            fringe_type  = "N",
            quantity     = 0,
            days         = 0,
            rate         = 0,
            estimated_total = 0,
            working_total   = 0,
            line_tag     = line_kind,
            sort_order   = 0,
        )
        # Optional initial formatting (2026-07-22): the convert-auto-dept-
        # label flow seeds the header styled like the derived label it
        # replaces, and fmt.group records WHICH auto group it claims (so
        # the derived label stops rendering even after a rename).
        _fmt = data.get("format")
        if line_kind == "header" and isinstance(_fmt, dict):
            try:
                _keep = {k: _fmt[k] for k in
                         ('group', 'size', 'bold', 'underline', 'italic',
                          'indent', 'color') if k in _fmt}
                if _keep:
                    new_ln.note = json.dumps(_keep)[:300]
            except Exception:
                pass
    else:
        new_ln = BudgetLine(
            budget_id    = bid,
            account_code = ref.account_code,
            account_name = ref.account_name,
            description  = "",
            is_labor     = ref.is_labor,
            fringe_type  = ref.fringe_type if ref.is_labor else "N",
            quantity     = 1,
            days         = 1,
            rate         = 0,
            sort_order   = 0,
        )
    db.session.add(new_ln)
    db.session.flush()

    section_lines.insert(insert_idx, new_ln)
    for i, ln in enumerate(section_lines):
        ln.sort_order = i

    db.session.commit()
    _touch_budget(bid)
    db.session.commit()
    return jsonify({"ok": True, "id": new_ln.id})


@app.route("/projects/<int:pid>/budget/<int:bid>/line/<int:lid>/duplicate", methods=["POST"])
@login_required
def line_duplicate(pid, bid, lid):
    """Duplicate a budget line, placing the new row directly below the source.

    Copies all value fields (rate/days/fringe/agent/schedule config/etc.) but
    CLEARS individual assignment (assigned_crew_id=NULL, no CrewAssignment
    rows). The source line's ScheduleDay rows are copied only when the
    caller sets duplicate_schedule=true in the POST body (default). When
    false, the duplicate starts with no schedule days — the user can build
    a fresh schedule for it.
    """
    from models import ScheduleDay
    Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    src = BudgetLine.query.filter_by(id=lid, budget_id=bid).first_or_404()

    _req_body = request.get_json(silent=True) or {}
    # Default true for backward compat with callers that don't pass the flag.
    duplicate_schedule = bool(_req_body.get("duplicate_schedule", True))

    try:
        # Build the new row with every value field copied from src, but with
        # assigned_crew_id cleared and a fresh sort_order (placed just after src).
        new_ln = BudgetLine(
            budget_id        = src.budget_id,
            account_code     = src.account_code,
            account_name     = src.account_name,
            description      = src.description,
            is_labor         = src.is_labor,
            estimated_total  = src.estimated_total,
            payroll_co       = src.payroll_co,
            quantity         = src.quantity,
            days             = src.days,
            rate             = src.rate,
            rate_type        = src.rate_type,
            est_ot           = src.est_ot,
            fringe_type      = src.fringe_type,
            agent_pct        = src.agent_pct,
            note             = src.note,
            # When the user says "no" to duplicating the schedule, the new
            # row should land in plain estimated mode — not the blue/italic
            # schedule-driven look. Forcing use_schedule=False here mirrors
            # the empty ScheduleDay set we're about to leave behind.
            # (User 2026-05-28: "if you do not copy the schedule, it
            # should go back to the estimated mode, not scheduled mode by
            # default.")
            use_schedule     = src.use_schedule if duplicate_schedule else False,
            days_unit        = src.days_unit,
            days_per_week    = src.days_per_week,
            parent_line_id   = src.parent_line_id,
            line_tag         = src.line_tag,
            sync_omit        = src.sync_omit,
            role_group       = src.role_group,
            unit_rate        = src.unit_rate,
            assigned_crew_id = None,                     # <-- cleared
            catalog_item_id  = src.catalog_item_id,
            working_total    = src.working_total,
            manual_actual    = src.manual_actual,
            schedule_labels  = src.schedule_labels,
            sort_order       = 0,                        # placeholder, reseated below
        )
        db.session.add(new_ln)
        db.session.flush()                               # populate new_ln.id

        # Re-seat sort_order so the copy sits immediately after the source in
        # its section. Fetch all section rows, re-index sequentially, inserting
        # the new line directly after the source.
        section_lines = BudgetLine.query.filter_by(
            budget_id=bid, account_code=src.account_code
        ).filter(BudgetLine.id != new_ln.id).order_by(
            BudgetLine.sort_order, BudgetLine.id
        ).all()
        src_idx = next((i for i, ln in enumerate(section_lines) if ln.id == src.id), 0)
        section_lines.insert(src_idx + 1, new_ln)
        for i, ln in enumerate(section_lines):
            ln.sort_order = i

        # Duplicate the source line's ScheduleDay rows when requested.
        # crew_member_id is cleared — the copy starts with no individual
        # attached even if the schedule days are copied.
        if duplicate_schedule:
            src_sched = ScheduleDay.query.filter_by(budget_line_id=src.id).all()
            for sd in src_sched:
                db.session.add(ScheduleDay(
                    budget_id       = sd.budget_id,
                    budget_line_id  = new_ln.id,
                    crew_member_id  = None,                  # <-- cleared
                    date            = sd.date,
                    episode         = sd.episode,
                    day_type        = sd.day_type,
                    rate_multiplier = sd.rate_multiplier,
                    note            = sd.note,
                    crew_instance   = sd.crew_instance,
                    est_ot_hours    = sd.est_ot_hours,
                    cell_flags      = sd.cell_flags,
                    schedule_mode   = sd.schedule_mode,
                ))

        # NOTE: CrewAssignment rows are intentionally NOT copied. The duplicate
        # is a fresh unassigned role — user fills it in via the normal flow.

        db.session.commit()
        _touch_budget(bid)
        db.session.commit()
        return jsonify({"ok": True, "id": new_ln.id})
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 400


def _resolve_sister_budget(edited_budget):
    """Resolve the version-pair sister of `edited_budget`:
      - edited is Working-family  → the project's CURRENT Estimated budget
      - edited is Estimated       → the project's CURRENT Working budget
    Returns the sister Budget or None. Never returns an archived or is_actual
    budget, and never the edited budget itself. Mirrors the current-version
    resolution used in budget_view (prefer version_status='current', fall back
    to any non-archived of the right type)."""
    if edited_budget is None or edited_budget.is_actual:
        return None
    all_b = Budget.query.filter_by(project_id=edited_budget.project_id).all()
    if _budget_type(edited_budget.budget_mode) == 'working':
        want = 'estimated'
    else:
        want = 'working'

    def _is_type(b):
        return (_budget_type(b.budget_mode) == want and not b.is_actual)

    sister = next(
        (b for b in all_b if _is_type(b) and b.version_status == 'current'), None
    ) or next(
        (b for b in all_b if _is_type(b) and b.version_status != 'archived'), None
    )
    if sister is None or sister.id == edited_budget.id or sister.is_actual \
            or sister.version_status == 'archived':
        return None
    return sister


def _sister_line_for(ln, sister_lines, sister_src_ids, sister_desc_index):
    """Find `ln`'s counterpart among `sister_lines` using the SAME pairing
    precedence as budget_view's sister_orphans block:
      (a) source_line_id link in EITHER direction, then
      (b) (account_code, normalized description) fallback.
    `sister_src_ids` maps sister_line.source_line_id → sister_line (for the
    case where a sister line points AT `ln`). `sister_desc_index` maps
    (account_code, normalized description) → sister_line. Returns the matched
    sister BudgetLine or None."""
    # (a1) ln points AT a sister line.
    if ln.source_line_id is not None:
        for _sl in sister_lines:
            if _sl.id == ln.source_line_id:
                return _sl
    # (a2) a sister line points AT ln.
    _sl = sister_src_ids.get(ln.id)
    if _sl is not None:
        return _sl
    # (b) (account_code, normalized description) fallback.
    _dk = (ln.account_code, (ln.description or '').strip().lower())
    return sister_desc_index.get(_dk)


def _mirror_line_move(edited_budget):
    """Mirror the CURRENT layout (section membership + relative ordering) of
    `edited_budget`'s lines onto its version-pair sister budget, so a drag /
    section-move in one version is reflected in the other (owner ask 2026-07).

    Algorithm — run AFTER the edited budget's reorder/section-move has been
    committed, so we read the final on-disk state:
      1. Resolve the sister budget (skip if none / same / archived / is_actual).
      2. For each edited line, find its sister via the standard pairing
         (_sister_line_for). Lines with no sister are left untouched.
      3. For each PAIRED sister line: copy the edited line's account_code +
         account_name (this reproduces a cross-section move) and assign it a
         sequentially-increasing sort_order that follows the edited budget's
         full line order. Sister-only lines (orphans — no counterpart on the
         edited side) keep their existing sort_order so they stay roughly in
         place; no lines are created or deleted.

    Fail-open: any error is logged and swallowed — a mirror failure must never
    break the user's drag. Does NOT trigger the estimated-edit 409 guard (that
    guard lives in upsert_line and only fires for user-initiated edits; this is
    a system write that touches sort_order/account_code directly)."""
    try:
        sister = _resolve_sister_budget(edited_budget)
        if sister is None:
            return

        edited_lines = (BudgetLine.query
                        .filter_by(budget_id=edited_budget.id)
                        .order_by(BudgetLine.sort_order, BudgetLine.id).all())
        sister_lines = BudgetLine.query.filter_by(budget_id=sister.id).all()
        if not sister_lines:
            return

        # Build pairing indexes over the sister budget's lines.
        #  - sister_src_ids: sister lines that point AT an edited line
        #    (edited_line.id → sister_line)
        #  - sister_desc_index: (account_code, normalized description) → sister
        sister_src_ids = {}
        for _sl in sister_lines:
            if _sl.source_line_id is not None:
                sister_src_ids.setdefault(_sl.source_line_id, _sl)
        sister_desc_index = {}
        for _sl in sister_lines:
            _dk = (_sl.account_code, (_sl.description or '').strip().lower())
            # First writer wins so pairing is stable / deterministic.
            sister_desc_index.setdefault(_dk, _sl)

        # Walk the edited budget's full order; for each edited line that HAS a
        # sister, mirror account_code/name and hand the sister the next
        # sort_order in sequence. Only reseat sisters we actually pair — leave
        # sister-only orphans alone.
        _coa = dict(FP_COA_SECTIONS)
        matched_sister_ids = set()
        seq = 0
        for eln in edited_lines:
            sl = _sister_line_for(eln, sister_lines, sister_src_ids, sister_desc_index)
            if sl is None or sl.id in matched_sister_ids:
                continue
            matched_sister_ids.add(sl.id)
            # Mirror section membership (cross-section move changes these).
            if sl.account_code != eln.account_code:
                sl.account_code = eln.account_code
                sl.account_name = _coa.get(eln.account_code) or eln.account_name
                # role_group is section-specific; clear it so the sister
                # doesn't carry a stale sub-group label into the new section.
                sl.role_group = eln.role_group
            else:
                # Same section — keep the edited side's sub-group label so
                # grouped clusters stay aligned across versions.
                sl.role_group = eln.role_group
            sl.sort_order = seq
            seq += 1

        db.session.commit()
        _touch_budget(sister.id)
        db.session.commit()
    except Exception as _mle:
        try:
            db.session.rollback()
        except Exception:
            pass
        logging.warning(f"[_mirror_line_move] mirror failed (fail-open): {_mle}")


@app.route("/projects/<int:pid>/budget/<int:bid>/line/reorder", methods=["POST"])
@login_required
def line_reorder(pid, bid):
    """Move a line to a new position. Within-section by default; pass
    target_section_code to move across sections (per user 2026-05-04)."""
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    data    = request.get_json(force=True) or {}
    line_id = int(data.get("line_id") or 0)
    after_id = data.get("after_id")   # None → first in section; int → move after this line
    target_section_code = data.get("target_section_code")  # cross-section move

    ln = BudgetLine.query.filter_by(id=line_id, budget_id=bid).first_or_404()

    # Cross-section move: update account_code (and account_name from
    # FP_COA_SECTIONS) before reordering, then sort within the new section.
    if target_section_code is not None:
        try:
            new_code = int(target_section_code)
        except (TypeError, ValueError):
            return jsonify({"error": "target_section_code must be an integer"}), 400
        if new_code != ln.account_code:
            new_name = dict(FP_COA_SECTIONS).get(new_code) or ln.account_name
            ln.account_code = new_code
            ln.account_name = new_name
            # Drop role_group when crossing sections — sub-group labels
            # are section-specific (e.g. "Executives" only makes sense in
            # 2000 Production Staff). Neighbor adoption below picks up the
            # right one if applicable.
            ln.role_group = None

    # Build the section list, holding child rows (parent_line_id set) out so
    # we can re-clip them under their parent in a deterministic second pass.
    # Without this, dragging a parent labor row would re-seat its sort_order
    # but its children (kit fees, mileage, per-diem) kept their old
    # sort_order — fine for the next page render because
    # _order_lines_with_children re-clusters by parent_id, but stale in the
    # DB and brittle for any path that doesn't go through that helper.
    raw_lines = BudgetLine.query.filter_by(
        budget_id=bid, account_code=ln.account_code
    ).filter(BudgetLine.id != line_id).order_by(BudgetLine.sort_order, BudgetLine.id).all()
    parents_only = [sl for sl in raw_lines if not sl.parent_line_id]
    children_by_parent = {}
    for sl in raw_lines:
        if sl.parent_line_id:
            children_by_parent.setdefault(sl.parent_line_id, []).append(sl)

    # The dragged row could itself be a child line (rare — the UI normally
    # excludes them from drag) or a parent. Either way insert it into the
    # parent stream at the requested position; the child-clip pass below
    # then reseats every parent's children together.
    section_lines = parents_only
    if after_id is None:
        section_lines.insert(0, ln)
    else:
        after_id = int(after_id)
        idx = next((i for i, sl in enumerate(section_lines) if sl.id == after_id),
                   len(section_lines) - 1)
        section_lines.insert(idx + 1, ln)

    # Re-stitch: parent, then its children, then next parent, etc.
    final_order = []
    for sl in section_lines:
        final_order.append(sl)
        for kid in children_by_parent.get(sl.id, []):
            final_order.append(kid)
    # Orphaned children (parent missing from this section) tail in.
    seen_kids = {kid.id for sl in section_lines for kid in children_by_parent.get(sl.id, [])}
    for pid, kids in children_by_parent.items():
        for kid in kids:
            if kid.id not in seen_kids:
                final_order.append(kid)

    for i, sl in enumerate(final_order):
        sl.sort_order = i

    # Adopt role_group from the dropped position's immediate parent neighbors.
    # Bias toward the row landed AFTER (the user dropped HERE so this is the
    # cluster they joined). Without aggressive adoption, dropping at a
    # group boundary leaves role_group unchanged → _cluster_by_subgroup
    # snaps the row back to its original cluster on next render and the
    # drag visually "doesn't stick" (user 2026-05-28).
    try:
        new_idx = next((i for i, sl in enumerate(section_lines) if sl.id == ln.id), None)
        if new_idx is not None:
            before = section_lines[new_idx - 1].role_group if new_idx > 0 else None
            after  = section_lines[new_idx + 1].role_group if new_idx + 1 < len(section_lines) else None
            # Priority: matching pair > before (the row we landed AFTER) > after.
            # The "after" row is the one we're now sitting above — usually
            # the same cluster — so it's the better default than leaving
            # the row's old role_group in place.
            target = ln.role_group
            if before is not None and after is not None:
                target = before if before == after else (before or after)
            elif before is not None:
                target = before
            elif after is not None:
                target = after
            if ln.role_group != target:
                ln.role_group = target
    except Exception:
        # If neighbor inference fails for any reason, silently keep the
        # existing role_group rather than breaking the reorder.
        pass

    db.session.commit()
    _touch_budget(bid)
    db.session.commit()

    # Mirror the resulting layout (section membership + relative order) onto
    # the version-pair sister budget so Estimated↔Working stay aligned
    # (owner ask 2026-07). Fail-open — never breaks the drag.
    _mirror_line_move(budget)
    return jsonify({"ok": True})


@app.route("/projects/<int:pid>/budget/<int:bid>/line/<int:lid>/set-group", methods=["POST"])
@login_required
def line_set_group(pid, bid, lid):
    """Explicitly set a line's role_group and re-seat its sort_order so it
    lands at the bottom of that group cluster. Used by the "Change Group…"
    option in the line row context menu — lets users move rows into groups
    that currently have no members (and therefore no visible drop target)."""
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    data  = request.get_json(force=True) or {}
    group = (data.get("role_group") or "").strip() or None

    ln = BudgetLine.query.filter_by(id=lid, budget_id=bid).first_or_404()
    ln.role_group = group

    # Re-seat sort_order: place the line at the end of the chosen group's
    # cluster. If the group has no existing members, place the line at the
    # end of the section (so it picks up the group label visibly).
    section_lines = BudgetLine.query.filter_by(
        budget_id=bid, account_code=ln.account_code
    ).filter(BudgetLine.id != ln.id).order_by(
        BudgetLine.sort_order, BudgetLine.id
    ).all()

    # Find last index of a row with this role_group; insert after it.
    last_match = -1
    for i, sl in enumerate(section_lines):
        if sl.role_group == group:
            last_match = i
    if last_match >= 0:
        section_lines.insert(last_match + 1, ln)
    else:
        section_lines.append(ln)

    for i, sl in enumerate(section_lines):
        sl.sort_order = i

    db.session.commit()
    _touch_budget(bid)
    db.session.commit()

    # Mirror the resulting layout onto the version-pair sister budget so
    # Estimated↔Working stay aligned (owner ask 2026-07). Fail-open.
    _mirror_line_move(budget)
    return jsonify({"ok": True})


@app.route("/projects/<int:pid>/budget/<int:bid>/line/<int:lid>/remove-instance", methods=["POST"])
@login_required
def remove_schedule_instance(pid, bid, lid):
    """Remove all schedule days (and crew assignment) for a specific crew_instance on a line.
    Used when reducing quantity on a scheduled labor line."""
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    ln = BudgetLine.query.filter_by(id=lid, budget_id=bid).first_or_404()
    data = request.get_json(force=True) or {}
    instance = int(data.get("instance", 1))
    _sm = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'

    # Remove schedule days for this instance
    ScheduleDay.query.filter_by(
        budget_line_id=lid, crew_instance=instance, schedule_mode=_sm
    ).delete()

    # Remove crew assignment for this instance
    ca = next((c for c in ln.crew_assignments if (c.instance or 1) == instance), None)
    if ca:
        db.session.delete(ca)

    # Renumber remaining instances to fill the gap (keep them contiguous)
    remaining_sds = ScheduleDay.query.filter_by(
        budget_line_id=lid, schedule_mode=_sm
    ).filter(ScheduleDay.crew_instance > instance).all()
    for sd in remaining_sds:
        sd.crew_instance = (sd.crew_instance or 1) - 1

    remaining_cas = [c for c in ln.crew_assignments if (c.instance or 1) > instance]
    for c in remaining_cas:
        c.instance = (c.instance or 1) - 1

    db.session.commit()
    _touch_budget(bid)
    db.session.commit()
    return jsonify({"ok": True, "removed_instance": instance})


@app.route("/projects/<int:pid>/budget/<int:bid>/working/init", methods=["POST"])
@login_required
def init_working_budget(pid, bid):
    """
    Re-sync working_total on every BudgetLine to match the current estimated total.
    Used to reset the Working budget's line values back to the Estimated baseline.
    Idempotent and safe to call at any time.

    Note: Creating a Working budget version (separate Budget object) is done via
    create_working_from_estimated. This route only refreshes the working_total
    column on existing lines — it does not create new Budget objects.
    """
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    lines  = BudgetLine.query.filter_by(budget_id=bid).all()
    fringe_cfgs = get_fringe_configs(db.session, pid)
    profile  = budget.payroll_profile
    pw_start = budget.payroll_week_start if budget.payroll_week_start is not None else (
        profile.payroll_week_start if profile else 6)
    _sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'
    for ln in lines:
        if ln.use_schedule:
            sched = ScheduleDay.query.filter_by(budget_line_id=ln.id, schedule_mode=_sched_mode).all()
            res = calc_line_from_schedule(ln, sched, fringe_cfgs, profile, pw_start)
        else:
            res = calc_line(ln, fringe_cfgs)
        ln.working_total = res['est_total']

    if not budget.working_initialized_at:
        budget.working_initialized_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "initialized_at": budget.working_initialized_at.isoformat()})


def _auto_tag_source_spec(line_tag):
    """Resolve an auto-line tag to its driving sources. Returns:
        (flag_key, role_scope, pd_col)
    where:
      flag_key   = key inside ScheduleDay.cell_flags JSON to look for
                   (None means no schedule-cell driver for this tag)
      role_scope = 'talent' | 'atl' | 'crew' | None — when set, only
                   cells whose parent labor line matches this role
                   group contribute (hotel/flight/mileage are split
                   per role group)
      pd_col     = ProductionDay column name to check (None when not
                   meal-driven). Meals come from production-day toggles,
                   not per-crew cell flags.
    Unknown tags return (None, None, None) — no-op.
    """
    if line_tag in ('per_diem_full', 'per_diem_breakfast',
                    'per_diem_lunch', 'per_diem_dinner', 'working_meal'):
        return (line_tag, None, None)
    if line_tag.startswith('hotel_'):
        return ('hotel', line_tag.split('_', 1)[1], None)
    if line_tag.startswith('flight_'):
        return ('flight', line_tag.split('_', 1)[1], None)
    if line_tag.startswith('mileage_'):
        return ('mileage', line_tag.split('_', 1)[1], None)
    _pd_col_map = {
        'craft_services':          'craft_services',
        'meal_courtesy_breakfast': 'courtesy_breakfast',
        'meal_first':              'first_meal',
        'meal_second':             'second_meal',
    }
    if line_tag in _pd_col_map:
        return (None, None, _pd_col_map[line_tag])
    return (None, None, None)


def _count_auto_line_sources(budget_id, line_tag):
    """Count how many ScheduleDay cells / ProductionDay rows still
    carry the flag that would resurrect an auto-line of this tag.
    Used by delete_line to refuse with a clear error message when
    the user tries to remove a line that the sync would just bring
    back. 2026-05-19."""
    import json as _json
    from budget_calc import get_role_group as _get_rg
    flag_key, role_scope, pd_col = _auto_tag_source_spec(line_tag)
    count = 0

    if flag_key:
        labor_lines = {ln.id: ln for ln in
                       BudgetLine.query.filter_by(budget_id=budget_id, is_labor=True).all()}
        rg_by_line = {lid: _get_rg(ln.account_code) for lid, ln in labor_lines.items()}
        for sd in ScheduleDay.query.filter_by(budget_id=budget_id).all():
            if not sd.cell_flags:
                continue
            try:
                flags = _json.loads(sd.cell_flags)
            except (ValueError, TypeError):
                continue
            # Legacy per_diem alias also counts as per_diem_full.
            _has = flags.get(flag_key) or (
                flag_key == 'per_diem_full' and flags.get('per_diem'))
            if not _has:
                continue
            if role_scope and rg_by_line.get(sd.budget_line_id) != role_scope:
                continue
            count += 1

    if pd_col:
        from models import ProductionDay as _PD
        for pd_row in _PD.query.filter_by(budget_id=budget_id).all():
            if getattr(pd_row, pd_col, False):
                count += 1

    return count


def _depopulate_auto_line_sources(budget_id, line_tag):
    """Strip every ScheduleDay cell_flag / ProductionDay column entry
    that drives an auto-created budget line of `line_tag`. Returns the
    number of source rows touched. Called by the purge-tag endpoint
    after the user explicitly asks for it; not called from delete_line
    (delete_line refuses instead and tells the user to invoke this).

    Tag → flag mapping is owned by _auto_tag_source_spec(). Anything
    unrecognized is a safe no-op (returns 0).
    """
    import json as _json
    from budget_calc import get_role_group as _get_rg
    flag_key, role_scope, pd_col = _auto_tag_source_spec(line_tag)
    touched = 0

    if flag_key:
        labor_lines = {ln.id: ln for ln in
                       BudgetLine.query.filter_by(budget_id=budget_id, is_labor=True).all()}
        rg_by_line = {lid: _get_rg(ln.account_code) for lid, ln in labor_lines.items()}
        for sd in ScheduleDay.query.filter_by(budget_id=budget_id).all():
            if not sd.cell_flags:
                continue
            try:
                flags = _json.loads(sd.cell_flags)
            except (ValueError, TypeError):
                continue
            if not (flags.get(flag_key) or
                    (flag_key == 'per_diem_full' and flags.get('per_diem'))):
                continue
            if role_scope and rg_by_line.get(sd.budget_line_id) != role_scope:
                continue
            flags.pop(flag_key, None)
            if flag_key == 'per_diem_full':
                flags.pop('per_diem', None)
            sd.cell_flags = _json.dumps(flags) if flags else None
            touched += 1
        if touched:
            logging.info(f"[purge-tag] stripped {flag_key} from {touched} "
                         f"cell(s) on budget {budget_id} (tag={line_tag})")

    if pd_col:
        from models import ProductionDay as _PD
        _pd_touched = 0
        for pd_row in _PD.query.filter_by(budget_id=budget_id).all():
            if getattr(pd_row, pd_col, False):
                setattr(pd_row, pd_col, False)
                _pd_touched += 1
        if _pd_touched:
            logging.info(f"[purge-tag] cleared {pd_col} on {_pd_touched} "
                         f"ProductionDay(s) on budget {budget_id} (tag={line_tag})")
        touched += _pd_touched
    return touched


@app.route("/projects/<int:pid>/budget/<int:bid>/schedule/purge-tag", methods=["POST"])
@login_required
def schedule_purge_tag(pid, bid):
    """Purge every schedule entry that would resurrect a given auto-
    line tag (per_diem_*, working_meal, hotel_<rg>, flight_<rg>,
    mileage_<rg>, craft_services, meal_*). Called by the UI after
    delete_line returns 400 with an `auto_line_sources` count, so the
    user can clear the driving flags + delete the line in one
    deliberate step.

    Body: { "line_tag": "<tag>" }
    Response: { ok: true, touched: <int> }
    """
    Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    data = request.get_json(force=True) or {}
    tag = (data.get("line_tag") or "").strip()
    if not tag or tag not in SCHEDULE_LINE_DEFS:
        return jsonify({"error": "Unknown line_tag"}), 400
    try:
        touched = _depopulate_auto_line_sources(bid, tag)
        # Also re-sync so the now-zero-count auto-line drops to qty=0 /
        # gets removed entirely in the next render.
        sync_schedule_driven_lines(bid, db.session)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.exception(f"[purge-tag] failed for {tag}: {e}")
        return jsonify({"error": str(e)}), 500
    try:
        _log_activity(action='update', entity_type='schedule',
                      entity_id=bid, entity_label=f'Purge {tag}',
                      budget_id=bid, project_id=pid,
                      before={'line_tag': tag, 'sources_remaining': '?'},
                      after={'line_tag': tag, 'sources_remaining': 0,
                             'touched': touched},
                      note=f'Purged {touched} schedule entr'
                           f'{"y" if touched == 1 else "ies"} '
                           f'driving auto-line "{tag}"')
    except Exception: pass
    return jsonify({"ok": True, "touched": touched, "line_tag": tag})


@app.route("/projects/<int:pid>/budget/<int:bid>/schedule/purge-all", methods=["POST"])
@login_required
def schedule_purge_all(pid, bid):
    """Nuke every cell_flag + ProductionDay meal/CS toggle on this
    budget. Per-day type (work / travel / off) is left intact — only
    the auto-line drivers are cleared. Used as a hard reset when the
    user wants to rebuild meals / per-diem / travel coverage from
    scratch. 2026-05-19 user request: "find a way to purge the deletes
    on the schedule to make sure that it actually doesn't exist".
    """
    Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    import json as _json
    cleared_flags = 0
    cleared_pd    = 0
    try:
        for sd in ScheduleDay.query.filter_by(budget_id=bid).all():
            if not sd.cell_flags:
                continue
            try:
                _json.loads(sd.cell_flags)
            except Exception:
                sd.cell_flags = None
                cleared_flags += 1
                continue
            sd.cell_flags = None
            cleared_flags += 1
        from models import ProductionDay as _PD
        for pd_row in _PD.query.filter_by(budget_id=bid).all():
            _any = False
            for col in ('craft_services', 'courtesy_breakfast',
                        'first_meal', 'second_meal'):
                if getattr(pd_row, col, False):
                    setattr(pd_row, col, False)
                    _any = True
            if _any:
                cleared_pd += 1
        sync_schedule_driven_lines(bid, db.session)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.exception(f"[purge-all] failed: {e}")
        return jsonify({"error": str(e)}), 500
    try:
        _log_activity(action='update', entity_type='schedule',
                      entity_id=bid, entity_label='Schedule flag purge',
                      budget_id=bid, project_id=pid,
                      before=None,
                      after={'cleared_cell_flags': cleared_flags,
                             'cleared_prod_day_flags': cleared_pd},
                      note=f'Cleared all schedule flags '
                           f'({cleared_flags} cells, {cleared_pd} prod days)')
    except Exception: pass
    return jsonify({"ok": True,
                    "cleared_cell_flags": cleared_flags,
                    "cleared_prod_day_flags": cleared_pd})


@app.route("/projects/<int:pid>/budget/<int:bid>/line/<int:lid>", methods=["DELETE"])
@login_required
def delete_line(pid, bid, lid):
    ln = BudgetLine.query.filter_by(id=lid, budget_id=bid).first_or_404()
    # Snapshot for activity log + undo before any cascade.
    _act_before = _budget_line_snapshot(ln)
    _act_label  = ln.description or ln.account_name
    _line_tag   = getattr(ln, 'line_tag', None)

    # ── Auto-line resurrection check FIRST (before any cascade) ────────
    # If the line is schedule-driven AND flags are still set, refuse the
    # delete BEFORE we destroy any ScheduleDay/CrewAssignment children.
    # Without this guard, the previous version cascaded everything, then
    # rolled back — losing the deletes we'd already issued. User
    # feedback 2026-05-19: keep sync as source of truth; kick error.
    if _line_tag and _line_tag in SCHEDULE_LINE_DEFS:
        _src_count = _count_auto_line_sources(bid, _line_tag)
        if _src_count > 0:
            return jsonify({
                "error": (f"Can't delete this line — the schedule still has "
                          f"{_src_count} entr{'y' if _src_count == 1 else 'ies'} "
                          f"flagged that would recreate it on the next sync. "
                          f"Click 'Purge driving entries' to clear them first."),
                "auto_line_sources": _src_count,
                "line_tag": _line_tag,
                "line_id": lid,
                "purge_url": f"/projects/{pid}/budget/{bid}/schedule/purge-tag",
            }), 400

    # Cascade-delete every artifact tied to this line so nothing orphans.
    # Per user 2026-04-28: when a line goes, its schedule cells, crew
    # assignments, and travel details should disappear too — the budget
    # always reflects the live state, no ghost rows inflating sync counts.
    # (The Activity tab will record the deletion for audit.)
    sched_ids = [r.id for r in ScheduleDay.query
                 .filter_by(budget_line_id=lid).with_entities(ScheduleDay.id).all()]
    if sched_ids:
        TravelDetail.query.filter(TravelDetail.schedule_day_id.in_(sched_ids))\
            .delete(synchronize_session=False)
        ScheduleDay.query.filter(ScheduleDay.id.in_(sched_ids))\
            .delete(synchronize_session=False)
    CrewAssignment.query.filter_by(budget_line_id=lid)\
        .delete(synchronize_session=False)

    # ── Cross-row FK nullification (2026-05-19) ────────────────────────
    # Postgres FK constraints don't ON DELETE SET NULL on these — they
    # raise IntegrityError if anything still points at us. Clean it up:
    #
    #  1. BudgetLine.source_line_id — Actual budget lines back-reference
    #     their Working source. Null the link and flip orphan_from_working
    #     so the Actual UI shows "(orphan)" instead of silently losing
    #     the connection. The Actual line itself stays (it may have
    #     linked transactions whose dollars we don't want to drop).
    #  2. BudgetLine.parent_line_id — child lines (kit fees, splits)
    #     get re-parented to NULL → they become top-level rows in the
    #     same section. User can delete them individually if desired.
    #  3. Transaction.budget_line_id + suggested_budget_line_id —
    #     transactions stay (the spend happened) but lose the specific
    #     line link. Drop to section-only coding via account_code (which
    #     they already carry as a snapshot of the line's coding).
    #  4. Location.budget_line_id — catering vendors linked to the line.
    #     Null it; user can re-link.
    try:
        # 1. source_line_id back-references → SET NULL + mark orphan
        from sqlalchemy import update as _upd
        db.session.execute(
            _upd(BudgetLine)
            .where(BudgetLine.source_line_id == lid)
            .values(source_line_id=None, orphan_from_working=True)
        )
        # 2. parent_line_id back-references → SET NULL
        db.session.execute(
            _upd(BudgetLine)
            .where(BudgetLine.parent_line_id == lid)
            .values(parent_line_id=None)
        )
        # 3. Transaction back-references — keep the txns, drop the link
        Transaction.query.filter_by(budget_line_id=lid)\
            .update({Transaction.budget_line_id: None,
                     Transaction.match_status: 'unmatched'},
                    synchronize_session=False)
        Transaction.query.filter_by(suggested_budget_line_id=lid)\
            .update({Transaction.suggested_budget_line_id: None},
                    synchronize_session=False)
        # 4. Location.budget_line_id back-references
        try:
            from models import Location as _Loc
            _Loc.query.filter_by(budget_line_id=lid)\
                .update({_Loc.budget_line_id: None}, synchronize_session=False)
        except Exception:
            # Location.budget_line_id may not exist on every install
            pass
    except Exception as _fe:
        db.session.rollback()
        logging.exception(f"[delete_line] FK cleanup failed for line {lid}: {_fe}")
        return jsonify({
            "error": f"Could not clear references to this line before delete: {_fe}",
        }), 500

    db.session.delete(ln)
    try:
        db.session.commit()
    except Exception as _de:
        db.session.rollback()
        logging.exception(f"[delete_line] commit failed for line {lid}: {_de}")
        return jsonify({
            "error": f"Delete failed: {_de}",
        }), 500
    # Re-sync schedule-driven totals so meal/travel/per-diem lines drop
    # the contribution from this line's now-gone schedule cells.
    try:
        sync_schedule_driven_lines(bid, db.session)
        db.session.commit()
    except Exception:
        db.session.rollback()
    # Activity log: record the delete with the full pre-snapshot so undo
    # can recreate the line later. _log_activity owns its own commit.
    try:
        _log_activity(
            action='delete', entity_type='budget_line',
            entity_id=lid, entity_label=_act_label,
            budget_id=bid, project_id=pid,
            before=_act_before, after=None,
            dollar_delta=-float((_act_before or {}).get('estimated_total', 0) or 0),
        )
    except Exception as _e:
        logging.warning(f"[activity] delete_line log failed: {_e}")
        try: db.session.rollback()
        except Exception: pass
    return jsonify({"ok": True})


# ── Actuals tab routes (ported from FPBudgetSync 2026-04-30) ─────────

def _normalize_vendor(v):
    """Lowercase + strip common credit-card noise so 'LYFT *RIDE MON 8AM'
    and 'Lyft' both normalize to 'lyft' for fuzzy sibling matching.
    Used by _sync_claim_state's fuzzy branch (2026-05-15) to match
    receipt-only rows against QBO charges across projects."""
    if not v:
        return ""
    import re as _re
    s = str(v).strip().lower()
    # Strip common prefixes credit-card processors prepend.
    for _p in ('sq *', 'sq*', 'tst* ', 'tst*', 'amzn mktp ', 'amzn mktp* ',
               'amazon mktpl*', 'amazon mktpl ', 'amazon mktp ', 'paypal *',
               'paypal*', 'pp*', 'pos debit ', 'remote online deposit '):
        if s.startswith(_p):
            s = s[len(_p):]
            break
    # Strip trailing " *" + ride/order id noise after a space-asterisk.
    s = _re.split(r'\s+\*', s, maxsplit=1)[0]
    # Strip trailing reference digits / dates / "ride mon 8am" tails.
    s = _re.sub(r'\s+\d[\w\-: ]*$', '', s).strip()
    # Collapse remaining whitespace.
    s = _re.sub(r'\s+', ' ', s)
    return s


def _sync_claim_state(txn):
    """Cross-project claim propagation. Two channels:

    (1) **QBO-id match** — siblings with the same
        (qbo_txn_id, qbo_txn_type) across other projects. Pre-2026-05-15
        this was the only channel and required both rows to be electronic
        (had qbo_txn_id). That missed a real workflow: user uploads a
        receipt in Project A, assigns it to a budget line — the row has
        no qbo_txn_id (yet?), so claim never fired, and the same expense
        synced from QBO into Project B showed up uncoded there. User
        report 2026-05-15: "I have a Lyft charge for $37.93 that is
        assigned to Car Service in 2026 Q2 Etoro Press Conference and
        it also is showing up in 2026 FP general operations actuals".

    (2) **Fuzzy match** — siblings on other projects with the same
        normalized vendor, same amount (to the cent), and txn_date
        within ±5 days. Bridges the doc-only-vs-QBO-elsewhere gap.
        Tight enough to avoid false positives (same vendor+amount+date
        across two projects within a 5-day window is almost certainly
        the same expense).

    Call this AFTER mutating `txn` (set/clear budget_line_id /
    account_code / not_project_expense) and BEFORE `db.session.commit()`.

    Rules (apply to siblings from both channels):
      • If THIS row is claimed (budget_line_id OR account_code OR
        not_project_expense) → set siblings' claimed_by_project_id to
        this project_id, AND mark them not_project_expense=True so they
        drop out of the other project's rollup. Don't trample a claim
        already held by a third project.
      • If THIS row was released (no claim flags), clear the claim on
        any sibling whose claimed_by_project_id == this project_id, and
        un-mark not_project_expense if it was set by us. Other-project
        claims (set by yet another project) are left alone.

    Idempotent: safe to call repeatedly.
    """
    # Claim signals — any of these on `txn` mean "this project owns the
    # expense, hide siblings elsewhere". Attaching a receipt counts:
    # uploading a doc to project A is an affirmative assertion that the
    # expense lives there. Without this, a user-uploaded receipt in
    # project A had no effect on a parallel QBO row in project B; the
    # duplicate sat there until the user remembered to code A's row.
    # 2026-05-15 user report: Etoro had a Lyft receipt; FP General Ops
    # had the same Lyft as a separate QBO row that nobody had claimed.
    is_claimed_now = bool(txn.budget_line_id or txn.account_code
                          or txn.not_project_expense
                          or txn.doc_upload_id)

    siblings_by_id = {}  # id → Transaction (dedupe across both channels)

    # ── Channel 1: QBO-id sibling lookup ──────────────────────────────
    if txn.qbo_txn_id and txn.qbo_txn_type:
        try:
            for s in (Transaction.query
                      .filter(Transaction.qbo_txn_id   == txn.qbo_txn_id,
                              Transaction.qbo_txn_type == txn.qbo_txn_type,
                              Transaction.project_id   != txn.project_id)
                      .all()):
                siblings_by_id[s.id] = s
        except Exception as _se:
            # Likely DDL hasn't run for the indexes yet; safe to skip.
            logging.warning("[claim-sync] qbo sibling lookup failed (skipping): %s", _se)

    # ── Channel 2: Fuzzy (vendor / amount / date) sibling lookup ──────
    # Only runs when we have enough signal to match safely. Requires
    # amount AND date AND a non-trivial vendor name. Doc-only / manual
    # / reconciled rows all qualify.
    if txn.amount is not None and txn.txn_date and (txn.vendor or '').strip():
        try:
            import datetime as _dt
            _v_norm = _normalize_vendor(txn.vendor)
            if _v_norm and len(_v_norm) >= 3:
                # ±5d date window — same as receipt-first reconciliation.
                _d0 = _dt.datetime.strptime(txn.txn_date, '%Y-%m-%d').date()
                _date_lo = (_d0 - _dt.timedelta(days=5)).isoformat()
                _date_hi = (_d0 + _dt.timedelta(days=5)).isoformat()
                # Amount: exact match to the cent. Cross-project Lyft
                # charges of $37.93 vs $37.94 should NOT match — tip
                # rounding differences could create false positives if
                # we loosen this.
                from decimal import Decimal as _Dec
                _amt = _Dec(str(txn.amount))
                _candidates = (Transaction.query
                               .filter(Transaction.project_id   != txn.project_id,
                                       Transaction.amount       == _amt,
                                       Transaction.txn_date     >= _date_lo,
                                       Transaction.txn_date     <= _date_hi)
                               .all())
                for s in _candidates:
                    if s.id in siblings_by_id:
                        continue
                    if _normalize_vendor(s.vendor) == _v_norm:
                        siblings_by_id[s.id] = s
        except Exception as _fe:
            # Don't let fuzzy match break the user's primary action.
            logging.warning("[claim-sync] fuzzy sibling lookup failed (skipping): %s", _fe)

    if not siblings_by_id:
        return

    if is_claimed_now:
        for s in siblings_by_id.values():
            # Don't trample a claim already held by a third project.
            # Only re-claim if unclaimed or claimed by this project.
            if s.claimed_by_project_id in (None, txn.project_id):
                s.claimed_by_project_id = txn.project_id
                # Drop sibling out of its project's "uncoded" pile.
                # Preserve the sibling's existing flags only if it's
                # already coded — we don't want to wipe their work.
                if not (s.budget_line_id or s.account_code):
                    s.not_project_expense = True
    else:
        for s in siblings_by_id.values():
            if s.claimed_by_project_id == txn.project_id:
                s.claimed_by_project_id = None
                # If the sibling was marked not-project SOLELY because
                # we claimed it, undo that. Heuristic: if it has no
                # other coding, we set it; revert.
                if (s.not_project_expense
                        and not s.budget_line_id and not s.account_code):
                    s.not_project_expense = False


def _txn_is_split_parent(txn):
    """True when this transaction has invoice_split children — it's an itemized
    document CONTAINER whose coding lives on the sublines. Coding the container
    again would double-count the document. (Review fix 2026-07.)"""
    if txn is None:
        return False
    return db.session.query(Transaction.id).filter_by(
        parent_transaction_id=txn.id, source='invoice_split').first() is not None


def _split_parent_id_set(pid):
    """Ids of all itemized-container transactions on a project (parents that
    have invoice_split children). Used to keep containers out of 'Needs coding'
    surfaces + AI code-suggestion passes. (Review fix 2026-07.)"""
    rows = (db.session.query(Transaction.parent_transaction_id)
            .filter(Transaction.project_id == pid,
                    Transaction.source == 'invoice_split',
                    Transaction.parent_transaction_id.isnot(None))
            .distinct().all())
    return {r[0] for r in rows}


def _clear_ai_code_suggestion(txn):
    """Clear a transaction's AI code suggestion after it's been coded/dismissed so
    it stops surfacing in the doc popup chip, the row ✨ chip, and the Dashboard
    'Codes to confirm' queue. Does NOT commit. (User 2026-06-22.)"""
    if txn is None:
        return
    txn.ai_suggested_code = None
    txn.ai_suggested_code_name = None
    txn.ai_code_confidence = None
    txn.ai_code_reason = None
    # Deterministic person/PO suggestions also stash the exact line here
    # (2026-07); clear it so a coded/dismissed row stops re-surfacing.
    txn.suggested_budget_line_id = None


def _add_evidence(txn_id, doc_id, kind):
    """Idempotently record a doc→expense evidence link (A2). Fail-open and
    commit-free — callers commit. Duplicate (txn, doc) pairs are no-ops."""
    if not txn_id or not doc_id:
        return
    try:
        from models import ExpenseEvidence
        if not ExpenseEvidence.query.filter_by(transaction_id=txn_id,
                                               doc_upload_id=doc_id).first():
            db.session.add(ExpenseEvidence(transaction_id=txn_id,
                                           doc_upload_id=doc_id, kind=kind))
    except Exception as _ee:
        logging.warning(f"[evidence] add failed txn={txn_id} doc={doc_id}: {_ee}")


def _guard_doc_expense(txn, data):
    """Actualizing 2.0 A1 (2026-07-20): a doc-born row is a DOCUMENT, not an
    expense until an explicit user action makes it one.

    REWORKED 2026-08-19 (owner: "AI suggested codes… doesn't create an
    expense… when I try to assign it to a line or take the AI suggestion it
    gives me an error… the whole creating-an-expense process is pretty
    muddy"): originally only the row dropdown's Create-expense option sent
    create_expense=true, and EVERY other explicit coding path — the doc
    editor's assign dropdown, drag-and-drop, the ✨ AI-suggestion accept,
    bulk coding — bounced with a 400. Coding a document to a budget line or
    section IS the create-expense intent, so all of these now activate the
    document as an expense (stamping activated_at + the primary evidence
    link) instead of erroring. These code paths are all user-driven clicks;
    nothing automated codes doc-born rows, so upload + AI suggestion alone
    still never creates spend — the doc stays $0 until a person codes it,
    matches it to an imported charge, or marks it as backup.
    Returns None (never blocks); callers commit."""
    if txn.source != 'doc_upload' or txn.activated_at is not None:
        return None
    txn.activated_at = datetime.utcnow()
    _add_evidence(txn.id, txn.doc_upload_id, 'primary')
    return None


@app.route("/projects/<int:pid>/actuals/transaction/<int:tid>/set-line", methods=["POST"])
@login_required
def actuals_set_line(pid, tid):
    """Click-to-code: set the budget_line_id on a transaction (or clear
    it). Auto-clones Working → Actual on the first link via
    actuals.link_transaction_to_line. Returns JSON."""
    txn = Transaction.query.filter_by(id=tid, project_id=pid).first_or_404()
    data = request.get_json(force=True) or {}
    if data.get("budget_line_id"):
        _ge = _guard_doc_expense(txn, data)
        if _ge is not None:
            return _ge
    raw  = data.get("budget_line_id")

    # Itemized container: its coding lives on the sublines — re-coding it would
    # double-count the document. (Review fix 2026-07.)
    if raw and _txn_is_split_parent(txn):
        return jsonify({"error": "This document is itemized into line items — the "
                                 "sublines carry the coding. Open the doc and clear "
                                 "the itemization to code it as one line."}), 409

    # Empty string / None / 0 = clear the link.
    if not raw:
        from actuals import unlink_transaction
        try:
            _before_clear = {'budget_line_id': txn.budget_line_id,
                             'account_code': txn.account_code,
                             'account_code_name': txn.account_code_name}
            unlink_transaction(tid)
            # Refresh the txn after unlink_transaction's commit so the
            # claim-sync sees the cleared state.
            db.session.refresh(txn)
            _sync_claim_state(txn)
            db.session.commit()
            try:
                _log_activity(
                    action='update', entity_type='transaction',
                    entity_id=txn.id,
                    entity_label=(txn.vendor or txn.note or f'Txn #{txn.id}')[:80],
                    project_id=pid,
                    before=_before_clear,
                    after={'budget_line_id': None, 'account_code': None,
                           'account_code_name': None},
                    note='Cleared coding')
            except Exception: pass
            return jsonify({"ok": True, "cleared": True})
        except Exception as e:
            logging.exception(f"[actuals] unlink failed: {e}")
            return jsonify({"error": str(e)}), 500

    try:
        line_id = int(raw)
    except (TypeError, ValueError):
        return jsonify({"error": "budget_line_id must be an integer"}), 400

    from actuals import link_transaction_to_line
    try:
        # Snapshot before-state for the activity log.
        _before = {'budget_line_id': txn.budget_line_id,
                   'account_code': txn.account_code,
                   'account_code_name': txn.account_code_name}
        result = link_transaction_to_line(
            tid, line_id, user_id=current_user.id
        )
        # Refresh after commit so UI gets the freshly-set fields.
        db.session.refresh(txn)
        # Cross-project claim: now that this row owns a budget line,
        # propagate to any sibling rows in other projects.
        _sync_claim_state(txn)
        # Coding it manually clears any AI code suggestion so it stops showing
        # in the popup / row chip / 'Codes to confirm' queue. (User 2026-06-22.)
        _clear_ai_code_suggestion(txn)
        db.session.commit()
        try:
            _label = (txn.vendor or txn.note or f'Txn #{txn.id}')[:80]
            _amt = float(txn.amount or 0)
            _coa_name = txn.account_code_name or ''
            _log_activity(
                action='update', entity_type='transaction',
                entity_id=txn.id, entity_label=_label,
                project_id=pid,
                before=_before,
                after={'budget_line_id': txn.budget_line_id,
                       'account_code': txn.account_code,
                       'account_code_name': _coa_name},
                dollar_delta=0,
                note=f'Coded ${_amt:,.2f} → {txn.account_code} {_coa_name}'.strip())
        except Exception: pass
        return jsonify({
            "ok":            True,
            "cleared":       False,
            "transaction": {
                "id":              txn.id,
                "budget_line_id":  txn.budget_line_id,
                "account_code":    txn.account_code,
                "account_code_name": txn.account_code_name,
                "match_status":    txn.match_status,
            },
            "actual_was_just_created":  result.get("actual_was_just_created"),
            "working_was_just_created": result.get("working_was_just_created"),
            "actual_budget_id":         result.get("actual_budget_id"),
        })
    except Exception as e:
        logging.exception(f"[actuals] link failed: {e}")
        return jsonify({"error": str(e)}), 500


