@app.route("/projects/<int:pid>/budget/<int:bid>/export.pdf")
@login_required
def export_pdf(pid, bid):
    budget  = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    project = ProjectSheet.query.get_or_404(pid)
    lines   = BudgetLine.query.filter_by(budget_id=bid).order_by(
        BudgetLine.account_code, BudgetLine.sort_order).all()
    fringe_cfgs = get_fringe_configs(db.session, pid)

    # ── Sub-budget filter (2026-05-26) ────────────────────────────────
    # When ?sub_budget=<id> is set, render the PDF as a slice of the
    # parent budget — keep only lines that are assigned to that
    # sub-budget. Same template, same calc, just a filtered line set.
    # The Top Sheet rolls up only the included lines, so the GRAND
    # TOTAL is the sub-budget's total (client sees only their slice).
    sub_budget_id = request.args.get('sub_budget', type=int)
    sub_budget_obj = None
    if sub_budget_id:
        sub_budget_obj = SubBudget.query.filter_by(
            id=sub_budget_id, project_id=pid).first()
        if not sub_budget_obj:
            return jsonify({"error": "Sub-budget not found"}), 404
        _sb_line_ids = {r[0] for r in db.session.query(SubBudgetLine.budget_line_id)
                                         .filter(SubBudgetLine.sub_budget_id == sub_budget_id)
                                         .all()}
        # Also include any child rows (kit fees) of included parent
        # lines, so the export reads naturally with their parent.
        _children = {ln.id for ln in lines
                     if ln.parent_line_id and ln.parent_line_id in _sb_line_ids}
        _keep_ids = _sb_line_ids | _children
        lines = [ln for ln in lines if ln.id in _keep_ids]

    # Per-export overrides from the Export Options dialog (see export_csv
    # for the same pattern). Applied to the in-memory Budget without
    # persisting so the saved settings stay untouched.
    suppress_zeros = request.args.get("suppress_zeros") == "1"
    if "fee_dispersed" in request.args:
        budget.company_fee_dispersed = request.args.get("fee_dispersed") == "1"
    profile  = budget.payroll_profile
    pw_start = budget.payroll_week_start if budget.payroll_week_start is not None else (
        profile.payroll_week_start if profile else 6)

    actuals_by_code = _actuals_by_section_code(pid)

    top_sheet   = calc_top_sheet(budget, lines, fringe_cfgs, actuals_by_code, profile, pw_start)
    detail_mode = request.args.get("detail", "0") == "1"
    dispersed   = bool(budget.company_fee_dispersed)

    # Build section detail for full-detail export. Schedule fetch MIRRORS
    # budget_view: legacy NULL-mode rows count, deduped per (instance, date)
    # with the mode-tagged row winning. The old strict mode filter made
    # export totals drop legacy days (same defect as the sub-budget card —
    # user report 2026-07-22: 'when I export sub budgets the totals are not
    # correct').
    sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'
    line_results = {}
    for ln in lines:
        if ln.use_schedule:
            _raw_sd = ScheduleDay.query.filter(
                ScheduleDay.budget_line_id == ln.id,
                db.or_(ScheduleDay.schedule_mode == sched_mode,
                       ScheduleDay.schedule_mode == None)).all()
            _dd = {}
            for _d in _raw_sd:
                _k = (_d.crew_instance or 1, _d.date)
                _ex = _dd.get(_k)
                if _ex is None or (_ex.schedule_mode is None
                                   and _d.schedule_mode == sched_mode):
                    _dd[_k] = _d
            line_results[ln.id] = calc_line_from_schedule(
                ln, list(_dd.values()), fringe_cfgs, profile, pw_start)
        else:
            line_results[ln.id] = calc_line(ln, fringe_cfgs)

    # Group lines into sections
    from budget_calc import FP_COA_SECTIONS
    def _section_for_code(code):
        best = None
        for start, _ in FP_COA_SECTIONS:
            if code >= start:
                best = start
            else:
                break
        return best
    section_name_map = dict(FP_COA_SECTIONS)
    sections_detail = {}
    for ln in lines:
        sk = _section_for_code(ln.account_code)
        if sk not in sections_detail:
            sections_detail[sk] = {"code": sk, "name": section_name_map.get(sk, ""), "lines": []}
        sections_detail[sk]["lines"].append(ln)
    # Apply the same parent-child + sub-group clustering the in-app view
    # uses, so kit-fee rows attach to their parent labor line and
    # headers/spacers stay in the right sub-group on export. Without
    # this, the PDF showed kit fees in raw sort_order position (e.g.
    # "Laptop" kit fee for Tech Producer landed under Robo Cam Op
    # instead). User report 2026-05-26.
    for sec in sections_detail.values():
        sec["lines"] = _order_lines_with_children(sec["lines"])
    # Tag each section with column-visibility booleans so the PDF can
    # collapse columns that have no data — per user request 2026-04-28
    # the export shouldn't render Payroll / OT / Fringe / Agent% / Disc%
    # column headers if every cell would be empty.
    for sec in sections_detail.values():
        labor_lines    = [_l for _l in sec["lines"] if getattr(_l, 'is_labor', False)]
        nonlabor_lines = [_l for _l in sec["lines"] if not getattr(_l, 'is_labor', False)]
        sec["has_labor"]    = bool(labor_lines)
        # Show "Payroll" in place of "Qty" only when a labor line in
        # this section actually has a payroll_co value. Otherwise
        # fall back to "Qty" (filled for non-labor rows).
        sec["has_payroll"]  = any((_l.payroll_co or '').strip()
                                   for _l in labor_lines)
        # Hide Qty entirely if no non-labor line has a meaningful qty
        # (everything == 1 or empty). Lets purely-labor sections drop
        # the col without affecting non-labor sections.
        sec["has_qty"]      = any(float(_l.quantity or 0) and float(_l.quantity or 0) != 1
                                   for _l in nonlabor_lines)
        # OT / Fringe: only show if a labor line actually has them.
        sec["has_ot"]       = any(float((line_results.get(_l.id) or {}).get("ot_amount", 0) or 0) > 0
                                   for _l in labor_lines)
        sec["has_fringe"]   = any(float((line_results.get(_l.id) or {}).get("fringe_amount", 0) or 0) > 0
                                   for _l in labor_lines)
        # Agent% (labor) or Disc% (non-labor): show if any line has
        # a non-zero value.
        sec["has_agent"]    = any(float(_l.agent_pct or 0) for _l in labor_lines)
        sec["has_discount"] = any(float(_l.agent_pct or 0) for _l in nonlabor_lines)
    sections_ordered = [sections_detail[sk] for sk, _ in FP_COA_SECTIONS if sk in sections_detail]

    company_settings = CompanySettings.query.get(1) or CompanySettings()
    is_working_view  = budget.budget_mode in ('working', 'actual')

    fee_m = (1 + float(budget.company_fee_pct)) if dispersed else 1.0

    # ── Client-facing rounding for dispersed mode ──────────────────────
    # When the Prod Co Fee is dispersed across line totals, the raw math
    # produces awkward numbers ($1,070, $1,650) that flag the gross-up
    # to clients/auditors. For PDF export only (in-app stays exact), we
    # round each line's dispersed total to the nearest $10. Flat $10
    # bucket across labor + non-labor (per user 2026-04-28 — the prior
    # $25-for-labor split risked shifting line totals between exports
    # when only the bucket boundary changed).
    #
    # IMPORTANT: rounding is INDEPENDENT per line — one line's rounded
    # total never depends on another. So the same budget always exports
    # the same PDF numbers; adding/removing a line doesn't shift the
    # rounded values of existing lines. Determinism is the priority
    # over making section sums hit perfect round numbers.
    PDF_BUCKET = 10.0
    pdf_line_totals = {}
    pdf_section_totals = {}
    if dispersed:
        # ── Two-pass rounding with grand-total reconciliation ──────────
        # Pass 1: round each line's dispersed total independently to the
        #         nearest $10. Independent rounding = stability — adding
        #         or editing one line never shifts another's rounded total.
        # Pass 2: compute drift between sum(rounded lines) and
        #         round(true grand total). If drift != 0, distribute the
        #         drift in $10 increments by bumping individual lines
        #         whose fractional remainder was closest to the rounding
        #         boundary (largest-remainder method). This keeps every
        #         bumped line within $10 of its natural rounded value
        #         while making the visible grand total exact.
        true_grand = 0.0
        line_exact = {}     # id → exact dispersed total
        line_remainder = {} # id → signed distance to next $10 bucket
        for sec in sections_ordered:
            for ln in sec["lines"]:
                res = line_results.get(ln.id) or {}
                exact = float(res.get("est_total") or 0) * fee_m
                line_exact[ln.id] = exact
                rounded = round(exact / PDF_BUCKET) * PDF_BUCKET
                pdf_line_totals[ln.id] = rounded
                true_grand += exact
                # Remainder = how far from the bucket boundary in the
                # OPPOSITE direction we'd have to go (positive if we
                # rounded down and could bump up, negative if we rounded
                # up and could bump down).
                line_remainder[ln.id] = exact - rounded

        # Target = true grand total rounded to $10. Drift = target − sum(rounded).
        target_grand = round(true_grand / PDF_BUCKET) * PDF_BUCKET
        sum_rounded = sum(pdf_line_totals.values())
        drift = round((target_grand - sum_rounded) / PDF_BUCKET)  # in $10 units

        if drift != 0:
            # Bump up: pick lines that rounded DOWN (positive remainder),
            #          sorted by largest remainder first (closest to bumping anyway).
            # Bump down: pick lines that rounded UP (negative remainder),
            #          sorted by most-negative remainder first.
            # Each pick adjusts by one $10 unit; iterate until drift = 0
            # or we run out of candidates.
            ordered_ids = sorted(line_remainder, key=lambda i: line_remainder[i], reverse=(drift > 0))
            step = PDF_BUCKET if drift > 0 else -PDF_BUCKET
            remaining = abs(drift)
            for lid in ordered_ids:
                if remaining == 0:
                    break
                # Stop once the remainder sign flips — bumping further
                # would mean rounding a line away from its natural target
                # by more than $10, which defeats nearest-$10 rounding.
                if (drift > 0 and line_remainder[lid] <= 0) or \
                   (drift < 0 and line_remainder[lid] >= 0):
                    break
                pdf_line_totals[lid] += step
                remaining -= 1

        # Section totals: clean sum of the (now reconciled) rounded lines.
        for sec in sections_ordered:
            pdf_section_totals[sec["code"]] = sum(
                pdf_line_totals.get(ln.id, 0) for ln in sec["lines"]
            )

        # Top-sheet rows: re-derive from the section totals so they
        # match the detail pages exactly. Falls back to round-to-$10 of
        # the raw estimated for sections that have no detail rows
        # (Workers' Comp / Payroll Fee auto-injects).
        for row in top_sheet.get("rows", []):
            code = row.get("code")
            if code in pdf_section_totals:
                row["pdf_rounded_estimated"] = pdf_section_totals[code]
            else:
                row["pdf_rounded_estimated"] = round(float(row["estimated"]) / PDF_BUCKET) * PDF_BUCKET
        # Grand total: sum of the (now reconciled) rounded rows.
        ts_rows = top_sheet.get("rows", [])
        if ts_rows:
            top_sheet["pdf_rounded_grand_total_estimated"] = sum(
                r.get("pdf_rounded_estimated", r["estimated"]) for r in ts_rows
            )

    # Filter out zero-total lines + zero-total sections when suppress_zeros
    # is on. Done at the template-data level so the math (top sheet,
    # company fee, grand total) still uses the full budget — only the
    # printed list shrinks.
    #
    # Per user 2026-04-28: lines that are zero BECAUSE of a discount
    # (agent_pct → 100%, i.e. a comped / in-kind item) are meaningful and
    # must stay visible. Only suppress lines that are zero for "no rate /
    # no qty / no days" reasons. Heuristic: if rate * qty * days > 0 and
    # the line is non-labor with a discount, keep it; the discount column
    # will show 100% so the client sees "yes this was considered, 100%
    # discounted to zero".
    def _is_zero_due_to_discount(ln):
        try:
            r = float(ln.rate or 0); q = float(ln.quantity or 0); d = float(ln.days or 0)
            ag = float(ln.agent_pct or 0)
            return (r * q * d) > 0 and not ln.is_labor and ag > 0
        except (TypeError, ValueError):
            return False

    if suppress_zeros:
        for sec in sections_ordered:
            sec["lines"] = [
                ln for ln in sec["lines"]
                if round(float(line_results.get(ln.id, {}).get("est_total") or 0), 2) != 0
                or _is_zero_due_to_discount(ln)
            ]
        sections_ordered = [s for s in sections_ordered if s["lines"]]
        top_sheet["rows"] = [
            r for r in top_sheet["rows"]
            if round(float(r.get("estimated") or 0), 2) != 0
            or round(float(r.get("actual") or 0), 2) != 0
        ]

    # Column picker (2026-05-15). Defaults preserve previous behavior:
    # working view → Est + Work + Var; estimated view → Est only.
    # User can override via the Export Options modal — flags arrive
    # as ?col_est=1&col_work=1&col_act=1&col_var=1&var_basis=...
    # The variance basis controls what the Variance column subtracts:
    #   est_v_work  → Working - Estimated  (overrun while planning)
    #   work_v_act  → Working - Actual     (overrun in production)
    #   est_v_act   → Estimated - Actual   (overrun vs original plan)
    _any_col_param = any(k in request.args for k in
                         ('col_est', 'col_work', 'col_act', 'col_var'))
    if _any_col_param:
        col_est  = request.args.get('col_est')  == '1'
        col_work = request.args.get('col_work') == '1'
        col_act  = request.args.get('col_act')  == '1'
        col_var  = request.args.get('col_var')  == '1'
    else:
        # Legacy defaults — no params means no modal-invoked export.
        col_est  = True
        col_work = is_working_view
        col_act  = False
        col_var  = is_working_view
    var_basis = request.args.get('var_basis') or 'est_v_work'
    if var_basis not in ('est_v_work', 'work_v_act', 'est_v_act'):
        var_basis = 'est_v_work'

    # ── Pull the Estimated peer's Top Sheet so the PDF's Estimated
    # column reads from the actual Estimated budget instead of the
    # current budget's pre-fee snapshot. Without this, exporting from
    # Working / Actual put the Working pre-fee value in the Estimated
    # column (e.g. Travel showed $961.70 instead of $17.70). The in-app
    # Top Sheet already does this — mirror it here. User report
    # 2026-05-15. Same fallback as the in-app block: if no Estimated
    # peer exists, est_top_sheet collapses to top_sheet (degenerates to
    # the pre-fix behavior, which is correct when there IS no separate
    # Estimated budget).
    est_top_sheet = None
    est_section_lookup = {}
    if budget.budget_mode == 'estimated':
        # Exporting an Estimated budget — its OWN rollup IS the Estimated
        # column. Don't re-resolve a "current Estimated peer"; that could
        # pick a DIFFERENT Estimated version and make the PDF disagree
        # with the budget on screen (root cause of the active-vs-export
        # mismatch). Mirrors budget_view. 2026-05-20.
        est_top_sheet = top_sheet
    else:
      try:
        # Find the project's current Estimated peer budget. Two-step
        # lookup that mirrors the in-app view (app.py:3791): prefer
        # version_status='current'; fall back to any non-archived row
        # so projects whose Estimated peer was superseded but not
        # archived still resolve correctly.
        #
        # Critical: don't filter on is_actual — Estimated budgets in
        # this codebase either have is_actual=False or NULL, and a
        # naive `is_actual == False` SQL filter excludes NULL rows
        # entirely. Was the silent reason the previous fix (29d99c8)
        # didn't take for this user. 2026-05-19 v2.
        _est_peer = (Budget.query
                     .filter(Budget.project_id == pid,
                             Budget.budget_mode == 'estimated',
                             Budget.version_status == 'current')
                     .order_by(Budget.id.desc()).first())
        if not _est_peer:
            _est_peer = (Budget.query
                         .filter(Budget.project_id == pid,
                                 Budget.budget_mode == 'estimated',
                                 Budget.version_status != 'archived')
                         .order_by(Budget.id.desc()).first())
        if _est_peer and _est_peer.id != budget.id:
            _eb_lines = (BudgetLine.query
                         .filter_by(budget_id=_est_peer.id)
                         .order_by(BudgetLine.account_code,
                                   BudgetLine.sort_order).all())
            if sub_budget_obj:
                # Sub-budget slice (2026-07-22): the Estimated column must
                # cover the SAME slice — pair est lines to the kept working
                # lines via source chains (either direction, incl. shared
                # ancestor) then (code, description). Previously the est
                # side used the FULL estimated budget, so the Top Sheet
                # mixed slice-Working numbers against full-Estimated ones.
                _kept_ids = {l.id for l in lines}
                _kept_src = {l.source_line_id for l in lines if l.source_line_id}
                _kept_keys = {(l.account_code, (l.description or '').strip().lower())
                              for l in lines}
                _eb_lines = [el for el in _eb_lines
                             if el.id in _kept_src
                             or (el.source_line_id is not None
                                 and (el.source_line_id in _kept_ids
                                      or el.source_line_id in _kept_src))
                             or (el.account_code,
                                 (el.description or '').strip().lower()) in _kept_keys]
            _eb_profile = _est_peer.payroll_profile
            _eb_pw_start = (_est_peer.payroll_week_start
                            if _est_peer.payroll_week_start is not None
                            else (_eb_profile.payroll_week_start if _eb_profile else 6))
            _eb_fringe = get_fringe_configs(db.session, pid)
            est_top_sheet = calc_top_sheet(
                _est_peer, _eb_lines, _eb_fringe, {},
                _eb_profile, _eb_pw_start,
            )
        else:
            est_top_sheet = top_sheet  # current budget IS the Estimated
      except Exception as _eee:
        logging.warning(f"[export_pdf] est_top_sheet build failed: {_eee}")
        est_top_sheet = top_sheet
    for _r in (est_top_sheet.get("rows") if est_top_sheet else []) or []:
        est_section_lookup[_r["code"]] = _r

    # ── Version labels for the budgets represented in this export ──────
    # The PDF compares an Estimated column against Working/Actual; show the
    # actual version of EACH budget whose column appears so the export is
    # unambiguous about exactly which versions were compared. (User 2026-06-03.)
    def _ver_str(b):
        if not b:
            return None
        lbl = getattr(b, 'version_label', None)
        if lbl:
            return str(lbl)
        n = getattr(b, 'version_number', None)
        return ('v%d' % n) if n else None
    est_budget_obj = (budget if budget.budget_mode == 'estimated'
                      else (_est_peer if ('_est_peer' in locals() and _est_peer) else budget))
    est_ver  = _ver_str(est_budget_obj)
    work_ver = _ver_str(budget) if is_working_view else None
    work_ver_label = ('Actual' if budget.budget_mode == 'actual' else 'Working')

    # ── Per-person travel/per-diem mirror rows (opt-in PDF export)
    # Reuses compute_travel_mirror_per_line — same helper the in-app
    # Budget tab uses to render the small italic "↪ Hotel — Crew /
    # ↪ Flights — Crew / ↪ Per Diem" rows under each labor person.
    # Gated by ?travel_notes=1 from the Export Options modal so the
    # default export stays compact. User request 2026-05-19: "I can
    # see, like, little hotel flights per diems, all of that. Can
    # that go out on the exports as well?". 2026-05-19.
    include_travel_notes = (request.args.get('travel_notes') == '1')
    travel_mirror_by_line = {}
    if include_travel_notes:
        try:
            from budget_calc import compute_travel_mirror_per_line
            _labor_lines = [ln for ln in lines if ln.is_labor]
            # Pull schedule days for this budget+mode. Same query
            # signature sync_schedule_driven_lines uses so the
            # per-person split reconciles with the aggregate.
            from sqlalchemy import or_ as _or_pdf_sd
            _sd_pdf = ScheduleDay.query.filter(
                ScheduleDay.budget_id == bid,
                _or_pdf_sd(ScheduleDay.schedule_mode == sched_mode,
                           ScheduleDay.schedule_mode.is_(None))
            ).all()
            travel_mirror_by_line = compute_travel_mirror_per_line(
                budget, _labor_lines, _sd_pdf, all_lines=lines)
        except Exception as _tm_e:
            logging.warning(f"[export_pdf] travel-mirror compute failed: {_tm_e}")

    html_str = render_template("budget_pdf.html",
        project=project,
        budget=budget,
        top_sheet=top_sheet,
        est_top_sheet=est_top_sheet,
        est_section_lookup=est_section_lookup,
        detail_mode=detail_mode,
        dispersed=dispersed,
        company_settings=company_settings,
        is_working_view=is_working_view,
        sections_ordered=sections_ordered,
        line_results=line_results,
        fee_m=fee_m,
        pdf_line_totals=pdf_line_totals,        # rounded dispersed line totals
        pdf_section_totals=pdf_section_totals,  # rounded dispersed section sums
        suppress_zeros=suppress_zeros,
        col_est=col_est, col_work=col_work, col_act=col_act, col_var=col_var,
        var_basis=var_basis,
        include_travel_notes=include_travel_notes,
        travel_mirror_by_line=travel_mirror_by_line,
        est_ver=est_ver, work_ver=work_ver, work_ver_label=work_ver_label,
        sub_budget=sub_budget_obj,
        today=date.today(),
    )

    pdf_bytes = WeasyprintHTML(string=html_str, base_url=request.host_url).write_pdf()
    mode_label = "Working" if is_working_view else "Estimated"
    # Human filenames (owner 2026-07-22: 'the PDF export default file names
    # are a bit crazy'): the old scheme concatenated project + budget name
    # (which usually REPEATS the project) with underscores —
    # 'GINTS_2026_GINTS_2026_Budget_Estimated_detail.pdf'. Now:
    #   'GINTS 2026 - Estimated v2 Detail.pdf'
    #   'GINTS 2026 - Sub-Budget Day 2 Filming.pdf'
    _ver_bit = f" v{budget.version_number}" if budget.version_number else ""
    if sub_budget_obj:
        fname = f"{project.name} - Sub-Budget {sub_budget_obj.name}.pdf"
    else:
        _detail_bit = "Detail" if detail_mode else "Top Sheet"
        fname = f"{project.name} - {mode_label}{_ver_bit} {_detail_bit}.pdf"
    fname = re.sub(r'\s+', ' ', fname).strip()
    return Response(
        pdf_bytes,
        mimetype="application/pdf",
        headers={"Content-Disposition": _content_disposition_attachment(fname)}
    )


# ════════════════════════════════════════════════════════════════════════
# Client estimate portal — send a budget as an estimate; client reviews &
# approves at a public /e/<token> link. (User 2026-06-03.)
# ════════════════════════════════════════════════════════════════════════

def _estimate_version_label(budget):
    mode_word = 'Working' if budget.budget_mode in ('working', 'actual') else 'Estimated'
    if budget.budget_mode == 'actual':
        mode_word = 'Actual'
    lbl = getattr(budget, 'version_label', None)
    if not lbl and getattr(budget, 'version_number', None):
        lbl = 'v%d' % budget.version_number
    # Always show a version number — a budget that predates versioning (no
    # label/number) is the first version. Better than a bare "Estimated".
    # (User 2026-06-04.)
    if not lbl:
        lbl = 'v1'
    return f"{mode_word} {lbl}".strip()


def _build_estimate_snapshot(project, budget, detail_mode):
    """Freeze the budget's section/line totals + presentation meta at send
    time, so the client always sees exactly what was sent and the approval is
    bound to this version even if the budget changes later. (User 2026-06-03.)"""
    from budget_calc import FP_COA_SECTIONS
    lines = (BudgetLine.query.filter_by(budget_id=budget.id)
             .order_by(BudgetLine.account_code, BudgetLine.sort_order).all())
    fringe_cfgs = get_fringe_configs(db.session, project.id)
    profile = budget.payroll_profile
    pw_start = (budget.payroll_week_start if budget.payroll_week_start is not None
                else (profile.payroll_week_start if profile else 6))
    sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'

    # Use the SAME Top Sheet calc the on-screen budget + PDF use, so the totals
    # the client sees match exactly. Summing raw line totals (the old approach)
    # omitted the company fee, fringes rolled at section level, workers' comp,
    # payroll fee and production insurance — so the grand total was wrong.
    # (User 2026-06-04.)
    ts = calc_top_sheet(budget, lines, fringe_cfgs, {}, profile, pw_start)
    grand = round(float(ts.get("grand_total_estimated") or 0), 2)
    dispersed = bool(ts.get("company_fee_dispersed"))
    fee = round(float(ts.get("company_fee") or 0), 2)

    sections = []
    for row in ts.get("rows", []):
        sections.append({
            "code": row.get("code"),
            "name": row.get("account") or '',
            "total": round(float(row.get("estimated") or 0), 2),
            "lines": [],
        })
    # When the company fee is NOT dispersed it's a separate top-sheet line; add
    # it so the sections sum to the grand total. (Dispersed → already folded into
    # each section's total, so no separate line.)
    if not dispersed and fee:
        sections.append({"code": 99999, "name": "Production Company Fee",
                         "total": fee, "lines": []})

    def _sec_for(code):
        best = None
        for start, _ in FP_COA_SECTIONS:
            if code is not None and code >= start:
                best = start
            else:
                break
        return best
    by_code = {s["code"]: s for s in sections}

    # Per-line calc pass — runs in BOTH modes: detail rows reuse it, and it
    # feeds the per-section DISCOUNT sums (owner 2026-07-22: "we are not
    # seeing discounts included at all in what it said to the client — I
    # definitely want those per section and then totaled"). Non-labor
    # agent_amount IS the line's discount (see calc_line); labor agent fees
    # are real charges, not discounts, so they're excluded.
    _line_res = {}
    for ln in lines:
        if getattr(ln, 'line_tag', None) in ('header', 'spacer'):
            continue
        if ln.use_schedule:
            sched = ScheduleDay.query.filter_by(budget_line_id=ln.id, schedule_mode=sched_mode).all()
            res = calc_line_from_schedule(ln, sched, fringe_cfgs, profile, pw_start)
        else:
            res = calc_line(ln, fringe_cfgs)
        _line_res[ln.id] = res
        if not ln.is_labor:
            _d = round(float((res or {}).get('agent_amount') or 0), 2)
            if _d:
                _sd = by_code.get(_sec_for(ln.account_code))
                if _sd is not None:
                    _sd["discount"] = round(_sd.get("discount", 0) + _d, 2)
    discount_total = round(sum(s.get("discount", 0) for s in sections), 2)

    # Optional per-line breakdown under each section (best-effort: section-level
    # adds like fringe / WC / fee live at the section total, not on a line).
    if detail_mode:
        for ln in lines:
            sdict = by_code.get(_sec_for(ln.account_code))
            if not sdict:
                continue
            # Sub-headers and spacers are presentation rows, not charges.
            # (Was `getattr(ln, 'is_header', False)` — an attribute that
            # doesn't exist — so they leaked into client estimates as plain
            # "$0.00" lines. Owner 2026-07-22: obey the header formatting on
            # client sends; never show amounts on headers/spacers.) Headers
            # carry their formatting JSON so the portal renders them styled;
            # spacers become a small visual gap.
            _tag = getattr(ln, 'line_tag', None)
            if _tag == 'spacer':
                sdict["lines"].append({"kind": "spacer"})
                continue
            if _tag == 'header':
                if not (ln.description or '').strip():
                    continue   # empty placeholder — never send
                _hfmt = {}
                try:
                    _hfmt = json.loads(ln.note) if ln.note else {}
                    if not isinstance(_hfmt, dict):
                        _hfmt = {}
                except Exception:
                    _hfmt = {}
                sdict["lines"].append({
                    "kind": "header",
                    "desc": (ln.description or '').strip(),
                    "fmt": {k: _hfmt.get(k) for k in
                            ('bold', 'underline', 'italic', 'color',
                             'size', 'indent') if _hfmt.get(k) is not None}})
                continue
            res = _line_res.get(ln.id) or {}
            sdict["lines"].append({
                "code": ln.account_code,
                "desc": (ln.description or '').strip(),
                "total": round(float(res.get('est_total') or 0), 2)})

    cs = CompanySettings.query.get(1) or CompanySettings()
    company_addr = [getattr(cs, 'address_line1', None), getattr(cs, 'address_line2', None),
                    ', '.join([x for x in [getattr(cs, 'city', None), getattr(cs, 'state', None),
                                           getattr(cs, 'zip_code', None)] if x])]
    snap = {
        "project_name": project.name,
        "version_label": _estimate_version_label(budget),
        "date": date.today().isoformat(),
        "prepared_by": getattr(budget, 'prepared_by', None),
        "prepared_by_title": getattr(budget, 'prepared_by_title', None),
        "prepared_by_email": getattr(budget, 'prepared_by_email', None),
        "prepared_by_phone": getattr(budget, 'prepared_by_phone', None),
        "client_name": getattr(budget, 'client_name', None),
        "company": {
            "name": getattr(cs, 'company_name', None),
            "address": [a for a in company_addr if a],
            "phone": getattr(cs, 'phone', None),
            "email": getattr(cs, 'email', None),
        },
        "detail_mode": bool(detail_mode),
        "grand_total": round(grand, 2),
        "discount_total": discount_total,
        "sections": sections,
    }
    return snap, round(grand, 2)


@app.route("/projects/<int:pid>/budget/<int:bid>/estimate/share", methods=["POST"])
@login_required
def estimate_share_create(pid, bid):
    """Create a client-facing estimate share for this budget. Freezes a
    snapshot, returns a public link, and optionally emails the client.
    (User 2026-06-03.)"""
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access or access.role not in ('owner', 'collaborator', 'editor'):
            return jsonify({"error": "Forbidden"}), 403
    project = ProjectSheet.query.get_or_404(pid)
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    body = request.get_json(silent=True) or {}
    detail_mode = bool(body.get('detail_mode'))

    # ── Resolve recipients ────────────────────────────────────────────────
    # New shape: recipients=[{name,email}, …]. Legacy shape: single
    # client_name/client_email (still honored when recipients absent).
    raw_recipients = body.get('recipients')
    recipients = []
    seen_emails = set()
    if isinstance(raw_recipients, list) and raw_recipients:
        for r in raw_recipients:
            if not isinstance(r, dict):
                continue
            em = (r.get('email') or '').strip()[:200]
            nm = (r.get('name') or '').strip()[:200] or None
            key = em.lower()
            if not em or key in seen_emails:
                continue
            seen_emails.add(key)
            # cc: copied for reference — gets a VIEW-ONLY link (role='cc'),
            # cannot approve or request changes. (Owner 2026-07-22.)
            recipients.append({"name": nm, "email": em,
                               "cc": bool(r.get('cc'))})
    else:
        # Legacy single-recipient path.
        lc_name = (body.get('client_name') or '').strip()[:200] or None
        lc_email = (body.get('client_email') or '').strip()[:200] or None
        if lc_email:
            recipients.append({"name": lc_name, "email": lc_email})
            seen_emails.add(lc_email.lower())
        elif lc_name:
            # Name only, no email — still record a share (link-only send).
            recipients.append({"name": lc_name, "email": None})

    if not recipients:
        # No recipients at all → create a single unaddressed share (copy-link).
        recipients.append({"name": None, "email": None})

    # send_email gate: legacy 'send_email' flag OR presence of the new
    # email_body/email_subject fields. If any recipient has an email and mail
    # is configured, we attempt to send.
    do_email = bool(body.get('send_email', True))
    send_as_me = bool(body.get('send_as_me'))
    email_subject_in = (body.get('email_subject') or '').strip()
    email_body_in = (body.get('email_body') or '')

    try:
        snap, grand = _build_estimate_snapshot(project, budget, detail_mode)
    except Exception as e:
        logging.exception("estimate snapshot failed")
        return jsonify({"error": "Could not build estimate snapshot", "detail": type(e).__name__}), 500

    import json as _json
    from datetime import timedelta as _td
    snapshot_str = _json.dumps(snap)
    version_label = snap.get("version_label")

    # "Send as me" — display name + Reply-To of the sending user (envelope
    # From address stays the configured sender for deliverability).
    sender_name = None
    reply_to = None
    if send_as_me:
        sender_name = (current_user.name or current_user.email)
        reply_to = current_user.email
    # Signature line: the sender's name when sending as me, else company/prepared-by.
    signature = (sender_name if send_as_me else None) or \
                (snap.get('company', {}) or {}).get('name') or (budget.prepared_by or '')

    mail_configured = bool(app.config.get('MAIL_USERNAME'))

    def _default_body(name_val, link_val, is_cc=False):
        who = name_val or "there"
        if is_cc:
            # CC copy: reference wording, no approve language — their link is
            # view-only anyway.
            return (f"Hi {who},\n\n"
                    f"You're copied on the estimate for {project.name} "
                    f"({version_label}) for your reference. You can view it "
                    f"here:\n\n"
                    f"{link_val}\n\n"
                    f"Estimated total: ${grand:,.2f}\n\n"
                    f"Thank you,\n"
                    f"{signature}")
        return (f"Hi {who},\n\n"
                f"Please review the estimate for {project.name} "
                f"({version_label}). You can view and approve it here:\n\n"
                f"{link_val}\n\n"
                f"Estimated total: ${grand:,.2f}\n\n"
                f"Thank you,\n"
                f"{signature}")

    def _render_body(name_val, link_val, is_cc=False):
        """Substitute placeholders in the user-authored body; ensure link present."""
        if not email_body_in.strip():
            return _default_body(name_val, link_val, is_cc)
        txt = (email_body_in
               .replace('{link}', link_val)
               .replace('{total}', f"${grand:,.2f}")
               .replace('{version}', version_label or '')
               .replace('{name}', name_val or 'there'))
        if link_val not in txt:
            txt = txt.rstrip() + "\n\n" + link_val
        return txt

    subj_default = f"{project.name} — Estimate for your review"

    def _render_subject(name_val, link_val):
        if not email_subject_in:
            return subj_default
        return (email_subject_in
                .replace('{link}', link_val)
                .replace('{total}', f"${grand:,.2f}")
                .replace('{version}', version_label or '')
                .replace('{name}', name_val or 'there'))

    results = []
    now = datetime.utcnow()
    expires = now + _td(days=90)
    for rec in recipients:
        token = secrets.token_urlsafe(32)
        _is_cc = bool(rec.get('cc'))
        share = EstimateShare(
            project_id=pid, budget_id=bid, token=token,
            client_name=rec['name'], client_email=rec['email'],
            detail_mode=detail_mode, version_label=version_label,
            snapshot_json=snapshot_str, grand_total=grand,
            status='sent', created_by_user_id=current_user.id,
            sent_at=now, expires_at=expires,
            role=('cc' if _is_cc else 'approver'))
        db.session.add(share)
        db.session.flush()  # assign share.id + keep token unique per row

        link = url_for('estimate_portal', token=token, _external=True)
        emailed = False
        email_error = None
        if rec['email'] and do_email:
            if not mail_configured:
                email_error = ("Email isn't configured on the server "
                               "(MAIL_USERNAME unset) — use the copyable link instead.")
            else:
                subj = _render_subject(rec['name'], link)
                bodytxt = _render_body(rec['name'], link, _is_cc)
                emailed = _send_email(rec['email'], subj, bodytxt,
                                      reply_to=reply_to, sender_name=sender_name)
                if emailed:
                    share.emailed = True
                else:
                    email_error = "Email send failed — use the copyable link instead."
        results.append({
            "share_id": share.id, "token": token, "link": link,
            "email": rec['email'], "name": rec['name'], "cc": _is_cc,
            "emailed": emailed, "email_error": email_error,
        })

        # Fail-open contact upsert (dedupe case-insensitively per project).
        if rec['email']:
            try:
                _upsert_client_contact(pid, rec['email'], rec['name'],
                                       source='estimate_send')
            except Exception:
                logging.warning("client-contact upsert failed for %s", rec['email'],
                                exc_info=True)

    db.session.commit()

    # Notify the project's Super/Admin audience once, listing all recipients.
    try:
        _budget_link = url_for('budget_view', pid=pid, bid=bid, _external=True)
        _who = current_user.name or current_user.email
        _recip_lines = []
        for r in results:
            if not r['email'] and not r['name']:
                continue
            label = ((r['name'] or '—') + (f" <{r['email']}>" if r['email'] else "")
                     + (" (cc — view only)" if r.get('cc') else ""))
            _state = ('emailed' if r['emailed']
                      else ('link only' if not r['email'] else 'link shared manually'))
            _recip_lines.append(f"  • {label} — {_state}")
        _recip_block = "\n".join(_recip_lines) or "  • (link only, no recipients)"
        _notify_project_event(
            pid,
            f"Estimate sent — {project.name} ({version_label})",
            (f"{_who} sent an estimate to the client for {project.name}.\n\n"
             f"Version: {version_label}\n"
             f"Recipients:\n{_recip_block}\n"
             f"Estimated total: ${grand:,.2f}\n\n"
             f"Open the budget: {_budget_link}"))
    except Exception:
        logging.warning("estimate-sent notify failed", exc_info=True)

    first = results[0]
    return jsonify({
        "ok": True,
        "shares": results,
        "version_label": version_label,
        "grand_total": grand,
        # Back-compat: top-level fields mirror the FIRST share so existing JS
        # that reads link/token/emailed/email_error keeps working.
        "share_id": first["share_id"], "token": first["token"],
        "link": first["link"], "emailed": first["emailed"],
        "email_error": first["email_error"],
    })


def _upsert_client_contact(pid, email, name=None, phone=None, company=None, source='manual'):
    """Idempotent client upsert on ProjectClient (the merged Clients list),
    deduped case-insensitively by (project_id, email). On an existing row we
    fill in a blank name/phone/company but never clobber existing data and
    NEVER touch its call-sheet flags. A brand-new estimate recipient is created
    with show_on_callsheet/receives_callsheet=False (it is not a call-sheet
    client until a user ticks it on) and placed at the end of the sort order.
    Kept under the historical name to minimise blast radius. Returns the
    ProjectClient row (committed by the caller)."""
    email = (email or '').strip()
    if not email:
        return None
    existing = (ProjectClient.query
                .filter(ProjectClient.project_id == pid,
                        db.func.lower(ProjectClient.email) == email.lower())
                .first())
    if existing:
        if name and not (existing.name or '').strip():
            existing.name = name[:200]
        if phone and not (existing.phone or '').strip():
            existing.phone = _normalize_phone(phone) or phone[:50]
        if company and not (existing.company or '').strip():
            existing.company = company[:200]
        # Provenance upgrade (mirrors the one-time migration): a manual client
        # who receives an estimate becomes source='estimate_send' so the
        # re-send checkboxes pre-check them next time. Never downgrades.
        if source == 'estimate_send' and (existing.source or 'manual') == 'manual':
            existing.source = 'estimate_send'
        return existing
    _max_sort = (db.session.query(db.func.max(ProjectClient.sort_order))
                 .filter(ProjectClient.project_id == pid).scalar())
    row = ProjectClient(
        project_id=pid, email=email[:200],
        name=(name or email)[:200],
        phone=(_normalize_phone(phone) or (phone[:50] if phone else None)),
        company=(company or None) and company[:200],
        source=source,
        show_on_callsheet=False, receives_callsheet=False,
        sort_order=int(_max_sort or 0) + 1,
        created_at=datetime.utcnow())
    db.session.add(row)
    return row


def _can_access_project(pid, edit=False):
    """True if current_user may view (edit=False) or mutate (edit=True) project
    pid. Admins/super always pass; others need a ProjectAccess row (and an
    editor-ish role for edit). Returns bool."""
    if current_user.role in ('super_admin', 'admin'):
        return True
    access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
    if not access:
        return False
    if edit:
        return access.role in ('owner', 'collaborator', 'editor')
    return True


@app.route("/projects/<int:pid>/estimate/recipients", methods=["GET"])
@login_required
def estimate_recipients(pid):
    """Feeds the estimate-send popup's recipient picker: the project's client
    contacts + distinct past EstimateShare recipients not already contacts.
    Side effect (lazy backfill): any past-share email that isn't yet a contact
    is upserted as source='estimate_send' so the People tab self-populates the
    first time this loads. (User 2026-07-08.)"""
    if not _can_access_project(pid):
        return jsonify({"error": "Forbidden"}), 403

    # Lazy backfill from historical sends → Clients list (ProjectClient).
    try:
        past_shares = (EstimateShare.query
                       .filter(EstimateShare.project_id == pid,
                               EstimateShare.client_email.isnot(None))
                       .order_by(EstimateShare.created_at.asc()).all())
        existing_emails = {
            (c.email or '').lower()
            for c in ProjectClient.query.filter_by(project_id=pid).all()
            if c.email
        }
        changed = False
        for s in past_shares:
            em = (s.client_email or '').strip()
            if em and em.lower() not in existing_emails:
                _upsert_client_contact(pid, em, s.client_name, source='estimate_send')
                existing_emails.add(em.lower())
                changed = True
        if changed:
            db.session.commit()
    except Exception:
        db.session.rollback()
        logging.warning("estimate recipients backfill failed", exc_info=True)

    # Only rows with an email are usable estimate recipients. Order estimate
    # senders + manual clients by creation, then id (created_at may be null on
    # legacy call-sheet clients).
    contacts = (ProjectClient.query
                .filter(ProjectClient.project_id == pid,
                        ProjectClient.email.isnot(None),
                        ProjectClient.email != '')
                .order_by(ProjectClient.created_at.asc(),
                          ProjectClient.id.asc())
                .all())
    contact_emails = {(c.email or '').lower() for c in contacts}
    contacts_out = [{
        "id": c.id, "name": c.name, "email": c.email,
        "phone": c.phone, "company": c.company, "source": c.source or 'manual',
    } for c in contacts]

    # Distinct past recipients not already contacts (should be empty after the
    # backfill above, but kept for robustness / mail-unconfigured cases).
    past_map = {}
    try:
        for s in (EstimateShare.query
                  .filter(EstimateShare.project_id == pid,
                          EstimateShare.client_email.isnot(None))
                  .order_by(EstimateShare.created_at.desc()).all()):
            em = (s.client_email or '').strip()
            key = em.lower()
            if not em or key in contact_emails or key in past_map:
                continue
            past_map[key] = {
                "name": s.client_name, "email": em,
                "last_sent": (s.created_at.isoformat() + 'Z') if s.created_at else None,
            }
    except Exception:
        logging.warning("past recipient lookup failed", exc_info=True)

    return jsonify({"contacts": contacts_out, "past": list(past_map.values())})


# NOTE (2026-07-13 Clients consolidation): the former
# /projects/<pid>/client-contacts create/update/delete endpoints were removed.
# Estimate recipients and call-sheet clients are now one list on ProjectClient;
# the '🤝 Clients' section's add/edit/delete go through the ProjectClient CRUD
# (project_client_save / project_client_delete), which now enforces the same
# case-insensitive email 409. Manual adds land as source='manual'; estimate
# sends auto-add via _upsert_client_contact (source='estimate_send').


# ── Call-sheet logos ────────────────────────────────────────────────────────────
# A per-project logo library (show / brand / client marks). Bytes are stored in
# Postgres (ProjectLogo.data), NOT Dropbox, so the call sheet can embed them as
# data: URIs in the PDF and serve them with immutable cache headers on the web.
# Per-call-sheet placement ({logo_id,x,w}) lives in CallSheetData.data_json
# ['logos']; the project fallback arrangement in ProjectSheet.logos_default.

_LOGO_MAX_BYTES   = 2 * 1024 * 1024   # 2 MB cap
_LOGO_CONTENT_TYPES = {
    'image/png':     'png',
    'image/jpeg':    'jpeg',
    'image/jpg':     'jpeg',
    'image/svg+xml': 'svg',
    'image/svg':     'svg',
}


def _logo_url(pid, lid):
    """The web (network-fetch) URL for a logo's bytes. NOT used in pdf_mode —
    weasyprint gets data: URIs instead (see _resolve_callsheet_logos)."""
    return url_for('project_logo_raw', pid=pid, lid=lid)


def _logo_placement_shape(p):
    """Normalize ONE stored placement dict into the FLOW shape
    {logo_id:int, order:float, h:float}.

    ONE ordered list, auto-spaced + auto-wrapped on render — no left/center/right
    slots anymore. Three input shapes are accepted (newest → oldest):

      • v2 (flow):  {logo_id, order, h}                         → used as-is.
      • v1 (slots): {logo_id, slot, order, h}                   → flatten: slots
        rank left(0) < center(1) < right(2); the returned `order` is a composite
        (slot_rank, old_order) encoded as slot_rank*1e6 + old_order so the caller's
        stable sort reproduces the old left→center→right, in-slot-order sequence.
      • v0 (freeform): {logo_id, x, w}  (x/w = percent)         → order = x
        (left-to-right position across the band), h = w (clamped 40-100).

    `order` is a SORT KEY only — the caller renumbers 0..n after sorting. Returns
    None if logo_id can't be parsed. (User 2026-07-09; flow rewrite 2026-07-09.)"""
    if not isinstance(p, dict):
        return None
    try:
        lid = int(p.get('logo_id'))
    except Exception:
        return None
    try:
        h = max(40.0, min(100.0, float(p.get('h', p.get('w', 70)))))
    except Exception:
        h = 70.0
    if 'slot' in p:
        # v1 slotted → flatten to a single flow order (slot group, then in-slot).
        slot = str(p.get('slot', 'left')).lower()
        _rank = {'left': 0, 'center': 1, 'right': 2}.get(slot, 0)
        try:
            in_slot = float(p.get('order', 0))
        except Exception:
            in_slot = 0.0
        order = _rank * 1_000_000.0 + in_slot
    elif 'order' in p or 'h' in p:
        # v2 flow shape (may be partial).
        try:
            order = float(p.get('order', 0))
        except Exception:
            order = 0.0
    else:
        # v0 freeform {x, w}: x = left-to-right position → flow order.
        try:
            order = max(0.0, min(100.0, float(p.get('x', 0))))
        except Exception:
            order = 0.0
    return {'logo_id': lid, 'order': order, 'h': h}


def _resolve_callsheet_logos(cs_data, project, embed=False):
    """Resolve the placed-logo strip for one call sheet into a render-ready list.

    Placement source of truth: cs_data['logos'] (a list; FLOW shape {logo_id,order,
    h}, with v1 {logo_id,slot,order,h} and v0 {logo_id,x,w} mapped on read — see
    _logo_placement_shape). When the sheet has NO 'logos' key at all, fall back to
    the project default arrangement (ProjectSheet.logos_default). An explicit empty
    list means "no logos" and does NOT fall back.

    Each returned item: {logo_id, order, h, name, src}. h is a clamped percent
    (40-100) mapped to a rem height by CSS; the strip auto-spaces the logos as ONE
    centered, flex-wrapping row (10+ logos flow onto extra rows — verified in
    weasyprint 68.1, so the PDF uses the same flex-wrap, no server-side chunking).
    src is EITHER a network URL (embed=False, web/screen) or a base64 data: URI
    (embed=True, pdf_mode — no network fetch back to the app). Missing/deleted ids
    are skipped. The list is sorted by `order` then renumbered 0..n. Returns []."""
    placements = None
    if isinstance(cs_data, dict) and 'logos' in cs_data:
        placements = cs_data.get('logos')
    elif project is not None and getattr(project, 'logos_default', None):
        try:
            placements = json.loads(project.logos_default)
        except Exception:
            placements = None
    if not isinstance(placements, list) or not placements:
        return []

    shaped = []
    for p in placements:
        s = _logo_placement_shape(p)
        if s is not None:
            shaped.append(s)
    if not shaped:
        return []

    ids = [s['logo_id'] for s in shaped]
    logos_by_id = {
        lg.id: lg for lg in ProjectLogo.query.filter(
            ProjectLogo.project_id == project.id,
            ProjectLogo.id.in_(ids)).all()
    } if project is not None else {}

    # Single flow order: preserve incoming order, then renumber 0..n.
    shaped.sort(key=lambda s: s['order'])
    import base64 as _b64
    total_embed = 0
    out = []
    _n = 0
    for s in shaped:
        lg = logos_by_id.get(s['logo_id'])
        if lg is None:
            continue  # deleted / not this project
        order = _n
        _n += 1
        if embed:
            total_embed += len(lg.data or b'')
            b64 = _b64.b64encode(lg.data or b'').decode('ascii')
            src = f"data:{lg.content_type};base64,{b64}"
        else:
            src = _logo_url(project.id, lg.id)
        out.append({
            'logo_id': lg.id, 'order': order, 'h': s['h'],
            'name': lg.name or '', 'src': src,
        })
    if embed and total_embed > 5 * 1024 * 1024:
        logging.warning(f"[CALLSHEET PDF] embedded logo payload large "
                        f"({total_embed} bytes) for project {getattr(project,'id',None)}")
    return out


@app.route("/projects/<int:pid>/logos", methods=["GET"])
@login_required
def project_logos_list(pid):
    """List the project's logo library (metadata + web URLs). No bytes."""
    if not _can_access_project(pid):
        return jsonify({"error": "Forbidden"}), 403
    logos = (ProjectLogo.query.filter_by(project_id=pid)
             .order_by(ProjectLogo.created_at.asc(), ProjectLogo.id.asc()).all())
    return jsonify({"logos": [{
        "id": lg.id, "name": lg.name or "",
        "content_type": lg.content_type,
        "width": lg.width, "height": lg.height,
        "url": _logo_url(pid, lg.id),
    } for lg in logos]})


@app.route("/projects/<int:pid>/logos", methods=["POST"])
@login_required
def project_logo_create(pid):
    """Upload a logo (multipart 'file' + optional 'name'). png/jpeg/svg, ≤2MB.
    Intrinsic width/height parsed via Pillow for raster (best-effort). Returns
    {id, name, url}."""
    if not _can_access_project(pid, edit=True):
        return jsonify({"error": "Forbidden"}), 403
    ProjectSheet.query.get_or_404(pid)

    f = request.files.get('file')
    if not f or not f.filename:
        return jsonify({"error": "No file provided"}), 400
    _upl_err = _validate_upload_file(f, 'image') if f else None
    if _upl_err:
        return jsonify({"error": _upl_err}), 400
    raw = f.read()
    if not raw:
        return jsonify({"error": "Empty file"}), 400
    if len(raw) > _LOGO_MAX_BYTES:
        return jsonify({"error": "File too large (max 2 MB)"}), 400

    ct = (f.mimetype or '').split(';')[0].strip().lower()
    kind = _LOGO_CONTENT_TYPES.get(ct)
    if not kind:
        # Fall back to extension sniff for browsers that send octet-stream.
        ext = (f.filename.rsplit('.', 1)[-1] if '.' in f.filename else '').lower()
        kind = {'png': 'png', 'jpg': 'jpeg', 'jpeg': 'jpeg', 'svg': 'svg'}.get(ext)
        if kind == 'png':   ct = 'image/png'
        elif kind == 'jpeg': ct = 'image/jpeg'
        elif kind == 'svg':  ct = 'image/svg+xml'
    if not kind:
        return jsonify({"error": "Unsupported type — use PNG, JPEG, or SVG"}), 400
    if kind == 'svg':
        ct = 'image/svg+xml'  # normalize (svg stored as-is otherwise)

    width = height = None
    if kind in ('png', 'jpeg'):
        try:
            from PIL import Image
            with Image.open(io.BytesIO(raw)) as im:
                width, height = int(im.width), int(im.height)
        except Exception:
            width = height = None  # Pillow missing / unparseable → null

    name = (request.form.get('name') or '').strip() or (f.filename or '').strip()
    row = ProjectLogo(
        project_id=pid, name=(name[:120] if name else None),
        content_type=ct, data=raw, width=width, height=height,
        created_at=datetime.utcnow())
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "id": row.id, "name": row.name or "",
                    "width": row.width, "height": row.height,
                    "url": _logo_url(pid, row.id)})


@app.route("/projects/<int:pid>/logos/<int:lid>/raw", methods=["GET"])
@login_required
def project_logo_raw(pid, lid):
    """Serve a logo's bytes with its content type + immutable long cache (the
    bytes for a given id never change — delete + re-upload mints a new id)."""
    if not _can_access_project(pid):
        return abort(403)
    lg = ProjectLogo.query.filter_by(id=lid, project_id=pid).first_or_404()
    from flask import make_response
    resp = make_response(lg.data or b'')
    # M6: logos serve inline only as raster images — anything else (svg/html/
    # unknown) goes out as a generic binary so it can't execute in our origin.
    _lg_ct = lg.content_type or "application/octet-stream"
    if not _lg_ct.startswith("image/") or _lg_ct == "image/svg+xml":
        _lg_ct = "application/octet-stream"
    resp.headers["Content-Type"]  = _lg_ct
    resp.headers["Cache-Control"] = "private, max-age=31536000, immutable"
    return resp


