@app.route("/admin/backup/transactions.json", methods=["GET"])
@login_required
@super_admin_required
def admin_backup_transactions():
    """READ-ONLY archive: every transaction's coding-relevant fields as JSON.
    Pulled before/after risky fixes so coding can be diffed and restored
    independent of Render PITR. (Code review remediation, 2026-06-04.)"""
    rows = (Transaction.query
            .with_entities(Transaction.id, Transaction.project_id,
                           Transaction.source, Transaction.vendor,
                           Transaction.amount, Transaction.txn_date,
                           Transaction.is_expense, Transaction.account_code,
                           Transaction.account_code_name,
                           Transaction.budget_line_id, Transaction.match_status,
                           Transaction.doc_upload_id,
                           Transaction.not_project_expense,
                           Transaction.qbo_txn_id, Transaction.qbo_txn_type)
            .order_by(Transaction.id).all())
    out = [{"id": r.id, "project_id": r.project_id, "source": r.source,
            "vendor": r.vendor,
            "amount": float(r.amount) if r.amount is not None else None,
            "txn_date": r.txn_date, "is_expense": bool(r.is_expense),
            "account_code": r.account_code,
            "account_code_name": r.account_code_name,
            "budget_line_id": r.budget_line_id, "match_status": r.match_status,
            "doc_upload_id": r.doc_upload_id,
            "not_project_expense": bool(r.not_project_expense),
            "qbo_txn_id": r.qbo_txn_id, "qbo_txn_type": r.qbo_txn_type}
           for r in rows]
    return jsonify({"generated_at": datetime.utcnow().isoformat() + 'Z',
                    "count": len(out), "transactions": out})


@app.route("/admin/coa-audit", methods=["GET", "POST"])
@login_required
@super_admin_required
def admin_coa_audit():
    """Find + fix chart-of-account drift left by the 2026-04 renumber (which
    rewrote budget_line codes but NOT the denormalized account_code /
    account_code_name copied onto each Transaction). GET = read-only report
    (open it in the browser). POST ?fix=txn_resync&apply=1 = re-sync every
    coded transaction's account_code + name from its linked budget line (the
    migrated source of truth). Optional ?project=<pid> to scope. Snapshot via
    /admin/backup/transactions.json first if you want a restore point.
    (User 2026-06-16 — 'no leftover ghosts from earlier codes'.)"""
    from budget_calc import COA_LEGACY_MAPPING
    _current_starts = {s for s, _ in FP_COA_SECTIONS}
    pid = request.args.get('project', type=int)

    def _line_name(ln):
        return (getattr(ln, 'account_name', None)
                or getattr(ln, 'description', None) or '')

    # ── Transactions whose denormalized code/name disagree with their line.
    tq = Transaction.query.filter(Transaction.budget_line_id.isnot(None))
    if pid:
        tq = tq.filter(Transaction.project_id == pid)
    txns = tq.all()
    line_ids = {t.budget_line_id for t in txns if t.budget_line_id}
    lines = {l.id: l for l in BudgetLine.query.filter(BudgetLine.id.in_(line_ids)).all()} if line_ids else {}
    txn_drift, txn_samples = 0, []
    to_fix = []
    for t in txns:
        ln = lines.get(t.budget_line_id)
        if not ln:
            continue
        want_code = ln.account_code
        want_name = _line_name(ln)
        if t.account_code != want_code or (t.account_code_name or '') != (want_name or ''):
            txn_drift += 1
            to_fix.append((t, want_code, want_name))
            if len(txn_samples) < 25:
                txn_samples.append({
                    "txn_id": t.id, "project_id": t.project_id, "vendor": t.vendor,
                    "txn_code": t.account_code, "txn_name": t.account_code_name,
                    "line_code": want_code, "line_name": want_name,
                    "txn_section": _section_name(_section_for_code(t.account_code)) if t.account_code is not None else None,
                    "line_section": _section_name(_section_for_code(want_code)) if want_code is not None else None,
                })

    # ── Budget lines whose stored name doesn't match the section its code
    # falls in (un-migrated sub-codes / mis-coded lines — human review).
    lq = BudgetLine.query
    if pid:
        from sqlalchemy import exists as _exists
        lq = lq.join(Budget, Budget.id == BudgetLine.budget_id).filter(Budget.project_id == pid)
    _valid_names = {n.strip().lower(): s for s, n in FP_COA_SECTIONS}
    line_drift, line_samples = 0, []
    for ln in lq.all():
        if ln.account_code is None:
            continue
        nm = (_line_name(ln) or '').strip().lower()
        sec_name = _section_name(_section_for_code(ln.account_code))
        if nm in _valid_names and nm != (sec_name or '').strip().lower():
            line_drift += 1
            if len(line_samples) < 25:
                line_samples.append({
                    "line_id": ln.id, "budget_id": ln.budget_id,
                    "code": ln.account_code, "name": _line_name(ln),
                    "code_section": sec_name})

    # ── Section-only transactions (no line) carrying a legacy-only code.
    sq = Transaction.query.filter(Transaction.budget_line_id.is_(None),
                                  Transaction.account_code.isnot(None))
    if pid:
        sq = sq.filter(Transaction.project_id == pid)
    legacy_only = 0
    for t in sq.all():
        if t.account_code in COA_LEGACY_MAPPING and t.account_code not in _current_starts:
            legacy_only += 1

    report = {
        "scope": ("project " + str(pid)) if pid else "ALL projects",
        "txn_code_name_drift": txn_drift,
        "txn_samples": txn_samples,
        "budget_line_section_mismatch": line_drift,
        "line_samples": line_samples,
        "section_only_legacy_code_txns": legacy_only,
        "note": ("GET is read-only. To repair the transaction drift, POST "
                 "this URL with ?fix=txn_resync&apply=1 — it copies each "
                 "transaction's account_code + name from its linked budget "
                 "line. Budget-line mismatches are listed for manual review "
                 "(the right fix depends on whether the code or the name is "
                 "correct)."),
    }

    if request.method == "POST" and request.args.get('fix') == 'txn_resync':
        if request.args.get('apply') != '1':
            report["dry_run"] = True
            report["would_fix"] = txn_drift
            return jsonify(report)
        fixed = 0
        for t, want_code, want_name in to_fix:
            t.account_code = want_code
            t.account_code_name = want_name or None
            fixed += 1
        db.session.commit()
        try:
            _log_activity(action='update', entity_type='coa_audit', entity_id=pid or 0,
                          entity_label='COA txn re-sync', project_id=pid,
                          note=f'Re-synced {fixed} transaction account codes from their budget lines')
        except Exception:
            pass
        report["applied"] = True
        report["txns_fixed"] = fixed
        return jsonify(report)

    return jsonify(report)


@app.route("/e/<token>", methods=["GET"])
def estimate_portal(token):
    """PUBLIC (no login): client-facing estimate review/approval page."""
    s = EstimateShare.query.filter_by(token=token).first()
    if not s:
        return render_template("estimate_portal.html", not_found=True), 404
    revoked = (s.status == 'revoked')
    expired = bool(s.expires_at and datetime.utcnow() > s.expires_at)
    if not revoked and not expired:
        s.view_count = (s.view_count or 0) + 1
        now = datetime.utcnow()
        if not s.first_viewed_at:
            s.first_viewed_at = now
        s.last_viewed_at = now
        if s.status == 'sent':
            s.status = 'viewed'
        db.session.commit()
    import json as _json
    snap = {}
    try:
        snap = _json.loads(s.snapshot_json) if s.snapshot_json else {}
    except Exception:
        snap = {}
    # Date + TIME the estimate was sent, in the budget's timezone — so a client
    # who gets several in one day can tell them apart. (User 2026-06-04.)
    sent_display = None
    if s.sent_at:
        try:
            from zoneinfo import ZoneInfo
            tzname = getattr(s.budget, 'timezone', None) or 'America/Los_Angeles'
            _dt_local = s.sent_at.replace(tzinfo=ZoneInfo('UTC')).astimezone(ZoneInfo(tzname))
            sent_display = _dt_local.strftime('%b %-d, %Y · %-I:%M %p %Z')
        except Exception:
            sent_display = s.sent_at.strftime('%b %d, %Y · %H:%M UTC')
    return render_template("estimate_portal.html",
                           share=s, snap=snap, revoked=revoked, expired=expired,
                           sent_display=sent_display, not_found=False)


@app.route("/e/<token>/respond", methods=["POST"])
def estimate_portal_respond(token):
    """PUBLIC: client approves or declines. Records typed-name e-signature."""
    s = EstimateShare.query.filter_by(token=token).first()
    if not s:
        return jsonify({"error": "Not found"}), 404
    if s.status == 'revoked':
        return jsonify({"error": "This estimate link has been revoked."}), 410
    if s.expires_at and datetime.utcnow() > s.expires_at:
        return jsonify({"error": "This estimate link has expired."}), 410
    if s.status in ('approved', 'declined'):
        return jsonify({"error": f"Already {s.status}.", "status": s.status}), 409
    # CC links are view-only — approval/changes belong to the primary
    # recipient(s). (Owner 2026-07-22: "cc should not be able to approve
    # or comment".) Legacy rows have role NULL = approver.
    if (getattr(s, 'role', None) or 'approver') == 'cc':
        return jsonify({"error": "This link is a CC copy for reference only — "
                                 "approval is handled by the primary recipient."}), 403
    body = request.get_json(silent=True) or {}
    action = (body.get('action') or '').strip().lower()
    name = (body.get('name') or '').strip()[:200]
    note = (body.get('note') or '').strip()[:2000] or None
    if action not in ('approve', 'decline'):
        return jsonify({"error": "Invalid action"}), 400
    # Both responses are tracked signatures: approvals AND change requests
    # need a typed name so it's always attributable who asked for what.
    # (Owner 2026-07-22: "track who asks revisions and who approves".)
    if not name:
        return jsonify({"error": "Please type your name to approve."
                        if action == 'approve' else
                        "Please type your name so we know who requested changes."}), 400
    s.status = 'approved' if action == 'approve' else 'declined'
    s.approver_name = name or None
    s.approver_note = note
    s.responded_at = datetime.utcnow()
    try:
        s.approver_ip = (request.headers.get('X-Forwarded-For', request.remote_addr) or '')[:64]
    except Exception:
        pass
    db.session.commit()
    # Notify the project's Super/Admin audience (plus the original sender) of the response.
    try:
        proj = ProjectSheet.query.get(s.project_id)
        creator = User.query.get(s.created_by_user_id) if s.created_by_user_id else None
        verb = 'APPROVED' if s.status == 'approved' else 'DECLINED'
        _who = s.approver_name or s.client_name or 'The client'
        _budget_link = url_for('budget_view', pid=s.project_id, bid=s.budget_id, _external=True)
        _notify_project_event(
            s.project_id,
            f"Estimate {verb} — {proj.name if proj else ''} ({s.version_label})",
            (f"{_who} {verb.lower()} the estimate for "
             f"{proj.name if proj else 'this project'} ({s.version_label}).\n\n"
             + (f"Note from client: {note}\n\n" if note else "")
             + f"{'Approved' if s.status == 'approved' else 'Estimate'} total: "
             f"${float(s.grand_total or 0):,.2f}\n\n"
             f"Open the budget: {_budget_link}"),
            extra_emails=([creator.email] if (creator and creator.email) else None))
    except Exception:
        logging.warning("estimate-response notify failed", exc_info=True)
    return jsonify({"ok": True, "status": s.status})


# ── Smart CSV import ──────────────────────────────────────────────────────────
# Fuzzy synonym map: target_field -> list of header strings (lowercased) that should match
_CSV_FIELD_SYNONYMS = {
    'account_code':    ['account code', 'acct code', 'acct', 'coa', 'coa code', 'code', 'category code', 'chart code', 'section code'],
    'account_name':    ['account', 'account name', 'category', 'section', 'department', 'dept', 'coa name'],
    'description':     ['description', 'line item', 'item', 'line', 'detail', 'position', 'role'],
    'is_labor':        ['is labor', 'labor', 'is_labor'],
    'quantity':        ['qty', 'quantity', 'count', '#', 'units', 'people', 'num', 'number'],
    'days':            ['days', 'day', 'weeks', 'week'],
    'rate':            ['rate', 'daily', 'day rate', 'unit rate', 'price', 'amount', 'weekly rate', 'daily rate', '$'],
    'rate_type':       ['rate type', 'period', 'unit', 'rate_type'],
    'fringe_type':     ['fringe', 'fringe type', 'union', 'fringe_type'],
    'agent_pct':       ['agent', 'agent pct', 'agent %', 'commission', 'agent fee', 'agent_pct'],
    'est_ot':          ['ot', 'overtime', 'est ot', 'est_ot'],
    'estimated_total': ['total', 'estimated', 'flat', 'flat total', 'line total', 'budget', 'estimated total', 'subtotal'],
    'note':            ['note', 'notes', 'comment', 'comments', 'remark', 'remarks'],
}

_CSV_TARGET_FIELDS = list(_CSV_FIELD_SYNONYMS.keys())


def _fuzzy_suggest_target(header):
    """Return (best_target, confidence, [alternatives]) for a CSV header."""
    import difflib
    h = (header or '').strip().lower()
    if not h:
        return (None, 0.0, [])
    scores = []
    for target, synonyms in _CSV_FIELD_SYNONYMS.items():
        # Best match across all synonyms for this target
        best = 0.0
        for syn in synonyms:
            r = difflib.SequenceMatcher(None, h, syn).ratio()
            if r > best:
                best = r
        # Exact contains bonus
        if any(syn == h for syn in synonyms):
            best = 1.0
        elif any(syn in h or h in syn for syn in synonyms):
            best = max(best, 0.85)
        scores.append((target, best))
    scores.sort(key=lambda x: x[1], reverse=True)
    best_target, best_score = scores[0]
    if best_score < 0.55:
        return (None, best_score, [t for t, _ in scores[1:3]])
    alternatives = [t for t, s in scores[1:3] if s >= 0.4]
    return (best_target, round(best_score, 2), alternatives)


def _resolve_account_code(code_val, name_val):
    """Return a valid FP_COA section start code from a numeric code or section name.

    Handles multiple code conventions:
    - Raw FP code: 700 → 700 (Talent)
    - Showbiz-style decimal: 7.00 → 700 (x100 multiplier)
    - Short int: 20 → 2000 (x100 multiplier)
    - Section range snap: 712 → 700 (Talent)
    - Fuzzy section name match as last resort
    """
    section_codes = {c for c, _ in FP_COA_SECTIONS}
    sorted_codes = sorted(section_codes)

    if code_val is not None and str(code_val).strip():
        raw = None
        try:
            raw = float(str(code_val).replace(',', '').strip())
        except (ValueError, TypeError):
            pass
        if raw is not None and raw > 0:
            # Try exact match at multiple scales
            for candidate in [int(raw), int(raw * 100), int(raw * 1000)]:
                if candidate in section_codes:
                    return candidate
            # Range snap: find the section that contains this code
            # Use the scale that produces a sensible FP-range value (typically x100 if < 1000)
            candidate = int(raw * 100) if raw < 1000 else int(raw)
            best = None
            for c in sorted_codes:
                if candidate >= c:
                    best = c
                else:
                    break
            if best is not None and candidate - best <= 500:
                return best

    # Fall back to fuzzy-match section name
    if name_val:
        import difflib
        n = str(name_val).strip().lower()
        if n and not n.startswith('total'):
            best_code, best_score = None, 0.0
            for start, sec_name in FP_COA_SECTIONS:
                sl = sec_name.lower()
                r = difflib.SequenceMatcher(None, n, sl).ratio()
                if n in sl or sl in n:
                    r = max(r, 0.85)
                # Word-level overlap bonus
                n_words = set(w for w in n.split() if len(w) > 2)
                s_words = set(w for w in sl.split() if len(w) > 2)
                if n_words and s_words and n_words & s_words:
                    r = max(r, 0.7)
                if r > best_score:
                    best_score = r
                    best_code = start
            if best_score >= 0.55:
                return best_code
    return None


def _dedupe_headers(raw_headers):
    """Normalize CSV header row: strip, fill blanks, dedupe duplicates."""
    seen = {}
    out = []
    for i, h in enumerate(raw_headers):
        hh = (h or '').strip()
        if not hh:
            hh = f"Column {i + 1}"
        if hh in seen:
            seen[hh] += 1
            hh = f"{hh} ({seen[hh]})"
        else:
            seen[hh] = 1
        out.append(hh)
    return out


def _score_header_row(cells):
    """Count how many cells in a row look like recognizable field names."""
    score = 0
    for cell in cells:
        if not cell or not str(cell).strip():
            continue
        _, conf, _ = _fuzzy_suggest_target(str(cell))
        if conf >= 0.6:
            score += 1
    return score


@app.route("/projects/<int:pid>/budget/<int:bid>/import/analyze", methods=["POST"])
@login_required
def import_csv_analyze(pid, bid):
    """Analyze uploaded CSV: auto-detect header row, suggest column mappings,
    preview first 10 data rows."""
    Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    f = request.files.get("file")
    if not f:
        return jsonify({"error": "No file uploaded"}), 400
    _upl_err = _validate_upload_file(f, 'csv') if f else None
    if _upl_err:
        return jsonify({"error": _upl_err}), 400

    try:
        content = f.read().decode("utf-8-sig")
    except UnicodeDecodeError:
        return jsonify({"error": "File must be UTF-8 encoded CSV"}), 400

    reader = csv.reader(io.StringIO(content))
    all_rows = list(reader)
    if not all_rows:
        return jsonify({"error": "Empty CSV"}), 400

    # Client may override auto-detection by passing header_row_index
    requested_header_idx = request.form.get("header_row_index", type=int)

    # Auto-detect header row: scan first 20 rows, pick the one with most field-like cells
    scan_rows = all_rows[: min(20, len(all_rows))]
    scores = [(idx, _score_header_row(row)) for idx, row in enumerate(scan_rows)]
    scores.sort(key=lambda x: x[1], reverse=True)
    best_score = scores[0][1] if scores else 0
    auto_header_idx = scores[0][0] if best_score >= 2 else 0

    header_idx = requested_header_idx if requested_header_idx is not None else auto_header_idx
    if header_idx < 0 or header_idx >= len(all_rows):
        header_idx = 0

    raw_headers = all_rows[header_idx]
    headers = _dedupe_headers(raw_headers)

    # Build fuzzy suggestions per header
    mappings = []
    for h in headers:
        target, confidence, alternatives = _fuzzy_suggest_target(h)
        mappings.append({
            "csv_col": h,
            "target": target,
            "confidence": confidence,
            "alternatives": alternatives,
        })

    # Pre-load existing lines for duplicate detection
    existing_lines = BudgetLine.query.filter_by(budget_id=bid).all()
    existing_index = {}
    for ln in existing_lines:
        key = (int(ln.account_code or 0), (ln.description or '').strip().lower())
        existing_index[key] = ln.id

    # Preview: first 10 data rows after the header
    data_rows = all_rows[header_idx + 1:]
    mapping_dict = {m["csv_col"]: m["target"] for m in mappings if m["target"]}
    preview = []
    for idx, row in enumerate(data_rows[:10]):
        row_dict = dict(zip(headers, row))
        parsed = {}
        for csv_col, target in mapping_dict.items():
            parsed[target] = row_dict.get(csv_col, '')
        resolved_code = _resolve_account_code(
            parsed.get('account_code'),
            parsed.get('account_name') or parsed.get('description'),
        )
        desc = (parsed.get('description') or '').strip().lower()
        dup_id = existing_index.get((resolved_code or 0, desc)) if resolved_code else None
        # Mark row as likely junk (total/empty/section) for UI hinting
        is_junk = _is_import_junk_row(parsed)
        preview.append({
            "row_index": idx,
            "csv_row": row_dict,
            "resolved_code": resolved_code,
            "duplicate_of_line_id": dup_id,
            "is_junk": is_junk,
        })

    # Return the first 20 raw rows for the header picker UI
    raw_preview = [list(r) for r in all_rows[: min(20, len(all_rows))]]

    return jsonify({
        "headers": headers,
        "mappings": mappings,
        "preview_rows": preview,
        "target_fields": [
            {"value": "", "label": "— skip this column —"},
            *[{"value": f, "label": f} for f in _CSV_TARGET_FIELDS],
        ],
        "row_count": len(data_rows),
        "coa_sections": [{"code": c, "name": n} for c, n in FP_COA_SECTIONS],
        "raw_preview": raw_preview,
        "header_row_index": header_idx,
        "auto_detected_header_index": auto_header_idx,
    })


def _is_import_junk_row(parsed):
    """Return True if a parsed row should be auto-skipped as junk
    (empty, total row, or section-header row)."""
    desc = (parsed.get('description') or '').strip()
    desc_low = desc.lower()
    code_raw = str(parsed.get('account_code') or '').strip()
    rate_raw = str(parsed.get('rate') or '').strip()
    total_raw = str(parsed.get('estimated_total') or '').strip()

    # Empty: no description and no rate and no total
    if not desc and not rate_raw and not total_raw:
        return True
    # Total rows (by convention: code "99" or "99.00", or description starts with "total")
    if code_raw in ('99', '99.0', '99.00'):
        return True
    if desc_low.startswith('total') or desc_low.startswith('subtotal'):
        return True
    # #REF!, #N/A, or similar error cells as description
    if desc_low.startswith('#'):
        return True
    return False


@app.route("/projects/<int:pid>/budget/<int:bid>/import/apply", methods=["POST"])
@login_required
def import_csv_apply(pid, bid):
    """Apply confirmed column mapping + per-row actions from a CSV upload."""
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    f = request.files.get("file")
    _upl_err = _validate_upload_file(f, 'csv') if f else None
    if _upl_err:
        return jsonify({"error": _upl_err}), 400
    mapping_json = request.form.get("mapping", "{}")
    actions_json = request.form.get("row_actions", "[]")
    header_row_index = request.form.get("header_row_index", 0, type=int)
    auto_skip_junk = request.form.get("auto_skip_junk", "1") == "1"

    if not f:
        return jsonify({"error": "No file uploaded"}), 400

    try:
        mapping = json.loads(mapping_json)
        row_actions = json.loads(actions_json) if actions_json else []
    except (ValueError, TypeError):
        return jsonify({"error": "Invalid mapping or actions JSON"}), 400

    try:
        content = f.read().decode("utf-8-sig")
    except UnicodeDecodeError:
        return jsonify({"error": "File must be UTF-8 encoded CSV"}), 400

    reader = csv.reader(io.StringIO(content))
    all_rows = list(reader)
    if header_row_index < 0 or header_row_index >= len(all_rows):
        return jsonify({"error": "Header row index out of range"}), 400

    headers = _dedupe_headers(all_rows[header_row_index])
    data_rows = [dict(zip(headers, row)) for row in all_rows[header_row_index + 1:]]

    # Helper coercions
    def _f(v, default=0.0):
        try:
            if v in (None, ''):
                return default
            s = str(v).replace(',', '').replace('$', '').replace('%', '').strip()
            # Handle negatives in parentheses: (500) → -500
            if s.startswith('(') and s.endswith(')'):
                s = '-' + s[1:-1]
            return float(s)
        except (ValueError, TypeError):
            return default

    def _b(v):
        return str(v).strip().lower() in ("true", "1", "yes", "y", "labor")

    added = 0
    updated = 0
    skipped = 0
    auto_skipped_junk = 0
    errors = []

    for idx, row_dict in enumerate(data_rows):
        # Per-row action from preview (only covers first 10 rows; rest default to "new")
        action = row_actions[idx] if idx < len(row_actions) else "new"
        if action == "skip" or action is None:
            skipped += 1
            continue

        # Build field dict from mapping
        fields = {}
        for csv_col, target in mapping.items():
            if not target:
                continue
            fields[target] = row_dict.get(csv_col, '')

        # Auto-skip junk rows (totals, section headers, empties, #REF! rows)
        if auto_skip_junk and _is_import_junk_row(fields):
            auto_skipped_junk += 1
            continue

        # Resolve account_code
        code = _resolve_account_code(
            fields.get('account_code'),
            fields.get('account_name') or fields.get('description'),
        )
        if not code:
            errors.append(f"Row {idx + header_row_index + 2}: could not resolve account code")
            skipped += 1
            continue

        # Account name fallback to COA section name
        section_name_map = dict(FP_COA_SECTIONS)
        account_name = (fields.get('account_name') or '').strip() or section_name_map.get(code, '')

        values = {
            "account_code":    code,
            "account_name":    account_name,
            "description":     (fields.get('description') or '').strip(),
            "is_labor":        _b(fields.get('is_labor', '')),
            "quantity":        _f(fields.get('quantity', 1), 1) or 1,
            "days":            _f(fields.get('days', 1), 1) or 1,
            "rate":            _f(fields.get('rate', 0)),
            "rate_type":       (fields.get('rate_type') or 'day_10').strip() or 'day_10',
            "est_ot":          _f(fields.get('est_ot', 0)),
            "fringe_type":     (fields.get('fringe_type') or 'N').strip()[:1].upper() or 'N',
            "agent_pct":       _f(fields.get('agent_pct', 0)),
            "estimated_total": _f(fields.get('estimated_total', 0)),
            "note":            (fields.get('note') or '').strip(),
        }

        try:
            if isinstance(action, dict) and action.get('update'):
                ln = BudgetLine.query.filter_by(id=int(action['update']), budget_id=bid).first()
                if not ln:
                    errors.append(f"Row {idx + header_row_index + 2}: line to update not found")
                    skipped += 1
                    continue
                for k, v in values.items():
                    setattr(ln, k, v)
                updated += 1
            else:  # "new" or anything else
                db.session.add(BudgetLine(budget_id=bid, **values))
                added += 1
        except Exception as e:
            errors.append(f"Row {idx + header_row_index + 2}: {e}")
            skipped += 1

    try:
        db.session.commit()
        _touch_budget(bid)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": f"Database error: {e}"}), 500

    return jsonify({
        "added": added,
        "updated": updated,
        "skipped": skipped,
        "auto_skipped_junk": auto_skipped_junk,
        "errors": errors[:50],  # cap error list
    })


# Legacy import route — kept for backward compatibility but redirects to the new UI
# Legacy naive-import route deleted 2026-07-20 (tools audit) — it only
# redirected to the smart import UI; old bookmarks now 404.
@app.route("/projects/<int:pid>/budget/<int:bid>/from-template", methods=["POST"])
@login_required
def budget_from_template(pid, bid):
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    tid    = request.form.get("template_id", type=int)
    tmpl   = BudgetTemplate.query.get_or_404(tid)
    for i, tl in enumerate(sorted(tmpl.lines, key=lambda x: x.sort_order)):
        db.session.add(BudgetLine(
            budget_id=bid,
            account_code=tl.account_code,
            account_name=tl.account_name,
            description=tl.description or "",
            is_labor=tl.is_labor,
            quantity=float(tl.quantity or 1),
            days=float(tl.days or 1),
            rate=float(tl.rate or 0),
            rate_type=tl.rate_type,
            fringe_type=tl.fringe_type,
            agent_pct=tl.agent_pct,
            estimated_total=float(tl.estimated_total or 0),
            sort_order=i,
        ))
    db.session.commit()
    flash(f"Applied template '{tmpl.name}' — {len(tmpl.lines)} lines added.", "success")
    return redirect(url_for("budget_view", pid=pid, bid=bid))


@app.route("/projects/<int:pid>/budget/<int:bid>/save-as-template", methods=["POST"])
@login_required
def save_as_template(pid, bid):
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    name   = request.form.get("template_name", "").strip()
    if not name:
        flash("Template name required.", "error")
        return redirect(url_for("budget_view", pid=pid, bid=bid))

    existing = BudgetTemplate.query.filter_by(name=name).first()
    if existing:
        flash(f"Template '{name}' already exists.", "error")
        return redirect(url_for("budget_view", pid=pid, bid=bid))

    tmpl = BudgetTemplate(name=name, description=f"Saved from {budget.name}")
    db.session.add(tmpl)
    db.session.flush()

    lines = BudgetLine.query.filter_by(budget_id=bid).order_by(
        BudgetLine.account_code, BudgetLine.sort_order).all()
    for i, ln in enumerate(lines):
        if ln.line_tag == 'kit_fee':  # skip auto-managed kit fee rows
            continue
        db.session.add(BudgetTemplateLine(
            template_id=tmpl.id,
            account_code=ln.account_code,
            account_name=ln.account_name,
            description=ln.description,
            is_labor=ln.is_labor,
            quantity=float(ln.quantity or 1),
            days=float(ln.days or 1),
            rate=float(ln.rate or 0),
            rate_type=ln.rate_type,
            fringe_type=ln.fringe_type,
            agent_pct=ln.agent_pct,
            estimated_total=float(ln.estimated_total or 0),
            sort_order=i,
        ))
    db.session.commit()
    flash(f"Saved as template '{name}'.", "success")
    return redirect(url_for("budget_view", pid=pid, bid=bid))


# ── Project / Budget Settings ─────────────────────────────────────────────────

@app.route("/projects/<int:pid>/budget/<int:bid>/settings", methods=["POST"])
@login_required
def budget_settings(pid, bid):
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    data   = request.get_json(force=True)
    if "name" in data:
        budget.name = data["name"].strip() or budget.name
    if "company_fee_pct" in data:
        # Defensive: in flat mode the pct field can arrive blank — don't 500.
        try:
            budget.company_fee_pct = float(data["company_fee_pct"]) / 100
        except (TypeError, ValueError):
            pass
    if "company_fee_mode" in data:
        # 'pct' (fee = pct × eligible subtotal) or 'flat' (fixed dollar fee).
        # Was never persisted, so picking "flat" silently reverted to percent
        # on reload. (User 2026-06-26.)
        m = (data.get("company_fee_mode") or 'pct').strip().lower()
        budget.company_fee_mode = m if m in ('pct', 'flat') else 'pct'
    if "company_fee_flat" in data:
        v = data.get("company_fee_flat")
        try:
            budget.company_fee_flat = float(v) if v not in (None, '', 'null') else 0
        except (TypeError, ValueError):
            budget.company_fee_flat = 0
    if "company_fee_dispersed" in data:
        budget.company_fee_dispersed = bool(data["company_fee_dispersed"])
    if "target_budget" in data:
        budget.target_budget = float(data["target_budget"]) if data["target_budget"] else None
    if "start_date" in data:
        try:
            _sd = datetime.strptime(data["start_date"], "%Y-%m-%d").date() if data["start_date"] else None
            if _sd is None or not _reject_insane_year(_sd):
                budget.start_date = _sd
        except ValueError:
            pass
    if "end_date" in data:
        try:
            _ed = datetime.strptime(data["end_date"], "%Y-%m-%d").date() if data["end_date"] else None
            if _ed is None or not _reject_insane_year(_ed):
                budget.end_date = _ed
        except ValueError:
            pass
    if "notes" in data:
        budget.notes = data["notes"] or None
    if "payroll_profile_id" in data:
        v = data.get("payroll_profile_id")
        budget.payroll_profile_id = int(v) if v else None
    if "payroll_week_start" in data:
        v = data.get("payroll_week_start")
        budget.payroll_week_start = int(v) if v is not None and v != '' else None
    if "timezone" in data:
        budget.timezone = data["timezone"] or "America/Los_Angeles"
    if "workers_comp_pct" in data:
        v = data.get("workers_comp_pct")
        budget.workers_comp_pct = float(v) / 100 if v is not None and v != '' else 0.03
    if "payroll_fee_pct" in data:
        v = data.get("payroll_fee_pct")
        budget.payroll_fee_pct = float(v) / 100 if v is not None and v != '' else 0.0175
    # Production Insurance: mode + pct + flat. Stored independently;
    # calc_top_sheet picks which input to use based on mode.
    if "production_insurance_mode" in data:
        m = (data.get("production_insurance_mode") or 'off').strip().lower()
        if m not in ('off', 'pct', 'flat'):
            m = 'off'
        budget.production_insurance_mode = m
    if "production_insurance_pct" in data:
        v = data.get("production_insurance_pct")
        try:
            budget.production_insurance_pct = (float(v) / 100) if v not in (None, '', 'null') else 0
        except (TypeError, ValueError):
            budget.production_insurance_pct = 0
    if "production_insurance_flat" in data:
        v = data.get("production_insurance_flat")
        try:
            budget.production_insurance_flat = float(v) if v not in (None, '', 'null') else 0
        except (TypeError, ValueError):
            budget.production_insurance_flat = 0
    if "fee_excluded_sections" in data:
        # Frontend sends an array of account-code ints (the sections the
        # user ticked as "exempt" in Settings). Empty array = fee applies
        # to every section (default). Stored as JSON text on the budget row.
        raw = data.get("fee_excluded_sections") or []
        try:
            codes = sorted({int(c) for c in raw})
        except (TypeError, ValueError):
            codes = []
        import json as _j_fee
        budget.fee_excluded_sections = _j_fee.dumps(codes) if codes else None
    if "fee_exclude_fringes" in data:
        # Default-ON: fringes on labor lines are excluded from the Prod
        # Co Fee base. User can disable per-budget if their prodco does
        # charge fee on fringes (rare).
        budget.fee_exclude_fringes = bool(data.get("fee_exclude_fringes"))
    if "client_name" in data:
        budget.client_name = data["client_name"].strip() or None
    if "prepared_by" in data:
        budget.prepared_by = data["prepared_by"].strip() or None
    if "prepared_by_title" in data:
        budget.prepared_by_title = data["prepared_by_title"].strip() or None
    if "prepared_by_email" in data:
        budget.prepared_by_email = data["prepared_by_email"].strip() or None
    if "prepared_by_phone" in data:
        budget.prepared_by_phone = data["prepared_by_phone"].strip() or None
    db.session.commit()
    try:
        # Capture which fields the request actually touched (not the full
        # object) so the activity entry tells us "fee_pct + payroll_profile
        # changed" rather than dumping every column.
        _changed = sorted(set(data.keys()) - {'csrf_token'})
        if _changed:
            _log_activity(action='update', entity_type='budget_settings',
                          entity_id=bid, entity_label=budget.name or 'Budget',
                          budget_id=bid, project_id=pid,
                          before=None, after={k: data.get(k) for k in _changed},
                          note=f'Updated budget settings: {", ".join(_changed)}')
    except Exception: pass
    return jsonify({"ok": True})


@app.route("/projects/<int:pid>/budget/<int:bid>/fee", methods=["POST"])
@login_required
def budget_fee_update(pid, bid):
    """Dedicated Production Company Fee save (2026-07-22, owner: 'move that
    production company fee thing to the budget view… make it right click…
    take it out of the settings page'). Edits THIS budget version only, so
    Estimated and Working can carry different fees. Small and strict on
    purpose — flat-fee saves through the monolithic settings route kept
    failing opaquely. Body: {mode: 'pct'|'flat', pct?, flat?, dispersed?};
    only provided keys change. Returns the saved values."""
    _require_project_role(pid, 'editor')
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    data = request.get_json(force=True) or {}
    m = (data.get("mode") or '').strip().lower()
    if m:
        if m not in ('pct', 'flat'):
            return jsonify({"error": f"unknown fee mode '{m}'"}), 400
        budget.company_fee_mode = m
    if "pct" in data:
        try:
            v = float(str(data["pct"]).replace('%', '').replace(',', '').strip())
        except (TypeError, ValueError):
            return jsonify({"error": "Percentage must be a number (e.g. 18)"}), 400
        # company_fee_pct is Numeric(6,4): stored /100, so input must be < 100
        # ×100 headroom-wise — cap at 99 to keep the column from overflowing.
        if not (0 <= v <= 99):
            return jsonify({"error": "Percentage must be between 0 and 99"}), 400
        budget.company_fee_pct = v / 100
    if "flat" in data:
        try:
            v = float(str(data["flat"]).replace('$', '').replace(',', '').strip())
        except (TypeError, ValueError):
            return jsonify({"error": "Flat amount must be a number (e.g. 25000)"}), 400
        if not (0 <= v <= 999_999_999):
            return jsonify({"error": "Flat amount out of range"}), 400
        budget.company_fee_flat = v
    if "dispersed" in data:
        budget.company_fee_dispersed = bool(data.get("dispersed"))
    db.session.commit()
    try:
        _log_activity(action='update', entity_type='budget_settings',
                      entity_id=bid, entity_label=budget.name or 'Budget',
                      budget_id=bid, project_id=pid, before=None,
                      after={k: data.get(k) for k in ('mode', 'pct', 'flat', 'dispersed') if k in data},
                      note='Updated Production Company Fee')
    except Exception: pass
    return jsonify({"ok": True,
                    "mode": budget.company_fee_mode or 'pct',
                    "pct": float(budget.company_fee_pct or 0),
                    "flat": float(budget.company_fee_flat or 0),
                    "dispersed": bool(budget.company_fee_dispersed)})


