@app.route("/projects/<int:pid>/locations/save", methods=["POST"])
@login_required
def location_save(pid):
    """Create or update a project location. New locations are also saved to the global library."""
    ProjectSheet.query.get_or_404(pid)
    data = request.get_json(force=True)
    lid  = data.get("id")
    is_new = not lid
    if lid:
        loc = Location.query.filter_by(id=lid, project_id=pid).first_or_404()
    else:
        loc = Location(project_id=pid)
        db.session.add(loc)
    _phone_fields = {"contact_phone", "dayof_phone"}
    _email_fields = {"contact_email", "dayof_email"}
    _loc_fields = ["name", "facility_name", "location_type", "address", "map_url",
                   "contact_name", "contact_email", "contact_phone",
                   "dayof_name", "dayof_email", "dayof_phone",
                   "billing_type", "daily_rate", "notes", "budget_line_id"]
    _title_fields = {"name", "facility_name", "contact_name", "dayof_name"}
    for f in _loc_fields:
        if f in data:
            val = data[f] if data[f] != "" else None
            if f in _phone_fields:
                val = _normalize_phone(val)
            elif f in _email_fields and val and not _validate_email(val):
                return jsonify({"error": f"Invalid email: {val}"}), 400
            elif f in _title_fields and val:
                val = val.strip().title()
            setattr(loc, f, val)

    # Per-location required-doc checklist — a list of keys from the modal
    # checkboxes, stored comma-separated. (User 2026-06-01.)
    if "required_docs" in data:
        rd = data.get("required_docs")
        if isinstance(rd, (list, tuple)):
            loc.required_docs = ",".join(str(x).strip() for x in rd if str(x).strip()) or None
        else:
            loc.required_docs = (str(rd).strip() or None) if rd else None

    # Auto-sync to global library on new location (unless user opted out)
    if is_new and data.get("save_to_library", True) and loc.name:
        existing_global = Location.query.filter_by(
            project_id=None, name=loc.name, active=True
        ).first()
        if not existing_global:
            lib = Location(project_id=None)
            db.session.add(lib)
            for f in _loc_fields:
                if f != "budget_line_id":
                    setattr(lib, f, getattr(loc, f))

    db.session.commit()
    try:
        _log_activity(
            action=('create' if is_new else 'update'),
            entity_type='location', entity_id=loc.id,
            entity_label=loc.name or 'Location',
            project_id=pid,
            before=None,
            after={'name': loc.name, 'address': loc.address,
                   'fields_changed': sorted([f for f in _loc_fields if f in data])},
            note=f'{"Added" if is_new else "Updated"} location "{loc.name}"')
    except Exception: pass
    return jsonify({"ok": True, "id": loc.id, "name": loc.name})


@app.route("/projects/<int:pid>/locations/picker-list")
@login_required
def location_picker_list(pid):
    """JSON list of candidate locations to assign to a budget line.
    Returns project-specific locations first (source='project') then
    global library locations (source='library'). Used by the Assign
    Location modal on 3300 budget lines."""
    ProjectSheet.query.get_or_404(pid)
    proj = Location.query.filter_by(project_id=pid, active=True).order_by(Location.name).all()
    libs = Location.query.filter_by(project_id=None, active=True).order_by(Location.name).all()

    def _row(l, source):
        return {
            "id": l.id,
            "name": l.name,
            "facility_name": l.facility_name or "",
            "location_type": l.location_type or "",
            "address": l.address or "",
            "source": source,
            "assigned_to_line_id": l.budget_line_id,
        }

    return jsonify({
        "project": [_row(l, "project") for l in proj],
        "library": [_row(l, "library") for l in libs],
    })


@app.route("/projects/<int:pid>/budget/<int:bid>/line/<int:lid>/assign-location", methods=["POST"])
@login_required
def line_assign_location(pid, bid, lid):
    """Assign a Location to a budget line. One location per line: if the
    line had a previous location assigned, its FK is cleared. Pass
    location_id=null to clear the current assignment without assigning
    a new one."""
    Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    ln = BudgetLine.query.filter_by(id=lid, budget_id=bid).first_or_404()
    data = request.get_json(force=True) or {}
    location_id = data.get("location_id")

    try:
        # Clear any existing assignment for this line.
        Location.query.filter_by(budget_line_id=lid).update({"budget_line_id": None})

        assigned = None
        if location_id is not None and location_id != "":
            loc = Location.query.get(int(location_id))
            if not loc:
                return jsonify({"error": f"location {location_id} not found"}), 404
            loc.budget_line_id = lid
            assigned = {"id": loc.id, "name": loc.name, "facility_name": loc.facility_name or ""}

        db.session.commit()
        _touch_budget(bid)
        db.session.commit()
        try:
            _label = ln.description or ln.account_name or '—'
            _log_activity(
                action='update', entity_type='budget_line_location',
                entity_id=lid, entity_label=_label,
                budget_id=bid, project_id=pid,
                before=None,
                after={'location_id': location_id, 'location_name': assigned['name'] if assigned else None},
                note=(f'Cleared location on {_label}' if not assigned
                      else f'Assigned location "{assigned["name"]}" to {_label}'))
        except Exception: pass
        return jsonify({"ok": True, "assigned": assigned})
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 400


@app.route("/projects/<int:pid>/locations/library")
@login_required
def location_library(pid):
    """Return global library locations (project_id=NULL) as JSON for the import picker."""
    # Exclude names already in this project
    existing_names = {l.name for l in Location.query.filter_by(project_id=pid, active=True).all()}
    libs = Location.query.filter_by(project_id=None, active=True).order_by(Location.name).all()
    return jsonify([{
        "id": l.id, "name": l.name, "location_type": l.location_type or "",
        "address": l.address or "", "map_url": l.map_url or "",
        "contact_name": l.contact_name or "", "contact_email": l.contact_email or "",
        "contact_phone": l.contact_phone or "",
        "dayof_name": l.dayof_name or "", "dayof_email": l.dayof_email or "",
        "dayof_phone": l.dayof_phone or "",
        "billing_type": l.billing_type or "per_day",
        "daily_rate": float(l.daily_rate) if l.daily_rate else None,
        "notes": l.notes or "",
        "already_in_project": l.name in existing_names,
    } for l in libs])


@app.route("/projects/<int:pid>/locations/<int:lid>/delete", methods=["POST"])
@login_required
def location_delete(pid, lid):
    loc = Location.query.filter_by(id=lid, project_id=pid).first_or_404()
    _name = loc.name
    loc.active = False
    db.session.commit()
    try:
        _log_activity(action='delete', entity_type='location',
                      entity_id=lid, entity_label=_name,
                      project_id=pid,
                      before={'name': _name, 'active': True},
                      after={'active': False},
                      note=f'Removed location "{_name}"')
    except Exception: pass
    return jsonify({"ok": True})


# ── Estimate-linked Transaction filter ────────────────────────────────────────
# DocUpload categories that represent FORECAST paperwork, not real spend.
# The upload handler (line ~16061) already refuses to auto-create a
# Transaction for these. The metadata-update handler (line ~17299) deletes
# any linked Transactions when a doc's category is changed to one of these
# values. Even so, legacy data + QBO-sync-then-manual-match can leave stray
# estimate-linked Transactions in the DB — defense-in-depth filter below
# excludes them from every Actual / Actualized rollup so they never inflate
# Actual columns or PO Actualized totals. 2026-05-14.
_NON_LEDGER_DOC_CATEGORIES = (
    'tax_form', 'contract', 'release', 'legal', 'insurance', 'misc',
    'estimate', 'quote', 'purchase_order',
)
def _exclude_estimate_linked_txns_clause():
    """Returns a SQLAlchemy clause to splat into a Transaction filter that
    keeps:
      - Transactions with no doc attached (manual entry, QBO sync without
        doc match) — always counted as real spend.
      - Transactions linked to a doc whose category is NOT in the
        non-ledger set (receipt/invoice/etc. — real spend events).
    Excludes Transactions linked to a doc whose category IS in the
    non-ledger set (estimates, quotes, POs, paperwork)."""
    from sqlalchemy import or_ as _or_t
    _bad_doc_ids = (db.session.query(DocUpload.id)
                    .filter(DocUpload.category.in_(_NON_LEDGER_DOC_CATEGORIES))
                    .subquery())
    return _or_t(
        Transaction.doc_upload_id.is_(None),
        Transaction.doc_upload_id.notin_(_bad_doc_ids),
    )


# ── Purchase Orders (per-project) ──────────────────────────────────────────────
# Per user 2026-05-04: vendor commitment tracking. POs are project-scoped;
# budget lines (typically non-labor) reference one via BudgetLine.po_id.
# Future: Transaction.po_id + DocUpload.po_id for spend rollup.

def _po_to_dict(po, *, with_rollup=False, project_id=None):
    """Serialize a PurchaseOrder. with_rollup adds budgeted (sum of
    BudgetLine.estimated_total for assigned lines) and over_cap flag."""
    out = {
        "id":             po.id,
        "po_number":      po.po_number,
        "vendor_name":    po.vendor_name,
        "vendor_contact": po.vendor_contact or "",
        "vendor_email":   po.vendor_email or "",
        "vendor_phone":   po.vendor_phone or "",
        "total_committed": float(po.total_committed) if po.total_committed is not None else None,
        "status":         po.status or "open",
        "issued_date":    po.issued_date.isoformat() if po.issued_date else None,
        "notes":          po.notes or "",
        "archived":       bool(po.archived),
        "created_at":     po.created_at.isoformat() if po.created_at else None,
    }
    # Surface source_doc_upload_id + denormalized filename. Wrapped
    # defensively in case the column / table hasn't been added yet on
    # a fresh deploy where the worker self-heal hasn't fully run.
    try:
        out["source_doc_upload_id"] = getattr(po, 'source_doc_upload_id', None)
    except Exception:
        out["source_doc_upload_id"] = None
    out["source_doc"] = None
    if out["source_doc_upload_id"]:
        try:
            _sd = db.session.get(DocUpload, out["source_doc_upload_id"])
            if _sd:
                out["source_doc"] = {
                    "id":       _sd.id,
                    "filename": _sd.filed_filename or _sd.original_filename or f"Upload #{_sd.id}",
                    "vendor":   _sd.vendor or "",
                    "amount":   float(_sd.amount) if _sd.amount is not None else None,
                    "category": _sd.category or "",
                }
        except Exception:
            pass
    # Additional doc attachments from "Add to PO" appends. Capture each
    # doc's category so the rollup below can split estimates vs receipts.
    out["attachments"] = []
    try:
        from models import PoDocAttachment
        for att in (PoDocAttachment.query
                    .filter_by(po_id=po.id)
                    .order_by(PoDocAttachment.created_at).all()):
            d = db.session.get(DocUpload, att.doc_upload_id)
            _superseded = getattr(att, 'superseded_at', None)
            out["attachments"].append({
                "id":       att.id,
                "doc_id":   att.doc_upload_id,
                "filename": (d.filed_filename or d.original_filename or f"Upload #{d.id}") if d else None,
                "amount":   float(att.amount) if att.amount is not None else None,
                "note":     att.note or "",
                "role":     att.role or "additional",
                "category": (d.category if d else None),
                "created_at": att.created_at.isoformat() if att.created_at else None,
                "superseded": bool(_superseded),
                "superseded_at": _superseded.isoformat() if _superseded else None,
            })
    except Exception:
        pass
    if with_rollup:
        from sqlalchemy import func as _func_po
        # Budget commitment: sum estimated_total of every BudgetLine
        # currently assigned to this PO. CRITICAL: filter to a single
        # canonical budget per project, otherwise the same logical line
        # gets counted in Estimated + Working + Actual (2–3× over-count)
        # because po_id is copied during the Working→Actual auto-clone.
        # Pick the project's current Working budget (parent_budget_id
        # set, version_status=current, is_actual=False) — falls back to
        # the latest non-actual current budget if no Working exists yet.
        # 2026-05-06 — fixes "PO shows 4 lines $65k when only 1 line is
        # assigned with $15k cap".
        _pid_for_rollup = project_id or po.project_id
        _canonical = (Budget.query
                      .filter_by(project_id=_pid_for_rollup,
                                 version_status='current',
                                 is_actual=False)
                      .filter(db.or_(Budget.budget_mode == 'working',
                               db.and_(Budget.budget_mode == None,
                                       Budget.parent_budget_id.isnot(None))))
                      .order_by(Budget.id.desc())
                      .first())
        if not _canonical:
            _canonical = (Budget.query
                          .filter_by(project_id=_pid_for_rollup,
                                     version_status='current',
                                     is_actual=False)
                          .order_by(Budget.id.desc())
                          .first())
        if _canonical:
            _po_lines = (BudgetLine.query
                         .filter(BudgetLine.po_id == po.id,
                                 BudgetLine.budget_id == _canonical.id)
                         .order_by(BudgetLine.account_code,
                                   BudgetLine.sort_order,
                                   BudgetLine.id)
                         .all())
            budgeted = sum((float(l.estimated_total or 0) for l in _po_lines), 0.0)
            line_count = len(_po_lines)
            # Per-line breakdown so the PO card can show which lines
            # contribute and at what amounts. Helps the user spot
            # mis-coded / duplicated lines that would otherwise just
            # show as a mysterious total.
            out["lines"] = [{
                "id":             l.id,
                "account_code":   l.account_code,
                "description":    l.description or l.account_name or '',
                "estimated_total": float(l.estimated_total or 0),
                "qty":            float(l.quantity or 0),
                "days":           float(l.days or 0),
                "rate":           float(l.rate or 0),
            } for l in _po_lines]
        else:
            budgeted, line_count = 0, 0
            out["lines"] = []
        out["budgeted"]   = float(budgeted)
        out["lines_total"] = float(budgeted)  # alias for clarity
        out["line_count"] = line_count

        # Three-bucket rollup, 2026-05-10. User feedback: the previous
        # "doc_attached_total" lumped vendor estimates/SOWs and receipts
        # together. Real workflow distinguishes them:
        #   estimates_total → vendor commitments (estimate / quote /
        #     contract / purchase_order categories) — what the vendor
        #     said the work would cost
        #   receipts_total  → receipts/invoices ATTACHED but not yet
        #     posted as transactions — informational
        #   billed_total    → ACTUALS — sum of Transaction.amount for
        #     transactions whose budget_line.po_id == this PO. This is
        #     the canonical "money paid out" number; over-cap fires
        #     only when this exceeds the cap.
        _ESTIMATE_CATS = {'estimate', 'quote', 'contract', 'purchase_order'}
        _RECEIPT_CATS  = {'receipt', 'invoice'}
        _est_sum = 0.0
        _rcp_sum = 0.0
        _all_sum = 0.0
        for a in (out.get("attachments") or []):
            if a.get("superseded"):
                continue   # replaced by a newer quote — not part of live totals
            amt = a.get("amount") or 0
            if not amt:
                continue
            amt = float(amt)
            _all_sum += amt
            cat = (a.get("category") or "").lower()
            if cat in _ESTIMATE_CATS:
                _est_sum += amt
            elif cat in _RECEIPT_CATS:
                _rcp_sum += amt
        out["estimates_total"]   = round(_est_sum, 2)
        out["receipts_total"]    = round(_rcp_sum, 2)
        out["doc_attached_total"] = round(_all_sum, 2)  # legacy field, kept

        # Billed = sum of transactions linked (via Transaction.budget_line_id)
        # to ANY budget line that maps to this PO. "Maps to this PO" means
        # one of:
        #   (a) line.po_id == po.id directly  — true for Working lines and
        #       for Actual lines that were cloned AFTER the PO was assigned
        #       (po_id is copied at clone time).
        #   (b) line.source_line_id points to a Working line with po_id ==
        #       po.id  — covers Actual lines that were cloned BEFORE the PO
        #       was assigned to the parent Working line. Their own po_id
        #       stays NULL forever (clone-time snapshot) but they're still
        #       the logical Actual-tab counterpart of the PO-assigned line,
        #       so transactions on them must count.
        #
        # Earlier versions only handled (a), which silently dropped every
        # Actual-linked transaction whose PO was assigned post-clone. User
        # report 2026-05-14.
        #
        # No double-count risk: each Transaction has exactly one
        # budget_line_id pointing at one BudgetLine row.
        _billed = 0.0
        try:
            # Subquery: ids of Working budget lines currently assigned to
            # this PO. Used to match Actual lines back via source_line_id
            # when the Actual's own po_id is NULL.
            _working_po_lines_sub = (db.session.query(BudgetLine.id)
                                     .filter(BudgetLine.po_id == po.id)
                                     .subquery())
            from sqlalchemy import or_ as _or_po
            _billed_q = (db.session
                         .query(_func_po.coalesce(_func_po.sum(_signed_amount()), 0))
                         .join(BudgetLine, BudgetLine.id == Transaction.budget_line_id)
                         .filter(_or_po(
                                     BudgetLine.po_id == po.id,
                                     BudgetLine.source_line_id.in_(_working_po_lines_sub),
                                 ),
                                 Transaction.not_project_expense == False,
                                 _exclude_estimate_linked_txns_clause()))
            _billed = float(_billed_q.scalar() or 0)
        except Exception as _be:
            logging.warning(f"[po rollup] billed calc failed for po={po.id}: {_be}")
        out["billed_total"] = round(_billed, 2)

        # Detail listing of the same transactions that fed billed_total.
        # Same OR filter; same estimate-link guard. Surfaces to the PO
        # card so the user can spot incorrectly-coded txns and either
        # mark them not-project-expense in place, or follow the link
        # back to the Actuals view to reassign to a different line/PO.
        # 2026-05-14 per user request.
        out["transactions"] = []
        try:
            _detail_q = (db.session
                         .query(Transaction, BudgetLine, DocUpload)
                         .join(BudgetLine, BudgetLine.id == Transaction.budget_line_id)
                         .outerjoin(DocUpload, DocUpload.id == Transaction.doc_upload_id)
                         .filter(_or_po(
                                     BudgetLine.po_id == po.id,
                                     BudgetLine.source_line_id.in_(_working_po_lines_sub),
                                 ),
                                 Transaction.not_project_expense == False,
                                 Transaction.is_expense == True,
                                 _exclude_estimate_linked_txns_clause())
                         .order_by(Transaction.txn_date.desc().nullslast(),
                                   Transaction.id.desc()))
            for _t, _ln, _d in _detail_q.all():
                out["transactions"].append({
                    "id":            _t.id,
                    # Already a YYYY-MM-DD string per Transaction model.
                    "txn_date":      _t.txn_date or "",
                    "vendor":        _t.vendor or "",
                    "amount":        float(_t.amount) if _t.amount is not None else None,
                    "note":          _t.note or "",
                    "source":        _t.source or "manual",
                    "match_status":  _t.match_status or "unmatched",
                    "budget_line_id":   _ln.id,
                    "account_code":     _ln.account_code,
                    "line_description": _ln.description or _ln.account_name or "",
                    # The Actual budget id the line belongs to — gives the
                    # template a target for the "Manage in Actuals" link.
                    "budget_id":     _ln.budget_id,
                    "doc_upload_id": _t.doc_upload_id,
                    "doc_filename":  (_d.filed_filename or _d.original_filename) if _d else None,
                })
        except Exception as _de:
            logging.warning(f"[po rollup] txn detail failed for po={po.id}: {_de}")

        # Cap usage drives off BILLED only — the user wants the over-cap
        # alert reserved for actual overspend, not a budgeted projection
        # exceeding the committed cap. Lines or estimates above cap can
        # still trigger informational banners (in the template), but
        # over_cap is the loud signal and it requires real money paid.
        # 2026-05-10.
        if po.total_committed is not None:
            cap_f = float(po.total_committed)
            out["over_cap"]      = _billed > cap_f
            out["cap_remaining"] = cap_f - _billed
            out["cap_used_basis"] = "billed"
        else:
            out["over_cap"]      = False
            out["cap_remaining"] = None
            out["cap_used_basis"] = "billed"
    return out


@app.route("/projects/<int:pid>/pos")
@login_required
def po_list_page(pid):
    """Render the project's PO tab — list of every PO with budgeted +
    invoiced totals against cap. Modeled after the Locations tab."""
    project = ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'viewer')
    from models import PurchaseOrder
    pos = (PurchaseOrder.query
           .filter_by(project_id=pid)
           .order_by(PurchaseOrder.archived.asc(),
                     PurchaseOrder.created_at.desc())
           .all())
    pos_data = [_po_to_dict(p, with_rollup=True, project_id=pid) for p in pos]
    # Resolve the budget context for the tab strip — prefer the
    # explicit return_bid query arg (set by the Budget tab's PO link),
    # fall back to the project's most recent current budget.
    return_bid_arg = request.args.get('return_bid', type=int)
    return_budget = None
    if return_bid_arg:
        return_budget = Budget.query.filter_by(id=return_bid_arg, project_id=pid).first()
    if not return_budget:
        return_budget = (Budget.query
                         .filter_by(project_id=pid, version_status='current')
                         .order_by(Budget.id.desc()).first())

    # ── Budget-view mirror: every PO-assigned line, grouped by COA section.
    # Lets the user see PO commitments through the lens of the chart of
    # accounts instead of by vendor. Mirrors the budget view's
    # section-header / lines-table structure. Per user 2026-05-14.
    #
    # Source set: BudgetLines with po_id IS NOT NULL on the project's
    # canonical Working budget (same canonical pick as _po_to_dict so
    # totals reconcile). PO meta carried inline per line so the template
    # can render a clickable PO badge that anchors to the matching card.
    lines_by_section = []
    try:
        from budget_calc import FP_COA_SECTIONS, FP_COA_NAMES
        _canonical_w = (Budget.query
                        .filter_by(project_id=pid,
                                   version_status='current',
                                   is_actual=False)
                        .filter(db.or_(Budget.budget_mode == 'working',
                               db.and_(Budget.budget_mode == None,
                                       Budget.parent_budget_id.isnot(None))))
                        .order_by(Budget.id.desc())
                        .first())
        if not _canonical_w:
            _canonical_w = (Budget.query
                            .filter_by(project_id=pid,
                                       version_status='current',
                                       is_actual=False)
                            .order_by(Budget.id.desc())
                            .first())
        if _canonical_w:
            # Single query: every PO-assigned line on the canonical
            # Working budget, with PO joined in for the badge.
            from models import PurchaseOrder as _PO
            _po_lines_q = (db.session
                           .query(BudgetLine, _PO)
                           .join(_PO, _PO.id == BudgetLine.po_id)
                           .filter(BudgetLine.budget_id == _canonical_w.id,
                                   BudgetLine.po_id.isnot(None))
                           .order_by(BudgetLine.account_code,
                                     BudgetLine.sort_order,
                                     BudgetLine.id))
            # Bucket lines by (start_code, section_name) using the COA
            # section that contains each line's account_code. The PO
            # tab's "Lines" badge already shows the canonical estimated
            # total per line; reuse that here.
            _coa_starts = [c for c, _ in FP_COA_SECTIONS]
            def _section_for(code):
                # Largest section start ≤ code.
                if code is None:
                    return (0, "Unassigned")
                _start = 0
                for _s in _coa_starts:
                    if _s <= code:
                        _start = _s
                    else:
                        break
                return (_start, FP_COA_NAMES.get(_start, "Unassigned"))

            _buckets = {}  # (start, name) -> list of dicts
            for _ln, _po in _po_lines_q.all():
                _key = _section_for(_ln.account_code)
                _buckets.setdefault(_key, []).append({
                    "id":              _ln.id,
                    "account_code":    _ln.account_code,
                    "description":    (_ln.description or _ln.account_name or ""),
                    "qty":             float(_ln.quantity or 0),
                    "days":            float(_ln.days or 0),
                    "rate":            float(_ln.rate or 0),
                    "estimated_total": float(_ln.estimated_total or 0),
                    "po_id":           _po.id,
                    "po_number":       _po.po_number,
                    "vendor_name":     _po.vendor_name,
                    "po_archived":     bool(_po.archived),
                })
            # Stable ascending order by section start code.
            for _key in sorted(_buckets.keys(), key=lambda k: k[0]):
                _ls = _buckets[_key]
                lines_by_section.append({
                    "code":  _key[0],
                    "name":  _key[1],
                    "lines": _ls,
                    "total": round(sum(l["estimated_total"] for l in _ls), 2),
                    "count": len(_ls),
                })
    except Exception as _ble:
        logging.warning(f"[po list] budget-view mirror build failed: {_ble}")

    return render_template("pos.html",
                           project=project,
                           pos=pos_data,
                           return_budget=return_budget,
                           lines_by_section=lines_by_section,
                           now=datetime.utcnow())


@app.route("/projects/<int:pid>/sub-budgets")
@login_required
def sub_budgets_page(pid):
    """Render the project's Sub-Budgets tab. Moved out of the POs page
    into its own tab per user 2026-05-26: 'I think we should move this
    into its own tab. It's substantial enough that it just needs to be
    on its own separate tab.'"""
    project = ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'viewer')

    return_bid_arg = request.args.get('return_bid', type=int)
    return_budget = None
    if return_bid_arg:
        return_budget = Budget.query.filter_by(id=return_bid_arg, project_id=pid).first()
    if not return_budget:
        return_budget = (Budget.query
                         .filter_by(project_id=pid, version_status='current')
                         .order_by(Budget.id.desc()).first())

    # Per-ROW fail-open (2026-07-22): the old page-wide try/except meant one
    # sub-budget whose rollup raised blanked EVERY sub-budget with only a
    # Render-log warning — 'sub budgets aren't displaying'. Now a failing row
    # still renders (without its rollup), the traceback lands in the
    # /admin/errors ring, and the page says how many rows degraded.
    sub_budgets_data = []
    sb_load_errors = 0
    try:
        _sbs = (SubBudget.query
                .filter_by(project_id=pid)
                .order_by(SubBudget.archived.asc(),
                          SubBudget.created_at.desc())
                .all())
    except Exception:
        logging.warning("[sub-budgets page] list query failed", exc_info=True)
        _sbs = []
    for sb in _sbs:
        try:
            sub_budgets_data.append(_sub_budget_to_dict(
                sb, with_rollup=True, project_id=pid,
                return_budget=return_budget))
        except Exception:
            sb_load_errors += 1
            logging.warning(f"[sub-budgets] row {sb.id} rollup failed",
                            exc_info=True)
            _record_bg_error(f"sub-budget #{sb.id} '{sb.name}' rollup",
                             tag=f"subbudget-{sb.id}")
            try:
                sub_budgets_data.append(_sub_budget_to_dict(
                    sb, with_rollup=False, project_id=pid,
                    return_budget=return_budget))
            except Exception:
                pass

    return render_template("sub_budgets.html",
                           project=project,
                           sub_budgets=sub_budgets_data,
                           sb_load_errors=sb_load_errors,
                           return_budget=return_budget,
                           now=datetime.utcnow())


@app.route("/projects/<int:pid>/pos.json")
@login_required
def po_list_json(pid):
    """JSON list of POs (for the budget-line PO picker modal)."""
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'viewer')
    from models import PurchaseOrder
    include_archived = request.args.get('include_archived') == '1'
    q = PurchaseOrder.query.filter_by(project_id=pid)
    if not include_archived:
        q = q.filter(PurchaseOrder.archived == False)  # noqa
    pos = q.order_by(PurchaseOrder.created_at.desc()).all()
    return jsonify({
        "ok": True,
        "pos": [_po_to_dict(p, with_rollup=True, project_id=pid) for p in pos],
    })


@app.route("/projects/<int:pid>/pos/save", methods=["POST"])
@login_required
def po_save(pid):
    """Create or update a PurchaseOrder. Body: {id?, po_number, vendor_name,
    vendor_contact?, vendor_email?, vendor_phone?, total_committed?, status?,
    issued_date?, notes?}. Returns the saved PO with rollup."""
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    from models import PurchaseOrder
    data = request.get_json(force=True) or {}
    pid_arg = data.get('id')
    if pid_arg:
        po = PurchaseOrder.query.filter_by(id=int(pid_arg), project_id=pid).first_or_404()
    else:
        po = PurchaseOrder(project_id=pid,
                           created_by_user_id=current_user.id if current_user.is_authenticated else None)
        db.session.add(po)
    # Field map → trim + length cap.
    for fld, cap in (('po_number', 80), ('vendor_name', 200),
                     ('vendor_contact', 200), ('vendor_email', 200),
                     ('vendor_phone', 50), ('notes', None)):
        if fld in data:
            v = (data.get(fld) or '').strip()
            setattr(po, fld, (v[:cap] if cap and v else (v or None)))
    if 'total_committed' in data:
        v = data.get('total_committed')
        if v in (None, '', 'null'):
            po.total_committed = None
        else:
            try:
                po.total_committed = round(float(v), 2)
            except (TypeError, ValueError):
                return jsonify({"error": "total_committed must be a number"}), 400
    if 'status' in data:
        s = (data.get('status') or 'open').strip().lower()
        if s in ('open', 'sent', 'received', 'closed', 'cancelled'):
            po.status = s
    if 'issued_date' in data:
        d = (data.get('issued_date') or '').strip()
        if not d:
            po.issued_date = None
        else:
            try:
                from datetime import datetime as _dt
                po.issued_date = _dt.strptime(d[:10], '%Y-%m-%d').date()
            except Exception:
                return jsonify({"error": "issued_date must be YYYY-MM-DD"}), 400
    if 'archived' in data:
        po.archived = bool(data.get('archived'))
    # Source doc attachment (added 2026-05-05). When a PO is created
    # from an estimate via the Docs tab, the originating DocUpload id
    # is forwarded here so the PO list page can show + link the source.
    # Wrapped in try/except defensively — if the column hasn't been
    # added yet by the worker self-heal (race on first deploy), this
    # silently no-ops instead of breaking the basic PO save flow.
    if 'source_doc_upload_id' in data:
        try:
            v = data.get('source_doc_upload_id')
            if v in (None, '', 'null', 0):
                po.source_doc_upload_id = None
            else:
                po.source_doc_upload_id = int(v)
        except (AttributeError, TypeError, ValueError):
            pass
    # Validate: po_number + vendor_name required.
    if not (po.po_number or '').strip() or not (po.vendor_name or '').strip():
        return jsonify({"error": "po_number and vendor_name are required"}), 400
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        # Likely the unique (project_id, po_number) constraint.
        if 'uq_po_project_number' in str(e) or 'duplicate' in str(e).lower():
            return jsonify({"error": "A PO with that number already exists on this project."}), 409
        return jsonify({"error": str(e)}), 400
    try:
        _log_activity(
            action=('create' if not pid_arg else 'update'), entity_type='purchase_order',
            entity_id=po.id, entity_label=f"{po.po_number} — {po.vendor_name}",
            project_id=pid,
            after={'po_number': po.po_number, 'vendor_name': po.vendor_name,
                   'total_committed': float(po.total_committed) if po.total_committed is not None else None,
                   'status': po.status},
            note=('Created PO' if not pid_arg else 'Updated PO'))
    except Exception: pass
    return jsonify({"ok": True, "po": _po_to_dict(po, with_rollup=True, project_id=pid)})


@app.route("/projects/<int:pid>/pos/<int:po_id>/delete", methods=["POST"])
@login_required
def po_delete(pid, po_id):
    """Soft-delete (archive) a PO. Lines stay assigned but the PO drops
    out of the active list. Use ?hard=1 to fully delete (clears po_id
    on every assigned line first)."""
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    from models import PurchaseOrder
    po = PurchaseOrder.query.filter_by(id=po_id, project_id=pid).first_or_404()
    label = f"{po.po_number} — {po.vendor_name}"
    if request.args.get('hard') == '1':
        # Hard delete: null out po_id on every assigned BudgetLine first.
        BudgetLine.query.filter_by(po_id=po.id).update({'po_id': None}, synchronize_session=False)
        db.session.delete(po)
    else:
        po.archived = True
    db.session.commit()
    try:
        _log_activity(action='delete', entity_type='purchase_order',
                      entity_id=po_id, entity_label=label, project_id=pid,
                      note=('Hard-deleted PO' if request.args.get('hard') == '1' else 'Archived PO'))
    except Exception: pass
    return jsonify({"ok": True})


@app.route("/docs/upload/<int:uid>/create-po", methods=["POST"])
@login_required
def create_po_from_doc(uid):
    """Create a new PurchaseOrder from an estimate / quote document.
    Body: {po_number, vendor_name (optional override), total_committed
    (optional override), status, issued_date, notes}. Defaults pulled
    from the DocUpload's OCR data when caller doesn't override.
    Returns the created PO with rollup."""
    from models import PurchaseOrder, PoDocAttachment
    doc = DocUpload.query.get_or_404(uid)
    pid = doc.project_id
    _require_project_role(pid, 'editor')
    data = request.get_json(force=True) or {}
    po_number = (data.get('po_number') or '').strip()
    if not po_number:
        return jsonify({"error": "po_number required"}), 400
    vendor_name = (data.get('vendor_name') or doc.vendor or '').strip()
    if not vendor_name:
        return jsonify({"error": "vendor_name required (no vendor on doc to default from)"}), 400
    total = data.get('total_committed')
    if total in (None, ''):
        total = float(doc.amount) if doc.amount is not None else None
    elif total is not None:
        try:
            total = round(float(total), 2)
        except (TypeError, ValueError):
            return jsonify({"error": "total_committed must be a number"}), 400
    issued = (data.get('issued_date') or '').strip()
    issued_date = None
    if issued:
        try:
            from datetime import datetime as _dt
            issued_date = _dt.strptime(issued[:10], '%Y-%m-%d').date()
        except Exception:
            return jsonify({"error": "issued_date must be YYYY-MM-DD"}), 400
    elif doc.doc_date:
        issued_date = doc.doc_date

    po = PurchaseOrder(
        project_id      = pid,
        po_number       = po_number[:80],
        vendor_name     = vendor_name[:200],
        vendor_contact  = (data.get('vendor_contact') or '').strip()[:200] or None,
        vendor_email    = (data.get('vendor_email')   or '').strip()[:200] or None,
        vendor_phone    = (data.get('vendor_phone')   or '').strip()[:50]  or None,
        total_committed = total,
        status          = (data.get('status') or 'open').strip().lower(),
        issued_date     = issued_date,
        notes           = (data.get('notes') or f'Created from estimate: {doc.filed_filename or doc.original_filename or f"Doc #{uid}"}').strip(),
        source_doc_upload_id = doc.id,
        created_by_user_id = current_user.id if current_user.is_authenticated else None,
    )
    db.session.add(po)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        if 'uq_po_project_number' in str(e) or 'duplicate' in str(e).lower():
            return jsonify({"error": "A PO with that number already exists on this project."}), 409
        return jsonify({"error": str(e)}), 400

    # If this doc is still flagged as an invoice/receipt/etc., flip it
    # to 'estimate' (creating a PO from it implies it was a forecast
    # doc) and clear any linked Transaction rows so it stops appearing
    # in Actuals. Mirrors the docs_upload_update non-ledger behaviour.
    # 2026-05-06 — covers Veryfi mis-classifications the user didn't
    # manually correct in the doc-detail modal first.
    try:
        _ledger_cats = {'invoice', 'receipt', 'expense', 'bill', None, ''}
        if (doc.category or '') in _ledger_cats:
            doc.category = 'estimate'
            db.session.commit()
        # Always clear linked txns — the doc is now a PO source, not a spend event.
        _txn_ids = [t.id for t in
                    Transaction.query.filter_by(doc_upload_id=doc.id).all()]
        if _txn_ids:
            Transaction.query.filter(Transaction.id.in_(_txn_ids)) \
                .delete(synchronize_session=False)
            db.session.commit()
            logging.info(f"[create_po_from_doc] cleared {len(_txn_ids)} "
                         f"Transaction row(s) for doc #{doc.id} (now a PO source)")
    except Exception as _e:
        logging.warning(f"[create_po_from_doc] post-create cleanup failed: {_e}")
        db.session.rollback()
    # Also record in the attachment junction so the source doc shows up
    # in the same list as future "Add to PO" appends.
    try:
        att = PoDocAttachment(
            po_id=po.id, doc_upload_id=doc.id,
            amount=doc.amount, role='source',
            note='Source estimate',
            created_by_user_id=current_user.id if current_user.is_authenticated else None,
        )
        db.session.add(att)
        db.session.commit()
    except Exception:
        db.session.rollback()
    try:
        _log_activity(action='create', entity_type='purchase_order',
                      entity_id=po.id, entity_label=f"{po.po_number} — {po.vendor_name}",
                      project_id=pid,
                      after={'po_number': po.po_number, 'vendor_name': po.vendor_name,
                             'total_committed': total, 'source_doc_upload_id': doc.id},
                      note=f'Created PO from estimate "{doc.filed_filename or doc.original_filename}"')
    except Exception: pass
    return jsonify({"ok": True, "po": _po_to_dict(po, with_rollup=True, project_id=pid)})


@app.route("/projects/<int:pid>/pos/<int:po_id>/attach-doc", methods=["POST"])
@login_required
def po_attach_doc(pid, po_id):
    """Attach an additional DocUpload (typically an estimate / quote /
    invoice) to an existing PO. Body: {doc_upload_id, bump_cap (bool),
    note}. When bump_cap is true and the doc has an amount + the PO has
    a cap, increment the cap by the doc's amount. Returns updated PO."""
    from models import PurchaseOrder, PoDocAttachment
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    po = PurchaseOrder.query.filter_by(id=po_id, project_id=pid).first_or_404()
    data = request.get_json(force=True) or {}
    raw = data.get('doc_upload_id')
    if not raw:
        return jsonify({"error": "doc_upload_id required"}), 400
    try:
        doc_id = int(raw)
    except (TypeError, ValueError):
        return jsonify({"error": "doc_upload_id must be int"}), 400
    doc = DocUpload.query.filter_by(id=doc_id, project_id=pid).first()
    if not doc:
        return jsonify({"error": "DocUpload not on this project"}), 404
    # Already attached? Bail with a friendly message.
    existing = PoDocAttachment.query.filter_by(po_id=po.id, doc_upload_id=doc.id).first()
    if existing:
        return jsonify({"error": "Doc already attached to this PO"}), 409
    bump_cap = bool(data.get('bump_cap', True))
    note = (data.get('note') or '').strip()[:300] or None
    att = PoDocAttachment(
        po_id=po.id, doc_upload_id=doc.id,
        amount=doc.amount, role='additional',
        note=note or (f'Added: {doc.filed_filename or doc.original_filename or f"Doc #{doc.id}"}'),
        created_by_user_id=current_user.id if current_user.is_authenticated else None,
    )
    db.session.add(att)
    cap_delta = 0
    if bump_cap and doc.amount is not None and po.total_committed is not None:
        cap_delta = float(doc.amount)
        po.total_committed = round(float(po.total_committed) + cap_delta, 2)
    db.session.commit()
    try:
        _log_activity(action='update', entity_type='purchase_order',
                      entity_id=po.id, entity_label=f"{po.po_number} — {po.vendor_name}",
                      project_id=pid,
                      note=(f'Attached "{doc.filed_filename or doc.original_filename}"'
                            + (f' (+${cap_delta:,.2f} to cap)' if cap_delta else '')))
    except Exception: pass
    return jsonify({"ok": True, "po": _po_to_dict(po, with_rollup=True, project_id=pid)})


@app.route("/projects/<int:pid>/pos/<int:po_id>/detach-doc/<int:att_id>", methods=["POST"])
@login_required
def po_detach_doc(pid, po_id, att_id):
    """Remove a doc attachment from a PO (the file stays in Docs). Body:
    {adjust_cap}. When adjust_cap is true and the PO has a cap, reduce the
    cap by the (non-superseded) attachment's amount. If the removed doc was
    the PO's source estimate, clear source_doc_upload_id too. (Replace is the
    history-preserving path; this is the hard remove for mistakes.)"""
    from models import PurchaseOrder, PoDocAttachment
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    po = PurchaseOrder.query.filter_by(id=po_id, project_id=pid).first_or_404()
    att = PoDocAttachment.query.filter_by(id=att_id, po_id=po_id).first_or_404()
    data = request.get_json(silent=True) or {}
    adjust_cap = bool(data.get('adjust_cap'))
    cap_delta = 0.0
    if (adjust_cap and not getattr(att, 'superseded_at', None)
            and att.amount is not None and po.total_committed is not None):
        cap_delta = -float(att.amount)
        po.total_committed = round(max(0.0, float(po.total_committed) + cap_delta), 2)
    if po.source_doc_upload_id == att.doc_upload_id:
        po.source_doc_upload_id = None
    db.session.delete(att)
    db.session.commit()
    return jsonify({"ok": True, "po": _po_to_dict(po, with_rollup=True, project_id=pid)})


@app.route("/projects/<int:pid>/pos/<int:po_id>/replace-estimate", methods=["POST"])
@login_required
def po_replace_estimate(pid, po_id):
    """Replace an attached estimate with an updated quote, preserving history.
    Body: {old_att_id, new_doc_upload_id, adjust_cap, note}. Attaches the new
    doc (same role as the old), stamps the old one superseded (kept on the PO,
    struck through, excluded from totals), repoints source_doc_upload_id when
    the source is the one being replaced, and shifts the cap by
    (new_amount - old_amount) when adjust_cap. (User 2026-06-15.)"""
    from models import PurchaseOrder, PoDocAttachment
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    po = PurchaseOrder.query.filter_by(id=po_id, project_id=pid).first_or_404()
    data = request.get_json(force=True) or {}
    try:
        old_att_id = int(data.get('old_att_id'))
        new_doc_id = int(data.get('new_doc_upload_id'))
    except (TypeError, ValueError):
        return jsonify({"error": "old_att_id and new_doc_upload_id are required"}), 400
    old = PoDocAttachment.query.filter_by(id=old_att_id, po_id=po.id).first_or_404()
    if getattr(old, 'superseded_at', None):
        return jsonify({"error": "That estimate is already superseded."}), 409
    new_doc = DocUpload.query.filter_by(id=new_doc_id, project_id=pid).first()
    if not new_doc:
        return jsonify({"error": "Replacement doc not on this project"}), 404
    # Block attaching the same doc, or a doc already actively attached.
    if new_doc.id == old.doc_upload_id:
        return jsonify({"error": "Pick a different document than the one being replaced."}), 400
    dupe = (PoDocAttachment.query
            .filter_by(po_id=po.id, doc_upload_id=new_doc.id)
            .filter(PoDocAttachment.superseded_at.is_(None)).first())
    if dupe:
        return jsonify({"error": "That document is already attached to this PO."}), 409
    note = (data.get('note') or '').strip()[:300] or None
    adjust_cap = bool(data.get('adjust_cap', True))
    old_label = None
    _od = db.session.get(DocUpload, old.doc_upload_id)
    if _od:
        old_label = _od.filed_filename or _od.original_filename or f"Doc #{_od.id}"
    new_att = PoDocAttachment(
        po_id=po.id, doc_upload_id=new_doc.id, amount=new_doc.amount,
        role=old.role or 'additional',
        note=note or (f'Updated quote — replaces {old_label}' if old_label else 'Updated quote'),
        created_by_user_id=current_user.id if current_user.is_authenticated else None,
    )
    db.session.add(new_att)
    db.session.flush()                       # need new_att.id for the back-link
    old.superseded_at = datetime.utcnow()
    old.superseded_by_att_id = new_att.id
    if (old.role or '') == 'source' or po.source_doc_upload_id == old.doc_upload_id:
        po.source_doc_upload_id = new_doc.id
    cap_delta = 0.0
    if adjust_cap and po.total_committed is not None:
        cap_delta = float(new_doc.amount or 0) - float(old.amount or 0)
        po.total_committed = round(max(0.0, float(po.total_committed) + cap_delta), 2)
    db.session.commit()
    try:
        _new_label = new_doc.filed_filename or new_doc.original_filename or f"Doc #{new_doc.id}"
        _log_activity(action='update', entity_type='purchase_order',
                      entity_id=po.id, entity_label=f"{po.po_number} — {po.vendor_name}",
                      project_id=pid,
                      note=(f'Replaced estimate "{old_label}" with "{_new_label}"'
                            + (f' (cap {"+"if cap_delta>=0 else ""}${cap_delta:,.2f})' if cap_delta else '')))
    except Exception:
        pass
    return jsonify({"ok": True, "po": _po_to_dict(po, with_rollup=True, project_id=pid)})


@app.route("/projects/<int:pid>/budget/<int:bid>/line/<int:lid>/po", methods=["POST"])
@login_required
def line_assign_po(pid, bid, lid):
    """Assign / unassign a budget line to a PurchaseOrder. Body:
    {po_id: int|null}. Null = unassign. Returns updated rollup so the
    UI can show the cap status without a full reload.

    Cross-version propagation (added 2026-05-19 per user request):
    Per project, the Working budget is the canonical owner of PO
    assignments. When this endpoint is called from a non-Working line
    (Estimated or Actual), it resolves the canonical Working sister
    line via:
      • Actual line  → BudgetLine.source_line_id (the explicit clone
                        backlink to its Working source)
      • Estimated line → (account_code, sort_order) match on the
                          project's current Working budget
    Then writes po_id on the Working sister AND on every Actual clone
    of that Working line (so PO rollups stay consistent without
    requiring a re-clone). The clicked line — including an Estimated
    one — also stores its own po_id (see below), so its badge renders
    from its own value and falls back to the Working sister key match
    only when its own po_id is unset.

    Net effect for the user: clicking the +PO badge in any view
    edits the project-wide assignment, and the badge re-renders
    correctly on all three views after refresh.
    """
    Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    _require_project_role(pid, 'editor')
    ln = BudgetLine.query.filter_by(id=lid, budget_id=bid).first_or_404()
    data = request.get_json(force=True) or {}
    raw = data.get('po_id')
    from models import PurchaseOrder

    # Resolve the new po_id value first (None vs validated integer).
    new_po_id = None
    if raw in (None, '', 'null', 0):
        new_po_id = None
    else:
        try:
            new_po_id = int(raw)
        except (TypeError, ValueError):
            return jsonify({"error": "po_id must be an integer or null"}), 400
        po = PurchaseOrder.query.filter_by(id=new_po_id, project_id=pid).first()
        if not po:
            return jsonify({"error": "PurchaseOrder not found on this project"}), 404

    # ── Resolve the canonical Working sister line ──────────────────────
    # Same project, mode=working, version_status preferred 'current'.
    canonical_working = None
    _wb = (Budget.query
           .filter_by(project_id=pid, budget_mode='working',
                      version_status='current')
           .filter(Budget.is_actual == False)
           .order_by(Budget.id.desc()).first())
    if not _wb:
        _wb = (Budget.query
               .filter_by(project_id=pid, budget_mode='working')
               .filter(Budget.is_actual == False)
               .filter(Budget.version_status != 'archived')
               .order_by(Budget.id.desc()).first())

    line_budget = Budget.query.get(bid)
    _is_working_line = (line_budget
                        and line_budget.budget_mode == 'working'
                        and not line_budget.is_actual)
    _is_actual_line  = bool(line_budget and line_budget.is_actual)

    if _is_working_line:
        canonical_working = ln
    elif _wb:
        if _is_actual_line and ln.source_line_id:
            # Actual → explicit backlink wins (most accurate).
            canonical_working = (BudgetLine.query
                                 .filter_by(id=ln.source_line_id,
                                            budget_id=_wb.id).first())
        if not canonical_working:
            # Fall back to (account_code, sort_order) match — same
            # rule the read-only badge uses to render Working PO on
            # Estimated/Actual rows.
            canonical_working = (BudgetLine.query
                                 .filter_by(budget_id=_wb.id,
                                            account_code=ln.account_code,
                                            sort_order=ln.sort_order)
                                 .first())

    # Apply to the line that was clicked (so the UI roundtrips correctly
    # without a full refresh on the same view) AND, separately, to the
    # canonical Working line + every Actual clone of that Working line.
    touched_ids = set()
    ln.po_id = new_po_id
    touched_ids.add(ln.id)

    if canonical_working and canonical_working.id != ln.id:
        canonical_working.po_id = new_po_id
        touched_ids.add(canonical_working.id)

    # Propagate to Actual clones of the canonical Working line.
    if canonical_working:
        for actual_clone in BudgetLine.query.filter_by(
                source_line_id=canonical_working.id).all():
            if actual_clone.id in touched_ids:
                continue
            actual_clone.po_id = new_po_id
            touched_ids.add(actual_clone.id)

    db.session.commit()

    # Return the updated PO rollup so the row UI can render the cap badge.
    out = {"ok": True, "po_id": ln.po_id, "touched_line_ids": sorted(touched_ids)}
    if ln.po_id:
        po = PurchaseOrder.query.get(ln.po_id)
        if po:
            out["po"] = _po_to_dict(po, with_rollup=True, project_id=pid)
    return out


# ── Sub-Budgets (2026-05-26) ─────────────────────────────────────────────
# User-defined slices of a project budget. Function parallel to POs but
# many-to-many with budget lines (so a line can be in multiple slices
# without contention with a PO assignment). Render on the same /pos page
# under their own section heading. Each one can be exported as a mini-
# PDF (filtered subset of the parent budget) for client handoff.

def _sub_budget_to_dict(sb, *, with_rollup=False, project_id=None,
                        return_budget=None):
    """Serialize a SubBudget. with_rollup adds lines_total, billed_total
    (sum of transactions on the included lines), cap status, and a
    per-line breakdown. Mirrors _po_to_dict's shape so the template
    can render both POs and sub-budgets with similar card markup."""
    out = {
        "id":              sb.id,
        "name":            sb.name,
        "description":     sb.description or "",
        "total_committed": float(sb.total_committed) if sb.total_committed is not None else None,
        "notes":           sb.notes or "",
        "archived":        bool(sb.archived),
        "budget_id":       sb.budget_id,
        "created_at":      sb.created_at.isoformat() if sb.created_at else None,
    }
    if not with_rollup:
        return out

    # Resolve the canonical Working budget for this project — same
    # picker _po_to_dict uses so totals reconcile.
    pid = project_id or sb.project_id
    canonical = (Budget.query
                 .filter_by(project_id=pid, version_status='current',
                            is_actual=False)
                 .filter(db.or_(Budget.budget_mode == 'working',
                               db.and_(Budget.budget_mode == None,
                                       Budget.parent_budget_id.isnot(None))))
                 .order_by(Budget.id.desc()).first())
    if not canonical:
        canonical = (Budget.query
                     .filter_by(project_id=pid, version_status='current',
                                is_actual=False)
                     .order_by(Budget.id.desc()).first())

    # Pull every line assigned to this sub-budget. Filter to the canonical
    # Working budget's line ids so cross-version clones don't double-count.
    sbl_q = (db.session.query(SubBudgetLine, BudgetLine)
             .join(BudgetLine, BudgetLine.id == SubBudgetLine.budget_line_id)
             .filter(SubBudgetLine.sub_budget_id == sb.id))
    if canonical:
        sbl_q = sbl_q.filter(BudgetLine.budget_id == canonical.id)
    sbl_q = sbl_q.order_by(SubBudgetLine.sort_order,
                           BudgetLine.account_code,
                           BudgetLine.sort_order,
                           BudgetLine.id)
    raw_rows = list(sbl_q.all())

    # ── Per-line total — compute via calc_line()/calc_line_from_schedule()
    # instead of reading the stored estimated_total field. Many lines
    # (labor with qty/days/rate, schedule-driven per-diem/hotel/flight,
    # etc.) don't have estimated_total populated on the DB row — it's
    # computed at render time from qty × days × rate (+ fringes for
    # labor). Using calc_line ensures the sub-budget card shows the
    # SAME total the user sees in the Budget tab. Per user report
    # 2026-05-26: "it doesn't show the total of the lines currently."
    line_rows = []
    if raw_rows and canonical:
        try:
            fringe_cfgs = get_fringe_configs(db.session, pid)
            _profile  = canonical.payroll_profile
            _pw_start = canonical.payroll_week_start if canonical.payroll_week_start is not None else (
                _profile.payroll_week_start if _profile else 6)
            _sched_mode = 'working' if canonical.budget_mode in ('working', 'actual') else 'estimated'
            for sbl, ln in raw_rows:
                # Use calc_line_from_schedule() for use_schedule lines so
                # the displayed total matches the gantt-driven computation.
                _sched_days_n = None
                if ln.use_schedule:
                    # MIRROR budget_view's fetch exactly: legacy rows carry
                    # schedule_mode NULL and must count, deduped per
                    # (instance, date) with the mode-tagged row winning.
                    # The old strict mode filter dropped legacy days —
                    # user report 2026-07-22: "5 days in the budget and
                    # schedule, but the sub budget shows 4 days".
                    _raw_sd = ScheduleDay.query.filter(
                        ScheduleDay.budget_line_id == ln.id,
                        db.or_(ScheduleDay.schedule_mode == _sched_mode,
                               ScheduleDay.schedule_mode == None)).all()
                    _dd = {}
                    for _d in _raw_sd:
                        _k = (_d.crew_instance or 1, _d.date)
                        _ex = _dd.get(_k)
                        if _ex is None or (_ex.schedule_mode is None
                                           and _d.schedule_mode == _sched_mode):
                            _dd[_k] = _d
                    _sched = list(_dd.values())
                    _res = calc_line_from_schedule(ln, _sched, fringe_cfgs, _profile, _pw_start)
                    # Weighted billable days from the calc (half day = 0.5)
                    # so the card's days column matches the budget's.
                    _sched_days_n = _res.get('day_count')
                else:
                    _res = calc_line(ln, fringe_cfgs)
                _eff_total = float(_res.get('est_total') or 0)
                line_rows.append({
                    "assignment_id":   sbl.id,
                    "id":              ln.id,
                    "account_code":    ln.account_code,
                    "description":     ln.description or ln.account_name or "",
                    "qty":             float(ln.quantity or 0),
                    # Schedule-driven lines show the SCHEDULE's day count,
                    # not the stale stored days field.
                    "days":            (float(_sched_days_n)
                                        if _sched_days_n is not None
                                        else float(ln.days or 0)),
                    "rate":            float(ln.rate or 0),
                    "estimated_total": _eff_total,
                    "is_labor":        bool(ln.is_labor),
                    "note":            sbl.note or "",
                })
        except Exception as _ce:
            logging.warning(f"[sub_budget] line total calc failed for sb={sb.id}: {_ce}")
            # Fall back to stored estimated_total so we still render something.
            for sbl, ln in raw_rows:
                line_rows.append({
                    "assignment_id":   sbl.id,
                    "id":              ln.id,
                    "account_code":    ln.account_code,
                    "description":     ln.description or ln.account_name or "",
                    "qty":             float(ln.quantity or 0),
                    "days":            float(ln.days or 0),
                    "rate":            float(ln.rate or 0),
                    "estimated_total": float(ln.estimated_total or 0),
                    "is_labor":        bool(ln.is_labor),
                    "note":            sbl.note or "",
                })

    lines_total = round(sum(r["estimated_total"] for r in line_rows), 2)
    line_count  = len(line_rows)

    # Actualized = sum of Transaction.amount for transactions linked to
    # any line in this sub-budget (either directly via budget_line_id or
    # via the Working sister through source_line_id, same OR pattern
    # _po_to_dict uses). Excludes not-project-expense / non-expense /
    # estimate-linked txns.
    billed = 0.0
    try:
        from sqlalchemy import or_ as _or_sb, func as _func_sb
        _line_ids = [r["id"] for r in line_rows]
        if _line_ids:
            _working_lines_sub = (db.session.query(BudgetLine.id)
                                  .filter(BudgetLine.id.in_(_line_ids))
                                  .subquery())
            _billed_q = (db.session
                         .query(_func_sb.coalesce(_func_sb.sum(_signed_amount()), 0))
                         .join(BudgetLine, BudgetLine.id == Transaction.budget_line_id)
                         .filter(_or_sb(BudgetLine.id.in_(_line_ids),
                                        BudgetLine.source_line_id.in_(_working_lines_sub)),
                                 Transaction.not_project_expense == False,
                                 _exclude_estimate_linked_txns_clause()))
            billed = float(_billed_q.scalar() or 0)
    except Exception as _bbe:
        logging.warning(f"[sub_budget] billed calc failed for sub_budget={sb.id}: {_bbe}")

    cap         = out["total_committed"]
    over        = (cap is not None and billed > cap)
    remaining   = (cap - billed) if cap is not None else None

    # Group the card's lines by COA section so the sub-budget reads like a
    # mini budget — department header + department subtotal (owner
    # 2026-08-19: "Can sub budgets organize better? Match department org?").
    sections = []
    try:
        from budget_calc import section_for_code, FP_COA_NAMES
        _sec_map = {}
        for _r in line_rows:
            _sc = section_for_code(_r.get("account_code") or 0)
            if _sc not in _sec_map:
                _sec_map[_sc] = {"code": _sc,
                                 "name": FP_COA_NAMES.get(_sc, f"Section {_sc}"),
                                 "lines": [], "subtotal": 0.0}
            _sec_map[_sc]["lines"].append(_r)
            _sec_map[_sc]["subtotal"] += float(_r.get("estimated_total") or 0)
        sections = [dict(s, subtotal=round(s["subtotal"], 2))
                    for s in sorted(_sec_map.values(), key=lambda s: s["code"])]
    except Exception as _sge:
        logging.warning(f"[sub_budget] section grouping failed for sb={sb.id}: {_sge}")

    out.update({
        "lines":         line_rows,
        "sections":      sections,
        "line_count":    line_count,
        "lines_total":   lines_total,
        "billed_total":  round(billed, 2),
        "over_cap":      over,
        "cap_remaining": remaining,
    })
    return out


@app.route("/projects/<int:pid>/sub-budgets/save", methods=["POST"])
@login_required
def sub_budget_save(pid):
    """Create or update a sub-budget. Body:
       { id?: int, name, description?, total_committed?, notes?, archived?, budget_id? }
    Returns the updated sub-budget dict.
    """
    _require_project_role(pid, 'editor')
    ProjectSheet.query.get_or_404(pid)
    data = request.get_json(force=True) or {}
    sb_id = data.get('id')
    if sb_id:
        sb = SubBudget.query.filter_by(id=sb_id, project_id=pid).first_or_404()
    else:
        sb = SubBudget(project_id=pid,
                       created_by_user_id=(current_user.id if current_user.is_authenticated else None))
        db.session.add(sb)
    # Name is required on create; on update, only overwrite if provided.
    if 'name' in data:
        nm = (data.get('name') or '').strip()
        if not nm:
            return jsonify({"error": "Sub-budget name is required"}), 400
        sb.name = nm[:200]
    elif not sb.id:
        return jsonify({"error": "Sub-budget name is required"}), 400
    if 'description' in data:
        sb.description = (data.get('description') or '').strip() or None
    if 'notes' in data:
        sb.notes = (data.get('notes') or '').strip() or None
    if 'total_committed' in data:
        raw = data.get('total_committed')
        if raw in (None, '', 'null'):
            sb.total_committed = None
        else:
            try: sb.total_committed = float(raw)
            except (TypeError, ValueError):
                return jsonify({"error": "total_committed must be a number"}), 400
    if 'archived' in data:
        sb.archived = bool(data.get('archived'))
    if 'budget_id' in data:
        bid = data.get('budget_id')
        if bid in (None, '', 0):
            sb.budget_id = None
        else:
            try: sb.budget_id = int(bid)
            except (TypeError, ValueError):
                return jsonify({"error": "budget_id must be an integer"}), 400
    db.session.commit()
    return jsonify({"ok": True,
                    "sub_budget": _sub_budget_to_dict(sb, with_rollup=True, project_id=pid)})


@app.route("/projects/<int:pid>/sub-budgets/<int:sb_id>/delete", methods=["POST"])
@login_required
def sub_budget_delete(pid, sb_id):
    """Permanent delete (hard=1 query param) OR soft archive."""
    _require_project_role(pid, 'editor')
    sb = SubBudget.query.filter_by(id=sb_id, project_id=pid).first_or_404()
    hard = request.args.get('hard') == '1'
    if hard:
        # Cascade DELETE on sub_budget_line via ON DELETE CASCADE in DDL.
        db.session.delete(sb)
    else:
        sb.archived = True
    db.session.commit()
    return jsonify({"ok": True})


@app.route("/projects/<int:pid>/sub-budgets/<int:sb_id>/lines", methods=["POST"])
@login_required
def sub_budget_add_lines(pid, sb_id):
    """Add one or more BudgetLine rows to this sub-budget.
    Body: { "line_ids": [int, ...] }. Duplicate assignments are silently
    skipped (UniqueConstraint catches them, we just don't fail).
    Returns the updated sub-budget rollup."""
    _require_project_role(pid, 'editor')
    sb = SubBudget.query.filter_by(id=sb_id, project_id=pid).first_or_404()
    data = request.get_json(force=True) or {}
    raw_ids = data.get('line_ids') or []
    if not isinstance(raw_ids, list):
        return jsonify({"error": "line_ids must be a list"}), 400
    try:
        line_ids = [int(x) for x in raw_ids]
    except (TypeError, ValueError):
        return jsonify({"error": "line_ids must be integers"}), 400
    # Filter to lines that belong to this project to prevent cross-project
    # leakage. Join through Budget to verify project_id.
    valid_q = (db.session.query(BudgetLine.id)
               .join(Budget, Budget.id == BudgetLine.budget_id)
               .filter(BudgetLine.id.in_(line_ids),
                       Budget.project_id == pid))
    valid_ids = {r[0] for r in valid_q.all()}
    # Skip ones already in this sub-budget.
    existing_q = (db.session.query(SubBudgetLine.budget_line_id)
                  .filter(SubBudgetLine.sub_budget_id == sb_id,
                          SubBudgetLine.budget_line_id.in_(valid_ids)))
    existing_ids = {r[0] for r in existing_q.all()}
    added = 0
    for lid in valid_ids - existing_ids:
        db.session.add(SubBudgetLine(sub_budget_id=sb_id, budget_line_id=lid))
        added += 1
    db.session.commit()
    return jsonify({"ok": True, "added": added,
                    "sub_budget": _sub_budget_to_dict(sb, with_rollup=True, project_id=pid)})


@app.route("/projects/<int:pid>/sub-budgets/<int:sb_id>/lines/<int:lid>", methods=["DELETE"])
@login_required
def sub_budget_remove_line(pid, sb_id, lid):
    """Remove a budget line from this sub-budget (the underlying
    BudgetLine row is untouched — only the assignment is dropped)."""
    _require_project_role(pid, 'editor')
    sb = SubBudget.query.filter_by(id=sb_id, project_id=pid).first_or_404()
    SubBudgetLine.query.filter_by(sub_budget_id=sb_id, budget_line_id=lid)\
        .delete(synchronize_session=False)
    db.session.commit()
    return jsonify({"ok": True,
                    "sub_budget": _sub_budget_to_dict(sb, with_rollup=True, project_id=pid)})


@app.route("/projects/<int:pid>/sub-budgets.json")
@login_required
def sub_budgets_json(pid):
    """JSON list of sub-budgets for this project. Used by the budget-line
    picker modal to let the user assign a line to a sub-budget from the
    Budget tab. Mirrors /pos.json."""
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'viewer')
    include_archived = request.args.get('include_archived') == '1'
    q = SubBudget.query.filter_by(project_id=pid)
    if not include_archived:
        q = q.filter(SubBudget.archived == False)  # noqa
    sbs = q.order_by(SubBudget.created_at.desc()).all()
    return jsonify({"ok": True,
                    "sub_budgets": [_sub_budget_to_dict(sb, with_rollup=True, project_id=pid)
                                    for sb in sbs]})


