# ── Call Sheet Distribution (foundation) ──────────────────────────────────

# Cache the on-disk stylesheet once — the emailed/archived PDF is the REAL sheet
# rendered through callsheet.html, and weasyprint has no HTTP path back to this
# worker to fetch /static/style.css. So we read it from disk and hand it to
# weasyprint directly (INLINE, not a network <link> fetch). (User 2026-07-09.)
_CALLSHEET_CSS_CACHE = None

def _callsheet_stylesheet_css():
    """Return a weasyprint.CSS built from static/style.css, or None if weasyprint
    is unavailable / the file can't be read. Cached after first successful load."""
    global _CALLSHEET_CSS_CACHE
    if _CALLSHEET_CSS_CACHE is not None:
        return _CALLSHEET_CSS_CACHE
    try:
        import weasyprint
        css_path = os.path.join(app.static_folder or 'static', 'style.css')
        with open(css_path, 'r', encoding='utf-8') as fh:
            _CALLSHEET_CSS_CACHE = weasyprint.CSS(string=fh.read())
    except Exception as e:
        logging.warning(f"[CALLSHEET PDF] stylesheet load failed: {e}")
        _CALLSHEET_CSS_CACHE = None
    return _CALLSHEET_CSS_CACHE


def _render_callsheet_real_pdf(pid, bid, project, budget, selected_date, sched_mode,
                               all_scheduled_dates, view='crew'):
    """Render the REAL call sheet (templates/callsheet.html) to PDF bytes for the
    given audience `view` (crew/talent/client/union/internal).

    This is the layout the owner sees on the site — same template, same CSS —
    rather than the bespoke summary in _render_callsheet_pdf_html. It renders in
    pdf_mode + recipient_mode so:
      • the JS-only sections (Key Personnel, Hospitals, Extras, Dept Notes,
        Useful Contacts) are rendered SERVER-SIDE (no JS runs in weasyprint),
      • per-day `hidden` + `text_overrides` are applied SERVER-SIDE (the JS gap),
      • all <script>/editing chrome is dropped.
    The stylesheet is inlined (see _callsheet_stylesheet_css) so weasyprint never
    has to fetch anything over the network. Returns bytes, or None on any failure
    (caller falls back to the legacy renderer). (User 2026-07-09.)"""
    try:
        import weasyprint
    except Exception as e:
        logging.warning(f"[CALLSHEET PDF] weasyprint unavailable: {e}")
        return None
    try:
        ctx = _callsheet_full_context(
            pid, bid, project, budget, selected_date, sched_mode,
            all_scheduled_dates)
        # In pdf_mode the logo layer must embed as base64 data: URIs — weasyprint
        # must not fetch /logos/…/raw back over the network.
        ctx['cs_logos'] = _resolve_callsheet_logos(
            ctx.get('cs_data') or {}, project, embed=True)
        cs_view, csv_flags = _callsheet_audience_flags(view)
        html_str = render_template(
            "callsheet.html",
            recipient_mode=True,   # read-only render (suppresses editing chrome)
            pdf_mode=True,         # server-side JS-section render + no <script>
            preview_mode=False,
            rec=None, send=None, token=None,
            already_confirmed=False,
            confirmed_local=None, viewed_local=None,
            personal_call='', personal_travel=[],
            date_display=selected_date.strftime("%A, %B %-d, %Y"),
            cs_view=cs_view,
            csv=csv_flags,
            **ctx,
        )
        css = _callsheet_stylesheet_css()
        stylesheets = [css] if css is not None else None
        # base_url lets weasyprint resolve any remaining relative refs from disk;
        # the stylesheet itself is passed inline above so this is only a fallback.
        pdf_bytes = weasyprint.HTML(
            string=html_str, base_url=app.static_folder or 'static'
        ).write_pdf(stylesheets=stylesheets)
        return pdf_bytes
    except Exception as e:
        logging.warning(f"[CALLSHEET PDF] real-template render failed "
                        f"(view={view}): {type(e).__name__}: {e}")
        return None


def _build_callsheet_pdf_bytes(pid, bid, project, budget, selected_date, sched_mode,
                               send_obj, view='crew'):
    """Build a COMPLETE call-sheet PDF (bytes) + suggested filename for one day.

    Reuses _callsheet_full_context so the crew grid, meals, and locations are
    the real assembled sheet (crew_rows is no longer empty). Shared by the
    prepare-send flow and the download/regenerate route so a legacy send with
    no stored pdf_data can still be reconstructed. Returns (pdf_bytes_or_None,
    filename). weasyprint is optional — pdf_bytes may be None. (User 2026-07-09.)"""
    # All scheduled (non-off) dates for this budget/mode — needed by full ctx.
    _date_rows = db.session.query(ScheduleDay.date).filter(
        ScheduleDay.budget_id == bid,
        ScheduleDay.schedule_mode == sched_mode,
        ScheduleDay.day_type != 'off',
    ).distinct().order_by(ScheduleDay.date).all()
    all_scheduled_dates = [r[0] for r in _date_rows]

    ctx = _callsheet_full_context(
        pid, bid, project, budget, selected_date, sched_mode, all_scheduled_dates)
    cs_data_dict = ctx.get('cs_data') or {}

    # Resolve each person's individual call time from the saved crew_call_times
    # (keyed "sec||role||name"), else fall back to the general crew call.
    cct = cs_data_dict.get('crew_call_times') or {}
    general_call = cs_data_dict.get('general_crew_call', '') or ''
    _by_name = {}
    for key, t in cct.items():
        nm = key.split('||')[-1].strip().lower()
        if nm and t:
            _by_name.setdefault(nm, t)

    crew_grid = []
    for r in ctx.get('crew_p2_all', []):
        nm = (r.get('name') or '').strip()
        call = _by_name.get(nm.lower(), '') or general_call or ''
        crew_grid.append({
            'section': r.get('p2_section') or r.get('section_name') or '',
            'role':    r.get('role') or '',
            'name':    nm or '—',
            'call':    call,
        })

    date_display = selected_date.strftime("%A, %B %-d, %Y")

    # PRIMARY: render the REAL sheet (callsheet.html) for the requested audience
    # view — this is the on-site layout the owner asked for. FALLBACK: if that
    # render fails or is suspiciously tiny (<5KB → something went wrong), drop to
    # the legacy bespoke summary so a send never loses its attachment.
    pdf_bytes = _render_callsheet_real_pdf(
        pid, bid, project, budget, selected_date, sched_mode,
        all_scheduled_dates, view=view)
    if not pdf_bytes or len(pdf_bytes) < 5120:
        if pdf_bytes:
            logging.warning("[CALLSHEET PDF] real render suspiciously small "
                            f"({len(pdf_bytes)} bytes) — falling back to legacy.")
        pdf_bytes = _generate_callsheet_pdf(
            send_obj=send_obj,
            project_name=project.name,
            date_display=date_display,
            cs_data=cs_data_dict,
            crew_rows=[],
            locations_today=ctx.get('locations_today') or [],
            crew_grid=crew_grid,
            meal_counts=ctx.get('meal_counts') or {},
        )
    version_label = (getattr(send_obj, 'version_label', '') or 'v1')
    filename = (f"CallSheet_{project.name.replace(' ', '_')}_"
                f"{selected_date.isoformat()}_{version_label}.pdf")
    return pdf_bytes, filename


def _archive_callsheet_to_dropbox(project, selected_date, version_label, pdf_bytes):
    """Mirror a sent call-sheet PDF into the project's Dropbox admin folder at
    01_ADMIN/CALL SHEETS/CallSheet_<YYYY-MM-DD>_<version>.pdf. The date is in the
    filename (owner: "with the date"). Returns the dropbox path or None.

    FAIL-OPEN: any error is swallowed with a warning — archiving must NEVER
    block or fail the send. (User 2026-07-09.)"""
    if not pdf_bytes or not getattr(project, 'dropbox_folder', None):
        return None
    try:
        dbx = _dbx_client()
    except Exception as e:
        logging.warning(f"[CALLSHEET ARCHIVE] Dropbox client unavailable: {e}")
        return None
    try:
        proj_root = (f"/{project.dropbox_folder.strip('/')}" if _DBX_NAMESPACE_ID
                     else f"{_DBX_OPS_ROOT}/{project.dropbox_folder.strip('/')}")
        _ver = re.sub(r"[^\w\-]+", "_", (version_label or 'v1')).strip('_') or 'v1'
        fname = f"CallSheet_{selected_date.isoformat()}_{_ver}.pdf"
        dbx_path = f"{proj_root}/01_ADMIN/CALL SHEETS/{fname}"
        from dropbox.files import WriteMode as _WM
        # overwrite: re-sending the same version replaces the prior artifact for
        # that version; different version labels get distinct filenames.
        dbx.files_upload(pdf_bytes, dbx_path, autorename=False, mode=_WM('overwrite'))
        logging.info(f"[CALLSHEET ARCHIVE] uploaded → {dbx_path}")
        return dbx_path
    except Exception as e:
        logging.warning(f"[CALLSHEET ARCHIVE] upload failed (non-fatal): "
                        f"{type(e).__name__}: {e}")
        return None


@app.route("/projects/<int:pid>/budget/<int:bid>/callsheet/<date_str>/distribution")
@login_required
def callsheet_distribution(pid, bid, date_str):
    """Get send history + recipient list for this call sheet day."""
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'
    try:
        selected_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        return jsonify({"error": "invalid date"}), 400
    sends = CallSheetSend.query.filter_by(
        budget_id=bid, date=selected_date, schedule_mode=sched_mode
    ).order_by(CallSheetSend.sent_at.desc()).all()
    # Config surface (booleans only — never expose secrets). mail_configured =
    # Flask-Mail has a username; sms_configured = all three Twilio env vars set.
    mail_configured = bool(app.config.get('MAIL_USERNAME'))
    sms_configured = bool(os.getenv('TWILIO_ACCOUNT_SID', '')
                          and os.getenv('TWILIO_AUTH_TOKEN', '')
                          and os.getenv('TWILIO_FROM_NUMBER', ''))
    # All display times in the BUDGET's timezone (Settings picker) — raw
    # isoformat strings were being rendered browser-local / raw UTC before.
    _tz = getattr(budget, "timezone", None) or "America/New_York"

    def _loc_dt(dt):
        if not dt:
            return None
        try:
            from zoneinfo import ZoneInfo
            local = dt.replace(tzinfo=ZoneInfo('UTC')).astimezone(ZoneInfo(_tz))
            return local.strftime('%b %-d, %-I:%M %p')
        except Exception:
            return dt.strftime('%b %-d, %-I:%M %p')

    return jsonify({
        "mail_configured": mail_configured,
        "sms_configured": sms_configured,
        "timezone": _tz,
        "sends": [{
            "id": s.id,
            "version_label": s.version_label or "",
            "sent_at": s.sent_at.isoformat() if s.sent_at else None,
            "sent_at_local": _loc_dt(s.sent_at),
            "sent_by": s.sent_by or "",
            "notes": s.notes or "",
            "pdf_url": url_for('callsheet_send_pdf', pid=pid, bid=bid, send_id=s.id),
            "has_pdf": bool(s.pdf_data),
            "archived": bool(s.dropbox_path),
            "recipients": [{
                "id": r.id, "name": r.name, "email": r.email or "",
                "type": r.recipient_type, "status": r.status,
                "viewed_at": r.viewed_at.isoformat() if r.viewed_at else None,
                "viewed_at_local": _loc_dt(r.viewed_at),
                "confirmed_at": r.confirmed_at.isoformat() if r.confirmed_at else None,
                "confirmed_at_local": _loc_dt(r.confirmed_at),
            } for r in s.recipients],
        } for s in sends],
    })


def _rep_view_maps(budget):
    """H6b (2026-07-20): ONE eager-loaded pass over the budget's labor lines →
    {support-contact email → view} and {name → view} maps, replacing the
    per-recipient _rep_recipient_view scans (labor_lines × assignments ×
    support_contacts lazy queries PER rep recipient). Same precedence: email
    hit beats name hit; Talent-section client → 'talent', else 'crew';
    first match in line order wins."""
    email_map, name_map = {}, {}
    if not budget:
        return email_map, name_map
    from sqlalchemy.orm import selectinload
    lines = (BudgetLine.query
             .options(selectinload(BudgetLine.crew_assignments)
                      .selectinload(CrewAssignment.crew_member)
                      .selectinload(CrewMember.support_contacts))
             .filter_by(budget_id=budget.id, is_labor=True).all())
    for ln in lines:
        view = 'talent' if ln.account_code == COA_CODE_TALENT else 'crew'
        for ca in ln.crew_assignments:
            cm = ca.crew_member if ca.crew_member_id else None
            if not (cm and cm.support_contacts):
                continue
            for sc in cm.support_contacts:
                if not sc.active:
                    continue
                e = (sc.email or '').strip().lower()
                n = (sc.name or '').strip().lower()
                if e and e not in email_map:
                    email_map[e] = view
                if n and n not in name_map:
                    name_map[n] = view
    return email_map, name_map


def _callsheet_send_worker(flask_app, pid, bid, send_id, view_by_rec_id,
                           audience_messages, host_url):
    """H1b (2026-07-20): the delivery half of a call-sheet send — PDF builds,
    Dropbox archive, and the per-recipient email/SMS loop — off the request
    thread. Progress is committed PER RECIPIENT (status 'sent'/'failed'), so
    the Send History reflects live state and a worker death mid-loop loses
    nothing already delivered. Was: 30 recipients = 30 sequential blocking
    provider calls inside one web request."""
    with flask_app.app_context():
        try:
            send = CallSheetSend.query.get(send_id)
            if send is None:
                return
            budget = Budget.query.get(bid)
            project = ProjectSheet.query.get(pid)
            selected_date = send.date
            sched_mode = send.schedule_mode
            version_label = send.version_label or 'v1'
            date_display = selected_date.strftime("%A, %B %-d, %Y")

            cs_rec = CallSheetData.query.filter_by(
                budget_id=bid, date=selected_date, schedule_mode=sched_mode).first()
            cs_data_dict = (json.loads(cs_rec.data_json)
                            if cs_rec and cs_rec.data_json else {})
            from models import LocationDay, Location
            loc_day_ids = [ld.location_id for ld in LocationDay.query.filter_by(
                budget_id=bid, date=selected_date).all()]
            pdf_locations = (Location.query
                             .filter(Location.id.in_(loc_day_ids)).all()
                             if loc_day_ids else [])

            _pdf_by_view = {}

            def _pdf_for_view(_view):
                if _view not in _pdf_by_view:
                    _b, _f = _build_callsheet_pdf_bytes(
                        pid, bid, project, budget, selected_date, sched_mode,
                        send, view=_view)
                    _pdf_by_view[_view] = (_b, _f)
                return _pdf_by_view[_view]

            recipients = list(send.recipients)
            _needed_views = {view_by_rec_id.get(r.id) or
                             _recipient_view_for_type(r.recipient_type)
                             for r in recipients}
            _needed_views.add('crew')
            for _v in _needed_views:
                _pdf_for_view(_v)

            crew_pdf_bytes, crew_pdf_filename = _pdf_by_view.get('crew', (None, None))
            if crew_pdf_bytes:
                send.pdf_data = crew_pdf_bytes
                send.pdf_filename = crew_pdf_filename
                send.dropbox_path = _archive_callsheet_to_dropbox(
                    project, selected_date, version_label, crew_pdf_bytes)
                db.session.commit()

            first_loc = pdf_locations[0] if pdf_locations else None
            loc_sms_line = ""
            if first_loc:
                loc_sms_line = f"\nLocation: {first_loc.name or ''}"
                if getattr(first_loc, 'address', None):
                    loc_sms_line += f"\n{first_loc.address}"

            cct = cs_data_dict.get('crew_call_times') or {}
            general_call = cs_data_dict.get('general_crew_call', '') or ''

            def _msg_for(rtype, field):
                view = audience_messages.get(rtype) or {}
                val = (view.get(field) or '').strip()
                if val:
                    return val
                dflt = audience_messages.get('default') or {}
                return (dflt.get(field) or '').strip()

            def _fill(tmpl, name, call_display, view_url):
                return (tmpl
                        .replace('{name}', name or '')
                        .replace('{call}', call_display or '')
                        .replace('{date}', date_display)
                        .replace('{project}', project.name)
                        .replace('{version}', version_label)
                        .replace('{link}', view_url))

            for rec in recipients:
                email = rec.email or ''
                phone = rec.phone or ''
                personal_call = ''
                name_lower = (rec.name or '').lower()
                for key, t in cct.items():
                    if key.split('||')[-1].strip().lower() == name_lower:
                        personal_call = t
                        break
                call_display = personal_call or general_call or 'TBD'
                view_url = host_url.rstrip('/') + f"/callsheet/view/{rec.confirm_token}"
                rtype = rec.recipient_type or 'crew'

                subject_tmpl = _msg_for(rtype, 'subject')
                if subject_tmpl:
                    subject = _fill(subject_tmpl, rec.name, call_display, view_url)
                else:
                    subject = f"Call Sheet — {project.name} — {date_display} ({version_label})"

                body_tmpl = _msg_for(rtype, 'body')
                if body_tmpl:
                    body = _fill(body_tmpl, rec.name, call_display, view_url)
                    if view_url not in body:
                        body = body.rstrip() + f"\n\nView & confirm your call: {view_url}\n"
                else:
                    body = (
                        f"Hi {rec.name},\n\n"
                        f"Your call sheet for {project.name} on {date_display} is ready.\n"
                        f"Your call time: {call_display}\n\n"
                        f"View & confirm your call: {view_url}\n\n"
                        f"Please confirm receipt by clicking the link above.\n\n"
                        f"— Framework Productions · contact@thefp.tv\n"
                    )
                _rec_pdf_bytes, _rec_pdf_filename = _pdf_for_view(
                    view_by_rec_id.get(rec.id) or _recipient_view_for_type(rtype))
                if not _rec_pdf_bytes:
                    _rec_pdf_bytes, _rec_pdf_filename = crew_pdf_bytes, crew_pdf_filename

                email_ok = None
                sms_ok = None
                if email:
                    email_ok = _send_email(email, subject, body,
                                           attachment_bytes=_rec_pdf_bytes,
                                           attachment_filename=_rec_pdf_filename)
                    if email_ok:
                        rec.status = "sent"
                if phone:
                    sms_lines = [
                        f"{project.name} — Call Sheet {date_display}",
                        f"Hi {rec.name}, your call: {call_display}",
                    ]
                    if body_tmpl:
                        first_line = _fill(body_tmpl, rec.name, call_display,
                                           view_url).strip().splitlines()
                        first_line = (first_line[0].strip() if first_line else '')[:140]
                        if first_line and view_url not in first_line:
                            sms_lines.insert(0, first_line)
                    sms_body = ("\n".join(sms_lines)
                                + f"{loc_sms_line}\n"
                                + f"Confirm: {view_url}")
                    sms_ok = _send_sms(phone, sms_body)
                    if sms_ok:
                        if rec.status == "pending":
                            rec.status = "sent"
                # Attempted but nothing went through → visible failure.
                if rec.status == "pending" and (email_ok is False or sms_ok is False):
                    rec.status = "failed"
                db.session.commit()   # per-recipient progress survives crashes
        except Exception as _we:
            logging.exception(f"[callsheet-send] worker failed for send {send_id}: {_we}")
            try:
                import sentry_sdk as _ssdk
                _ssdk.capture_exception(_we)
            except Exception:
                pass
            try:
                db.session.rollback()
                for r in CallSheetRecipient.query.filter_by(
                        send_id=send_id, status='pending').all():
                    r.status = 'failed'
                db.session.commit()
            except Exception:
                pass
        finally:
            try:
                db.session.remove()
            except Exception:
                pass


@app.route("/projects/<int:pid>/budget/<int:bid>/callsheet/<date_str>/prepare-send", methods=["POST"])
@login_required
def callsheet_prepare_send(pid, bid, date_str):
    """Create a CallSheetSend record with recipients and send emails."""
    import secrets as _secrets_mod
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    project = ProjectSheet.query.get_or_404(pid)
    sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'
    try:
        selected_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        return jsonify({"error": "invalid date"}), 400
    data = request.get_json(force=True) or {}
    version_label = data.get("version_label", "v1")
    send = CallSheetSend(
        budget_id=bid,
        date=selected_date,
        schedule_mode=sched_mode,
        version_label=version_label,
        notes=data.get("notes", ""),
        sent_by=ADMIN_EMAIL,
        sent_at=datetime.utcnow(),
    )
    db.session.add(send)
    db.session.flush()
    recipients_in = data.get("recipients", [])
    created_recs = []
    for r in recipients_in:
        token = _secrets_mod.token_urlsafe(32)
        rec = CallSheetRecipient(
            send_id=send.id,
            recipient_type=r.get("type", "crew"),
            name=r.get("name", ""),
            email=r.get("email", ""),
            phone=r.get("phone", "") or None,
            confirm_token=token,
            status="pending",
        )
        db.session.add(rec)
        created_recs.append((rec, r.get("email", ""), r.get("phone", "")))
    db.session.commit()

    date_display = selected_date.strftime("%A, %B %-d, %Y")

    # Build call sheet data for PDF / SMS context
    cs_rec = CallSheetData.query.filter_by(
        budget_id=bid, date=selected_date, schedule_mode=sched_mode).first()
    cs_data_dict = json.loads(cs_rec.data_json) if cs_rec and cs_rec.data_json else {}

    # Build locations list for the SMS summary (first location line).
    from models import LocationDay, Location
    loc_day_ids = [ld.location_id for ld in LocationDay.query.filter_by(
        budget_id=bid, date=selected_date).all()]
    pdf_locations = Location.query.filter(Location.id.in_(loc_day_ids)).all() if loc_day_ids else []

    # Generate ONE PDF PER DISTINCT AUDIENCE VIEW among the checked recipients
    # (crew/talent/client/union → their redacted view of the REAL sheet). Each
    # recipient's email attaches the PDF matching their type. Per-TYPE (not per-
    # recipient): the personal travel card still lives on each person's web link,
    # and per-recipient renders would be dozens of weasyprint passes. Cache keyed
    # by audience view so we render each view at most once. (User 2026-07-09.)
    # H6b: resolve every recipient's audience view from ONE eager-loaded pass
    # (rep rows inherit their client's view; everything else maps by type).
    _rep_email_view, _rep_name_view = _rep_view_maps(budget)
    _view_by_rec_id = {}
    for _r, _e, _p in created_recs:
        _rt = (_r.recipient_type or 'crew').strip().lower()
        if _rt == 'rep':
            _view_by_rec_id[_r.id] = (
                _rep_email_view.get((_r.email or '').strip().lower())
                or _rep_name_view.get((_r.name or '').strip().lower())
                or 'crew')
        else:
            _view_by_rec_id[_r.id] = _recipient_view_for_type(_rt)

    # H1b: PDFs + Dropbox archive + the per-recipient email/SMS loop run in a
    # background thread (same pattern as _duplicate_worker). The response
    # returns immediately; per-recipient status lands in Send History as the
    # worker progresses (committed per recipient).
    audience_messages = data.get("audience_messages")
    if not isinstance(audience_messages, dict):
        audience_messages = cs_data_dict.get('audience_messages') or {}
    _host_url = request.host_url
    import threading as _send_threading
    _send_threading.Thread(
        target=_callsheet_send_worker,
        args=(app, pid, bid, send.id, dict(_view_by_rec_id),
              dict(audience_messages), _host_url),
        daemon=True).start()

    return jsonify({"ok": True, "send_id": send.id, "background": True,
                    "queued": len(created_recs)})


@app.route("/projects/<int:pid>/budget/<int:bid>/callsheet/send/<int:send_id>/pdf")
@login_required
def callsheet_send_pdf(pid, bid, send_id):
    """Download the archived PDF for one sent call-sheet version. Serves the
    exact bytes stored at send time; for legacy sends with no stored pdf_data
    it regenerates from _callsheet_full_context. Project-gated like the
    neighboring callsheet routes. (User 2026-07-09.)"""
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    project = ProjectSheet.query.get_or_404(pid)
    send = CallSheetSend.query.filter_by(id=send_id, budget_id=bid).first_or_404()

    pdf_bytes = send.pdf_data
    fname = send.pdf_filename
    if not pdf_bytes:
        # Legacy send (pre-archive) — reconstruct from the current sheet state.
        sched_mode = send.schedule_mode or (
            'working' if budget.budget_mode in ('working', 'actual') else 'estimated')
        pdf_bytes, fname = _build_callsheet_pdf_bytes(
            pid, bid, project, budget, send.date, sched_mode, send)
    if not pdf_bytes:
        return jsonify({"error": "PDF unavailable (PDF rendering not configured)"}), 503
    if not fname:
        _ver = send.version_label or 'v1'
        fname = (f"CallSheet_{project.name.replace(' ', '_')}_"
                 f"{send.date.isoformat()}_{_ver}.pdf")
    return Response(
        pdf_bytes,
        mimetype="application/pdf",
        headers={"Content-Disposition": _content_disposition_attachment(fname)},
    )


@app.route("/projects/<int:pid>/budget/<int:bid>/callsheet/<date_str>/pdf")
@login_required
def callsheet_current_pdf(pid, bid, date_str):
    """Download the CURRENT (unsent) call sheet for a day as a PDF, regenerated
    live from _callsheet_full_context. Lets the internal view grab a PDF without
    logging a send. (User 2026-07-09.)"""
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    project = ProjectSheet.query.get_or_404(pid)
    sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'
    try:
        selected_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        return jsonify({"error": "invalid date"}), 400
    # Lightweight stand-in for a send row so the renderer has a version label.
    _stub = CallSheetSend(budget_id=bid, date=selected_date,
                          schedule_mode=sched_mode, version_label='current')
    # Internal download = the admin's full copy (view='internal' shows everything:
    # all contacts, reps, background, full crew list — no audience redaction).
    pdf_bytes, fname = _build_callsheet_pdf_bytes(
        pid, bid, project, budget, selected_date, sched_mode, _stub, view='internal')
    if not pdf_bytes:
        return jsonify({"error": "PDF unavailable (PDF rendering not configured)"}), 503
    return Response(
        pdf_bytes,
        mimetype="application/pdf",
        headers={"Content-Disposition": _content_disposition_attachment(fname)},
    )


def _resolve_recipient_crew_member(name, email):
    """Resolve a call-sheet recipient (identified only by name/email — the
    CallSheetRecipient row carries no crew_member_id) to a CrewMember.
    Order: case-insensitive email → CrewMember, else case-insensitive name.
    Returns the CrewMember or None. (User 2026-07-08.)"""
    if email:
        _e = email.strip().lower()
        if _e:
            cm = CrewMember.query.filter(
                db.func.lower(CrewMember.email) == _e).first()
            if cm:
                return cm
    if name:
        _n = name.strip().lower()
        if _n and _n not in ('—', '-'):
            return CrewMember.query.filter(
                db.func.lower(CrewMember.name) == _n).first()
    return None


def _personal_travel_for(budget, selected_date, sched_mode, crew_member, rec_name):
    """Return this recipient's personal travel items for the day — flights,
    hotels (whose check_in..check_out span the date), car rentals — as view
    dicts INCLUDING the confirmation number. Only the recipient's own travel;
    nothing about anyone else. (User 2026-07-08.)

    Linkage matches callsheet_view: TravelDetail → schedule_day_id, so we find
    the recipient's ScheduleDay rows on this budget/mode, plus (for hotels
    spanning multiple days) any of the recipient's ScheduleDays whose hotel
    check_in..check_out range covers selected_date.
    """
    if not budget:
        return []
    # Find the crew member's schedule days on this budget/mode. If we resolved a
    # CrewMember, match via their assignments' budget lines; else fall back to
    # name_override on assignments.
    line_ids_all = [ln.id for ln in BudgetLine.query.filter_by(
        budget_id=budget.id, is_labor=True).all()]
    if not line_ids_all:
        return []
    cas = CrewAssignment.query.filter(
        CrewAssignment.budget_line_id.in_(line_ids_all)).all()
    my_keys = set()  # (budget_line_id, instance)
    for ca in cas:
        matched = False
        if crew_member and ca.crew_member_id == crew_member.id:
            matched = True
        elif (not ca.crew_member_id) and ca.name_override and rec_name and \
                ca.name_override.strip().lower() == rec_name.strip().lower():
            matched = True
        if matched:
            my_keys.add((ca.budget_line_id, ca.instance or 1))
    if not my_keys:
        return []
    my_line_ids = list({k[0] for k in my_keys})
    # ALL of the recipient's schedule days (used to gather their travel rows),
    # scoped to their assignment keys.
    all_my_days = ScheduleDay.query.filter(
        ScheduleDay.budget_id == budget.id,
        ScheduleDay.schedule_mode == sched_mode,
        ScheduleDay.budget_line_id.in_(my_line_ids),
        ScheduleDay.day_type != 'off',
    ).all()
    all_my_days = [d for d in all_my_days
                   if (d.budget_line_id, d.crew_instance or 1) in my_keys]
    # The recipient's schedule days on THIS date (primary travel — flights, cars,
    # and same-day hotels — matches callsheet_view's day linkage exactly).
    today_sd_ids = {d.id for d in all_my_days if d.date == selected_date}
    all_sd_ids   = [d.id for d in all_my_days]
    if not all_sd_ids:
        return []
    tds = TravelDetail.query.filter(
        TravelDetail.schedule_day_id.in_(all_sd_ids)).all()

    def _tm(x): return x.strftime('%-I:%M %p') if x else None
    def _dd(x): return x.strftime('%b %-d') if x else None
    out = []
    for td in tds:
        # Include a travel row when it's linked to a schedule day ON this date,
        # OR (hotels) when its check_in..check_out range spans this date — so a
        # hotel booked against the arrival day still shows on the shoot day.
        on_today = td.schedule_day_id in today_sd_ids
        spans = (td.kind == 'hotel' and td.check_in and td.check_out
                 and td.check_in <= selected_date <= td.check_out)
        if not (on_today or spans):
            continue
        v = {"id": td.id, "kind": td.kind,
             "confirmation_no": td.confirmation_no, "notes": td.notes}
        if td.kind == 'flight':
            v.update(airline=td.airline, flight_no=td.flight_no,
                     depart_airport=td.depart_airport, arrive_airport=td.arrive_airport,
                     depart_at=_tm(td.depart_at), arrive_at=_tm(td.arrive_at))
        elif td.kind == 'hotel':
            v.update(hotel_name=td.hotel_name, hotel_address=td.hotel_address,
                     check_in=_dd(td.check_in), check_out=_dd(td.check_out),
                     room_type=td.room_type)
        elif td.kind == 'car_rental':
            v.update(rental_co=td.rental_co, pickup_location=td.pickup_location,
                     pickup_at=_tm(td.pickup_at), return_at=_tm(td.return_at))
        elif td.kind == 'car_service':
            v.update(rental_co=td.rental_co, pickup_location=td.pickup_location,
                     dropoff_location=td.dropoff_location, contact_phone=td.contact_phone,
                     pickup_at=_tm(td.pickup_at), return_at=_tm(td.return_at),
                     self_report=bool(td.self_report))
        elif td.kind == 'mileage':
            v.update(miles=(str(td.miles) if td.miles is not None else None),
                     route=td.route)
        # Sort key: prefer an explicit time, else the hotel check-in (as a
        # datetime), else sort last. Uniform datetime type avoids date/datetime
        # comparison errors.
        _srt_dt = td.depart_at or td.pickup_at
        if _srt_dt is None and td.check_in is not None:
            _srt_dt = datetime.combine(td.check_in, datetime.min.time())
        if _srt_dt is None:
            _srt_dt = datetime.max
        out.append(((_srt_dt, td.id), v))
    # Multi-entry: order by time then id so two flights / car services on one
    # day read in sequence. Strip the private sort key before returning.
    out.sort(key=lambda pair: pair[0])
    return [v for _k, v in out]


def _rep_recipient_view(budget, rec_name, rec_email):
    """A Representation recipient (an agent/manager) inherits their CLIENT's
    audience view: a rep of talent gets the Talent view, a rep of crew gets the
    Crew view. (User 2026-07-14: "representation should get the same view as
    their client… if their talent → TalentView; if it's rep of a crew → Crew
    view.")

    Resolve the SupportContact this recipient is — scoped to crew members with
    assignments on THIS budget's labor lines (mirrors how rep_contacts itself is
    built) — case-insensitive email first, then name. From SupportContact →
    crew_member → their assignment's budget line: Talent section (COA_CODE_TALENT
    account code) → 'talent', else → 'crew'. Unresolvable → 'crew' (the
    pre-2026-07-14 behavior)."""
    if not budget:
        return 'crew'
    _email = (rec_email or '').strip().lower()
    _name = (rec_name or '').strip().lower()
    if _name in ('—', '-'):
        _name = ''
    if not _email and not _name:
        return 'crew'
    labor_lines = BudgetLine.query.filter_by(
        budget_id=budget.id, is_labor=True).all()
    # Pass 1 matches on email, pass 2 on name — so an email hit always wins over
    # a name hit (same precedence as _resolve_recipient_crew_member).
    for _by_email in (True, False):
        key = _email if _by_email else _name
        if not key:
            continue
        for ln in labor_lines:
            for ca in ln.crew_assignments:
                if not ca.crew_member_id:
                    continue
                cm = ca.crew_member
                if not (cm and cm.support_contacts):
                    continue
                for sc in cm.support_contacts:
                    if not sc.active:
                        continue
                    field = (sc.email if _by_email else sc.name) or ''
                    if field.strip().lower() == key:
                        return ('talent' if ln.account_code == COA_CODE_TALENT
                                else 'crew')
    return 'crew'


def _recipient_view_for_type(rec_type):
    """Map a recipient type → the audience view the recipient sheet renders.
    Crew (and anything unrecognized) get the full Crew view; client-type
    recipients get the Client view; talent get the Talent view. (User
    2026-07-08.)"""
    t = (rec_type or 'crew').strip().lower()
    if t == 'client':
        return 'client'
    if t == 'talent':
        return 'talent'
    if t == 'union':
        # Union recipients get the UNION view — the editor's ?view=union (and
        # its per-view hides) is exactly what they receive. Previously they
        # fell through to 'crew', so the union editor view and the union
        # send/print disagreed. (User 2026-07-13.)
        return 'union'
    return 'crew'


def _rep_client_crew_member(budget, rec_name, rec_email):
    """The crew member a Representation recipient reps. Resolves the SupportContact
    this recipient is — email-CI first, then name, scoped to crew assigned on THIS
    budget's labor lines (mirrors _rep_recipient_view's scan) — and returns its
    crew_member so a rep inherits their CLIENT's individual call time + travel.
    None when unresolvable. (User 2026-07-14: reps should see the call/flight/hotel
    of the person they rep, labeled with that person's name.)"""
    if not budget:
        return None
    _email = (rec_email or '').strip().lower()
    _name = (rec_name or '').strip().lower()
    if _name in ('—', '-'):
        _name = ''
    if not _email and not _name:
        return None
    labor_lines = BudgetLine.query.filter_by(budget_id=budget.id, is_labor=True).all()
    for _by_email in (True, False):
        key = _email if _by_email else _name
        if not key:
            continue
        for ln in labor_lines:
            for ca in ln.crew_assignments:
                if not ca.crew_member_id:
                    continue
                cm = ca.crew_member
                if not (cm and cm.support_contacts):
                    continue
                for sc in cm.support_contacts:
                    if not sc.active:
                        continue
                    field = (sc.email if _by_email else sc.name) or ''
                    if field.strip().lower() == key:
                        return cm
    return None


def _personal_call_for(cs_portal_data, *candidate_names):
    """This person's individual CALL time from crew_call_times (keyed
    sec||role||name — match the last segment by name), else the general crew call.
    Only real per-person OVERRIDES are stored in crew_call_times (non-override
    cells follow the general call and are NOT persisted — see collectCrewCallTimes),
    so any hit here is an intentional individual time that must win over the
    general call. (User 2026-07-14: "the individual's call time, not the general;
    a specific line persists over the general even when the general changes.")

    Matches on ANY of the candidate names — the recipient's send name AND their
    resolved crew-member name — because a crew_assignment name_override can make the
    cast-grid key (crew-member name) differ from the name the send recorded, which
    otherwise left talent showing no call at all. (User 2026-07-14: talent call not
    showing at the top.)"""
    cct = cs_portal_data.get('crew_call_times') or {}
    cands = {(n or '').strip().lower() for n in candidate_names
             if n and (n or '').strip().lower() not in ('', '—', '-')}
    if cands:
        for key, t in cct.items():
            if key.split('||')[-1].strip().lower() in cands and (t or '').strip():
                return t
    return cs_portal_data.get('general_crew_call', '') or ''


def _build_callsheet_recipient_context(send, rec_name, rec_email, rec_type):
    """Shared context builder for the tokenized recipient view AND the
    login-gated preview. Given a send + recipient identity, returns the kwargs
    dict for callsheet.html rendered in recipient_mode — the FULL sheet (crew,
    meals, locations, weather, notes, etc.) via _callsheet_full_context, plus
    the personal layer (this person's call time + travel/confirmations) and the
    forced audience view. Callers add rec/token/confirm state. (User
    2026-07-08.)"""
    date_display = send.date.strftime("%A, %B %-d, %Y") if send else ""
    budget = Budget.query.get(send.budget_id) if send else None
    project = ProjectSheet.query.get(budget.project_id) if budget else None
    cs_portal_data = {}
    cs_locations = []
    sched_mode_p = 'estimated'
    if send and budget:
        sched_mode_p = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'
        cs_rec = CallSheetData.query.filter_by(
            budget_id=send.budget_id, date=send.date, schedule_mode=sched_mode_p).first()
        if cs_rec and cs_rec.data_json:
            try:
                cs_portal_data = json.loads(cs_rec.data_json)
            except Exception:
                pass
        from models import LocationDay, Location
        loc_day_ids = [ld.location_id for ld in LocationDay.query.filter_by(
            budget_id=send.budget_id, date=send.date).all()]
        cs_locations = Location.query.filter(Location.id.in_(loc_day_ids)).all() if loc_day_ids else []

    # Personal-layer SUBJECT: normally the recipient themselves. A Representation
    # recipient (agent/manager) is a PROXY — the call time + travel card refer to
    # the CLIENT they rep, labeled with the client's name so it's clear whose
    # details these are. (User 2026-07-14.)
    _is_rep = (rec_type or '').strip().lower() == 'rep'
    proxy_cm = _rep_client_crew_member(budget, rec_name, rec_email) if _is_rep else None
    personal_is_proxy = bool(proxy_cm and (proxy_cm.name or '').strip())
    subject_name = ((proxy_cm.name if personal_is_proxy else rec_name) or '').strip()
    name_lower = subject_name.lower()

    # Resolve the subject → crew member up front: a rep uses the client (proxy_cm);
    # otherwise the recipient themselves. Used for both the call lookup (its name is
    # a match candidate) and the personal travel below.
    crew_member = proxy_cm or _resolve_recipient_crew_member(rec_name, rec_email)
    _cm_name = (crew_member.name if crew_member and crew_member.name else '')
    personal_call = _personal_call_for(cs_portal_data, subject_name, _cm_name)

    # Cast time grid: the SUBJECT's own pickup/HMU/on-set/wrap/drop-off, keyed
    # (like crew_call_times) by the last ||-segment (name). talent_times is a
    # {key: {field: time}} dict; CALL is intentionally NOT here (it rides
    # crew_call_times → personal_call above). (2026-07-14.)
    tt_all = cs_portal_data.get('talent_times') or {}
    personal_talent_times = {}
    for key, vals in tt_all.items():
        if isinstance(vals, dict) and key.split('||')[-1].strip().lower() == name_lower:
            personal_talent_times = vals
            break

    # Personal travel (with confirmations) for the SUBJECT's crew member (resolved
    # above) — a rep sees the client's flight/hotel/car.
    personal_travel = []
    if send and budget:
        personal_travel = _personal_travel_for(
            budget, send.date, sched_mode_p, crew_member, subject_name)

    # Timezone lives on BUDGET (the Settings-tab picker) — the old
    # project-attr lookup always fell through to New York. (User 2026-07-09:
    # "viewed 5:02 PM… definitely wasn't — match the project settings.")
    tz_name = (getattr(budget, "timezone", None)
               or getattr(project, "timezone", None)
               or "America/New_York")

    ctx = {
        "date_display": date_display,
        "project_name": project.name if project else "",
        # cs_data/cs_locations retained for backward-compat but the FULL context
        # below overrides cs_data with the same underlying record.
        "cs_data": cs_portal_data,
        "cs_locations": cs_locations,
        "personal_call": personal_call,
        "personal_travel": personal_travel,
        "personal_talent_times": personal_talent_times,
        # Who the personal layer is ABOUT and whether the recipient is a proxy
        # (a rep viewing their client's details). Drives the "Your Call / Your
        # details" vs "<Name>'s Call / <Name>'s details" labels. (User 2026-07-14.)
        "personal_owner_name": subject_name,
        "personal_is_proxy": personal_is_proxy,
        # Recipient type so the template can suppress the personal call/travel
        # blocks for audiences that shouldn't get them (union, vendors/partners).
        "recipient_type": (rec_type or 'crew').strip().lower(),
        "tz_name": tz_name,
    }

    # ── Build the FULL sheet context so recipients see the complete call sheet
    # (crew grid, meals, weather, notes, locations, quote…) — identical to the
    # internal print view. (User 2026-07-08.)
    if send and budget and project:
        _pid, _bid = budget.project_id, budget.id
        date_rows = db.session.query(ScheduleDay.date).filter(
            ScheduleDay.budget_id == _bid,
            ScheduleDay.schedule_mode == sched_mode_p,
            ScheduleDay.day_type != 'off',
        ).distinct().order_by(ScheduleDay.date).all()
        all_scheduled_dates = [r[0] for r in date_rows]
        full = _callsheet_full_context(
            _pid, _bid, project, budget, send.date, sched_mode_p,
            all_scheduled_dates)
        ctx.update(full)  # full context wins on shared keys (cs_data, project…)

    # Forced audience view per recipient type (recipients never get the internal
    # editing switcher). Representation recipients ('rep') inherit their client's
    # view (talent's rep → talent view, crew's rep → crew view) via a
    # budget-scoped SupportContact lookup; everything else maps by type. This is
    # the single place preview + tokenized recipient view both flow through.
    if (rec_type or '').strip().lower() == 'rep':
        _resolved_view = _rep_recipient_view(budget, rec_name, rec_email)
    else:
        _resolved_view = _recipient_view_for_type(rec_type)
    cs_view, csv_flags = _callsheet_audience_flags(_resolved_view)
    ctx["cs_view"] = cs_view
    ctx["csv"] = csv_flags
    return ctx


@app.route("/callsheet/view/<token>")
def callsheet_view_public(token):
    """Public link: mark as viewed, show confirm page."""
    rec = CallSheetRecipient.query.filter_by(confirm_token=token).first_or_404()
    if not rec.viewed_at:
        rec.viewed_at = datetime.utcnow()
        if rec.status == "sent":
            rec.status = "viewed"
        db.session.commit()
    send = CallSheetSend.query.get(rec.send_id)
    already_confirmed = rec.confirmed_at is not None
    ctx = _build_callsheet_recipient_context(
        send, rec.name, rec.email, rec.recipient_type)
    return render_template(
        "callsheet.html",
        recipient_mode=True,
        rec=rec,
        send=send,
        already_confirmed=already_confirmed,
        token=token,
        preview_mode=False,
        confirmed_local=_fmt_local(rec.confirmed_at, ctx["tz_name"]),
        viewed_local=_fmt_local(rec.viewed_at, ctx["tz_name"]),
        **ctx,
    )


@app.route("/callsheet/confirm/<token>", methods=["POST"])
def callsheet_confirm_public(token):
    """Public link: record confirmation."""
    rec = CallSheetRecipient.query.filter_by(confirm_token=token).first_or_404()
    if not rec.confirmed_at:
        rec.confirmed_at = datetime.utcnow()
        rec.status = "confirmed"
        if not rec.viewed_at:
            rec.viewed_at = rec.confirmed_at
        db.session.commit()
    send = CallSheetSend.query.get(rec.send_id)
    ctx = _build_callsheet_recipient_context(
        send, rec.name, rec.email, rec.recipient_type)
    return render_template(
        "callsheet.html",
        recipient_mode=True,
        rec=rec,
        send=send,
        already_confirmed=True,
        token=token,
        preview_mode=False,
        confirmed_local=_fmt_local(rec.confirmed_at, ctx["tz_name"]),
        viewed_local=_fmt_local(rec.viewed_at, ctx["tz_name"]),
        **ctx,
    )


# ── Call-sheet preview (login-gated, no send) ─────────────────────────────────

@app.route("/projects/<int:pid>/budget/<int:bid>/callsheet/<date_str>/preview")
@login_required
def callsheet_preview_as(pid, bid, date_str):
    """Render the tokenized recipient view for a given person WITHOUT creating a
    send — so an admin can see exactly what a recipient receives (incl. their
    personal travel/confirmations block). ?as=<crew_member_id or email>.
    (User 2026-07-08.)"""
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    try:
        selected_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        return "Invalid date", 400
    sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'

    as_val = (request.args.get('as') or '').strip()
    # Optional audience override (?type=talent|client|union|rep|partner|crew) —
    # previews were hardcoded to the crew view, so per-audience content (and
    # per-view hides, 2026-07-13) couldn't be previewed for other audiences.
    _t = (request.args.get('type') or '').strip().lower()
    rec_type = _t if _t in ('crew', 'talent', 'client', 'union', 'rep', 'partner', 'manual') else 'crew'
    rec_name, rec_email = '', ''
    cm = None
    if as_val.isdigit():
        cm = CrewMember.query.get(int(as_val))
    if cm is None and '@' in as_val:
        cm = CrewMember.query.filter(
            db.func.lower(CrewMember.email) == as_val.lower()).first()
    if cm is None and as_val:
        cm = CrewMember.query.filter(
            db.func.lower(CrewMember.name) == as_val.lower()).first()
    if cm is not None:
        rec_name, rec_email = cm.name, (cm.email or '')
    elif '@' in as_val:
        rec_email = as_val
        rec_name = as_val
    else:
        rec_name = as_val or 'Recipient'

    # Build a transient (unsaved) send + recipient so the shared context builder
    # and template work unchanged. Never committed.
    fake_send = CallSheetSend(
        budget_id=bid, date=selected_date, schedule_mode=sched_mode,
        version_label='PREVIEW')
    fake_rec = CallSheetRecipient(
        recipient_type=rec_type, name=rec_name, email=rec_email or None,
        status='pending')

    ctx = _build_callsheet_recipient_context(
        fake_send, rec_name, rec_email, rec_type)
    return render_template(
        "callsheet.html",
        recipient_mode=True,
        rec=fake_rec,
        send=fake_send,
        already_confirmed=False,
        token=None,
        preview_mode=True,
        confirmed_local=None,
        viewed_local=None,
        **ctx,
    )


