@app.route("/api/quote")
@login_required
def get_quote():
    """Return a random inspirational quote. Uses Claude API if key is set, else fallback list."""
    import random
    source_type = request.args.get('type', 'random')

    api_key = os.getenv("ANTHROPIC_API_KEY")
    if _HAS_ANTHROPIC and api_key:
        type_map = {
            'film':   'a famous film or movie (cite the film title)',
            'tv':     'a TV show or series (cite the show name)',
            'book':   'a book or literary work (cite title and author)',
            'person': 'a famous person — historical or contemporary',
            'random': 'a book, film, TV show, or famous person (choose at random)',
        }
        source_desc = type_map.get(source_type, type_map['random'])
        prompt = (
            f"Give me one short, clever, unexpected quote from {source_desc}. "
            "Avoid the most famous or overused quotes — pick something lesser-known, "
            "witty, or surprising that would make a film/TV production crew smile. "
            "It can be funny, dry, or unexpectedly profound. "
            "Format it exactly as:\n"
            "\"[quote text]\"\n"
            "— [Source / Author]\n\n"
            "Return ONLY the formatted quote. No explanation, no preamble."
        )
        try:
            client = _anthropic_sdk.Anthropic(api_key=api_key)
            msg = client.messages.create(
                model="claude-haiku-4-5-20251001",
                max_tokens=200,
                messages=[{"role": "user", "content": prompt}]
            )
            quote_text = msg.content[0].text.strip()
            return jsonify({"quote": quote_text, "type": source_type, "source": "ai"})
        except Exception as e:
            logging.warning(f"Quote API call failed: {e}")
            # Fall through to fallback

    # Fallback: random from curated list, optionally filtered by type
    pool = _QUOTE_FALLBACK if source_type == 'random' else [q for q in _QUOTE_FALLBACK if q[2] == source_type]
    if not pool:
        pool = _QUOTE_FALLBACK
    text, attribution, qtype = random.choice(pool)
    return jsonify({"quote": f'{text}\n— {attribution}', "type": qtype, "source": "fallback"})


@app.route("/admin/ai/ping", methods=["GET"])
@login_required
def admin_ai_ping():
    """Health check for the AI layer (spec §1/§9). Returns provider status; with
    ?test=1 runs ONE live categorize against a sample (uses a Claude call if the
    key is set). Super-admin/admin only. (User 2026-06-17.)"""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden"}), 403
    import ai_layer
    out = {"status": ai_layer.status()}
    if request.args.get('test') == '1':
        sample = {
            "taxonomy": [
                {"id": "travel",   "name": "Travel", "examples": ["flights", "hotels", "rideshare", "gas"]},
                {"id": "meals",    "name": "Meals & Entertainment", "examples": ["restaurants", "coffee"]},
                {"id": "supplies", "name": "Supplies", "examples": ["amazon", "office"]},
            ],
            "document": {"vendor": "Shell", "category": "Gas", "total": 42.10,
                         "line_items": [{"description": "Unleaded fuel"}]},
            "past_corrections": [],
        }
        out["categorize_test"] = ai_layer.categorize(sample)
    return jsonify(out)


@app.route("/projects/<int:pid>/budget/<int:bid>/callsheet/<date_str>/save", methods=["POST"])
@login_required
def callsheet_save(pid, bid, date_str):
    """AJAX: save call sheet day data (editable overrides)."""
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    try:
        selected_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        return jsonify({"error": "invalid date"}), 400
    sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'
    # Audit C2 hardening (2026-07-20): (a) an empty/invalid body must never
    # wipe a live sheet; (b) merge over the stored blob so keys this client
    # build doesn't emit survive; (c) optimistic concurrency — a stale tab
    # gets a 409 instead of silently clobbering another editor's changes.
    payload = request.get_json(force=True, silent=True)
    if not isinstance(payload, dict) or not payload:
        return jsonify({"error": "empty or invalid payload — nothing saved"}), 400
    client_rev = payload.pop('_rev', None)
    rec = CallSheetData.query.filter_by(
        budget_id=bid, date=selected_date, schedule_mode=sched_mode).first()
    if not rec:
        rec = CallSheetData(budget_id=bid, date=selected_date, schedule_mode=sched_mode)
        db.session.add(rec)
    else:
        server_rev = rec.updated_at.isoformat() if rec.updated_at else None
        if client_rev and server_rev and client_rev != server_rev:
            return jsonify({"error": "conflict", "conflict": True,
                            "server_rev": server_rev}), 409
        try:
            stored = json.loads(rec.data_json) if rec.data_json else {}
        except Exception:
            stored = {}
        if isinstance(stored, dict):
            payload = {**stored, **payload}
    rec.data_json = json.dumps(payload)
    rec.updated_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "rev": rec.updated_at.isoformat()})


@app.route("/projects/<int:pid>/budget/<int:bid>/callsheet/contacts")
@login_required
def callsheet_contacts_api(pid, bid):
    """Return all crew members for this budget for Key Personnel dropdowns.

    When ?date=YYYY-MM-DD is passed, each contact is also flagged on_day=True
    when that person has a non-off ScheduleDay for this budget+date+mode
    (resolved crew→assignment→schedule day the same way callsheet_view does).
    Non-crew recipients (clients/unions/reps) are on_day=False here — the send
    modal pre-checks them only if flagged to receive the sheet. (User 2026-07-08.)
    """
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    lines = BudgetLine.query.filter_by(budget_id=bid, is_labor=True).all()

    # Build the on-day crew_member_id + name set for the requested date.
    on_day_cm_ids  = set()
    on_day_names   = set()
    date_str = (request.args.get('date') or '').strip()
    if date_str:
        try:
            _d = datetime.strptime(date_str, "%Y-%m-%d").date()
        except ValueError:
            _d = None
        if _d is not None:
            sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'
            _days = ScheduleDay.query.filter(
                ScheduleDay.budget_id == bid,
                ScheduleDay.schedule_mode == sched_mode,
                ScheduleDay.date == _d,
                ScheduleDay.day_type != 'off',
            ).all()
            _line_ids = list({d.budget_line_id for d in _days if d.budget_line_id})
            _by_line_inst = {(d.budget_line_id, d.crew_instance or 1) for d in _days}
            if _line_ids:
                for _ca in CrewAssignment.query.filter(
                        CrewAssignment.budget_line_id.in_(_line_ids)).all():
                    if (_ca.budget_line_id, _ca.instance or 1) not in _by_line_inst:
                        continue
                    if _ca.crew_member_id:
                        on_day_cm_ids.add(_ca.crew_member_id)
                    elif _ca.name_override:
                        on_day_names.add(_ca.name_override.strip().lower())

    contacts = []
    seen_ids = set()
    for ln in lines:
        for ca in ln.crew_assignments:
            if ca.crew_member_id and ca.crew_member_id not in seen_ids:
                cm = ca.crew_member
                if cm:
                    contacts.append({
                        "id": cm.id,
                        "name": cm.name,
                        "role": ln.description or ln.account_name,
                        "phone": cm.phone or "",
                        "email": cm.email or "",
                        "on_day": cm.id in on_day_cm_ids,
                    })
                    seen_ids.add(cm.id)
            elif ca.name_override and not ca.crew_member_id:
                contacts.append({
                    "id": None,
                    "name": ca.name_override,
                    "role": ln.description or ln.account_name,
                    "phone": "",
                    "email": "",
                    "on_day": ca.name_override.strip().lower() in on_day_names,
                })
    return jsonify(contacts)


def _callsheet_full_context(pid, bid, project, budget, selected_date,
                            sched_mode, all_scheduled_dates):
    """Assemble the FULL call-sheet content context (the template kwargs that
    describe the sheet itself: crew grid, locations, meals, weather, notes,
    travel, cs_data + hidden/text/dept overrides, confirm status, on-day sets).

    Single source of truth shared by the internal editing view (callsheet_view)
    AND the tokenized recipient view / preview so recipients see the identical
    sheet. Request-scoped bits that are NOT sheet content — the audience-view
    flags (cs_view/csv), date navigation, distribution/send history — stay in
    the individual routes and are merged on top. (User 2026-07-08.)

    Returns a dict of template kwargs. Byte-for-byte the same logic that used to
    live inline in callsheet_view; moved, not rewritten."""
    # Determine day type for the selected date and compute shoot-day number
    # Only "work" days count toward the shoot day number; travel/hold/half get their own label
    _day_types_today = db.session.query(ScheduleDay.day_type).filter(
        ScheduleDay.budget_id == bid,
        ScheduleDay.schedule_mode == sched_mode,
        ScheduleDay.date == selected_date,
        ScheduleDay.day_type != 'off',
    ).distinct().all()
    _day_types_today = [r[0] for r in _day_types_today]
    primary_day_type = _day_types_today[0] if _day_types_today else None

    # Shoot day number = position among work days only
    shooting_day_num = None
    _work_dates = [r[0] for r in db.session.query(ScheduleDay.date).filter(
        ScheduleDay.budget_id == bid,
        ScheduleDay.schedule_mode == sched_mode,
        ScheduleDay.day_type == 'work',
    ).distinct().order_by(ScheduleDay.date).all()]
    _total_shoot_days = len(_work_dates)
    if selected_date in _work_dates:
        shooting_day_num = _work_dates.index(selected_date) + 1
    elif selected_date in all_scheduled_dates and primary_day_type:
        # Non-work day: show day-type label but no shoot day number
        shooting_day_num = None

    # Schedule days for selected date
    days_today = ScheduleDay.query.filter(
        ScheduleDay.budget_id == bid,
        ScheduleDay.schedule_mode == sched_mode,
        ScheduleDay.date == selected_date,
        ScheduleDay.day_type != 'off',
    ).order_by(ScheduleDay.budget_line_id, ScheduleDay.crew_instance).all()

    # Budget lines active today
    line_ids = list({d.budget_line_id for d in days_today if d.budget_line_id})
    lines_today = BudgetLine.query.filter(BudgetLine.id.in_(line_ids)).order_by(
        BudgetLine.account_code, BudgetLine.sort_order).all() if line_ids else []
    lines_by_id = {ln.id: ln for ln in lines_today}

    # Crew assignments for those lines
    assignments = CrewAssignment.query.filter(
        CrewAssignment.budget_line_id.in_(line_ids)
    ).all() if line_ids else []
    crew_ids = [a.crew_member_id for a in assignments if a.crew_member_id]
    crew_by_id = {c.id: c for c in CrewMember.query.filter(
        CrewMember.id.in_(crew_ids)).all()} if crew_ids else {}

    # Locations today
    location_days_today = LocationDay.query.filter_by(budget_id=bid, date=selected_date).all()
    loc_ids = [ld.location_id for ld in location_days_today]
    locations_today = Location.query.filter(Location.id.in_(loc_ids)).all() if loc_ids else []
    locations_by_id = {loc.id: loc for loc in locations_today}

    # Production day (meals)
    prod_day = ProductionDay.query.filter_by(
        budget_id=bid, date=selected_date, schedule_mode=sched_mode).first()

    # Meal headcounts — use actual crew count on this shoot day, not budget line quantity.
    # days_today already contains non-off ScheduleDay rows for selected_date.
    _day_headcount = len([d for d in days_today if d.day_type != 'off'])
    meal_counts = {}
    if prod_day:
        if prod_day.courtesy_breakfast:
            meal_counts['courtesy_breakfast'] = _day_headcount
        if prod_day.first_meal:
            meal_counts['first_meal'] = _day_headcount
        if prod_day.second_meal:
            meal_counts['second_meal'] = _day_headcount
    # Craft services: only when THIS production day has it flagged. (Was
    # unconditional whenever anyone was scheduled — user 2026-07-08: "Craft
    # services is always turning on yes even if there are no craft services
    # on that day.")
    if _day_headcount and prod_day and getattr(prod_day, 'craft_services', False):
        meal_counts['craft_services'] = _day_headcount
    # Working meals: per-person cell flag count for this day
    def _parse_flags(cf):
        try: return json.loads(cf) if cf else {}
        except Exception: return {}
    _wm_count = sum(
        1 for d in days_today
        if d.day_type != 'off' and _parse_flags(d.cell_flags).get('working_meal')
    )
    if _wm_count:
        meal_counts['working_meal'] = _wm_count

    # Build crew list grouped by COA section, with day type per instance
    days_by_line_inst = {}
    for d in days_today:
        days_by_line_inst[(d.budget_line_id, d.crew_instance or 1)] = d

    # Travel details for today's schedule days, keyed by schedule_day_id, so each
    # person's flight/hotel/car (with confirmation #) renders on their call sheet.
    # (User 2026-06-22, travel Slice 2.)
    _sd_ids_today = [d.id for d in days_today]
    _travel_by_sd = {}
    if _sd_ids_today:
        for _td in TravelDetail.query.filter(
                TravelDetail.schedule_day_id.in_(_sd_ids_today)).all():
            _travel_by_sd.setdefault(_td.schedule_day_id, []).append(_td)

    # Hotel span: a reservation keyed to one anchor day should ALSO show on the
    # internal sheet for every day its check_in..check_out range covers (same
    # inclusive span the recipient personal card uses), so a person mid-stay
    # sees their hotel line on any day's internal call sheet — not only the
    # anchor day. Look up hotels on the SAME (line, instance) whose range spans
    # selected_date, and attach them to today's matching schedule day.
    _keys_today = {(d.budget_line_id, d.crew_instance or 1): d for d in days_today}
    if _keys_today:
        _line_ids_today = list({k[0] for k in _keys_today.keys() if k[0]})
        # This person's OTHER schedule days (same budget/mode/line/instance) that
        # could carry a spanning hotel reservation.
        _span_days = ScheduleDay.query.filter(
            ScheduleDay.budget_id == bid,
            ScheduleDay.schedule_mode == sched_mode,
            ScheduleDay.budget_line_id.in_(_line_ids_today),
        ).all() if _line_ids_today else []
        _span_days = [s for s in _span_days
                      if (s.budget_line_id, s.crew_instance or 1) in _keys_today]
        _span_sd_ids = [s.id for s in _span_days]
        _sd_line_inst = {s.id: (s.budget_line_id, s.crew_instance or 1)
                         for s in _span_days}
        _already = {(_td.schedule_day_id, _td.id)
                    for _lst in _travel_by_sd.values() for _td in _lst}
        if _span_sd_ids:
            for _htd in TravelDetail.query.filter(
                    TravelDetail.schedule_day_id.in_(_span_sd_ids),
                    TravelDetail.kind == 'hotel').all():
                if not (_htd.check_in and _htd.check_out
                        and _htd.check_in <= selected_date <= _htd.check_out):
                    continue
                _key = _sd_line_inst.get(_htd.schedule_day_id)
                _today_sd = _keys_today.get(_key) if _key else None
                if _today_sd is None:
                    continue
                # Avoid double-listing the hotel on its own anchor day.
                if (_today_sd.id, _htd.id) in _already:
                    continue
                _travel_by_sd.setdefault(_today_sd.id, []).append(_htd)
                _already.add((_today_sd.id, _htd.id))

    def _cs_td_view(td):
        def _tm(x): return x.strftime('%-I:%M %p') if x else None
        def _dd(x): return x.strftime('%b %-d') if x else None
        v = {"id": td.id, "kind": td.kind, "confirmation_no": td.confirmation_no, "notes": td.notes}
        if td.kind == 'flight':
            v.update(airline=td.airline, flight_no=td.flight_no,
                     depart_airport=td.depart_airport, arrive_airport=td.arrive_airport,
                     depart_at=_tm(td.depart_at), arrive_at=_tm(td.arrive_at))
        elif td.kind == 'hotel':
            v.update(hotel_name=td.hotel_name, hotel_address=td.hotel_address,
                     check_in=_dd(td.check_in), check_out=_dd(td.check_out),
                     room_type=td.room_type)
        elif td.kind == 'car_rental':
            v.update(rental_co=td.rental_co, pickup_location=td.pickup_location,
                     pickup_at=_tm(td.pickup_at), return_at=_tm(td.return_at))
        elif td.kind == 'car_service':
            v.update(rental_co=td.rental_co, pickup_location=td.pickup_location,
                     dropoff_location=td.dropoff_location, contact_phone=td.contact_phone,
                     pickup_at=_tm(td.pickup_at), return_at=_tm(td.return_at),
                     self_report=bool(td.self_report))
        return v

    def _cs_travel_for(sd):
        if not sd:
            return []
        # Multi-entry: sort each person's travel lines by kind then time so two
        # flights / two car services on one day render in reading order.
        from datetime import datetime as _dt_srt
        _kind_ord = {'flight': 0, 'car_service': 1, 'car_rental': 2,
                     'hotel': 3, 'mileage': 4}
        def _key(t):
            _t = (t.depart_at or t.pickup_at or _dt_srt.max)
            return (_kind_ord.get(t.kind, 9), _t, t.id)
        return [_cs_td_view(t) for t in sorted(_travel_by_sd.get(sd.id, []), key=_key)]

    crew_rows = []  # {section_code, section_name, role, name, day_type, phone, email}
    for ln in lines_today:
        sec_code = _section_for_code(ln.account_code)
        sec_name = _section_name(sec_code)
        line_assignments = [a for a in assignments if a.budget_line_id == ln.id]
        if line_assignments:
            for a in line_assignments:
                inst = a.instance or 1
                sd = days_by_line_inst.get((ln.id, inst))
                day_type = sd.day_type if sd else 'work'
                cm = crew_by_id.get(a.crew_member_id) if a.crew_member_id else None
                name = a.name_override or (cm.name if cm else '') or '—'
                phone = cm.phone if cm else ''
                email = cm.email if cm else ''
                crew_rows.append({
                    'section_code': sec_code,
                    'section_name': sec_name,
                    'role': ln.description or ln.account_name,
                    'name': name,
                    'day_type': day_type,
                    'phone': phone or '',
                    'email': email or '',
                    'account_code': ln.account_code,
                    'budget_line_id': ln.id,
                    'instance': inst,
                    'crew_member_id': a.crew_member_id,
                    'travel': _cs_travel_for(sd),
                })
        else:
            # Line has no assignment yet — show role with blank name
            for inst in range(1, int(ln.quantity or 1) + 1):
                sd = days_by_line_inst.get((ln.id, inst))
                day_type = sd.day_type if sd else 'work'
                crew_rows.append({
                    'section_code': sec_code,
                    'section_name': sec_name,
                    'role': ln.description or ln.account_name,
                    'name': '—',
                    'day_type': day_type,
                    'phone': '',
                    'email': '',
                    'account_code': ln.account_code,
                    'budget_line_id': ln.id,
                    'instance': inst,
                    'crew_member_id': None,
                    'travel': _cs_travel_for(sd),
                })

    # Separate ATL/Talent from crew.
    # 2026-04 renumber: ATL no longer has its own section code — ATL roles
    # live inside Production Staff (COA_CODE_PROD_STAFF=2000). We identify
    # them by role-name match against _ATL_ROLE_LABELS. Talent is its own
    # section (COA_CODE_TALENT=2100). Everything else labor-like is BG crew.
    def _row_is_atl(r):
        # ATL ("Above the Line") section removed per user 2026-06-22 — it's not
        # wanted on call sheets. Directors/producers/etc. now flow into their
        # normal department in the crew list instead of a separate ATL block.
        # (Future: a "department head" checkbox on the People tab.)
        return False
    atl_rows     = [r for r in crew_rows if _row_is_atl(r)]
    talent_rows  = [r for r in crew_rows if r['account_code'] == COA_CODE_TALENT]
    crew_rows_bg = [r for r in crew_rows
                    if r['account_code'] != COA_CODE_TALENT and not _row_is_atl(r)]

    # Agent / representative per talent row (owner 2026-09-01: "add in the
    # agent or representative column for talent"). First active agent-type
    # SupportContact per crew member — same pick as the crew page's
    # agent_map. Internal view only (csv.talent_agent); fail-open.
    try:
        _tal_cm_ids = {r['crew_member_id'] for r in talent_rows if r.get('crew_member_id')}
        if _tal_cm_ids:
            _agent_by_cm = {}
            for _ag in (SupportContact.query
                        .filter(SupportContact.crew_member_id.in_(_tal_cm_ids),
                                SupportContact.role_type == 'agent',
                                SupportContact.active == True)  # noqa: E712
                        .order_by(SupportContact.id).all()):
                _agent_by_cm.setdefault(_ag.crew_member_id, _ag)
            for r in talent_rows:
                _ag = _agent_by_cm.get(r.get('crew_member_id'))
                if _ag:
                    r['agent_name']  = _ag.name or ''
                    r['agent_phone'] = _ag.phone or ''
                    r['agent_email'] = _ag.email or ''
    except Exception as _age:
        logging.warning(f"[callsheet] talent agent lookup failed: {_age}")

    # ── Build Page 2 unified crew list (ATL + Talent + Production Staff) ────
    _P2_SECTION_SORT = {
        "Above the Line": 0,
        "Talent": 1,
        "Direction / AD": 10,
        "Production": 11,
        "Camera": 20,
        "Grip & Electric": 30,
        "Sound": 40,
        "Art": 50,
        "Hair & Makeup": 60,
        "Wardrobe": 70,
        "Locations": 80,
        "Transportation": 90,
        "Control Room": 95,
        "EPK / BTS": 96,
        "Craft Services": 97,
    }

    def _p2_section_for_row(r):
        # 2026-04 renumber: "Above the Line" is no longer a section code;
        # ATL roles live in Production Staff. Detect by role name.
        if _row_is_atl(r):
            return "Above the Line"
        if r['account_code'] == COA_CODE_TALENT:
            return "Talent"
        # Production Staff or anything else — use subgroup or section_name
        sg = _get_prod_staff_subgroup(r['role'])
        return sg if sg else r['section_name']

    crew_p2_all = []
    for r in crew_rows:
        sect = _p2_section_for_row(r)
        crew_key = f"{r['budget_line_id']}:{r['instance']}"
        # p2_section_default is frozen to the pre-override group. The
        # crew_call_times key ("sec||role||name") is built from THIS so that
        # dragging a person to another department never orphans their saved
        # individual call time. p2_section is the (possibly overridden) group
        # used for display/grouping. (User 2026-07-08.)
        crew_p2_all.append({**r, 'p2_section': sect,
                            'p2_section_default': sect, 'p2_crew_key': crew_key})

    # ── Load saved call sheet day data ─────────────────────────────────────
    cs_rec = CallSheetData.query.filter_by(
        budget_id=bid, date=selected_date, schedule_mode=sched_mode).first()
    cs_data = json.loads(cs_rec.data_json) if cs_rec and cs_rec.data_json else {}
    cs_rev = (cs_rec.updated_at.isoformat() if cs_rec and cs_rec.updated_at else '')

    # ── Apply per-day department overrides / renames / custom depts ─────────
    # These are DISPLAY truth for page-2 grouping and are honored across ALL
    # views (screen, print, browser PDF, preview). Overrides win over the
    # server-side default guess; renames relabel a group's header; custom depts
    # are user-created empty buckets people can be dragged into.
    #   dept_overrides: {crew_key: dept_name}   crew_key = "<line_id>:<instance>"
    #   dept_renames:   {original_name: new_name}
    #   custom_depts:   [names…]                sort after standard groups
    # (User 2026-07-08.)
    dept_overrides = cs_data.get('dept_overrides', {}) or {}
    dept_renames   = cs_data.get('dept_renames', {}) or {}
    custom_depts   = cs_data.get('custom_depts', []) or []

    def _apply_dept_rename(name):
        return dept_renames.get(name, name)

    _custom_sort_base = 94  # custom depts slot just before Control Room(95)/CS(97)
    for idx, r in enumerate(crew_p2_all):
        # 1) per-person override wins over the default section
        ov = dept_overrides.get(r['p2_crew_key'])
        if ov:
            r['p2_section'] = ov
        # 2) header rename (applied to whatever section the row now sits in)
        r['p2_section'] = _apply_dept_rename(r['p2_section'])

    # Build a stable sort key per (possibly renamed / custom) section.
    _renamed_custom = [_apply_dept_rename(c) for c in custom_depts]
    def _p2_sort_for_section(sect):
        # Standard sections keep their canonical order (renames don't move a
        # group — we resolve the sort key from the ORIGINAL name when possible).
        if sect in _P2_SECTION_SORT:
            return _P2_SECTION_SORT[sect]
        # A renamed standard header: find its original name's sort weight.
        for _orig, _new in dept_renames.items():
            if _new == sect and _orig in _P2_SECTION_SORT:
                return _P2_SECTION_SORT[_orig]
        # Custom depts sort together, just before Control Room, preserving
        # their creation order.
        if sect in _renamed_custom:
            return _custom_sort_base + (_renamed_custom.index(sect) * 0.01)
        return 99
    for r in crew_p2_all:
        r['p2_sort'] = _p2_sort_for_section(r['p2_section'])

    crew_p2_all.sort(key=lambda x: (x['p2_sort'], x['role'], x['name']))

    # Custom (and renamed-custom) departments that currently have zero rows must
    # still render as empty drop targets on the internal view. Collect the list
    # of section names present so the template can append missing custom groups.
    _sections_present = {r['p2_section'] for r in crew_p2_all}
    p2_custom_empty = [c for c in _renamed_custom if c not in _sections_present]
    # The FULL set of custom dept names (renamed) — a custom dept that has crew
    # dragged into it is "present" (so not in p2_custom_empty) yet must STILL be
    # deletable, so the template needs the complete list to mark every custom box
    # as custom + render its ✕. (User 2026-07-09.)
    p2_custom_all = list(_renamed_custom)

    # Apply saved location ordering for this day
    saved_loc_order = cs_data.get('location_order', [])
    if saved_loc_order and location_days_today:
        ld_by_id = {ld.id: ld for ld in location_days_today}
        ordered = [ld_by_id[lid] for lid in saved_loc_order if lid in ld_by_id]
        remaining = [ld for ld in location_days_today if ld.id not in set(saved_loc_order)]
        location_days_today = ordered + remaining

    # Group by LOCATION_TYPES order for the call sheet (stable — keeps any saved
    # manual order as the tiebreaker within a type). Unknown/blank types sort last.
    location_days_today = sorted(
        location_days_today,
        key=lambda ld: location_type_meta(
            getattr(locations_by_id.get(ld.location_id), 'location_type', None)
        )['order'])

    # Available contacts for Key Personnel dropdowns (all crew on this budget)
    _labor_lines = BudgetLine.query.filter_by(budget_id=bid, is_labor=True).all()
    available_contacts = []
    _seen_cm = set()
    for _ln in _labor_lines:
        for _ca in _ln.crew_assignments:
            if _ca.crew_member_id and _ca.crew_member_id not in _seen_cm:
                _cm = _ca.crew_member
                if _cm:
                    available_contacts.append({
                        "id": _cm.id,
                        "name": _cm.name,
                        "role": _ln.description or _ln.account_name,
                        "phone": _cm.phone or "",
                        "email": _cm.email or "",
                    })
                    _seen_cm.add(_ca.crew_member_id)
            elif _ca.name_override and not _ca.crew_member_id:
                available_contacts.append({
                    "id": None,
                    "name": _ca.name_override,
                    "role": _ln.description or _ln.account_name,
                    "phone": "",
                    "email": "",
                })

    # Clients for this project (shown on call sheet if show_on_callsheet)
    # Plain dicts (not ORM objects) — the template both renders these AND
    # tojson's them for the distribution list, and a ProjectClient isn't JSON
    # serializable, which 500'd the whole call sheet for any project that had a
    # client. (Bug fix 2026-06-22.)
    project_clients_cs = [{
        "name": c.name, "title": getattr(c, 'title', None),
        "company": getattr(c, 'company', None),
        "phone": getattr(c, 'phone', None), "email": getattr(c, 'email', None),
    } for c in ProjectClient.query.filter_by(
        project_id=pid, show_on_callsheet=True
    ).order_by(ProjectClient.sort_order).all()]

    # Unions for this project (for call sheet Page 2)
    project_unions_cs = ProjectUnion.query.filter_by(
        project_id=pid
    ).order_by(ProjectUnion.sort_order).all()

    # JSON-serializable copy of the unions for the distribution-panel recipient
    # list (JS tojson can't serialize ORM objects). These are LISTED in the send
    # modal under a "⚖ Union" group but NEVER pre-checked — receives_callsheet is
    # surfaced only as a muted 'flagged' chip for context, it does NOT auto-add
    # anyone to a send. A union contact is emailed only when the user physically
    # ticks it for that specific send. (User 2026-07-13.)
    project_unions_cs_json = [{
        "id": u.id,
        "union_name": u.union_name or "",
        "contact_name": u.contact_name or "",
        "email": u.email or "",
        "phone": u.phone or "",
        "receives_callsheet": bool(u.receives_callsheet),
    } for u in project_unions_cs]

    # Vendors & partners for this project (venue ops, rental-house pickup/dropoff
    # coordinators, etc.) — JSON-serializable copy for the distribution-panel
    # recipient list. LISTED in the send modal under a "🚚 Vendors & Partners"
    # group but NEVER pre-checked: a partner is emailed only when the user
    # physically ticks it for that specific send. (User 2026-07-13.)
    project_partners_cs = ProjectPartner.query.filter_by(
        project_id=pid
    ).order_by(ProjectPartner.sort_order, ProjectPartner.id).all()
    project_partners_cs_json = [{
        "id": p.id,
        "name": p.name or "",
        "role": p.role or "",
        "company": p.company or "",
        "email": p.email or "",
        "phone": p.phone or "",
    } for p in project_partners_cs]

    # Representation contacts for crew on this budget
    rep_contacts = []
    _seen_cm_rep = set()
    for _ln in _labor_lines:
        for _ca in _ln.crew_assignments:
            if _ca.crew_member_id and _ca.crew_member_id not in _seen_cm_rep:
                _cm = _ca.crew_member
                if _cm and _cm.support_contacts:
                    for sc in _cm.support_contacts:
                        if sc.active:
                            rep_contacts.append({
                                'rep_id': sc.id,
                                'crew_name': _cm.name,
                                'crew_role': _ln.description or _ln.account_name,
                                'rep_name': sc.name,
                                'rep_role_type': sc.role_type,
                                'rep_company': sc.company or '',
                                'rep_phone': sc.phone or '',
                                'rep_email': sc.email or '',
                                'notify_callsheet': bool(sc.notify_callsheet),
                                # The view this rep inherits from their client
                                # (talent's rep → talent view, else crew view) —
                                # shown as a hint in the send panel. (2026-07-14.)
                                'client_audience': (
                                    'talent' if _ln.account_code == COA_CODE_TALENT
                                    else 'crew'),
                            })
                _seen_cm_rep.add(_ca.crew_member_id)

    # Key contacts (ATL + Production Staff with known senior roles)
    KEY_ROLE_PRIORITY = ['Director', 'Executive Producer', 'Producer', 'Creative Director',
                         'Line Producer', 'UPM', 'Production Supervisor', '1st AD', 'Set Medic']
    key_contacts = []
    seen_roles = set()
    for priority_role in KEY_ROLE_PRIORITY:
        for r in crew_rows:
            if priority_role.lower() in r['role'].lower() and priority_role not in seen_roles:
                key_contacts.append(r)
                seen_roles.add(priority_role)
                break

    all_budgets = Budget.query.filter_by(project_id=pid).order_by(Budget.created_at.desc()).all()
    parent_names = {}
    for b in all_budgets:
        if b.parent_budget_id:
            parent = next((x for x in all_budgets if x.id == b.parent_budget_id), None)
            if parent:
                parent_names[b.id] = parent.name

    # Next scheduled day (for Advance Schedule section)
    next_day_date = None
    next_day_lines_preview = []
    if all_scheduled_dates and selected_date in all_scheduled_dates:
        cur_idx = all_scheduled_dates.index(selected_date)
        if cur_idx + 1 < len(all_scheduled_dates):
            next_day_date = all_scheduled_dates[cur_idx + 1]
            next_lines = db.session.query(ScheduleDay).filter(
                ScheduleDay.budget_id == bid,
                ScheduleDay.schedule_mode == sched_mode,
                ScheduleDay.date == next_day_date,
                ScheduleDay.day_type != 'off',
            ).order_by(ScheduleDay.budget_line_id).limit(20).all()
            next_line_ids = list({d.budget_line_id for d in next_lines if d.budget_line_id})
            if next_line_ids:
                next_day_lines_preview = BudgetLine.query.filter(
                    BudgetLine.id.in_(next_line_ids)
                ).order_by(BudgetLine.account_code, BudgetLine.sort_order).all()

    # Advance schedule shows the PEOPLE working the next day (names), not roles.
    # (User 2026-06-22.) Resolve each next-day cell to its assigned crew name.
    next_day_people = []
    if next_day_date:
        try:
            _nd_lines = {ln.id: ln for ln in BudgetLine.query.filter(
                BudgetLine.id.in_(next_line_ids)).all()} if next_line_ids else {}
            _nd_cas = CrewAssignment.query.filter(
                CrewAssignment.budget_line_id.in_(next_line_ids)).all() if next_line_ids else []
            _nd_ca_by_key = {(ca.budget_line_id, ca.instance or 1): ca for ca in _nd_cas}
            _seen_nd = set()
            for d in next_lines:
                ln = _nd_lines.get(d.budget_line_id)
                if not ln:
                    continue
                role, person = _resolve_person_for_cell(ln, d.crew_instance, _nd_ca_by_key)
                nm = (person or '').strip()
                if nm and nm not in ('—', '-') and nm.lower() not in _seen_nd:
                    _seen_nd.add(nm.lower())
                    next_day_people.append({"name": nm, "role": role or ''})
            next_day_people.sort(key=lambda p: p['name'].lower())
        except Exception:
            next_day_people = []

    current_working_bid = next(
        (b.id for b in all_budgets if _budget_type(b.budget_mode) == 'working' and b.version_status == 'current'), None
    ) or next(
        (b.id for b in all_budgets if _budget_type(b.budget_mode) == 'working' and b.version_status != 'archived'), None
    )
    current_estimated_bid = next(
        (b.id for b in all_budgets if _budget_type(b.budget_mode) == 'estimated' and b.version_status == 'current'), None
    ) or next(
        (b.id for b in all_budgets if _budget_type(b.budget_mode) == 'estimated' and b.version_status != 'archived'), None
    )

    # ── Confirmation status map for crew list ────────────────────────────────
    # confirm_status: most-recent send for this date; name_lower → {status,…}.
    # sent_versions: version-aware "already sent" map across ALL sends for this
    # date, keyed by BOTH name and email (lowercased) → [version_label,…]. The
    # Send panel uses it to auto-uncheck anyone already sent the current version
    # label so a re-send doesn't duplicate them. (User 2026-07-14.)
    confirm_status = {}
    sent_versions = {}
    _all_sends_today = CallSheetSend.query.filter_by(
        budget_id=bid, date=selected_date, schedule_mode=sched_mode
    ).order_by(CallSheetSend.sent_at.desc()).all()
    for _snd in _all_sends_today:
        _vl = (_snd.version_label or '').strip()
        if not _vl:
            continue
        for _rcp in _snd.recipients:
            for _idk in ((_rcp.name or '').strip().lower(),
                         (_rcp.email or '').strip().lower()):
                if _idk:
                    _bucket = sent_versions.setdefault(_idk, [])
                    if _vl not in _bucket:
                        _bucket.append(_vl)
    latest_send = _all_sends_today[0] if _all_sends_today else None
    if latest_send:
        # Format in the BUDGET's timezone (Settings-tab picker) — these were
        # raw UTC before ("viewed 5:02 PM" that never happened, 2026-07-09).
        _cs_tz = getattr(budget, "timezone", None) or "America/New_York"
        for rcp in latest_send.recipients:
            key = rcp.name.strip().lower()
            confirm_status[key] = {
                "status":       rcp.status,
                "viewed_at":    _fmt_local(rcp.viewed_at, _cs_tz)    if rcp.viewed_at    else None,
                "confirmed_at": _fmt_local(rcp.confirmed_at, _cs_tz) if rcp.confirmed_at else None,
            }

    # ── On-day set for send-modal pre-checking (User 2026-07-08) ─────────────
    # People actually scheduled this day = everyone in crew_rows (crew + talent,
    # resolved from today's non-off ScheduleDays exactly as above). Clients and
    # other non-crew recipients are NOT on-day (they get pre-checked only if
    # separately flagged to receive the sheet — handled below).
    on_day_names  = sorted({(r['name'] or '').strip().lower()
                            for r in crew_rows if r.get('name') and r['name'] not in ('—', '-')})
    on_day_emails = sorted({(r['email'] or '').strip().lower()
                            for r in crew_rows if r.get('email')})

    return dict(
        project=project,
        budget=budget,
        all_budgets=all_budgets,
        parent_names=parent_names,
        selected_date=selected_date,
        all_scheduled_dates=all_scheduled_dates,
        shooting_day_num=shooting_day_num,
        total_shoot_days=_total_shoot_days,
        primary_day_type=primary_day_type,
        days_today=days_today,
        lines_by_id=lines_by_id,
        assignments=assignments,
        crew_by_id=crew_by_id,
        location_days_today=location_days_today,
        locations_today=locations_today,
        locations_by_id=locations_by_id,
        prod_day=prod_day,
        sched_mode=sched_mode,
        key_contacts=key_contacts,
        atl_rows=atl_rows,
        talent_rows=talent_rows,
        crew_rows=crew_rows_bg,
        all_crew_rows=crew_rows,
        current_working_bid=current_working_bid,
        current_estimated_bid=current_estimated_bid,
        cs_data=cs_data,
        cs_rev=cs_rev,
        available_contacts=available_contacts,
        next_day_date=next_day_date,
        next_day_people=next_day_people,
        next_day_lines_preview=next_day_lines_preview,
        project_clients_cs=project_clients_cs,
        project_unions_cs=project_unions_cs,
        project_unions_cs_json=project_unions_cs_json,
        project_partners_cs_json=project_partners_cs_json,
        rep_contacts=rep_contacts,
        crew_p2_all=crew_p2_all,
        p2_custom_empty=p2_custom_empty,
        p2_custom_all=p2_custom_all,
        confirm_status=confirm_status,
        sent_versions=sent_versions,
        meal_counts=meal_counts,
        on_day_names=on_day_names,
        on_day_emails=on_day_emails,
        # Resolved logo layer (web URLs). pdf_mode swaps these for data: URIs in
        # _render_callsheet_real_pdf so weasyprint never fetches over the network.
        cs_logos=_resolve_callsheet_logos(cs_data, project, embed=False),
    )


def _callsheet_audience_flags(view):
    """Build the audience-view flag dict (csv) for a given view name.
    Internal = full; restricted views hide contact/section data per the
    confirmed matrix. Everything fails SAFE — an unknown view hides contacts.
    Shared by the internal editing view and the tokenized recipient view (the
    recipient view forces the view per recipient type)."""
    _v = (view or 'internal').strip().lower()
    if _v not in ('internal', 'crew', 'client', 'talent', 'union'):
        _v = 'internal'
    return _v, {
        'view':            _v,
        'is_full':         _v == 'internal',
        # Union used to be bare lists only ('logistics': _v != 'union') — but
        # that meant the union EDITOR view showed no locations to hide, while
        # union recipients fell through to the crew view and saw everything.
        # Union now shows logistics/KP like the others (contact info still
        # excluded below); redact per-sheet with per-view 👁 hides. (User
        # 2026-07-13: "make it show the locations... so I can hide things for
        # the union... and make sure it actually prints for them that way.")
        'logistics':       True,
        'crew_contact':    _v in ('internal', 'crew'),                     # phones/emails on crew rows
        'talent_contact':  _v == 'internal',
        # Agent/rep column on the cast grid — production-facing info, so
        # internal only (same policy as 'reps'). 2026-09-01.
        'talent_agent':    _v == 'internal',
        'clients':         _v in ('internal', 'client'),
        'reps':            _v == 'internal',
        'background':      _v in ('internal', 'crew'),                     # extras list (production-facing)
        'dept_notes':      _v in ('internal', 'crew'),
        'key_personnel':   True,                                           # names for all; contacts gated below
        'kp_contact':      _v in ('internal', 'crew'),                     # client/talent/union: KP names only
        'full_crew_list':  _v in ('internal', 'crew', 'client', 'union'),  # talent: no full crew list
        # Bottom-of-sheet zone (Meals Scheduled + Additional Notes + Quote):
        # everyone INCLUDING talent. Talent doesn't get the full crew grid, but a
        # cast member still needs meals + notes — redact per-sheet with per-view 👁
        # hides if a given day shouldn't show them. (User 2026-07-14.)
        'bottom_zone':     _v in ('internal', 'crew', 'client', 'union', 'talent'),
        'talent_list':     True,                                           # all views show cast (names ≥)
        'crew_phone_in_list': _v == 'crew',                               # crew view adds phone to the crew list
    }


@app.route("/projects/<int:pid>/budget/<int:bid>/callsheet")
@app.route("/projects/<int:pid>/budget/<int:bid>/callsheet/<date_str>")
@login_required
def callsheet_view(pid, bid, date_str=None):
    project = ProjectSheet.query.get_or_404(pid)
    budget  = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()

    sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'

    # All scheduled (non-off) dates for this budget/mode
    date_rows = db.session.query(ScheduleDay.date).filter(
        ScheduleDay.budget_id == bid,
        ScheduleDay.schedule_mode == sched_mode,
        ScheduleDay.day_type != 'off',
    ).distinct().order_by(ScheduleDay.date).all()
    all_scheduled_dates = [r[0] for r in date_rows]

    # Resolve selected date — remember last viewed per budget.
    # fromisoformat (not strptime %Y-%m-%d): it parses zero-padded odd years
    # ("0202-07-14") the same way isoformat() emits them, so nav URLs round-
    # trip even on corrupt-year rows instead of falling back to day 1 forever
    # (the "parked on July 14" bug, user 2026-07-09).
    _session_key = f"cs_last_date_{bid}"
    if date_str:
        try:
            selected_date = date.fromisoformat(date_str)
        except ValueError:
            selected_date = all_scheduled_dates[0] if all_scheduled_dates else date.today()
        from flask import session as _session
        _session[_session_key] = selected_date.isoformat()
    else:
        from flask import session as _session
        _saved = _session.get(_session_key)
        if _saved and all_scheduled_dates:
            try:
                _candidate = date.fromisoformat(_saved)
                selected_date = _candidate if _candidate in all_scheduled_dates else all_scheduled_dates[0]
            except ValueError:
                selected_date = all_scheduled_dates[0]
        else:
            selected_date = all_scheduled_dates[0] if all_scheduled_dates else date.today()

    ctx = _callsheet_full_context(
        pid, bid, project, budget, selected_date, sched_mode, all_scheduled_dates)

    # Audience view — request-scoped (internal editing view switcher).
    cs_view, csv_flags = _callsheet_audience_flags(request.args.get('view'))

    return render_template(
        "callsheet.html",
        recipient_mode=False,
        cs_view=cs_view,
        csv=csv_flags,
        **ctx,
    )


# ── Helpers ───────────────────────────────────────────────────────────────────


def _touch_budget(bid):
    """Update budget.updated_at to now. Call after any meaningful change."""
    now = datetime.utcnow()
    db.session.execute(text("UPDATE budget SET updated_at = :now WHERE id = :id"),
                       {"now": now, "id": bid})
    try:
        name = current_user.name or current_user.email.split("@")[0]
    except Exception:
        name = "someone"
    _budget_last_editor[bid] = {"name": name, "at": now}
    # Auto-sync budget start/end dates from schedule
    _sync_budget_dates_from_schedule(bid)


def _sync_budget_dates_from_schedule(bid):
    """Set budget.start_date / end_date from min/max of ScheduleDay dates.

    Ignores typing-artifact years (<1990) so one corrupt ScheduleDay can't
    drag the whole schedule window to year 0202 — which is exactly how
    CLIBURN 25's gantt got parked on 07/0202 (user 2026-07-09)."""
    try:
        row = (db.session.query(
                func.min(ScheduleDay.date), func.max(ScheduleDay.date))
               .filter(ScheduleDay.budget_id == bid,
                       ScheduleDay.date >= date(1990, 1, 1),
                       ScheduleDay.date <= date(2100, 12, 31))
               .first())
        if row and row[0]:
            budget = Budget.query.get(bid)
            if budget:
                budget.start_date = row[0]
                budget.end_date = row[1]
    except Exception:
        pass


def _budget_type(budget_mode):
    """Return 'working' for working/actual modes, else 'estimated'."""
    return 'working' if budget_mode in ('working', 'actual') else 'estimated'


def _supersede_current(project_id, budget_type, exclude_id=None):
    """Mark all 'current' budgets of the given type as 'superseded'."""
    budgets = Budget.query.filter_by(project_id=project_id, version_status='current').all()
    for b in budgets:
        if b.id == exclude_id:
            continue
        if _budget_type(b.budget_mode) == budget_type:
            b.version_status = 'superseded'


def _version_groups(all_budgets):
    """Group a project's budgets into version rows for the version pickers:
    [{version_number, estimated, working, is_current}], newest first.

    Skips is_actual budgets — they share budget_mode='working'/'actual' with
    real Working budgets but aren't peers in the version-group sense (the
    version switcher only swaps Estimated↔Working). Without this filter,
    peer_working_bid could resolve to the Actual budget when it's more
    recently created. C-5, 2026-05-08. Shared by budget_view AND gantt_view
    so the Budget and Schedule pages list IDENTICAL versions (2026-08-19).
    """
    _vn_map = {}
    for _b in all_budgets:
        if _b.is_actual:
            continue
        _vn = _b.version_number or 1
        if _vn not in _vn_map:
            _vn_map[_vn] = {'version_number': _vn, 'estimated': None, 'working': None}
        if _budget_type(_b.budget_mode) == 'estimated':
            # prefer current over superseded
            if _vn_map[_vn]['estimated'] is None or _b.version_status == 'current':
                _vn_map[_vn]['estimated'] = _b
        else:
            if _vn_map[_vn]['working'] is None or _b.version_status == 'current':
                _vn_map[_vn]['working'] = _b
    _max_vn = max(_vn_map.keys()) if _vn_map else 1
    for _vd in _vn_map.values():
        _vd['is_current'] = (_vd['version_number'] == _max_vn)
    return sorted(_vn_map.values(), key=lambda x: x['version_number'], reverse=True)


def _copy_budget_lines(source_id, dest_id, link_source=False):
    """Copy all BudgetLine rows from source budget to dest budget.
    Returns {old_line_id: new_line_id} mapping for use by _copy_schedule_days.

    Parent rows (parent_line_id=None) are processed first so that child rows
    (kit fees, etc.) can have their parent_line_id remapped correctly.

    link_source (AUDIT FIX 2026-07, HIGH-4): when True, each copied line gets
    source_line_id = its source line's id — the explicit clone link. This was
    never set on UI-created Working budgets, so every cross-budget resolver
    silently fell back to positional/description matching (the exact fragility
    source_line_id exists to fix).

    PHASE 4 (2026-07): now passed True for BOTH new Working budgets (link →
    their Estimated source line) AND new Estimated versions (link → the prior
    Estimated version's line). The estimated-side link completes the version
    chain old_working→est_vN←est_v(N+1)←new_working that
    create_working_from_estimated walks to remap coded transactions. A
    source_line_id set on an Estimated line is inert for every reader (audited
    STEP-0): resolvers either discriminate on the line's budget/is_actual or
    key off the current Working budget's lines exclusively.
    """
    src_lines = BudgetLine.query.filter_by(budget_id=source_id).order_by(
        BudgetLine.account_code, BudgetLine.sort_order).all()

    # Pre-load all crew assignments in one query to avoid lazy-load inside flush loop
    src_line_ids = [ln.id for ln in src_lines]
    src_cas = CrewAssignment.query.filter(
        CrewAssignment.budget_line_id.in_(src_line_ids)
    ).all() if src_line_ids else []
    cas_by_line = {}
    for ca in src_cas:
        cas_by_line.setdefault(ca.budget_line_id, []).append(ca)

    # Two-pass: parents first, then children (so line_id_map has parent IDs ready)
    parents  = [ln for ln in src_lines if not ln.parent_line_id]
    children = [ln for ln in src_lines if ln.parent_line_id]

    line_id_map = {}
    for ln in parents + children:
        new_ln = BudgetLine(
            budget_id=dest_id,
            account_code=ln.account_code,
            account_name=ln.account_name,
            description=ln.description,
            is_labor=ln.is_labor,
            sort_order=ln.sort_order,
            estimated_total=ln.estimated_total,
            payroll_co=ln.payroll_co,
            quantity=ln.quantity,
            days=ln.days,
            rate=ln.rate,
            rate_type=ln.rate_type,
            est_ot=ln.est_ot,
            fringe_type=ln.fringe_type,
            agent_pct=ln.agent_pct,
            note=ln.note,
            use_schedule=ln.use_schedule,
            days_unit=ln.days_unit,
            days_per_week=ln.days_per_week,
            # Identification fields
            line_tag=ln.line_tag,
            role_group=ln.role_group,
            unit_rate=ln.unit_rate,
            assigned_crew_id=ln.assigned_crew_id,
            # Parent-child relationship (remapped to new IDs)
            parent_line_id=line_id_map.get(ln.parent_line_id) if ln.parent_line_id else None,
            # Explicit clone link (Working → its Estimated source line).
            source_line_id=(ln.id if link_source else None),
            # ── 2026-05-26: previously missing — caused new-version totals
            # to diverge from source. sync_omit is the critical one: when
            # a source line has manual override on (per-diem qty hand-
            # tweaked, custom flight days set, etc.), failing to copy it
            # meant the new version booted with sync_omit=False, and the
            # next render's sync_schedule_driven_lines overwrote the
            # manual value with whatever the schedule computed. Source
            # kept the manual value (sync skipped it), copy got the auto
            # value → identical input, different output. User report
            # 2026-05-26 "when I make a new version of an estimated the
            # numbers don't match".
            #
            # The others (schedule_labels, po_id, catalog_item_id) don't
            # affect calc totals directly but should carry across version
            # boundaries so the new version mirrors the source's vendor
            # commitments / quick-entry catalog links / custom labels.
            #
            # working_total + manual_actual stay un-copied per the
            # deliberate "new budget = no working override" semantic.
            sync_omit=bool(getattr(ln, 'sync_omit', False)),
            schedule_labels=ln.schedule_labels,
            po_id=ln.po_id,
            catalog_item_id=ln.catalog_item_id,
        )
        db.session.add(new_ln)
        db.session.flush()  # get new_ln.id
        line_id_map[ln.id] = new_ln.id

        # Copy crew assignments (pre-loaded above — no lazy-load inside flush loop)
        for ca in cas_by_line.get(ln.id, []):
            db.session.add(CrewAssignment(
                budget_line_id=new_ln.id,
                instance=ca.instance or 1,
                crew_member_id=ca.crew_member_id,
                name_override=ca.name_override,
                rate_override=ca.rate_override,
                fringe_override=ca.fringe_override,
                agent_override=ca.agent_override,
                omit_flags=ca.omit_flags,
                role_number=ca.role_number,
            ))

    return line_id_map


def _copy_budget_extras(source_bid, dest_bid, dest_mode=None):
    """Copy budget-scoped editable tables that aren't budget_lines or
    schedule days: tax credits, catering bills, location-day bookings,
    direct-added contacts, and per-day call sheet overrides. Without
    this, every Working clone started with no tax credits / no catering
    plan / no location bookings even though the source Estimated had
    them — silent data loss the user only notices when something they
    configured is missing. 2026-05-06.

    Project-level data (FringeConfig with project_id, Locations,
    CrewMembers, Contacts) is shared automatically since it's scoped to
    project_id, not budget_id — no copy needed.
    """
    from models import (TaxCredit, CateringBill, LocationDay,
                        BudgetDirectContact, CallSheetData)

    # TaxCredit — copy every row with sort order preserved.
    for tc in TaxCredit.query.filter_by(budget_id=source_bid).all():
        db.session.add(TaxCredit(
            budget_id=dest_bid,
            name=tc.name, jurisdiction=tc.jurisdiction,
            credit_rate=tc.credit_rate, applies_to=tc.applies_to,
            min_spend=tc.min_spend, cap=tc.cap, notes=tc.notes,
            sort_order=tc.sort_order or 0,
        ))

    # CateringBill — vendor billing entries.
    for cb in CateringBill.query.filter_by(budget_id=source_bid).all():
        db.session.add(CateringBill(
            budget_id=dest_bid,
            period_start=cb.period_start, period_end=cb.period_end,
            vendor=cb.vendor, amount=cb.amount, note=cb.note,
        ))

    # LocationDay — per-day location bookings. Skip duplicates against
    # the unique constraint (budget_id, location_id, date).
    seen_ld = set()
    for ld in LocationDay.query.filter_by(budget_id=source_bid).all():
        key = (ld.location_id, ld.date)
        if key in seen_ld:
            continue
        seen_ld.add(key)
        db.session.add(LocationDay(
            budget_id=dest_bid,
            location_id=ld.location_id, date=ld.date,
            day_type=ld.day_type, note=ld.note,
        ))

    # BudgetDirectContact — manually-added contact-sheet entries.
    seen_dc = set()
    for dc in BudgetDirectContact.query.filter_by(budget_id=source_bid).all():
        if dc.crew_member_id in seen_dc:
            continue
        seen_dc.add(dc.crew_member_id)
        db.session.add(BudgetDirectContact(
            budget_id=dest_bid,
            crew_member_id=dc.crew_member_id,
            role=dc.role, sort_order=dc.sort_order or 0,
        ))

    # CallSheetData — per-day overrides. Map schedule_mode to 'working'
    # when cloning into a Working/Actual budget so the gantt finds them.
    dest_cs_mode = 'working' if dest_mode in ('working', 'actual') else None
    for cs in CallSheetData.query.filter_by(budget_id=source_bid).all():
        db.session.add(CallSheetData(
            budget_id=dest_bid,
            date=cs.date,
            schedule_mode=dest_cs_mode or cs.schedule_mode or 'estimated',
            data_json=cs.data_json,
        ))

    # Intentionally NOT copied:
    #   CallSheetSend  — historical send log; new budget = new history.
    #   ActivityLog    — audit log of actions on the source budget.


def _copy_schedule_days(source_bid, dest_bid, line_id_map, dest_mode=None):
    """Copy ScheduleDay + ProductionDay + TravelDetail rows verbatim.

    Every column on the source rows is reproduced on the destination so the
    cloned schedule produces identical sync_schedule_driven_lines output —
    meals, per-diem, hotel, flights, mileage all match the source.

    Critical fields the previous version dropped:
      - ProductionDay.is_production_day — drives meal-day filtering and
        production-day-only auto-injects (insurance daily rate, etc.).
        Without it the clone treated every day as non-production.
      - TravelDetail rows — FK to ScheduleDay, carry per-cell flight /
        hotel / car-rental / mileage data. Previously orphaned because
        the new ScheduleDay rows had new IDs.

    dest_mode: the budget_mode of the destination budget. When it is
    'working' or 'actual', copied rows are stored with schedule_mode=
    'working' so the Working gantt finds them immediately.
    2026-05-06 — fixes "schedule duplicate is recalculating meals/etc".
    """
    from models import TravelDetail
    dest_sched_mode = 'working' if dest_mode in ('working', 'actual') else None

    # Cross-family clone (owner 2026-07-22: "create a new estimated from the
    # previous working version"): a WORKING source cloned into an ESTIMATED
    # dest must land its schedule as 'estimated'-mode rows — otherwise the
    # new Estimated's schedule reads empty and use_schedule lines compute $0.
    # Copy only the source's active-mode rows (mode-tagged + legacy NULL,
    # deduped, tagged row wins) and restamp them.
    _src_budget = Budget.query.get(source_bid)
    _restamp = None
    if (_src_budget and _src_budget.budget_mode in ('working', 'actual')
            and dest_mode not in ('working', 'actual')):
        _restamp = 'estimated'

    # Build sched_id_map = {old_schedule_day_id: new_schedule_day_id} so
    # TravelDetail rows can be reparented onto the cloned ScheduleDays.
    sched_id_map = {}
    src_days = ScheduleDay.query.filter_by(budget_id=source_bid).all()
    if _restamp:
        _dd_cross = {}
        for d in src_days:
            if d.schedule_mode not in ('working', None):
                continue
            _k = (d.budget_line_id, d.crew_instance or 1, d.date)
            _ex = _dd_cross.get(_k)
            if _ex is None or (_ex.schedule_mode is None
                               and d.schedule_mode == 'working'):
                _dd_cross[_k] = d
        src_days = list(_dd_cross.values())
    for d in src_days:
        new_lid = line_id_map.get(d.budget_line_id)
        if d.budget_line_id and not new_lid:
            continue  # skip orphaned days (line wasn't copied)
        new_sd = ScheduleDay(
            budget_id=dest_bid,
            budget_line_id=new_lid,
            crew_member_id=d.crew_member_id,
            crew_instance=d.crew_instance,
            date=d.date,
            episode=d.episode,
            day_type=d.day_type,
            rate_multiplier=d.rate_multiplier,
            note=d.note,
            est_ot_hours=d.est_ot_hours,
            cell_flags=d.cell_flags,
            schedule_mode=_restamp or dest_sched_mode or d.schedule_mode,
        )
        db.session.add(new_sd)
        db.session.flush()  # so new_sd.id is available for TravelDetail FK
        sched_id_map[d.id] = new_sd.id

    # ── TravelDetail — per-(date, person, kind) flight / hotel / car
    # rental / mileage detail rows that FK to ScheduleDay. Previously
    # orphaned on every clone because new ScheduleDays got new IDs.
    if sched_id_map:
        src_tds = TravelDetail.query.filter(
            TravelDetail.schedule_day_id.in_(sched_id_map.keys())
        ).all()
        for td in src_tds:
            new_sd_id = sched_id_map.get(td.schedule_day_id)
            if not new_sd_id:
                continue
            db.session.add(TravelDetail(
                schedule_day_id=new_sd_id,
                kind=td.kind,
                confirmation_no=td.confirmation_no,
                notes=td.notes,
                airline=td.airline, flight_no=td.flight_no,
                depart_at=td.depart_at, arrive_at=td.arrive_at,
                depart_airport=td.depart_airport,
                arrive_airport=td.arrive_airport,
                hotel_name=td.hotel_name, hotel_address=td.hotel_address,
                check_in=td.check_in, check_out=td.check_out,
                room_type=td.room_type,
                rental_co=td.rental_co,
                pickup_at=td.pickup_at, return_at=td.return_at,
                pickup_location=td.pickup_location,
                miles=td.miles,
            ))

    # Clear any stale ProductionDay rows for dest_bid (e.g. from a previous
    # failed attempt where SQLite reused the same budget_id after a rollback).
    ProductionDay.query.filter_by(budget_id=dest_bid).delete()
    # Deduplicate by date before inserting — older DBs have UNIQUE(budget_id,
    # date) without schedule_mode, so we take the first row per date.
    seen_pd_dates = set()
    for pd in ProductionDay.query.filter_by(budget_id=source_bid).all():
        if pd.date in seen_pd_dates:
            continue
        seen_pd_dates.add(pd.date)
        db.session.add(ProductionDay(
            budget_id=dest_bid,
            date=pd.date,
            schedule_mode=dest_sched_mode or pd.schedule_mode,
            craft_services=getattr(pd, 'craft_services', False),
            courtesy_breakfast=pd.courtesy_breakfast,
            first_meal=pd.first_meal,
            second_meal=pd.second_meal,
            # is_production_day was missing before — that single boolean
            # reset to False on every clone changed which days counted
            # toward production-only auto-injects (insurance daily rate,
            # location day count, etc.), shifting the Working totals away
            # from Estimated even though everything LOOKED copied.
            is_production_day=getattr(pd, 'is_production_day', False),
        ))



def _infer_line_subgroup(ln):
    """Infer a line's sub-group (Direction / AD, Camera, etc.) from its
    role_group field OR by keyword-matching the description against
    _PROD_STAFF_SUBGROUPS / _TALENT_SUBGROUPS. Returns None for sections
    that don't use sub-groups."""
    rg = getattr(ln, 'role_group', None)
    if rg:
        return rg
    code = int(getattr(ln, 'account_code', 0) or 0)
    if code == COA_CODE_PROD_STAFF:
        for kw, grp in _PROD_STAFF_SUBGROUPS:
            if kw.lower() in (ln.description or '').lower():
                return grp
    elif code == COA_CODE_TALENT:
        try:
            return _get_talent_subgroup(ln.description)
        except Exception:
            return None
    return None


def _cluster_by_subgroup(lines):
    """Cluster a list of lines by their sub-group, preserving first-appearance
    order of each group. Used to keep same-group lines together so we don't
    render duplicate sub-department headers when new lines are added later.
    Only clusters lines in sub-grouped sections (currently 1000 Production Staff).
    Other sections pass through unchanged.

    Headers + spacers (line_tag in {'header','spacer'}) don't have a
    sub-group of their own. They get bucketed with the labor line that
    SITS ABOVE THEM in sort_order — so a header dragged between two
    Camera lines stays with Camera instead of bouncing to the
    uncategorized bucket. Per user 2026-05-26: "I drag it into the
    camera department. It keeps moving back out into a different spot
    each time."
    """
    is_subgrouped = any(
        int(getattr(ln, 'account_code', 0) or 0) == COA_CODE_PROD_STAFF for ln in lines
    )
    if not is_subgrouped:
        return list(lines)

    # Pre-pass: walk lines in sort_order and tag header/spacer rows
    # with the effective subgroup carried from the preceding labor line.
    # If there's no preceding labor line in this section, fall back to
    # the next labor line's group (so a header at the top of a section
    # sticks to the first group).
    by_sort = sorted(lines, key=lambda x: (x.sort_order or 0, x.id))
    effective_group = {}
    current_group = None
    # Forward pass for "carry from previous labor line".
    for ln in by_sort:
        tag = getattr(ln, 'line_tag', None)
        if tag in ('header', 'spacer'):
            effective_group[ln.id] = current_group
        else:
            g = _infer_line_subgroup(ln)
            if g:
                current_group = g
                effective_group[ln.id] = g
            else:
                effective_group[ln.id] = current_group
    # Backward pass to fill in headers/spacers that came BEFORE any
    # labor line (no preceding group to inherit from).
    next_group = None
    for ln in reversed(by_sort):
        tag = getattr(ln, 'line_tag', None)
        if tag in ('header', 'spacer'):
            if effective_group.get(ln.id) is None:
                effective_group[ln.id] = next_group
        else:
            g = _infer_line_subgroup(ln)
            if g:
                next_group = g

    group_order = []
    buckets = {}
    for ln in lines:
        g = effective_group.get(ln.id) or _infer_line_subgroup(ln) or ''
        if g not in buckets:
            buckets[g] = []
            group_order.append(g)
        buckets[g].append(ln)
    ordered = []
    for g in group_order:
        ordered.extend(sorted(buckets[g], key=lambda x: (x.sort_order or 0, x.id)))
    return ordered


def _order_lines_with_children(lines):
    """Return lines reordered so:
    1. Lines with the same role_group are clustered together (no duplicate
       sub-department headers when new Quick Entry lines are added later)
    2. Kit-fee/child rows appear immediately after their parent
    Ordering within each group is stable by (sort_order, id).
    """
    children_by_parent = {}
    parents = []
    for ln in lines:
        pid = getattr(ln, 'parent_line_id', None)
        if pid:
            children_by_parent.setdefault(pid, []).append(ln)
        else:
            parents.append(ln)

    ordered_parents = _cluster_by_subgroup(parents)

    result = []
    for ln in ordered_parents:
        result.append(ln)
        result.extend(children_by_parent.get(ln.id, []))

    # Orphaned children (parent in different section) go at end
    all_parent_ids = {ln.id for ln in ordered_parents}
    for pid, kids in children_by_parent.items():
        if pid not in all_parent_ids:
            result.extend(kids)
    return result


def _section_for_code(code):
    best = FP_COA_SECTIONS[0][0]
    for start, _ in FP_COA_SECTIONS:
        if code >= start:
            best = start
        else:
            break
    return best


def _section_name(code):
    for start, name in FP_COA_SECTIONS:
        if start == code:
            return name
    return str(code)


