@app.template_filter("currency")
def currency_filter(v):
    try:
        return f"${float(v):,.2f}"
    except (TypeError, ValueError):
        return "$0.00"


# ── Foreign-currency → USD conversion (2026-06-11) ─────────────────────────
# Receipts in CNY/KRW/GBP/EUR/… are converted to USD using the rate on the
# receipt's date, from frankfurter.dev (ECB data; free; no key). Rates cached
# in fx_rate (immutable historical facts). All best-effort: on any failure the
# caller keeps the original amount and flags the doc for manual review.
_FX_ALIASES = {
    'RMB': 'CNY', 'YUAN': 'CNY', '元': 'CNY', '￥': 'CNY', '¥': 'CNY',
    '£': 'GBP', 'GBP£': 'GBP', '€': 'EUR', 'EU': 'EUR', '₩': 'KRW', 'WON': 'KRW',
    'US$': 'USD', 'US': 'USD', '$': 'USD', 'USD$': 'USD',
}
# Currencies frankfurter/ECB publishes (the ones we can auto-convert).
_FX_SUPPORTED = {'USD', 'EUR', 'GBP', 'CNY', 'KRW', 'JPY', 'CAD', 'AUD', 'CHF',
                 'HKD', 'SGD', 'SEK', 'NOK', 'DKK', 'PLN', 'CZK', 'MXN', 'NZD',
                 'ZAR', 'BRL', 'INR', 'IDR', 'ILS', 'MYR', 'PHP', 'THB', 'TRY',
                 'HUF', 'RON', 'ISK', 'BGN'}


def _normalize_ccy(c):
    if not c:
        return None
    c = str(c).strip().upper()
    return _FX_ALIASES.get(c, c)


def _usd_rate_for(currency, date_str):
    """USD value of 1 unit of `currency` on date_str (YYYY-MM-DD). Cached in
    fx_rate. Returns float or None (unsupported / no date / fetch failed)."""
    cur = _normalize_ccy(currency)
    if cur == 'USD':
        return 1.0
    if not cur or cur not in _FX_SUPPORTED or not date_str:
        return None
    d = str(date_str)[:10]
    if len(d) != 10:
        return None
    row = FxRate.query.filter_by(date=d, currency=cur).first()
    if row:
        return float(row.usd_rate)
    try:
        import requests as _rq
        r = _rq.get(f"https://api.frankfurter.dev/v1/{d}",
                    params={"base": cur, "symbols": "USD"}, timeout=8)
        if r.status_code != 200:
            return None
        rate = (r.json().get("rates") or {}).get("USD")
        if rate is None:
            return None
        try:
            db.session.add(FxRate(date=d, currency=cur, usd_rate=rate))
            db.session.commit()
        except Exception:
            db.session.rollback()
        return float(rate)
    except Exception as _e:
        logging.warning(f"[fx] rate fetch failed {cur} {d}: {type(_e).__name__}")
        return None


def _convert_to_usd(amount, currency, date_str):
    """(usd_amount, rate, normalized_ccy). usd_amount/rate are None when the
    currency is non-USD but unconvertible (caller keeps the original + flags)."""
    cur = _normalize_ccy(currency)
    try:
        amt = float(amount)
    except (TypeError, ValueError):
        return (None, None, cur)
    if cur is None or cur == 'USD':
        return (round(amt, 2), 1.0, 'USD')
    rate = _usd_rate_for(cur, date_str)
    if rate is None:
        return (None, None, cur)
    return (round(amt * rate, 2), rate, cur)


@app.route("/admin/docs/project/<int:pid>/convert-foreign", methods=["POST"])
@login_required
def admin_docs_convert_foreign(pid):
    """Convert existing foreign-currency receipts to USD using each receipt's
    OCR currency + total and the FX rate on its date. Sets original_amount /
    original_currency, rewrites amount to USD, and updates the linked Actuals
    transaction. Skips docs already converted (original_currency set). Dry-run by
    default; ?apply=1 to write. Body/params: limit (default 500). (User
    2026-06-11.)"""
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access or access.role not in ('owner', 'collaborator', 'editor'):
            return jsonify({"error": "Forbidden"}), 403
    body = request.get_json(silent=True) or {}
    apply = (request.args.get('apply') == '1') or bool(body.get('apply'))
    try:
        limit = max(1, min(int(body.get('limit') or request.args.get('limit') or 500), 2000))
    except (TypeError, ValueError):
        limit = 500
    import json as _json
    rows = (DocUpload.query
            .filter(DocUpload.project_id == pid,
                    DocUpload.status != 'deleted',
                    DocUpload.original_currency.is_(None),   # not yet converted
                    DocUpload.veryfi_data.isnot(None))
            .all())
    converted, skipped, unconvertible, errors = 0, 0, [], []
    sample = []
    by_ccy = {}
    for d in rows:
        try:
            vr = _json.loads(d.veryfi_data) if d.veryfi_data else {}
        except Exception:
            vr = {}
        ccy = _normalize_ccy(vr.get('currency_code'))
        if not ccy or ccy == 'USD':
            skipped += 1
            continue
        try:
            foreign_total = float(vr.get('total'))
        except (TypeError, ValueError):
            unconvertible.append({"id": d.id, "reason": "no OCR total", "ccy": ccy})
            continue
        date_str = (d.doc_date.isoformat() if d.doc_date else (vr.get('date') or '')[:10]) or None
        usd, rate, _ = _convert_to_usd(foreign_total, ccy, date_str)
        by_ccy[ccy] = by_ccy.get(ccy, 0) + 1
        if usd is None:
            unconvertible.append({"id": d.id, "ccy": ccy, "amount": foreign_total,
                                  "reason": ("no date" if not date_str else "rate unavailable")})
            continue
        if len(sample) < 25:
            sample.append({"id": d.id, "vendor": d.vendor,
                           "from": f"{foreign_total:,.2f} {ccy}", "to_usd": usd,
                           "rate": rate, "date": date_str})
        if apply:
            try:
                d.original_amount = round(foreign_total, 2)
                d.original_currency = ccy
                d.amount = usd
                d.note = ((d.note + ' | ') if (d.note or '').strip() else '') + \
                    f"Converted {foreign_total:,.2f} {ccy} → ${usd:,.2f} @ {rate:.5f} on {date_str}"
                # Keep the linked Actuals transaction(s) in USD too.
                (Transaction.query
                 .filter_by(doc_upload_id=d.id)
                 .update({"amount": usd}, synchronize_session=False))
                db.session.commit()
            except Exception as e:
                db.session.rollback()
                errors.append(f"#{d.id}: {type(e).__name__}")
                continue
        converted += 1
    return jsonify({"dry": (not apply), "applied": apply,
                    "convertible": converted, "skipped_usd_or_none": skipped,
                    "unconvertible_count": len(unconvertible),
                    "by_currency": by_ccy,
                    "sample": sample, "unconvertible": unconvertible[:25],
                    "errors": errors[:25]})


# ── Background re-OCR of unpaired receipts (2026-06-11) ─────────────────────
# Re-runs Veryfi on receipts NOT linked to an electronic charge, to fix bad OCR
# amounts/dates and pick up a currency code (then convert to USD), so actuals
# read correctly and the matcher has clean data. Daemon thread + status poll,
# mirroring the source-import drain. Re-OCR costs Veryfi credits, so it's
# explicitly opt-in and bounded by `limit`.
_REPROCESS = {}   # pid -> progress dict (best-effort, per-worker; DB is truth)


def _call_veryfi_bounded(item, secs=90):
    """Run fp_analyzer._call_veryfi with a hard wall-clock cap. The Veryfi SDK
    has no client-side timeout, so one doc Veryfi can't fetch (huge/corrupt
    file, server-side stall) blocks the whole reprocess loop indefinitely. Run
    it in a daemon thread and abandon it if it overruns — returns None on
    timeout so the caller records an error, stamps the doc, and moves on. The
    stuck thread is daemon and the run is bounded, so a rare leak is harmless."""
    import threading as _th
    from fp_analyzer import _call_veryfi
    box = {}

    def _run():
        try:
            box['item'] = _call_veryfi(item)
        except Exception as e:   # noqa: BLE001
            box['err'] = e
    t = _th.Thread(target=_run, daemon=True)
    t.start()
    t.join(secs)
    if t.is_alive():
        return None              # timed out — leave the thread to die on its own
    if 'err' in box:
        raise box['err']
    return box.get('item')


def _unpaired_docs_base_query(pid):
    """Receipts/invoices NOT paired to an electronic charge, for project `pid`.

    Shared by the re-OCR worker and the status endpoint so both agree on the
    denominator. 'Paired' = a qbo_sync/csv_import/reconciled transaction points
    at the doc. Excludes deleted / duplicate docs.
    """
    paired_ids = (db.session.query(Transaction.doc_upload_id)
                  .filter(Transaction.project_id == pid,
                          Transaction.source.in_(('qbo_sync', 'csv_import', 'reconciled')),
                          Transaction.doc_upload_id.isnot(None)))
    return (DocUpload.query
            .filter(DocUpload.project_id == pid,
                    DocUpload.category.in_(('receipt', 'invoice')),
                    DocUpload.status.notin_(('deleted', 'duplicate')),
                    DocUpload.is_duplicate == False,           # noqa: E712
                    DocUpload.id.notin_(paired_ids)))


def _reprocess_worker(flask_app, pid, user_id, limit):
    import json as _json
    from datetime import datetime as _dt
    prog = _REPROCESS[pid]
    with flask_app.app_context():
        try:
            from fp_analyzer import _call_veryfi, extract_card_last4 as _c4
            # Resumable: only docs not yet stamped this campaign. A worker
            # recycle leaves reprocessed_at set on whatever was done, so a
            # re-kick picks up exactly the remainder instead of starting over.
            docs = (_unpaired_docs_base_query(pid)
                    .filter(DocUpload.reprocessed_at.is_(None))
                    .order_by(DocUpload.id).limit(limit).all())
            prog['total'] = len(docs)

            def _stamp(doc):
                # Mark attempted (success OR failure OR skip) in its own txn so
                # the queue always drains and nothing is retried forever.
                try:
                    doc.reprocessed_at = _dt.utcnow()
                    db.session.commit()
                except Exception:
                    db.session.rollback()

            for d in docs:
                if not prog['running']:
                    break
                path = d.source_archive_path or d.filed_dropbox_path
                if not path:
                    prog['skipped'] += 1
                    prog['processed'] += 1
                    _stamp(d)
                    continue
                try:
                    item = {"original_filename": d.original_filename or '', "staged_path": path}
                    item = _call_veryfi_bounded(item, secs=90)
                    vr = (item or {}).get("vr") or {}
                    if item is None or item.get("error") or not vr:
                        # None = OCR timed out (Veryfi couldn't fetch/parse this
                        # file); record + stamp so the queue keeps draining.
                        prog['errors'] = prog.get('errors', 0) + 1
                        prog['processed'] += 1
                        _stamp(d)
                        continue
                    v = vr.get("vendor") or {}
                    new_vendor = v.get("name") or v.get("raw_name") or d.vendor
                    try:
                        new_total = float(vr.get("total")) if vr.get("total") is not None else None
                    except Exception:
                        new_total = None
                    new_date = d.doc_date
                    try:
                        _ds = (vr.get("date") or "")[:10]
                        if _ds:
                            new_date = _dt.strptime(_ds, "%Y-%m-%d").date()
                    except Exception:
                        pass
                    ccy = _normalize_ccy(vr.get("currency_code"))
                    orig_amt, orig_ccy = None, None
                    usd_amount = new_total
                    if new_total is not None and ccy and ccy != 'USD':
                        _usd, _rate, _ = _convert_to_usd(new_total, ccy,
                                                         new_date.isoformat() if new_date else None)
                        orig_amt, orig_ccy = new_total, ccy
                        if _usd is not None:
                            usd_amount = _usd
                    # Apply updates
                    d.vendor = new_vendor
                    if new_date:
                        d.doc_date = new_date
                    if usd_amount is not None:
                        d.amount = usd_amount
                    if orig_ccy:
                        d.original_amount = orig_amt
                        d.original_currency = orig_ccy
                    _c = _c4(vr)
                    if _c:
                        d.card_last4 = _c
                    d.veryfi_data = _json.dumps(vr)
                    # Mirror onto the receipt's own ledger row.
                    upd = {"vendor": d.vendor}
                    if usd_amount is not None:
                        upd["amount"] = usd_amount
                    if new_date:
                        upd["txn_date"] = new_date.isoformat()
                    (Transaction.query
                     .filter_by(doc_upload_id=d.id, source='doc_upload')
                     .update(upd, synchronize_session=False))
                    d.reprocessed_at = _dt.utcnow()
                    # AI data cleanup on the freshly re-OCR'd doc (vendor
                    # normalization + extraction flags). force=True because OCR
                    # just rewrote the vendor. Advisory, fail-open. (2026-06-18.)
                    try:
                        r = _ai_clean_document(d, force=True)
                        if r and r.get('applied'):
                            prog['cleaned'] = prog.get('cleaned', 0) + 1
                    except Exception as _cle:
                        logging.warning(f"[reprocess] cleanup failed for doc #{d.id}: {_cle}")
                    db.session.commit()
                    prog['reprocessed'] += 1
                    prog['last'] = (d.vendor or '')[:40]
                except Exception as _pe:
                    db.session.rollback()
                    prog['errors'] = prog.get('errors', 0) + 1
                    _stamp(d)
                finally:
                    prog['processed'] += 1
                    try:
                        import gc as _gc; _gc.collect()
                    except Exception:
                        pass
            # Re-match now that the receipt data is cleaner.
            if prog.get('reprocessed'):
                try:
                    from actuals import run_auto_match
                    prog['auto_match_suggestions'] = run_auto_match(pid).get('suggestions')
                except Exception:
                    pass
                # Refresh the double-coded review queue so the Dashboard is ready
                # when the user comes back. (2026-06-18.)
                try:
                    _clusters, _flags = _run_double_coded_scan(pid)
                    db.session.commit()
                    prog['dup_flags'] = _flags
                except Exception:
                    db.session.rollback()
        except Exception as _we:
            prog['fatal'] = type(_we).__name__
        finally:
            prog['running'] = False
            prog['done'] = True
            try:
                db.session.remove()
            except Exception:
                pass


@app.route("/admin/docs/project/<int:pid>/reprocess-unpaired", methods=["POST"])
@login_required
def admin_docs_reprocess_unpaired(pid):
    """Start a background re-OCR of receipts not paired to an electronic charge.
    Returns immediately; poll /reprocess-unpaired-status. Re-OCR uses Veryfi
    credits. Body/params: limit (default 250); reset=1 clears prior
    reprocessed_at stamps to force a full fresh pass. The job is resumable —
    progress lives in doc_upload.reprocessed_at, so re-kicking after a worker
    recycle continues the remainder. (User 2026-06-11; resumable 2026-06-15.)"""
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access or access.role not in ('owner', 'collaborator', 'editor'):
            return jsonify({"error": "Forbidden"}), 403
    cur = _REPROCESS.get(pid)
    if cur and cur.get('running'):
        return jsonify({"already_running": True,
                        **{k: cur.get(k) for k in ('total', 'processed', 'reprocessed')}})
    body = request.get_json(silent=True) or {}
    try:
        limit = max(1, min(int(body.get('limit') or request.args.get('limit') or 250), 1000))
    except (TypeError, ValueError):
        limit = 250
    reset = str(body.get('reset') or request.args.get('reset') or '').lower() in ('1', 'true', 'yes')
    if reset:
        _unpaired_docs_base_query(pid).update({DocUpload.reprocessed_at: None},
                                              synchronize_session=False)
        db.session.commit()
    _REPROCESS[pid] = {'running': True, 'done': False, 'total': None, 'processed': 0,
                       'reprocessed': 0, 'skipped': 0, 'errors': 0, 'last': None}
    import threading
    threading.Thread(target=_reprocess_worker, args=(app, pid, current_user.id, limit),
                     daemon=True).start()
    return jsonify({"started": True, "limit": limit, "reset": reset})


@app.route("/cron/reprocess-unpaired", methods=["POST", "GET"])
def cron_reprocess_unpaired():
    """Unattended trigger for the reprocess job (no browser session needed) —
    for a scheduled 4pm-ET kick-off. The worker re-OCRs unpaired receipts, then
    runs AI cleanup + the double-coded scan. Auth: a secret token (env CRON_TOKEN)
    via ?token=, an X-Cron-Token header, or JSON body. DISABLED unless CRON_TOKEN
    is set on the server. Target with ?pid= or ?project=<name substring>.
    (User 2026-06-18.)"""
    expected = os.getenv("CRON_TOKEN")
    body = request.get_json(silent=True) or {}
    token = (request.args.get("token") or request.headers.get("X-Cron-Token")
             or body.get("token"))
    import hmac as _cron_hmac
    if not expected or not token or not _cron_hmac.compare_digest(str(token), str(expected)):
        return jsonify({"error": "forbidden"}), 403
    # Resolve the target project by id or by name substring.
    proj = None
    pid_raw = request.args.get("pid") or body.get("pid")
    if pid_raw:
        try:
            proj = ProjectSheet.query.get(int(pid_raw))
        except (TypeError, ValueError):
            proj = None
    if proj is None:
        name = (request.args.get("project") or body.get("project") or '').strip()
        if name:
            proj = (ProjectSheet.query
                    .filter(ProjectSheet.name.ilike(f"%{name}%"))
                    .order_by(ProjectSheet.id.desc()).first())
    if proj is None:
        return jsonify({"error": "project not found (pass ?pid= or ?project=)"}), 404
    pid = proj.id
    cur = _REPROCESS.get(pid)
    if cur and cur.get('running'):
        return jsonify({"already_running": True, "pid": pid})
    try:
        limit = max(1, min(int(request.args.get("limit") or body.get("limit") or 250), 1000))
    except (TypeError, ValueError):
        limit = 250
    reset = str(request.args.get("reset") or body.get("reset") or '').lower() in ('1', 'true', 'yes')
    if reset:
        _unpaired_docs_base_query(pid).update({DocUpload.reprocessed_at: None},
                                              synchronize_session=False)
        db.session.commit()
    _REPROCESS[pid] = {'running': True, 'done': False, 'total': None, 'processed': 0,
                       'reprocessed': 0, 'skipped': 0, 'errors': 0, 'last': None}
    import threading
    threading.Thread(target=_reprocess_worker, args=(app, pid, None, limit),
                     daemon=True).start()
    logging.info(f"[cron] reprocess+cleanup started for project {pid} ('{proj.name}'), limit {limit}")
    return jsonify({"started": True, "pid": pid, "project": proj.name, "limit": limit, "reset": reset})


@app.route("/admin/docs/project/<int:pid>/reprocess-unpaired-status", methods=["GET"])
@login_required
def admin_docs_reprocess_status(pid):
    """DB-derived progress — readable from ANY worker and accurate after a
    recycle (unlike the old per-worker in-memory dict). 'remaining' counts
    unpaired docs not yet stamped; 'done' is true when the queue is drained."""
    from sqlalchemy import func as _func
    base = _unpaired_docs_base_query(pid)
    total = base.count()
    remaining = base.filter(DocUpload.reprocessed_at.is_(None)).count()
    last_at = (base.filter(DocUpload.reprocessed_at.isnot(None))
               .with_entities(_func.max(DocUpload.reprocessed_at)).scalar())
    processed = total - remaining
    # "active" heuristic: a doc was stamped within the last 90s → a worker is
    # almost certainly still churning. Survives the status hitting a different
    # worker than the one running the job.
    active = False
    secs_since = None
    if last_at is not None:
        try:
            secs_since = (datetime.utcnow() - last_at).total_seconds()
            active = secs_since < 90 and remaining > 0
        except Exception:
            pass
    mem = _REPROCESS.get(pid) or {}
    return jsonify({
        "exists": total > 0 or processed > 0,
        "total": total, "processed": processed, "remaining": remaining,
        "done": remaining == 0 and total >= 0,
        "active": active or bool(mem.get('running')),
        "last_stamp_age_s": round(secs_since) if secs_since is not None else None,
        # best-effort live detail from whichever worker happens to serve this:
        "running": bool(mem.get('running')), "errors": mem.get('errors'),
        "reprocessed": mem.get('reprocessed'), "last": mem.get('last'),
        "auto_match_suggestions": mem.get('auto_match_suggestions'),
        "fatal": mem.get('fatal'),
    })


