def _ingest_document_bytes(pid, project, filename, content_type, data, uploader=None):
    """Full document-ingest pipeline for RAW BYTES — extracted verbatim from
    docs_upload_post (2026-09-01) so the Dropbox drop-folder sweep can push
    files through the IDENTICAL path as a web upload: Veryfi OCR -> type
    detection -> auto-file -> DocUpload row -> AI cleanup -> travel extract ->
    auto-Transaction -> claim sync. Returns (payload_dict, http_status);
    callers jsonify. uploader is REQUIRED in practice (DocUpload.uploader_id
    is NOT NULL) — the drop-folder sweep passes the sweeping user."""
    import hashlib, uuid as _uuid
    file_hash = hashlib.sha256(data).hexdigest()

    # Duplicate detection: hash match against an existing row in this
    # project that actually has a file in Dropbox. The strict rule —
    # `filed_dropbox_path IS NOT NULL` — kills ghost matches in two
    # failure modes:
    #   1. status='error' rows (Veryfi connection reset, OOM, etc.)
    #   2. partial-failure rows where OCR succeeded but the Dropbox
    #      filing step failed (status may be 'done' or 'review' but
    #      no file actually landed). Without this guard a re-upload
    #      gets flagged Duplicate against a phantom row.
    # `is_duplicate_of` carries the original upload id so the UI can
    # link back to the master copy.
    duplicate_of = (
        DocUpload.query
        .filter_by(project_id=pid, file_hash=file_hash)
        .filter(DocUpload.filed_dropbox_path.isnot(None))
        # Exclude review rows: they point at _UPLOADS_PENDING/, not a
        # real processed location. We don't want a not-yet-confirmed
        # upload to ghost-flag a fresh retry as a duplicate.
        .filter(DocUpload.status != 'review')
               .filter(DocUpload.status != 'deleted')
        .first()
    )

    content_type = content_type or "application/octet-stream"
    ext = os.path.splitext(filename)[1].lower() if filename else ""
    # r2_key kept as a unique filing id (for DocUpload.r2_key column).
    # The actual R2 upload was removed — source of truth is Dropbox.
    r2_key = f"docs/{pid}/{_uuid.uuid4().hex}{ext}"

    # Project must have a Dropbox folder set up for the Analyzer to file
    # to. If it doesn't, bail early so we don't save a ghost upload row.
    if not project.dropbox_folder:
        return jsonify({
            "error": "Project has no Dropbox folder configured — cannot file."
        }), 500

    # ── FP Document Analyzer integration (2026-04-20) ────────────────────
    # Route every upload through the embedded fp_analyzer: Veryfi OCR →
    # doc-type detection → auto-file to the correct 01_ADMIN subfolder
    # when confidence ≥ threshold. Low-confidence docs come back as
    # status='review' and the user finishes filing via the review UI.
    import re as _re
    from datetime import datetime as _dt
    from fp_analyzer import analyze_and_file_single
    import json as _json

    _raw_user = ((getattr(uploader, 'name', None)
                  or (getattr(uploader, 'email', '') or '').split('@')[0])
                 if uploader is not None else None) or 'drop-folder'
    _safe_user = _re.sub(r"[^\w\- ]", "", _raw_user) or "unknown"

    # Capture the size BEFORE running the analyzer so we can safely
    # release the bytes after the route finishes (the DocUpload row at
    # the bottom of this function only needs file_size, not the bytes
    # themselves).
    _data_size = len(data)

    try:
        result = analyze_and_file_single(
            file_bytes=data,
            filename=filename,
            project_name=project.dropbox_folder,   # Analyzer files under /{ops_root}/{project_name}/...
            user_name=_safe_user,
        )
    except Exception as _ae:
        logging.exception("Analyzer pipeline crashed")
        return {"error": f"Analyzer failed: {_ae}"}, 500
    # Release the file bytes now that the analyzer has consumed them
    # (it copies bytes into a temp file + Veryfi request internally).
    # Per user 2026-04-29: reduces peak working set so concurrent
    # uploads don't OOM Render's 512 MB worker. gc.collect runs at the
    # bottom of the route after the DB row is committed, NOT in a
    # finally block — earlier finally placement deleted `data` before
    # the DocUpload row was built and broke every upload with
    # UnboundLocalError on len(data).
    try:
        del data
    except Exception:
        pass

    status_map = {
        "filed":         "done",          # auto-filed to correct folder
        "needs_review":  "review",        # low-confidence → user picks in review UI
        "error":         "error",         # OCR / conversion failure
    }
    upload_status = status_map.get(result.get("status"), "error")

    # Extract structured OCR data from the Veryfi response so we can
    # display vendor/amount/date on the docs dashboard. The analyzer
    # now puts the raw vr on the result dict regardless of filed vs.
    # needs_review status, so high-confidence uploads also get their
    # extracted data stored on the row (was a bug — previously only
    # review rows kept the OCR data).
    vr = result.get("vr") or {}

    vendor_name = None
    amount      = None
    doc_date    = None
    doc_number  = None
    if vr:
        v = vr.get("vendor") or {}
        vendor_name = v.get("name") or v.get("raw_name")
        try:
            amount = float(vr.get("total")) if vr.get("total") is not None else None
        except Exception:
            amount = None
        try:
            from datetime import datetime as _dt_mod
            _d = vr.get("date") or ""
            doc_date = _dt_mod.strptime(_d[:10], "%Y-%m-%d").date() if _d else None
        except Exception:
            doc_date = None
        # Pull whichever doc-number-style field Veryfi extracted. We
        # don't yet know the user-confirmed type at this point so we
        # take the first available one — the modal will show it under
        # the right label depending on the doc type.
        doc_number = (vr.get("invoice_number")
                      or vr.get("purchase_order_number")
                      or vr.get("tax_id")
                      or vr.get("ein")
                      or None)
        if doc_number:
            doc_number = str(doc_number)[:100]
    from fp_analyzer import extract_card_last4 as _extract_card4
    card_last4 = _extract_card4(vr) if vr else None

    # Receipt detail for tax-credit reporting — Veryfi already returns subtotal /
    # tax / tip and the merchant address/phone; break them out so tip can be
    # excluded and name+address shown on submissions. (User 2026-07.)
    def _vmoney(x):
        try:
            return round(float(x), 2) if x not in (None, '', 'null') else None
        except (TypeError, ValueError):
            return None
    _v_ven   = (vr.get("vendor") or {}) if vr else {}
    r_subtotal = _vmoney(vr.get("subtotal")) if vr else None
    r_tax      = _vmoney(vr.get("tax")) if vr else None
    r_tip      = _vmoney(vr.get("tip")) if vr else None
    r_maddr    = (str(_v_ven.get("address"))[:300] if isinstance(_v_ven, dict) and _v_ven.get("address") else None)
    r_mphone   = (str(_v_ven.get("phone_number"))[:40] if isinstance(_v_ven, dict) and _v_ven.get("phone_number") else None)

    # Foreign-currency receipts → convert to USD by the receipt's date so the
    # ledger + matching use USD. Original foreign figure is kept; if conversion
    # isn't possible (unsupported currency / no date / fetch fail) we keep the
    # original amount and flag a note. (User 2026-06-11.)
    fx_original_amount = None
    fx_original_currency = None
    fx_note = None
    if vr and amount is not None:
        _ccy = _normalize_ccy(vr.get("currency_code"))
        if _ccy and _ccy != 'USD':
            fx_original_amount = amount
            fx_original_currency = _ccy
            _usd, _rate, _ = _convert_to_usd(amount, _ccy,
                                             doc_date.isoformat() if doc_date else None)
            if _usd is not None:
                fx_note = (f"Converted {fx_original_amount:,.2f} {_ccy} → "
                           f"${_usd:,.2f} @ {_rate:.5f} on {doc_date}")
                amount = _usd
            else:
                fx_note = (f"Foreign receipt ({_ccy}) — auto-conversion unavailable; "
                           f"amount is still {_ccy}, set USD manually")

    # Late-stage duplicate re-check. Catches the race where two parallel
    # POSTs for the same file both pass the pre-analysis duplicate query
    # (because neither has committed yet), then both file to Dropbox.
    # By the time we get here, the first request has typically already
    # committed its row — so the second one finds it. The second upload's
    # filed file then gets routed to /_DUPLICATES/ below, instead of
    # silently producing two clean copies.
    if not duplicate_of:
        duplicate_of = (
            DocUpload.query
            .filter_by(project_id=pid, file_hash=file_hash)
            .filter(DocUpload.filed_dropbox_path.isnot(None))
            .filter(DocUpload.status != 'review')
               .filter(DocUpload.status != 'deleted')
            .first()
        )

    # Persist the upload row with whatever we got back from the Analyzer.
    upload = DocUpload(
        project_id=pid,
        uploader_id=(uploader.id if uploader is not None else None),
        r2_key=r2_key,
        original_filename=filename,
        file_size=_data_size,
        content_type=content_type,
        file_hash=file_hash,
        status=upload_status,
        veryfi_data=_json.dumps(vr) if vr else None,
        vendor=vendor_name,
        amount=amount,                       # USD (converted if foreign)
        original_amount=fx_original_amount,  # foreign figure, if any
        original_currency=fx_original_currency,
        note=fx_note,
        doc_date=doc_date,
        doc_number=doc_number,
        card_last4=card_last4,
        subtotal=r_subtotal, tax=r_tax, tip=r_tip,
        merchant_address=r_maddr, merchant_phone=r_mphone,
        # confidence column is 0-100; Analyzer returns 0-1
        confidence=round(float(result.get("confidence") or 0) * 100, 2),
        category=result.get("doc_type"),
        veryfi_category=(vr.get("category") if vr else None),
        filed_filename=result.get("new_filename") or None,
        # For status='done': filed_path is the final processed location.
        # For status='review': fall back to staged_path so /docs/upload/
        # <uid>/raw can still serve the file from _SOURCE_ARCHIVE/ for
        # the preview modal. filed_at stays NULL so the UI knows the
        # doc isn't actually filed yet.
        filed_dropbox_path=result.get("filed_path") or result.get("staged_path"),
        filed_at=_dt.utcnow() if result.get("filed_path") else None,
        # Mission-critical fail-safe (2026-04-30): the source archive
        # path always points to the original uploaded bytes in Dropbox
        # at _SOURCE_ARCHIVE/, regardless of whether the processed copy
        # was filed, sent to review, or errored. The archive is never
        # deleted by the app — it's the durable source-of-truth.
        source_archive_path=result.get("staged_path"),
        # byte-hash match ONLY. A Dropbox autorename (" (1)" suffix) means a
        # DIFFERENT receipt happened to produce the same vendor/date/total
        # filename — NOT a duplicate. Treating it as one buried real spend with
        # no transaction. (Code review 2026-06-04.)
        is_duplicate=bool(duplicate_of),
        # Record WHICH upload the bytes matched so the docs UI can link
        # back and offer Keep-both / It's-a-duplicate. Only the exact
        # hash match (duplicate_of) carries an id; the soft filename-
        # collision signal (result['duplicate']) has no specific peer.
        duplicate_of_id=duplicate_of.id if duplicate_of else None,
    )
    db.session.add(upload)
    db.session.commit()

    # AI data cleanup (vendor normalization + extraction sanity). Advisory and
    # fail-open; runs BEFORE the auto-Transaction so the charge inherits the
    # clean vendor name. Auto-applies ≥0.70, else queues a review flag. (2026-06-18.)
    try:
        _ai_clean_document(upload)
        db.session.commit()
    except Exception as _cle:
        logging.warning(f"[docs/upload] ai cleanup failed for upload #{upload.id}: {_cle}")
        db.session.rollback()

    # Travel-doc intelligence: if this looks like a hotel/flight/car reservation,
    # auto-extract the confirmation # + travel details (suggestion only — the user
    # applies it to a person + travel day in the doc-detail Travel panel). Advisory
    # and fail-open. (User 2026-06-22.)
    try:
        if _looks_like_travel(upload):
            _ai_extract_travel(upload)
            db.session.commit()
    except Exception as _tle:
        logging.warning(f"[docs/upload] travel extract failed for upload #{upload.id}: {_tle}")
        db.session.rollback()

    # ── Auto-create a Transaction row for every doc upload (2026-04-30) ─
    # Each receipt / invoice / etc. that lands in Docs becomes an
    # immediate Actuals candidate: a Transaction with source='doc_upload'
    # and doc_upload_id set. budget_line_id stays NULL — the user picks
    # the line from the Actuals tab, which triggers the Working→Actual
    # auto-clone the first time.
    #
    # We skip duplicate-flagged uploads (already filed as a duplicate
    # of an earlier upload) and error-status uploads (no real file).
    # Tax forms / contracts / releases also skipped because they aren't
    # spend events — they're paperwork that lives in Docs but doesn't
    # belong on the actuals ledger.
    # Doc types that DO NOT create a Transaction at upload time:
    #   tax_form / contract / release / legal / insurance / misc → pure
    #     paperwork; not a spend event.
    #   estimate / quote / purchase_order → FORECAST documents (Working
    #     budget territory). They should feed planning, not actuals.
    #     Slice 3+ will surface a "Convert to Working line" affordance
    #     so the user can turn an estimate into a budgeted line item
    #     with the doc as backing paper. Until then they live as
    #     reference docs only.
    _NON_LEDGER_TYPES = {'tax_form', 'contract', 'release', 'legal',
                         'insurance', 'misc', 'employee_vendor_doc',
                         'estimate', 'quote', 'purchase_order'}
    auto_txn = None
    if (upload.status in ('done', 'review')
            and not upload.is_duplicate
            and (upload.category or '') not in _NON_LEDGER_TYPES):
        try:
            from datetime import datetime as _dt_mod
            _txn_date = upload.doc_date.isoformat() if upload.doc_date else None
            auto_txn = Transaction(
                project_id          = pid,
                source              = 'doc_upload',
                doc_upload_id       = upload.id,
                vendor              = upload.vendor,
                amount              = upload.amount,
                txn_date            = _txn_date,
                card_last4          = upload.card_last4,
                is_expense          = True,
                note                = upload.note,
                # No account_code yet — user picks budget line in Actuals.
                # match_status stays 'unmatched' until the user confirms.
                match_status        = 'unmatched',
                created_via_user_id = (uploader.id if uploader is not None else None),
            )
            db.session.add(auto_txn)
            db.session.flush()
            # Advisory AI coding suggestion (2026-06-18). Fail-open: a model
            # hiccup must never block the upload. Stored on the txn; the user
            # sees a "✨ suggested" chip in Actuals and clicks Accept to code.
            try:
                _ai_suggest_code_for_txn(auto_txn)
            except Exception as _ae:
                logging.warning(f"[docs/upload] ai categorize failed for txn "
                                f"#{auto_txn.id}: {_ae}")
            # Cross-project claim: a receipt upload is an affirmative
            # "this expense belongs here" signal. Fire _sync_claim_state
            # so any QBO sibling on another project (same vendor + amount
            # + date within ±5d) gets claimed_by_project_id set and
            # not_project_expense=True, dropping it out of that project's
            # uncoded pile. Without this, user uploads a Lyft receipt to
            # Etoro and the same Lyft in FP General Ops sits there
            # uncoded until they remember to fix it.
            try:
                _sync_claim_state(auto_txn)
            except Exception as _ce:
                logging.warning(f"[docs/upload] cross-project claim failed "
                                f"for txn #{auto_txn.id}: {_ce}")
            db.session.commit()
            logging.info(f"[docs/upload] Created Transaction #{auto_txn.id} "
                         f"from DocUpload #{upload.id} (vendor={upload.vendor!r}, "
                         f"amount={upload.amount}, doc_date={_txn_date})")
        except Exception as _te:
            logging.warning(f"[docs/upload] Auto-Transaction creation failed for "
                            f"upload #{upload.id}: {_te}")
            db.session.rollback()
            auto_txn = None

    # Activity log
    try:
        _log_activity(
            action='create', entity_type='doc_upload',
            entity_id=upload.id,
            entity_label=(upload.filed_filename or upload.original_filename or f'Upload #{upload.id}'),
            project_id=pid,
            before=None,
            after={'status': upload.status, 'vendor': upload.vendor,
                   'amount': float(upload.amount or 0),
                   'category': upload.category,
                   'transaction_id': auto_txn.id if auto_txn else None},
            note=f'Uploaded "{upload.original_filename}"' +
                 (f' (filed as {upload.category})' if upload.filed_dropbox_path else '') +
                 (f' → Actuals txn #{auto_txn.id}' if auto_txn else ''))
    except Exception: pass

    # If this upload's content hash matched an earlier row, FLAG it for
    # review instead of auto-burying it (per user 2026-05-29). The file
    # stays filed in its normal type-folder (Dropbox already gave it a
    # " (1)" suffix if the name collided), so a genuinely-separate but
    # byte-identical recurring invoice — same vendor / amount / date,
    # no invoice number — is never silently hidden. The docs UI shows a
    # "Possible duplicate of #X" banner with Keep-both / It's-a-duplicate
    # actions; /docs/upload/<uid>/resolve-duplicate does the burying only
    # when the user confirms. Veryfi can't disambiguate byte-identical
    # files (identical input → identical OCR), so user input is the only
    # reliable signal here.
    if duplicate_of and result.get("filed_path"):
        upload.note = (f"Possible duplicate of upload #{duplicate_of.id} "
                       f"({duplicate_of.filed_filename or duplicate_of.original_filename}). "
                       f"Review: keep both, or confirm it's a duplicate.")
        db.session.commit()
        logging.info(f"[DOCS] upload #{upload.id}: flagged as possible duplicate "
                     f"of #{duplicate_of.id} (awaiting review, NOT auto-buried)")

    # Force any remaining Pillow/Veryfi response buffers to release
    # before responding. Safe here because all DB work is committed.
    try:
        import gc as _gc
        _gc.collect()
    except Exception:
        pass

    # Build a structured client response so the upload UI can show the
    # correct state (filed with path, or needs review, or error).
    # Common bag of fields surfaced to the JS so the freshly-prepended
    # row carries the same OCR-extracted data the server-rendered rows
    # do (used by the doc-detail modal to pre-populate vendor/amount/
    # doc_date without an extra round-trip).
    _ocr_fields = {
        "vendor":     upload.vendor,
        "amount":     float(upload.amount) if upload.amount is not None else None,
        "doc_date":   upload.doc_date.isoformat() if upload.doc_date else None,
        "doc_number": upload.doc_number,
    }
    if result.get("status") == "filed":
        _is_dup = bool(duplicate_of)
        return {
            # "review_dup" tells the upload UI this is a flagged-but-kept
            # possible duplicate (filed in place, awaiting Keep-both /
            # confirm), distinct from the old "duplicate" = buried state.
            "status":      "review_dup" if _is_dup else "ok",
            "upload_id":   upload.id,
            "filed_path":  upload.filed_dropbox_path,
            # Include the renamed filename so the JS prepend shows the
            # Analyzer's date/vendor/amount-formatted name instead of
            # falling back to the original (often random/uuid) filename.
            "new_filename":   upload.filed_filename or result.get("new_filename"),
            "filed_filename": upload.filed_filename,
            "doc_type":    result.get("doc_type"),
            "confidence":  result.get("confidence"),
            "duplicate":   _is_dup or bool(result.get("duplicate")),
            "duplicate_of": duplicate_of.id if duplicate_of else None,
            "message":     (f"Possible duplicate of #{duplicate_of.id} — filed, flagged for review."
                            if _is_dup
                            else f"Filed as {result.get('doc_type')} ({int((result.get('confidence') or 0) * 100)}% confidence)."),
            **_ocr_fields,
        }, 201
    if result.get("status") == "needs_review":
        return {
            "status":      "review",
            "upload_id":   upload.id,
            "doc_type":    result.get("doc_type"),
            "confidence":  result.get("confidence"),
            "new_filename": result.get("new_filename"),
            "message":     f"OCR complete but confidence too low to auto-file "
                           f"({int((result.get('confidence') or 0) * 100)}%). Review required.",
            **_ocr_fields,
        }, 202
    # status == 'error'
    return {
        "status":   "error",
        "upload_id": upload.id,
        "error":    result.get("error") or "Unknown analyzer error",
    }, 500


@app.route("/docs/<int:pid>/upload", methods=["POST"])
@login_required
def docs_upload_post(pid):
    project = ProjectSheet.query.get_or_404(pid)
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access:
            return jsonify({"error": "Forbidden"}), 403

    f = request.files.get("file")
    if not f or not f.filename:
        return jsonify({"error": "No file provided"}), 400
    _upl_err = _validate_upload_file(f, 'document') if f else None
    if _upl_err:
        return jsonify({"error": _upl_err}), 400

    data = f.read()
    payload, code = _ingest_document_bytes(pid, project, f.filename,
                                           f.content_type, data,
                                           uploader=current_user)
    return jsonify(payload), code


# ── Dropbox drop folder (owner 2026-09-01) ───────────────────────────────
# "A dump folder where you download files, and then it processes it
#  through the document reader." Each project gets /<slug>/_INBOX in
# Dropbox; anything placed there is pulled through the SAME ingest
# pipeline as a web upload, then moved to _INBOX/_imported so it never
# double-processes. Swept on demand (📥 button) and automatically when
# the Docs tab loads (client-side throttled).

_DROP_FOLDER_NAME = "_INBOX"
_DROP_SWEEP_MAX_FILES = 10          # per sweep — bounds worker memory
_DROP_SWEEP_MAX_BYTES = 25 * 1024 * 1024


def _drop_folder_path(project):
    if _DBX_NAMESPACE_ID:
        return f"/{project.dropbox_folder}/{_DROP_FOLDER_NAME}"
    return f"{_DBX_OPS_ROOT}/{project.dropbox_folder}/{_DROP_FOLDER_NAME}"


@app.route("/projects/<int:pid>/docs/drop-sweep", methods=["POST"])
@login_required
def docs_drop_sweep(pid):
    project = ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    if not project.dropbox_folder:
        return jsonify({"error": "Project has no Dropbox folder configured."}), 400
    import mimetypes
    try:
        dbx = _dbx_client()
    except Exception as _ce:
        return jsonify({"error": f"Dropbox unavailable: {_ce}"}), 502
    path = _drop_folder_path(project)
    try:
        entries = dbx.files_list_folder(path).entries
    except Exception:
        # First use — create the folder (and its _imported child) so the
        # user has somewhere to drop files. Not an error.
        try:
            dbx.files_create_folder_v2(path)
        except Exception:
            pass
        try:
            dbx.files_create_folder_v2(f"{path}/_imported")
        except Exception:
            pass
        return jsonify({"ok": True, "created": True, "imported": 0, "skipped": 0,
                        "path": path,
                        "message": "Drop folder created — put files in it and sweep again."})
    import dropbox as _dbx_mod
    files = [e for e in entries if isinstance(e, _dbx_mod.files.FileMetadata)]
    allowed = _UPLOAD_ALLOW['document']
    imported, skipped, errors = 0, 0, []
    remaining = 0
    for i, e in enumerate(files):
        if imported + skipped >= _DROP_SWEEP_MAX_FILES:
            remaining = len(files) - i
            break
        ext = e.name.rsplit('.', 1)[-1].lower() if '.' in e.name else ''
        if ext not in allowed:
            skipped += 1
            errors.append(f"{e.name}: type .{ext or '?'} not accepted")
            continue
        if (e.size or 0) > _DROP_SWEEP_MAX_BYTES:
            skipped += 1
            errors.append(f"{e.name}: larger than 25 MB")
            continue
        try:
            _md, _resp = dbx.files_download(e.path_display)
            data = _resp.content
            ctype = mimetypes.guess_type(e.name)[0] or "application/octet-stream"
            payload, code = _ingest_document_bytes(
                pid, project, e.name, ctype, data, uploader=current_user)
            del data
            if code >= 500:
                skipped += 1
                errors.append(f"{e.name}: {payload.get('error') or 'ingest failed'}")
                continue   # leave the file in place for a retry
            imported += 1
            # Move out of the inbox so the next sweep doesn't re-read it
            # (the hash dedupe would catch it anyway — this keeps the
            # folder legible). Original bytes are already archived to
            # _SOURCE_ARCHIVE by the ingest pipeline.
            try:
                dbx.files_move_v2(e.path_display,
                                  f"{path}/_imported/{e.name}", autorename=True)
            except Exception as _mv:
                logging.warning(f"[drop-sweep] move failed for {e.name}: {_mv}")
        except Exception as _fe:
            db.session.rollback()
            skipped += 1
            errors.append(f"{e.name}: {_fe}")
            logging.exception(f"[drop-sweep] failed on {e.name}")
    try:
        import gc as _gc
        _gc.collect()
    except Exception:
        pass
    return jsonify({"ok": True, "imported": imported, "skipped": skipped,
                    "remaining": remaining, "errors": errors[:10], "path": path})


@app.route("/docs/upload/<int:uid>/retry-filing", methods=["POST"])
@login_required
def docs_upload_retry_filing(uid):
    """Retry filing an already-uploaded doc to Dropbox. Used when the initial
    upload succeeded to R2 but the Dropbox filing failed (common for legacy
    'pending' rows from before the current_user.username bug fix)."""
    upload = DocUpload.query.get_or_404(uid)
    # Access check
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(
            project_id=upload.project_id, user_id=current_user.id).first()
        if not access:
            return jsonify({"error": "Forbidden"}), 403
    if upload.status == 'filed':
        return jsonify({"ok": True, "already_filed": True,
                        "path": upload.filed_dropbox_path})

    project = ProjectSheet.query.get(upload.project_id)
    if not project or not project.dropbox_folder:
        return jsonify({"error": "Project has no Dropbox folder configured"}), 400

    # Re-fetch bytes: Dropbox filed copy → durable source archive → legacy R2.
    # (Was _r2_download only, but R2 uploads were removed — that path is a dead
    # store, so retry-filing always failed. _docs_fetch_bytes resolves the
    # bytes from whichever store still has them.)
    data, _fname = _docs_fetch_bytes(upload)
    if data is None:
        return jsonify({"error": "Could not locate source bytes for this upload"}), 500

    try:
        import re as _re
        from datetime import datetime as _dt
        from fp_analyzer import _safe_filename as _ana_safe_filename
        uploader = User.query.get(upload.uploader_id)
        _raw_user = (getattr(uploader, 'name', None)
                     or (uploader.email or '').split('@')[0]
                     or 'unknown') if uploader else 'unknown'
        _safe_user = _re.sub(r"[^\w\- ]", "", _raw_user) or "unknown"
        _proj_root = f"/{project.dropbox_folder}" if _DBX_NAMESPACE_ID else f"{_DBX_OPS_ROOT}/{project.dropbox_folder}"
        # Sanitize the filename into a single path segment — a '/' or '\' in the
        # original filename must not create surprise subfolders.
        _safe_name = _ana_safe_filename(upload.original_filename)
        dbx_filing_path = f"{_proj_root}/01_ADMIN/PROCESSED DOCUMENTS/{_safe_user}/{_safe_name}"
        _dbx = _dbx_client()
        from dropbox.files import WriteMode as _WM
        _dbx.files_upload(data, dbx_filing_path, autorename=True, mode=_WM('add'))
        upload.status = 'filed'
        upload.filed_dropbox_path = dbx_filing_path
        upload.filed_at = _dt.utcnow()
        db.session.commit()
        return jsonify({"ok": True, "path": dbx_filing_path})
    except Exception as e:
        logging.exception("Retry filing failed")
        return jsonify({"error": str(e)}), 500


@app.route("/docs/repair-extensions", methods=["GET", "POST"])
@login_required
def docs_repair_extensions():
    # Destructive/one-time repair tool — super-admin only before outside
    # users arrive (tools audit 2026-07-20).
    if getattr(current_user, 'role', None) != 'super_admin':
        abort(403)
    """Repair legacy DocUpload rows whose FILED file was named '.pdf' but whose
    bytes are actually a JPEG/PNG (the old build_name() hard-coded '.pdf' on
    every filed doc). The SOURCE ARCHIVE extension is ground truth — the
    pristine-archive flow always wrote true extensions.

    Scans rows where filed_dropbox_path ends '.pdf' AND source_archive_path
    ends '.jpg'/'.jpeg'/'.png'. In live mode (?dry=0) each filed file is moved
    to the same path with the corrected extension (autorename=True to survive
    collisions), and filed_dropbox_path / filed_filename / content_type are
    updated. Dry-run is the DEFAULT — mutations happen only on explicit ?dry=0.

    Query params:
      ?dry=1   (default) — report candidates only, no mutations.
      ?dry=0             — perform the renames.
      ?pid=<id>          — scope to a single project.
    """
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden"}), 403

    dry = (request.values.get("dry", "1").strip().lower() not in ("0", "false", "no"))
    pid = request.values.get("pid", type=int)

    _IMG_EXTS = ('.jpg', '.jpeg', '.png')
    _CT_BY_EXT = {'.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.png': 'image/png'}

    q = DocUpload.query.filter(
        DocUpload.filed_dropbox_path.isnot(None),
        DocUpload.source_archive_path.isnot(None),
    )
    if pid:
        q = q.filter(DocUpload.project_id == pid)

    candidates = []
    for u in q.all():
        filed = (u.filed_dropbox_path or '')
        arch_ext = os.path.splitext(u.source_archive_path or '')[1].lower()
        if filed.lower().endswith('.pdf') and arch_ext in _IMG_EXTS:
            candidates.append((u, arch_ext))

    renamed = 0
    errors = []
    sample = []
    dbx = None

    for u, arch_ext in candidates:
        old_path = u.filed_dropbox_path
        # Swap the trailing '.pdf' for the true archive extension.
        new_path = old_path[:-4] + arch_ext
        if len(sample) < 10:
            sample.append({"id": u.id, "from": old_path, "to": new_path})
        if dry:
            continue
        try:
            if dbx is None:
                dbx = _dbx_client()
            meta = dbx.files_move_v2(old_path, new_path, autorename=True)
            actual = meta.metadata.path_display
            u.filed_dropbox_path = actual
            u.filed_filename = os.path.basename(actual)
            u.content_type = _CT_BY_EXT.get(arch_ext, 'application/octet-stream')
            db.session.commit()
            renamed += 1
        except Exception as e:
            db.session.rollback()
            errors.append({"id": u.id, "err": f"{type(e).__name__}: {e}"})

    return jsonify({
        "ok": True,
        "dry": dry,
        "candidates": len(candidates),
        "renamed": renamed,
        "errors": errors,
        "sample": sample,
    })


def _split_integrity_doc_total(upload, parent):
    """doc_total for a document: abs(parent txn amount), else upload.amount.
    Mirrors the itemize endpoints' notion of the document's ceiling."""
    if parent is not None and parent.amount is not None:
        return abs(float(parent.amount))
    if upload.amount is not None:
        return abs(float(upload.amount))
    return 0.0


def _split_integrity_veryfi_items(upload):
    """Veryfi line items → [{description, amount}] — identical extraction to
    docs_upload_line_items so the healer's positional re-pair pairs the SAME
    rows the UI would have offered."""
    vd = {}
    if upload.veryfi_data:
        try:
            vd = upload.veryfi_data if isinstance(upload.veryfi_data, dict) else json.loads(upload.veryfi_data)
        except Exception:
            vd = {}
    items = []
    for li in (vd.get("line_items") or []):
        if not isinstance(li, dict):
            continue
        amt = li.get("total")
        if amt is None:
            amt = li.get("price")
        try:
            amt = round(abs(float(amt)), 2) if amt is not None else None
        except (TypeError, ValueError):
            amt = None
        desc = (li.get("description") or li.get("text") or '').strip()
        if desc or amt:
            items.append({"description": desc[:200], "amount": amt})
    return items


def _split_integrity_child_target(k):
    """Reconstruct a child's line-picker value the way docs_upload_line_items
    rehydrates it: WORKING line id, else 'section:<code>', else None."""
    if k.budget_line_id:
        bl = BudgetLine.query.get(k.budget_line_id)
        if bl:
            return str(_picker_value_for_line(bl))
    if k.account_code:
        return f"section:{k.account_code}"
    return None


@app.route("/admin/repair-date-years", methods=["GET", "POST"])
@login_required
def admin_repair_date_years(pid=None):
    # Destructive/one-time repair tool — super-admin only before outside
    # users arrive (tools audit 2026-07-20).
    if getattr(current_user, 'role', None) != 'super_admin':
        abort(403)
    """Repair typing-artifact YEARS in schedule-adjacent dates (2026-07-09).

    The HTML date input commits mid-keystroke ('2026' → 0202), which stored
    ScheduleDay/LocationDay/etc rows in year 202 and wedged the call-sheet
    date nav. Scans every date column that feeds schedules/call sheets for
    years < 1990 and (with ?dry=0) rewrites the year to ?year= (default 2026),
    keeping month/day.

    ?dry=1 (default) reports; ?dry=0 mutates. ?year=2026 target. super_admin.
    """
    if getattr(current_user, 'role', None) != 'super_admin':
        return jsonify({"error": "Forbidden"}), 403
    dry = (request.values.get("dry", "1").strip().lower() not in ("0", "false", "no"))
    try:
        target_year = int(request.values.get("year", "2026"))
    except ValueError:
        return jsonify({"error": "year must be an integer"}), 400
    if target_year < 1990 or target_year > 2100:
        return jsonify({"error": "target year out of range"}), 400

    from models import LocationDay, TravelDetail
    findings, fixed = [], 0

    def _scan(model, col_name, label_cols=()):
        nonlocal fixed
        col = getattr(model, col_name)
        rows = model.query.filter(col < date(1990, 1, 1)).all()
        for r in rows:
            old = getattr(r, col_name)
            if old is None:
                continue
            new = old.replace(year=target_year)
            findings.append({
                "table": model.__tablename__, "id": r.id, "column": col_name,
                "old": old.isoformat(), "new": new.isoformat(),
                **{lc: getattr(r, lc, None) for lc in label_cols},
            })
            if not dry:
                setattr(r, col_name, new)
                fixed += 1

    _scan(ScheduleDay,   "date", ("budget_id",))
    _scan(LocationDay,   "date", ("budget_id", "location_id"))
    _scan(ProductionDay, "date", ("budget_id",))
    _scan(CallSheetData, "date", ("budget_id",))
    _scan(CallSheetSend, "date", ("budget_id",))
    _scan(TravelDetail,  "check_in")
    _scan(TravelDetail,  "check_out")
    # Round 2 (2026-07-09): the gantt window defaults to Budget.start_date,
    # which the schedule auto-derive had stamped from the then-corrupt
    # ScheduleDays — the view stayed parked on 07/0202 after the day rows
    # were healed. Scan the derived/settings-entered date fields too.
    from models import PurchaseOrder
    _scan(Budget,        "start_date", ("project_id", "name"))
    _scan(Budget,        "end_date",   ("project_id", "name"))
    _scan(DocUpload,     "doc_date",   ("project_id",))
    _scan(PurchaseOrder, "issued_date", ("project_id",))

    if not dry and fixed:
        db.session.commit()
        try:
            _log_activity(action='update', entity_type='schedule_day', entity_id=0,
                          entity_label=f'Repaired {fixed} corrupt-year dates → {target_year}',
                          note='Typing-artifact years (<1990) rewritten; see server log')
        except Exception:
            pass
    return jsonify({"ok": True, "dry": dry, "target_year": target_year,
                    "found": len(findings), "fixed": fixed,
                    "findings": findings[:200]})


@app.route("/projects/<int:pid>/actuals/absorb-linked-receipts", methods=["GET", "POST"])
@login_required
def actuals_absorb_linked_receipts(pid):
    """Repair sweep (2026-07-08): absorb doc-born placeholder rows whose doc
    ALREADY rides on a charge. The manual /link-doc path historically set
    charge.doc_upload_id without merging the receipt's own placeholder txn the
    way the suggested-match Confirm path (actuals.confirm_match) does — so the
    receipt kept showing under "Receipts to place" after being linked.
    /link-doc now absorbs on the spot; this crawls the legacy leftovers.

    ?dry=1 (default) reports; ?dry=0 runs confirm_match per pair (which merges
    coding/card/note off the placeholder before deleting it).
    """
    if getattr(current_user, 'role', None) != 'super_admin':
        return jsonify({"error": "Forbidden"}), 403
    dry = (request.values.get("dry", "1").strip().lower() not in ("0", "false", "no"))
    ProjectSheet.query.get_or_404(pid)
    from actuals import confirm_match
    pairs, healed, skipped, errors = [], [], [], []
    charges = (Transaction.query
               .filter(Transaction.project_id == pid,
                       Transaction.doc_upload_id.isnot(None),
                       Transaction.source.notin_(('doc_upload', 'invoice_split')))
               .all())
    for t in charges:
        sister = (Transaction.query
                  .filter_by(doc_upload_id=t.doc_upload_id, source='doc_upload')
                  .first())
        if not sister or sister.id == t.id:
            continue
        entry = {"charge_id": t.id, "placeholder_id": sister.id,
                 "vendor": t.vendor, "doc_upload_id": t.doc_upload_id,
                 "charge_amount": float(t.amount) if t.amount is not None else None,
                 "placeholder_amount": float(sister.amount) if sister.amount is not None else None,
                 "match_status": t.match_status}
        pairs.append(entry)
        if dry:
            continue
        if t.match_status not in ('suggested', 'confirmed'):
            skipped.append(entry)     # ambiguous state — leave for a human
            continue
        try:
            confirm_match(t.id)
            healed.append(t.id)
        except Exception as e:
            db.session.rollback()
            errors.append({"charge_id": t.id, "error": f"{type(e).__name__}: {e}"})
    return jsonify({"ok": True, "dry": dry, "pairs": pairs,
                    "healed": healed, "skipped": skipped, "errors": errors})


@app.route("/projects/<int:pid>/docs/reset-person-invoices", methods=["GET", "POST"])
@login_required
def docs_reset_person_invoices(pid):
    """TEST-RESET (owner request 2026-07-08): return every PERSON-ATTACHED
    INVOICE in a project to fresh-upload state so the OCR→auto-matching
    pipeline can be re-tested end-to-end. The file + OCR (veryfi_data) stay
    intact; only match/coding/person state is cleared.

    Per doc (category='invoice', crew_member_id set):
      1. DELETE its invoice_split children (doc-wide net: doc_upload_id OR
         parent_transaction_id in the doc's non-split txn ids).
      2. UNMATCH any electronic charge holding the doc (unmatch_receipt —
         restores the doc-born row where confirming had absorbed it).
      3. CLEAR coding + review + match + AI/deterministic-suggestion state on
         every txn that was tied to the doc (incl. the unlinked charges).
      4. CLEAR doc.crew_member_id — person re-detection is part of the test.

    ?dry=1 (default): report + snapshot only. ?dry=0: mutate (per-doc commits,
    each inside try/except so one bad doc can't poison the batch).
    The full BEFORE snapshot is returned in BOTH modes — the caller must save
    it; it is the manual restore path.
    """
    if getattr(current_user, 'role', None) != 'super_admin':
        return jsonify({"error": "Forbidden"}), 403
    dry = (request.values.get("dry", "1").strip().lower() not in ("0", "false", "no"))
    ProjectSheet.query.get_or_404(pid)

    from sqlalchemy import or_ as _or_rpi
    from actuals import unlink_transaction, unmatch_receipt

    docs = (DocUpload.query
            .filter(DocUpload.project_id == pid,
                    DocUpload.category == 'invoice',
                    DocUpload.crew_member_id.isnot(None))
            .order_by(DocUpload.id.asc())
            .all())

    def _txn_snap(t):
        return {
            "id": t.id, "source": t.source, "vendor": t.vendor,
            "amount": float(t.amount) if t.amount is not None else None,
            "txn_date": t.txn_date, "note": t.note,
            "doc_upload_id": t.doc_upload_id,
            "parent_transaction_id": t.parent_transaction_id,
            "budget_line_id": t.budget_line_id,
            "account_code": t.account_code,
            "account_code_name": t.account_code_name,
            "match_status": t.match_status,
            "match_confidence": (float(t.match_confidence)
                                 if t.match_confidence is not None else None),
            "suggested_budget_line_id": t.suggested_budget_line_id,
            "suggested_account_code": t.suggested_account_code,
            "ai_suggested_code": t.ai_suggested_code,
            "ai_suggested_code_name": t.ai_suggested_code_name,
            "reviewed_at": (t.reviewed_at.isoformat() if t.reviewed_at else None),
            "reviewed_by": t.reviewed_by,
        }

    snapshot, reset_ids, errors = [], [], []
    for doc in docs:
        own = Transaction.query.filter_by(doc_upload_id=doc.id).all()
        own_ids = [t.id for t in own if t.source != 'invoice_split']
        kid_filters = [Transaction.doc_upload_id == doc.id]
        if own_ids:
            kid_filters.append(Transaction.parent_transaction_id.in_(own_ids))
        kids = (Transaction.query
                .filter(Transaction.source == 'invoice_split',
                        _or_rpi(*kid_filters))
                .all())
        snapshot.append({
            "doc": {"id": doc.id,
                    "filename": doc.filed_filename or doc.original_filename,
                    "vendor": doc.vendor,
                    "amount": float(doc.amount) if doc.amount is not None else None,
                    "crew_member_id": doc.crew_member_id,
                    "status": doc.status},
            "txns": [_txn_snap(t) for t in own if t.source != 'invoice_split'],
            "split_children": [_txn_snap(t) for t in kids],
        })
        if dry:
            continue
        try:
            kid_ids = {k.id for k in kids}
            for k in kids:
                db.session.delete(k)
            db.session.commit()
            charge_ids = []
            for t in own:
                if t.id in kid_ids:
                    continue
                if t.source not in ('doc_upload', 'invoice_split'):
                    unmatch_receipt(t.id)          # commits; clears doc link
                    charge_ids.append(t.id)
            # Everything that still points at the doc (doc-born row, possibly
            # freshly restored by unmatch_receipt) + the unlinked charges.
            sweep = Transaction.query.filter_by(doc_upload_id=doc.id).all()
            if charge_ids:
                sweep += Transaction.query.filter(Transaction.id.in_(charge_ids)).all()
            for t in sweep:
                if t.budget_line_id or t.account_code:
                    unlink_transaction(t.id)       # commits
                    t = Transaction.query.get(t.id)
                    if t is None:
                        continue
                t.suggested_budget_line_id = None
                t.suggested_account_code = None
                t.ai_suggested_code = None
                t.ai_suggested_code_name = None
                t.ai_code_confidence = None
                t.ai_code_reason = None
                t.match_status = 'unmatched'
                t.match_confidence = None
                t.reviewed_at = None
                t.reviewed_by = None
                t.updated_at = datetime.utcnow()
            doc.crew_member_id = None
            db.session.commit()
            reset_ids.append(doc.id)
        except Exception as e:
            db.session.rollback()
            logging.exception(f"[reset-person-invoices] doc {doc.id}: {e}")
            errors.append({"doc_id": doc.id, "error": f"{type(e).__name__}: {e}"})

    if not dry and reset_ids:
        try:
            _log_activity(action='update', entity_type='doc_upload', entity_id=0,
                          entity_label=f'Test-reset {len(reset_ids)} person invoices',
                          project_id=pid,
                          note='Fresh-upload matching test: uncoded, unmatched, '
                               'splits removed, person cleared')
        except Exception:
            pass

    return jsonify({"ok": True, "dry": dry, "candidates": len(docs),
                    "reset": reset_ids, "errors": errors,
                    "snapshot": snapshot})


@app.route("/docs/split-integrity", methods=["GET", "POST"])
@login_required
def docs_split_integrity():
    # Destructive/one-time repair tool — super-admin only before outside
    # users arrive (tools audit 2026-07-20).
    if getattr(current_user, 'role', None) != 'super_admin':
        abort(403)
    """One-time repair crawler for PHANTOM itemization splits (2026-07).

    Old itemization saves (before the over-total guard + doc-wide sweep) left
    two rot patterns behind:
      • BROKEN — a bad OCR pull filled EVERY child row with the FULL doc total
        (doc 739: 9 children × $4,121.54 = ~$37k of phantom coded spend on one
        $4,121.54 invoice), and/or stale children lingered under a doc's PREVIOUS
        parent after a parent-flip. The server-enforced invariant is: a doc's
        children may never sum to MORE than the doc total. So
        sum(children) > doc_total + 0.01 is DEFINITIVELY broken.
      • SUSPECT (report-only, never auto-touched) — a single child equal to the
        whole doc total with no description: might be a legit single-line split,
        might be a phantom; left for the owner to eyeball.

    SCAN (all projects, or ?pid=): every DocUpload with ANY invoice_split
    children (matched doc-wide: doc_upload_id == doc.id OR parent_transaction_id
    IN the doc's non-split txn ids — same net the itemize sweep casts).

    HEAL (live, ?dry=0, BROKEN docs only, each inside try/except):
      (a) POSITIONAL RE-PAIR — if the doc has veryfi_items, their count equals
          the number of NON-remainder children, and their amounts fit under the
          doc total: rebuild the itemization pairing item i's amount+description
          with child i's own budget line (children ordered by id = original pull
          order). Preserves a remainder child's target as the main line.
      (b) CLEAR + FLAG — otherwise delete ALL the doc's children, un-code the
          parent + siblings, and report the doc so the owner can redo it by hand.

    Both heal paths route through _itemize_apply — the SAME code the live
    /itemize save uses — so healed docs are byte-for-byte what a correct manual
    save would have produced.

    Query params:
      ?dry=1 (default) — classify + report only, no writes.
      ?dry=0           — perform the heals (mutations ONLY here).
      ?pid=<id>        — scope to a single project.
    """
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden"}), 403

    dry = (request.values.get("dry", "1").strip().lower() not in ("0", "false", "no"))
    pid = request.values.get("pid", type=int)

    from sqlalchemy import or_ as _or_si

    # Every DocUpload that owns at least one invoice_split child, scoped to
    # ?pid= if given. We collect distinct doc_upload_ids off the children so a
    # child stranded under a flipped parent (doc_upload_id still set) is caught.
    kq = Transaction.query.filter(Transaction.source == 'invoice_split',
                                  Transaction.doc_upload_id.isnot(None))
    if pid:
        kq = kq.filter(Transaction.project_id == pid)
    doc_ids = sorted({k.doc_upload_id for k in kq.all()})

    scanned = 0
    broken = 0
    suspects = []
    healed = []
    cleared = []
    errors = []
    phantom_removed_total = 0.0

    for did in doc_ids:
        try:
            upload = DocUpload.query.get(did)
            if upload is None:
                continue
            if pid and upload.project_id != pid:
                continue
            parent = _doc_parent_txn(did)
            # Doc-wide child match: by doc_upload_id OR under any of the doc's
            # NON-split txn ids (mirrors the itemize replace-on-save sweep).
            sib_ids = [t.id for t in Transaction.query
                       .filter(Transaction.doc_upload_id == did,
                               Transaction.source != 'invoice_split').all()]
            cq = Transaction.query.filter(
                Transaction.source == 'invoice_split',
                _or_si(Transaction.doc_upload_id == did,
                       Transaction.parent_transaction_id.in_(sib_ids) if sib_ids
                       else Transaction.doc_upload_id == did))
            kids = cq.order_by(Transaction.id).all()
            if not kids:
                continue
            scanned += 1

            doc_total = _split_integrity_doc_total(upload, parent)
            kid_sum = round(sum(float(k.amount) for k in kids if k.amount is not None), 2)
            fname = upload.filed_filename or upload.original_filename or f'Upload #{upload.id}'

            is_broken = kid_sum > doc_total + 0.01

            # SUSPECT (report-only): a lone child == full doc total, no desc,
            # not the remainder feed. Never auto-touched.
            if (not is_broken and len(kids) == 1
                    and abs(float(kids[0].amount or 0) - doc_total) <= 0.01
                    and not (kids[0].note or '').strip()
                    and (kids[0].note or '') != 'Remainder → main line'):
                suspects.append({"id": upload.id, "filename": fname,
                                 "child_amt": round(float(kids[0].amount or 0), 2)})
                continue

            if not is_broken:
                continue
            broken += 1

            # --- Classify the heal path (needed for BOTH dry + live) ---
            non_rem = [k for k in kids if (k.note or '') != 'Remainder → main line']
            rem_kids = [k for k in kids if (k.note or '') == 'Remainder → main line']
            items = _split_integrity_veryfi_items(upload)
            item_sum = round(sum((it["amount"] or 0.0) for it in items), 2)
            can_repair = bool(items) and len(items) == len(non_rem) and \
                (doc_total <= 0 or item_sum <= doc_total + 0.01)

            # main_line_raw for the rebuild: preserve an existing remainder
            # child's target; else '' (healed docs get no synthetic main line).
            main_raw = _split_integrity_child_target(rem_kids[0]) if rem_kids else ''

            if can_repair:
                rows = [{"amount": items[i]["amount"] or 0.0,
                         "description": items[i]["description"],
                         "budget_line_id": _split_integrity_child_target(non_rem[i])}
                        for i in range(len(non_rem))]
                new_sum = round(sum((r["amount"] or 0.0) for r in rows), 2)
                # remainder that _itemize_apply would auto-append to main line
                if main_raw and (doc_total - new_sum) > 0.01:
                    new_sum = round(new_sum + (doc_total - new_sum), 2)
                phantom_removed_total += round(kid_sum - min(new_sum, doc_total), 2)
                entry = {"id": upload.id, "filename": fname,
                         "children": len(rows), "new_sum": new_sum}
                if dry:
                    healed.append(entry)
                else:
                    # strict=False: legacy rebuilds pass uncoded children
                    # verbatim so healing stays byte-for-byte. (2026-07-20.)
                    result, status = _itemize_apply(upload, parent, rows, main_raw,
                                                    strict=False)
                    if status:
                        errors.append({"id": upload.id, "err": result.get("error", "apply rejected")})
                    else:
                        entry["children"] = result.get("children", len(rows))
                        healed.append(entry)
            else:
                # CLEAR + FLAG — reuse the itemize clear path (rows=[], main '').
                reason = ("no veryfi items to re-pair from" if not items else
                          f"{len(items)} items != {len(non_rem)} non-remainder children"
                          if len(items) != len(non_rem) else
                          f"items sum ${item_sum:,.2f} exceeds doc total ${doc_total:,.2f}")
                phantom_removed_total += round(kid_sum - min(0.0, doc_total), 2)
                entry = {"id": upload.id, "filename": fname, "reason": reason}
                if dry:
                    cleared.append(entry)
                else:
                    result, status = _itemize_apply(upload, parent, [], '')
                    if status:
                        errors.append({"id": upload.id, "err": result.get("error", "clear rejected")})
                    else:
                        cleared.append(entry)
        except Exception as e:
            db.session.rollback()
            errors.append({"id": did, "err": f"{type(e).__name__}: {e}"})

    return jsonify({
        "ok": True,
        "dry": dry,
        "scanned_docs_with_children": scanned,
        "broken": broken,
        "suspects": suspects,
        "healed": healed,
        "cleared": cleared,
        "errors": errors,
        "phantom_removed_total": round(phantom_removed_total, 2),
    })


