@app.route("/docs/upload/<int:uid>/preview-link", methods=["GET"])
@login_required
def docs_upload_preview_link(uid):
    """Generate a short-lived Dropbox temporary link for the filed file
    so the docs detail modal can embed the image / PDF inline. Dropbox
    temporary links expire in 4 hours — plenty for a session, but the
    client re-fetches per modal open so a stale link is never served."""
    upload = DocUpload.query.get_or_404(uid)
    deny = _docs_check_row_access(upload)
    if deny:
        return deny

    if not upload.filed_dropbox_path:
        return jsonify({"error": "No filed file to preview"}), 404

    _ops_prefix_str = (_DBX_OPS_ROOT or "").rstrip("/") if _DBX_NAMESPACE_ID else ""
    raw_path  = upload.filed_dropbox_path
    norm_path = raw_path
    if _ops_prefix_str and norm_path.startswith(_ops_prefix_str + "/"):
        norm_path = norm_path[len(_ops_prefix_str):]

    try:
        dbx = _dbx_client()
    except Exception as e:
        return jsonify({"error": f"Dropbox init failed: {e}"}), 500

    last_err = None
    for path_try in (norm_path, raw_path) if norm_path != raw_path else (norm_path,):
        try:
            res = dbx.files_get_temporary_link(path_try)
            return jsonify({
                "ok":           True,
                "url":          res.link,
                "content_type": upload.content_type or "application/octet-stream",
                "filename":     upload.filed_filename or upload.original_filename,
            })
        except Exception as e:
            last_err = e
            continue
    return jsonify({
        "error": f"Dropbox temp link failed: {type(last_err).__name__}: {last_err}",
    }), 500


@app.route("/docs/upload/<int:uid>/dropbox-link", methods=["GET"])
@login_required
def docs_upload_dropbox_link(uid):
    """Return a permanent Dropbox shared-link URL for the filed file so
    the docs detail modal's "Open in Dropbox" button opens the web UI
    preview (NOT the temp content URL, which downloads). Uses
    sharing_create_shared_link_with_settings; if a shared link already
    exists for this path, Dropbox returns it via list_shared_links."""
    upload = DocUpload.query.get_or_404(uid)
    deny = _docs_check_row_access(upload)
    if deny:
        return deny

    if not upload.filed_dropbox_path:
        return jsonify({"error": "No filed file"}), 404

    _ops_prefix_str = (_DBX_OPS_ROOT or "").rstrip("/") if _DBX_NAMESPACE_ID else ""
    raw_path  = upload.filed_dropbox_path
    norm_path = raw_path
    if _ops_prefix_str and norm_path.startswith(_ops_prefix_str + "/"):
        norm_path = norm_path[len(_ops_prefix_str):]

    try:
        dbx = _dbx_client()
    except Exception as e:
        return jsonify({"error": f"Dropbox init failed: {e}"}), 500

    def _shared_link_for(path_try):
        """Try to fetch or create a shared link for one Dropbox path.
        Returns (url, error). Mirrors the duplicated logic that used to
        live inline so we can call it for both filed and archive paths."""
        from dropbox.sharing import SharedLinkSettings, RequestedVisibility
        try:
            _existing = dbx.sharing_list_shared_links(path=path_try, direct_only=True)
            if _existing.links:
                return _existing.links[0].url, None
        except Exception:
            pass
        try:
            link = dbx.sharing_create_shared_link_with_settings(
                path_try,
                settings=SharedLinkSettings(requested_visibility=RequestedVisibility.team_only),
            )
            return link.url, None
        except Exception as e:
            if "shared_link_already_exists" in str(e):
                try:
                    _existing = dbx.sharing_list_shared_links(path=path_try, direct_only=True)
                    if _existing.links:
                        return _existing.links[0].url, None
                except Exception as e2:
                    return None, e2
            return None, e

    last_err = None
    primary_url = None
    for path_try in (norm_path, raw_path) if norm_path != raw_path else (norm_path,):
        url, err = _shared_link_for(path_try)
        if url:
            primary_url = url
            break
        last_err = err

    # Source archive link — surfaces in the modal as "📎 Source" so the
    # user can always recover the original uploaded bytes regardless of
    # what happened to the processed copy. Best-effort; never fail the
    # primary call over an archive link.
    archive_url = None
    if upload.source_archive_path:
        try:
            arch_norm = upload.source_archive_path
            if _ops_prefix_str and arch_norm.startswith(_ops_prefix_str + "/"):
                arch_norm = arch_norm[len(_ops_prefix_str):]
            archive_url, _ = _shared_link_for(arch_norm)
        except Exception:
            archive_url = None

    if primary_url:
        return jsonify({
            "ok": True,
            "url": primary_url,
            "archive_url":  archive_url,
            "archive_path": upload.source_archive_path,
        })
    return jsonify({
        "error": f"Could not create Dropbox link: {type(last_err).__name__}: {last_err}",
        "archive_url":  archive_url,
        "archive_path": upload.source_archive_path,
    }), 500


def _doc_intended_path(upload):
    """Where this DocUpload SHOULD live in Dropbox given its CURRENT (maybe
    user-edited) fields — mirrors the analyzer's Option-B filing layout:
      {ops}/{project}/{TYPE_FOLDER}/{uploader}[/{vendor}]/{date_TYPE_…_amount.pdf}
    Built from the row's own fields (not the original OCR), so vendor / type
    / date / amount / doc-number edits all reflect. Returns None if it can't
    resolve (no project folder / type). 2026-05-29."""
    from fp_analyzer import DOCUMENT_TYPES, build_name, safe as _ana_safe, _ops_prefix
    proj = ProjectSheet.query.get(upload.project_id)
    proj_name = (proj.dropbox_folder or '').strip('/') if proj else ''
    doc_type = (upload.category or 'misc').lower()
    type_folder = DOCUMENT_TYPES.get(doc_type, DOCUMENT_TYPES['misc'])
    if not proj_name or not type_folder:
        return None
    # Synthetic Veryfi-shaped dict so build_name applies the correct
    # per-type token order (e.g. invoice → date_vendor_invoice#_total).
    vr = {
        "date":   upload.doc_date.isoformat() if upload.doc_date else "",
        "vendor": {"name": upload.vendor or "Unknown"},
        "total":  float(upload.amount) if upload.amount is not None else None,
        "invoice_number":        upload.doc_number or None,
        "purchase_order_number": upload.doc_number or None,
        "tax_id":                upload.doc_number or None,
    }
    # True extension: the source archive carries the real format (JPEG phone
    # photos stay .jpg, not a mislabeled .pdf). Fall back to the filed name's
    # extension, then '.pdf'.
    _true_ext = (os.path.splitext(upload.source_archive_path or '')[1]
                 or os.path.splitext(upload.filed_filename or '')[1]
                 or '.pdf').lower()
    fname = build_name(vr, doc_type, ext=_true_ext)
    ops  = _ops_prefix()
    base = f"{ops}/{proj_name}/{type_folder}" if ops else f"/{proj_name}/{type_folder}"
    up = upload.uploader
    raw = (up.name if (up and up.name) else
           (up.email.split('@')[0] if (up and up.email) else 'unknown'))
    raw = re.sub(r"[^\w\- ]", "", raw) or "unknown"   # matches upload-time _safe_user
    user_folder = _ana_safe(raw)
    if doc_type in ('invoice', 'contract', 'purchase_order', 'insurance'):
        return f"{base}/{user_folder}/{_ana_safe(upload.vendor or 'Unknown_Vendor')}/{fname}"
    # Employee/Vendor supporting docs are organised by the PERSON they're
    # attached to (the crew dropdown), not the uploader — so every doc for a
    # given person lands in one packet folder:
    #   …/EMPLOYEE_VENDOR_DOCS/<Person>/<date>_EMPDOC_<doctype>.pdf
    # Falls back to the uploader folder when no crew member is linked yet.
    # (User 2026-05-30.)
    if doc_type == 'employee_vendor_doc':
        person_folder = None
        if upload.crew_member_id:
            cm = CrewMember.query.get(upload.crew_member_id)
            if cm and (cm.name or '').strip():
                person_folder = _ana_safe(cm.name.strip())
        return f"{base}/{person_folder or user_folder}/{fname}"
    return f"{base}/{user_folder}/{fname}"


def _filing_matches(cur_path, intended_path):
    """True if the filed file is already where it should be. Ignores:
      • a Dropbox autorename ' (1)' suffix (collision churn), and
      • letter case — Dropbox is case-insensitive but case-preserving, so a
        path differing only by case (e.g. greg_Oldenburg vs Greg_Oldenburg)
        is the SAME location; trying to "move" it just throws a folder
        write-conflict. Treat it as already-correct. (User 2026-05-29.)"""
    def _norm(p):
        b = os.path.basename(p or '')
        b = re.sub(r' \(\d+\)(\.[^.]+)$', r'\1', b)
        return (os.path.dirname(p or '').lower(), b.lower())
    return _norm(cur_path) == _norm(intended_path)


def _refile_doc(upload, dry=False):
    """Move a filed doc's Dropbox copy to match its current fields. Skips
    review/unfiled rows and special folders (_DUPLICATES / _SOURCE_ARCHIVE /
    _UPLOADS_PENDING). Returns {changed, from, to, error?}. On a real run it
    updates filed_dropbox_path / filed_filename (caller commits)."""
    cur = upload.filed_dropbox_path
    if not cur or upload.status not in ('done', 'filed'):
        return {"changed": False, "reason": "not filed"}
    if any(seg in cur for seg in ('/_DUPLICATES/', '/_SOURCE_ARCHIVE/', '/_UPLOADS_PENDING/')):
        return {"changed": False, "reason": "special folder"}
    intended = _doc_intended_path(upload)
    if not intended:
        return {"changed": False, "reason": "unresolved"}
    if _filing_matches(cur, intended):
        return {"changed": False, "reason": "already correct"}
    if dry:
        return {"changed": True, "dry": True, "from": cur, "to": intended,
                "id": upload.id, "name": upload.filed_filename or upload.original_filename}
    from fp_analyzer import get_dropbox_client as _ana_dbx
    dbx = _ana_dbx()
    try:
        meta = dbx.files_move_v2(cur, intended, autorename=True,
                                 allow_ownership_transfer=False)
        final = meta.metadata.path_display
        upload.filed_dropbox_path = final
        upload.filed_filename     = os.path.basename(final)
        logging.info(f"[refile] upload #{upload.id}: {cur} → {final}")
        return {"changed": True, "from": cur, "to": final, "id": upload.id}
    except Exception as e:
        # Self-heal: a prior partial/interrupted run may have ALREADY moved
        # the file to `intended` without recording it (DB still points at the
        # old path → move source is now not_found). If the intended location
        # holds the file, just record it — no data lost, idempotent re-runs.
        if 'not_found' in str(e).lower():
            try:
                m2 = dbx.files_get_metadata(intended)
                final = getattr(m2, 'path_display', intended)
                upload.filed_dropbox_path = final
                upload.filed_filename     = os.path.basename(final)
                logging.info(f"[refile] upload #{upload.id}: healed DB → {final} (file already moved)")
                return {"changed": True, "healed": True, "from": cur, "to": final, "id": upload.id}
            except Exception:
                pass
        logging.warning(f"[refile] upload #{upload.id} move failed: {e}")
        return {"changed": False, "error": str(e), "from": cur, "to": intended, "id": upload.id}


@app.route("/projects/<int:pid>/debug-mirror", methods=["GET"])
@login_required
def debug_mirror(pid):
    # Destructive/one-time repair tool — super-admin only before outside
    # users arrive (tools audit 2026-07-20).
    if getattr(current_user, 'role', None) != 'super_admin':
        abort(403)
    """Diagnostic: what does the auto-mirror resolve + do? Returns the resolved
    working/actual budget ids, how many Working lines lack a mirror, and the
    result (or error) of calling ensure_actual_mirrors. (User 2026-06-02.)"""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden"}), 403
    all_b = Budget.query.filter_by(project_id=pid).all()
    wbid = next((b.id for b in all_b if _budget_type(b.budget_mode) == 'working'
                 and not b.is_actual and b.version_status == 'current'), None)
    abid = next((b.id for b in all_b if b.is_actual and b.version_status == 'current'), None)
    w = Budget.query.get(wbid) if wbid else None
    a = Budget.query.get(abid) if abid else None
    have = {l.source_line_id for l in a.lines if l.source_line_id} if a else set()
    missing = [l.id for l in (w.lines if w else []) if l.id not in have]
    result = {"wbid": wbid, "abid": abid,
              "working_line_count": (len(w.lines) if w else 0),
              "actual_source_links": len(have),
              "missing_count": len(missing), "missing_ids": missing[:10],
              "wbudget_mode": (w.budget_mode if w else None),
              "abudget_mode": (a.budget_mode if a else None)}
    from actuals import ensure_actual_mirrors
    try:
        result["added"] = ensure_actual_mirrors(pid, working_bid=wbid, actual_bid=abid)
        result["error"] = None
    except Exception as e:
        db.session.rollback()
        import traceback as _tb
        result["added"] = None
        result["error"] = type(e).__name__ + ': ' + str(e)[:200]
        result["tb"] = _tb.format_exc()[-400:]
    return jsonify(result)


@app.route("/projects/<int:pid>/actual-audit", methods=["GET"])
@login_required
def actual_audit(pid):
    """READ-ONLY diagnostic for the Actual-mirrors-Working invariant. Reports,
    without writing anything:
      • line counts for estimated / working / actual budgets
      • actual_orphans  : Actual lines whose source_line_id is NULL or does not
                          point at a line in the current Working budget — with a
                          count of every dependent row (txns, crew, schedule,
                          sub-budget, docs, locations) so we know what is at
                          stake before touching them, plus a best-guess merge
                          target (a Working line with the same account+desc).
      • working_missing : Working lines with no Actual mirror (these SHOULD be
                          created so Actual reflects Working).
      • dup_src         : Working line ids that >1 Actual line points at
                          (true duplicate mirrors) — the live-bug shape.
      • actual_dup_desc : (account_code, lower desc) groups inside the Actual
                          budget with more than one line.
    Admin only. (User 2026-06-01.)"""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    ProjectSheet.query.get_or_404(pid)
    all_b = Budget.query.filter_by(project_id=pid).all()
    def _pick(kind):
        return (next((b for b in all_b if _budget_type(b.budget_mode) == kind
                      and not b.is_actual and b.version_status == 'current'), None)
                or next((b for b in all_b if _budget_type(b.budget_mode) == kind
                         and not b.is_actual and b.version_status != 'archived'), None))
    est = _pick('estimated')
    wrk = _pick('working')
    act = (next((b for b in all_b if b.is_actual and b.version_status == 'current'), None)
           or next((b for b in all_b if b.is_actual and b.version_status != 'archived'), None))
    if not (wrk and act):
        return jsonify({"error": "could not resolve working + actual budgets"}), 400

    wlines = BudgetLine.query.filter_by(budget_id=wrk.id).all()
    alines = BudgetLine.query.filter_by(budget_id=act.id).all()
    w_by_id = {l.id: l for l in wlines}
    # Working line lookup by (account, normalized desc) for orphan merge hints.
    w_by_key = {}
    for w in wlines:
        w_by_key.setdefault((w.account_code, (w.description or '').strip().lower()), []).append(w.id)

    a_ids = [l.id for l in alines]
    def _counts(model, col='budget_line_id'):
        if not a_ids:
            return {}
        from sqlalchemy import func as _f
        rows = (db.session.query(getattr(model, col), _f.count(model.id))
                .filter(getattr(model, col).in_(a_ids))
                .group_by(getattr(model, col)).all())
        return {k: int(v) for k, v in rows if k is not None}
    c_txn  = _counts(Transaction)
    c_txns = _counts(Transaction, 'suggested_budget_line_id')
    c_crew = _counts(CrewAssignment)
    c_sch  = _counts(ScheduleDay)
    c_sub  = _counts(SubBudgetLine)
    c_loc  = _counts(Location)
    def _deps(lid):
        # DocUpload links to a line indirectly (via Transaction.doc_upload_id),
        # so it is captured by the txn count — it has no budget_line_id of its own.
        return {"txn": c_txn.get(lid, 0), "txn_sugg": c_txns.get(lid, 0),
                "crew": c_crew.get(lid, 0), "sched": c_sch.get(lid, 0),
                "sub": c_sub.get(lid, 0), "loc": c_loc.get(lid, 0)}

    # actual lines grouped by the working line they mirror
    src_map = {}
    orphans = []
    for a in alines:
        if a.source_line_id and a.source_line_id in w_by_id:
            src_map.setdefault(a.source_line_id, []).append(a.id)
        else:
            hint = w_by_key.get((a.account_code, (a.description or '').strip().lower()), [])
            d = _deps(a.id)
            orphans.append({"id": a.id, "code": a.account_code,
                            "desc": (a.description or '')[:40],
                            "src": a.source_line_id, "parent": a.parent_line_id,
                            "tag": a.line_tag, "deps": d,
                            "dep_total": sum(d.values()),
                            "merge_hint_working_ids": hint})
    dup_src = [{"working_id": wid, "working_desc": (w_by_id[wid].description or '')[:40],
                "actual_ids": ids, "deps_each": {str(i): _deps(i) for i in ids}}
               for wid, ids in src_map.items() if len(ids) > 1]
    working_missing = [{"id": w.id, "code": w.account_code, "desc": (w.description or '')[:40],
                        "tag": w.line_tag, "parent": w.parent_line_id}
                       for w in wlines if w.id not in src_map]

    # duplicate (account, desc) groups inside actual
    a_by_key = {}
    for a in alines:
        a_by_key.setdefault((a.account_code, (a.description or '').strip().lower()), []).append(a)
    actual_dup_desc = []
    for (code, desc), grp in a_by_key.items():
        if len(grp) > 1 and desc:
            actual_dup_desc.append({"code": code, "desc": desc[:40],
                                    "lines": [{"id": g.id, "src": g.source_line_id,
                                               "parent": g.parent_line_id, "tag": g.line_tag,
                                               "deps": _deps(g.id)} for g in grp]})

    return jsonify({
        "budgets": {"estimated": {"id": est.id if est else None,
                                  "lines": (len(BudgetLine.query.filter_by(budget_id=est.id).all()) if est else 0)},
                    "working": {"id": wrk.id, "lines": len(wlines)},
                    "actual":  {"id": act.id, "lines": len(alines)}},
        "summary": {"actual_orphans": len(orphans),
                    "working_missing_mirror": len(working_missing),
                    "dup_src_groups": len(dup_src),
                    "actual_dup_desc_groups": len(actual_dup_desc)},
        "actual_orphans": sorted(orphans, key=lambda o: -o["dep_total"]),
        "working_missing": working_missing,
        "dup_src": dup_src,
        "actual_dup_desc": actual_dup_desc,
    })


@app.route("/projects/<int:pid>/rebuild-actual-mirror", methods=["POST"])
@login_required
def rebuild_actual_mirror(pid):
    # Destructive/one-time repair tool — super-admin only before outside
    # users arrive (tools audit 2026-07-20).
    if getattr(current_user, 'role', None) != 'super_admin':
        abort(403)
    """Make the Actual budget structurally MIRROR the Working budget by fixing
    the duplicate-clone corruption surfaced by /actual-audit. Three operations,
    each independently gated; dry-run by default (apply only with ?apply=1):

      DEDUP (always planned): for every Working line that >1 Actual line points
        at (source_line_id), keep the Actual line carrying the most dependent
        rows (transactions/crew/schedule/sub-budget/location — tiebreak: lowest
        id) and DELETE the empty twin(s). Before deleting a twin we:
          • migrate any dependent rows it does carry onto the keeper
            (txn.budget_line_id + .suggested_budget_line_id, crew, schedule,
            sub-budget, location), and
          • re-parent any Actual line whose parent_line_id pointed at the twin
            to the keeper,
        so nothing is orphaned and no transaction is lost.

      CREATE (?create=1, default on apply): clone every Working line that has NO
        Actual mirror into the Actual budget (so new Working lines — e.g. a kit
        fee — appear in Actual), parent remapped through the source chain.

      ORPHANS: Actual lines whose source_line_id is null/invalid. Those with
        ZERO dependents are deleted (?drop_orphans=1). Those carrying data are
        NEVER touched here — they're reported under orphans_kept for manual
        review (could be a real expense whose Working line was deleted).

    Does NOT change planned/computed fields on surviving lines (fringe/rate/
    sort) — that's the separate /sync-actual-from-working?fields=1 path.
    Admin only. (User 2026-06-01.)"""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    apply = (request.args.get('apply') == '1')
    do_create = (request.args.get('create') == '1') or apply  # default-on when applying
    drop_orphans = (request.args.get('drop_orphans') == '1')
    ProjectSheet.query.get_or_404(pid)
    all_b = Budget.query.filter_by(project_id=pid).all()
    def _pick(kind):
        return (next((b for b in all_b if _budget_type(b.budget_mode) == kind
                      and not b.is_actual and b.version_status == 'current'), None)
                or next((b for b in all_b if _budget_type(b.budget_mode) == kind
                         and not b.is_actual and b.version_status != 'archived'), None))
    wrk = _pick('working')
    act = (next((b for b in all_b if b.is_actual and b.version_status == 'current'), None)
           or next((b for b in all_b if b.is_actual and b.version_status != 'archived'), None))
    if not (wrk and act):
        return jsonify({"error": "could not resolve working + actual budgets"}), 400

    wlines = BudgetLine.query.filter_by(budget_id=wrk.id).all()
    alines = BudgetLine.query.filter_by(budget_id=act.id).all()
    w_by_id = {l.id: l for l in wlines}
    a_by_id = {l.id: l for l in alines}
    a_ids = list(a_by_id.keys())

    from sqlalchemy import func as _f
    def _counts(model, col='budget_line_id'):
        if not a_ids:
            return {}
        rows = (db.session.query(getattr(model, col), _f.count(model.id))
                .filter(getattr(model, col).in_(a_ids))
                .group_by(getattr(model, col)).all())
        return {k: int(v) for k, v in rows if k is not None}
    c_txn  = _counts(Transaction)
    c_txns = _counts(Transaction, 'suggested_budget_line_id')
    c_crew = _counts(CrewAssignment)
    c_sch  = _counts(ScheduleDay)
    c_sub  = _counts(SubBudgetLine)
    c_loc  = _counts(Location)
    def _dep_total(lid):
        return (c_txn.get(lid, 0) + c_txns.get(lid, 0) + c_crew.get(lid, 0)
                + c_sch.get(lid, 0) + c_sub.get(lid, 0) + c_loc.get(lid, 0))

    # children-by-parent within the actual budget (for safe reparenting)
    children_of = {}
    for l in alines:
        if l.parent_line_id:
            children_of.setdefault(l.parent_line_id, []).append(l.id)

    # group actual lines by the working line they mirror
    src_map = {}
    orphan_lines = []
    for a in alines:
        if a.source_line_id and a.source_line_id in w_by_id:
            src_map.setdefault(a.source_line_id, []).append(a)
        else:
            orphan_lines.append(a)

    report = {"dry": (not apply), "applied": apply,
              "budgets": {"working": wrk.id, "actual": act.id},
              "counts_before": {"working": len(wlines), "actual": len(alines)},
              "dedup": {"groups": 0, "delete": [], "migrations": [], "reparents": []},
              "create": {"count": 0, "lines": []},
              "orphans_dropped": [], "orphans_kept": [],
              "errors": []}

    delete_ids = set()
    keeper_for = {}   # twin_id -> keeper_id

    # ── 1) DEDUP ──────────────────────────────────────────────────────
    for wid, grp in src_map.items():
        if len(grp) <= 1:
            continue
        report["dedup"]["groups"] += 1
        grp_sorted = sorted(grp, key=lambda l: (-_dep_total(l.id), l.id))
        keeper = grp_sorted[0]
        for twin in grp_sorted[1:]:
            delete_ids.add(twin.id)
            keeper_for[twin.id] = keeper.id
            mig = {"twin": twin.id, "keeper": keeper.id, "desc": (twin.description or '')[:30],
                   "moved": {"txn": c_txn.get(twin.id, 0), "txn_sugg": c_txns.get(twin.id, 0),
                             "crew": c_crew.get(twin.id, 0), "sched": c_sch.get(twin.id, 0),
                             "sub": c_sub.get(twin.id, 0), "loc": c_loc.get(twin.id, 0)}}
            if any(mig["moved"].values()):
                report["dedup"]["migrations"].append(mig)
            else:
                report["dedup"]["delete"].append({"twin": twin.id, "keeper": keeper.id,
                                                  "desc": (twin.description or '')[:30]})

    # reparent plan: any actual line whose parent is a doomed twin → keeper
    for twin_id in list(delete_ids):
        for child_id in children_of.get(twin_id, []):
            if child_id in delete_ids:
                continue
            report["dedup"]["reparents"].append({"child": child_id, "from": twin_id,
                                                  "to": keeper_for[twin_id]})

    # ── 2) CREATE missing mirrors ─────────────────────────────────────
    missing = [w for w in wlines if w.id not in src_map]
    report["create"]["count"] = len(missing)
    report["create"]["lines"] = [{"working_id": w.id, "desc": (w.description or '')[:32],
                                   "tag": w.line_tag} for w in missing]

    # ── 3) ORPHANS ────────────────────────────────────────────────────
    for o in orphan_lines:
        if _dep_total(o.id) == 0:
            report["orphans_dropped"].append({"id": o.id, "desc": (o.description or '')[:32],
                                               "src": o.source_line_id, "tag": o.line_tag})
        else:
            report["orphans_kept"].append({"id": o.id, "desc": (o.description or '')[:32],
                                           "src": o.source_line_id, "tag": o.line_tag,
                                           "deps": {"txn": c_txn.get(o.id, 0),
                                                    "txn_sugg": c_txns.get(o.id, 0),
                                                    "crew": c_crew.get(o.id, 0),
                                                    "sched": c_sch.get(o.id, 0),
                                                    "sub": c_sub.get(o.id, 0),
                                                    "loc": c_loc.get(o.id, 0)}})

    report["projected_actual_lines"] = (len(alines) - len(delete_ids)
                                        + (len(missing) if do_create else 0)
                                        - (len(report["orphans_dropped"]) if drop_orphans else 0))

    # ── APPLY ─────────────────────────────────────────────────────────
    if apply:
        try:
            # a) migrate dependents off each twin onto its keeper, then reparent
            for twin_id in delete_ids:
                keep = keeper_for[twin_id]
                Transaction.query.filter_by(budget_line_id=twin_id).update(
                    {"budget_line_id": keep}, synchronize_session=False)
                Transaction.query.filter_by(suggested_budget_line_id=twin_id).update(
                    {"suggested_budget_line_id": keep}, synchronize_session=False)
                ScheduleDay.query.filter_by(budget_line_id=twin_id).update(
                    {"budget_line_id": keep}, synchronize_session=False)
                SubBudgetLine.query.filter_by(budget_line_id=twin_id).update(
                    {"budget_line_id": keep}, synchronize_session=False)
                Location.query.filter_by(budget_line_id=twin_id).update(
                    {"budget_line_id": keep}, synchronize_session=False)
                # crew: avoid (budget_line_id, instance) unique clash — bump
                # instance numbers past whatever the keeper already uses.
                ca_twin = CrewAssignment.query.filter_by(budget_line_id=twin_id).all()
                if ca_twin:
                    maxi = db.session.query(_f.max(CrewAssignment.instance)).filter_by(
                        budget_line_id=keep).scalar() or 0
                    for i, ca in enumerate(ca_twin, start=1):
                        ca.budget_line_id = keep
                        ca.instance = maxi + i
                # reparent children of the twin onto the keeper
                BudgetLine.query.filter_by(parent_line_id=twin_id).update(
                    {"parent_line_id": keep}, synchronize_session=False)
            db.session.flush()
            # b) delete the twins
            if delete_ids:
                BudgetLine.query.filter(BudgetLine.id.in_(delete_ids)).delete(
                    synchronize_session=False)
            db.session.flush()
            # c) create missing mirrors
            if do_create and missing:
                _skip = {'id', 'budget_id', 'source_line_id', 'parent_line_id'}
                _cols = [c for c in BudgetLine.__table__.columns.keys() if c not in _skip]
                act_by_src = {l.source_line_id: l for l in
                              BudgetLine.query.filter_by(budget_id=act.id).all()
                              if l.source_line_id}
                for w in missing:
                    nl = BudgetLine(budget_id=act.id, source_line_id=w.id)
                    for c in _cols:
                        setattr(nl, c, getattr(w, c))
                    db.session.add(nl)
                    db.session.flush()
                    act_by_src[w.id] = nl
                # remap parents through the source chain for ALL actual lines
                for a in BudgetLine.query.filter_by(budget_id=act.id).all():
                    if not a.source_line_id:
                        continue
                    w = w_by_id.get(a.source_line_id)
                    np = (act_by_src.get(w.parent_line_id).id
                          if (w and w.parent_line_id and act_by_src.get(w.parent_line_id))
                          else None)
                    if a.parent_line_id != np:
                        a.parent_line_id = np
            # d) drop zero-dep orphans
            if drop_orphans and report["orphans_dropped"]:
                oid = [o["id"] for o in report["orphans_dropped"]]
                BudgetLine.query.filter(BudgetLine.id.in_(oid)).delete(
                    synchronize_session=False)
            db.session.commit()
            report["counts_after"] = {"actual": len(BudgetLine.query.filter_by(budget_id=act.id).all())}
        except Exception as e:
            db.session.rollback()
            report["errors"].append(str(e))
            return jsonify(report), 500

    return jsonify(report)


@app.route("/admin/qbo-imports/repair-refunds", methods=["POST"])
@login_required
def qbo_repair_refunds():
    """Repair pre-2026-06-04 QBO rows where refunds imported as POSITIVE
    expenses (CC refunds / Purchase-with-Credit) and BillPayments imported as
    credits. Re-queries QBO over a date window and corrects is_expense on
    existing local rows (only that boolean is touched). Reports QBO refunds with
    no local row too. DRY-RUN by default; ?apply=1 to write. Admin only.
    Body/params: project=<pid> (required), start_date, end_date (YYYY-MM-DD;
    default = last 365 days → today). (Code review 2026-06-04.)"""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    from models import QBOConnection
    conn = QBOConnection.query.first()
    if not conn or not conn.refresh_token:
        return jsonify({"error": "QuickBooks not connected. Go to Admin → QBO to authorize.",
                        "needs_oauth": True}), 400
    body = request.get_json(silent=True) or {}
    apply = (request.args.get('apply') == '1') or bool(body.get('apply'))
    pid_raw = request.args.get('project') or body.get('project')
    try:
        pid = int(pid_raw)
    except (TypeError, ValueError):
        return jsonify({"error": "project (pid) required"}), 400
    project = ProjectSheet.query.get_or_404(pid)
    import re as _re, datetime as _dt
    _date_re = _re.compile(r"^\d{4}-\d{2}-\d{2}$")
    start_date = (body.get('start_date') or request.args.get('start_date') or '').strip() \
        or (_dt.date.today() - _dt.timedelta(days=365)).isoformat()
    end_date = (body.get('end_date') or request.args.get('end_date') or '').strip() \
        or _dt.date.today().isoformat()
    if not _date_re.match(start_date) or not _date_re.match(end_date):
        return jsonify({"error": "start_date/end_date must be YYYY-MM-DD"}), 400
    # Which corrections to apply: credit_only (safe — removes wrongly-counted
    # spend) | expense_only (ADDS spend; double-count risk vs CSV) | both.
    direction = (body.get('direction') or request.args.get('direction') or 'both').lower()
    if direction not in ('both', 'credit_only', 'expense_only'):
        return jsonify({"error": "direction must be both|credit_only|expense_only"}), 400
    from qbo_sync import repair_is_expense
    try:
        result = repair_is_expense(project, conn, db, start_date, end_date,
                                   apply=apply, direction=direction)
    except Exception as e:
        logging.exception("qbo repair-refunds failed")
        return jsonify({"error": "Repair failed", "detail": type(e).__name__}), 500
    if apply and result.get('fixed'):
        try:
            _log_activity(action='update', entity_type='transaction', entity_id=0,
                          entity_label=f"QBO refund repair ({result['fixed']} fixed)",
                          project_id=pid, before=None, after={'fixed': result['fixed']},
                          note=(f"Repaired is_expense on {result['fixed']} QBO rows "
                                f"({result['flip_to_credit_count']} refunds→credit, "
                                f"{result['flip_to_expense_count']} bill payments→expense)"))
        except Exception:
            pass
    return jsonify(result)


@app.route("/admin/qbo-imports/purge", methods=["POST"])
@login_required
def qbo_imports_purge(pid=None):
    """Undo electronic (QuickBooks) imports — delete Transactions with
    source='qbo_sync'. Receipts (doc_upload), typed rows (manual_entry) and
    invoice splits are NEVER touched. Dry-run by default; ?apply=1 to delete.
    Scope: ?project=<pid> limits to one project; default = all projects.

    Before deleting we:
      • release cross-project claims that point at a project whose qbo rows
        are being removed (clear claimed_by_project_id on surviving rows),
      • detach any child transaction whose parent is being deleted
        (parent_transaction_id → NULL) so no split is orphaned.
    Linked DocUploads are left intact (the link lives on the txn side).
    Admin only. (User 2026-06-01.)"""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    apply = (request.args.get('apply') == '1')
    scope_pid = request.args.get('project')
    try:
        scope_pid = int(scope_pid) if scope_pid not in (None, '', 'all') else None
    except (TypeError, ValueError):
        return jsonify({"error": "project must be an integer or 'all'"}), 400

    # Defense-in-depth: never delete a qbo_sync row that is matched to a receipt
    # (doc_upload_id set). Confirming a match now flips source→'reconciled', but
    # rows confirmed before that fix are still source='qbo_sync' with a doc link;
    # deleting them would lose the receipt's only ledger row. (Code review
    # 2026-06-04.)
    q = (Transaction.query
         .filter(Transaction.source == 'qbo_sync')
         .filter(Transaction.doc_upload_id.is_(None)))
    if scope_pid is not None:
        q = q.filter(Transaction.project_id == scope_pid)
    rows = q.all()

    # Per-project breakdown so the user can confirm scope before deleting.
    by_proj = {}
    dates = []
    ids = []
    for t in rows:
        ids.append(t.id)
        if t.txn_date:
            dates.append(t.txn_date)
        p = by_proj.setdefault(t.project_id, {"total": 0, "coded": 0, "uncoded": 0,
                                              "claimed": 0, "with_doc": 0,
                                              "amount": 0.0})
        p["total"] += 1
        if t.budget_line_id:
            p["coded"] += 1
        else:
            p["uncoded"] += 1
        if t.claimed_by_project_id:
            p["claimed"] += 1
        if t.doc_upload_id:
            p["with_doc"] += 1
        p["amount"] += float(t.amount or 0)

    # Context: what is being PRESERVED (so the user sees the blast radius).
    preserved = {}
    for src in ('manual_entry', 'doc_upload', 'invoice_split', 'reconciled'):
        pq = Transaction.query.filter(Transaction.source == src)
        if scope_pid is not None:
            pq = pq.filter(Transaction.project_id == scope_pid)
        preserved[src] = pq.count()
    # qbo_sync rows kept because they're matched to a receipt (excluded above).
    _mq = (Transaction.query.filter(Transaction.source == 'qbo_sync')
           .filter(Transaction.doc_upload_id.isnot(None)))
    if scope_pid is not None:
        _mq = _mq.filter(Transaction.project_id == scope_pid)
    preserved['qbo_sync_matched_kept'] = _mq.count()

    # Project names for readability
    pnames = {p.id: p.name for p in ProjectSheet.query.all()}
    report = {"dry": (not apply), "applied": apply,
              "scope": ("all projects" if scope_pid is None else f"project {scope_pid}"),
              "qbo_sync_total": len(rows),
              "date_range": ([min(dates), max(dates)] if dates else None),
              "by_project": {f"{pid_}{(' · '+pnames[pid_]) if pnames.get(pid_) else ''}": v
                             for pid_, v in sorted(by_proj.items())},
              "preserved_counts": preserved,
              "errors": []}

    if apply and ids:
        try:
            idset = set(ids)
            # 1) detach children whose parent is being deleted
            child_q = Transaction.query.filter(
                Transaction.parent_transaction_id.in_(idset))
            detached = 0
            for c in child_q.all():
                if c.id not in idset:        # don't bother for rows also dying
                    c.parent_transaction_id = None
                    detached += 1
            # 2) release cross-project claims pointing at affected projects
            affected_projects = set(by_proj.keys())
            released = (Transaction.query
                        .filter(Transaction.claimed_by_project_id.in_(affected_projects))
                        .filter(~Transaction.id.in_(idset))
                        .update({"claimed_by_project_id": None},
                                synchronize_session=False))
            db.session.flush()
            # 3) delete the qbo_sync rows
            deleted = (Transaction.query
                       .filter(Transaction.id.in_(idset))
                       .delete(synchronize_session=False))
            db.session.commit()
            report["deleted"] = int(deleted)
            report["children_detached"] = detached
            report["claims_released"] = int(released or 0)
        except Exception as e:
            db.session.rollback()
            report["errors"].append(str(e))
            return jsonify(report), 500

    return jsonify(report)


# ── Bank-CSV actuals import (e.g. Chase monthly export) ───────────────────────
_BANK_CSV_SYNONYMS = {
    # role -> ordered candidate header names (lowercased, exact-first then contains)
    'date':   ['transaction date', 'trans date', 'txn date', 'date', 'posting date'],
    'pdate':  ['post date', 'posted date'],
    'desc':   ['description', 'payee', 'merchant', 'name', 'transaction'],
    'amount': ['amount', 'amt'],
    'debit':  ['debit', 'withdrawal', 'withdrawals', 'money out', 'charge', 'charges'],
    'credit': ['credit', 'deposit', 'deposits', 'money in'],
    'card':   ['card', 'card number', 'card no', 'last 4', 'last four', 'card last 4'],
    'type':   ['type', 'transaction type'],
    'cat':    ['category'],
    'memo':   ['memo', 'notes', 'note'],
}


def _bank_pick_col(fieldnames, role):
    """Resolve a CSV header to a logical role. Exact match wins, then substring."""
    fields = [(f, (f or '').strip().lower()) for f in (fieldnames or [])]
    cands = _BANK_CSV_SYNONYMS.get(role, [])
    for c in cands:                                  # exact
        for orig, low in fields:
            if low == c:
                return orig
    for c in cands:                                  # substring
        for orig, low in fields:
            if c in low:
                return orig
    return None


def _bank_parse_money(s):
    """'-$1,234.56' / '(1,234.56)' / '' -> float or None."""
    if s is None:
        return None
    t = str(s).strip()
    if not t:
        return None
    neg = t.startswith('(') and t.endswith(')')
    t = t.replace('(', '').replace(')', '').replace('$', '').replace(',', '').strip()
    if not t:
        return None
    try:
        v = float(t)
    except ValueError:
        return None
    return -v if neg else v


def _bank_parse_date(s):
    """Return YYYY-MM-DD or None."""
    t = (s or '').strip()
    if not t:
        return None
    from datetime import datetime as _dt
    for fmt in ('%m/%d/%Y', '%Y-%m-%d', '%m/%d/%y', '%m-%d-%Y', '%d/%m/%Y'):
        try:
            return _dt.strptime(t, fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue
    return None


def _parse_bank_csv(content, charge_sign='auto'):
    """Parse a bank/credit-card CSV into normalized rows + stats. Handles both a
    single signed Amount column and split Debit/Credit columns. Returns
    (rows, stats) where each row is a dict ready for a Transaction:
      {txn_date, vendor, amount(+), is_expense, card_last4, note, kind, type}
    kind ∈ charge | credit | payment | transfer | zero.

    Sign convention is NOT assumed: Chase exports charges as NEGATIVE, but Amex
    (and others) export charges as POSITIVE — assuming neg=charge inverted a whole
    Amex statement, classifying every charge as a credit so spend vanished from
    rollups. `charge_sign` ∈ auto | pos | neg: 'auto' detects polarity from the
    file (split debit/credit layout is unambiguous; for a single signed column,
    if positives dominate spend rows we treat positive=charge). The chosen
    polarity is reported so the user can verify before applying. (Code review
    2026-06-04.)"""
    reader = csv.DictReader(io.StringIO(content))
    fn = reader.fieldnames or []
    col = {r: _bank_pick_col(fn, r) for r in _BANK_CSV_SYNONYMS}
    raw_rows, errors = [], []
    used_split = False
    for i, raw in enumerate(reader, start=2):   # line 1 = header
        g = lambda r: (raw.get(col[r]) if col.get(r) else None)
        date = _bank_parse_date(g('date')) or _bank_parse_date(g('pdate'))
        vendor = (g('desc') or '').strip()
        ttype = (g('type') or '').strip()
        amt = _bank_parse_money(g('amount'))
        if amt is None:    # split debit/credit layout (unambiguous: debit=charge)
            d = _bank_parse_money(g('debit'))
            c = _bank_parse_money(g('credit'))
            if d not in (None, 0):
                amt = -abs(d); used_split = True
            elif c not in (None, 0):
                amt = abs(c); used_split = True
        if not date or amt is None:
            errors.append({"line": i, "reason": "unparseable date/amount",
                           "vendor": vendor[:40]})
            continue
        card = ''.join(ch for ch in (g('card') or '') if ch.isdigit())[-4:]
        note_bits = [b for b in [(g('cat') or '').strip(), (g('memo') or '').strip()] if b]
        note = ' · '.join(note_bits) or None
        # Transfers / card-payoffs are NOT project expenses (sign-independent).
        ttl, vl = ttype.lower(), vendor.lower()
        is_transfer = ('xfer' in ttl or 'transfer' in ttl
                       or 'online transfer' in vl or 'transfer to' in vl
                       or 'transfer from' in vl)
        is_payment = ('payment' in ttl or 'loan_pmt' in ttl
                      or 'payment to chase card' in vl or 'to chase card ending' in vl
                      or 'card payment' in vl)
        raw_rows.append({"txn_date": date, "vendor": vendor[:300], "amt": amt,
                         "card_last4": card or None, "note": note, "type": ttype,
                         "is_transfer": is_transfer, "is_payment": is_payment})

    # Decide polarity from real spend/credit rows (exclude transfers/payments/zero).
    spend = [r for r in raw_rows if not r["is_transfer"] and not r["is_payment"] and r["amt"] != 0]
    pos = sum(1 for r in spend if r["amt"] > 0)
    neg = sum(1 for r in spend if r["amt"] < 0)
    if charge_sign == 'pos':
        positive_is_charge, polarity_source = True, 'forced'
    elif charge_sign == 'neg':
        positive_is_charge, polarity_source = False, 'forced'
    elif used_split:
        positive_is_charge, polarity_source = False, 'split-columns'   # debit already made negative
    else:
        # Card/bank statements have far more charges than credits. If positives
        # clearly dominate, the file uses positive=charge (Amex-style).
        positive_is_charge = (pos > neg and pos >= 3 * max(neg, 1))
        polarity_source = 'auto'

    rows = []
    for r in raw_rows:
        amt = r["amt"]
        if amt == 0:
            kind = 'zero'
        elif r["is_transfer"]:
            kind = 'transfer'
        elif r["is_payment"]:
            kind = 'payment'
        else:
            is_charge = (amt > 0) if positive_is_charge else (amt < 0)
            kind = 'charge' if is_charge else 'credit'
        rows.append({"txn_date": r["txn_date"], "vendor": r["vendor"],
                     "amount": round(abs(amt), 2),
                     "is_expense": (kind == 'charge'),
                     "card_last4": r["card_last4"], "note": r["note"],
                     "kind": kind, "type": r["type"]})
    stats = {"detected_columns": {k: v for k, v in col.items() if v},
             "parse_errors": errors,
             "charge_polarity": ('positive = charge' if positive_is_charge else 'negative = charge'),
             "polarity_source": polarity_source,
             "spend_sign_counts": {"positive": pos, "negative": neg}}
    return rows, stats


@app.route("/projects/<int:pid>/actuals/import-bank-csv", methods=["POST"])
@login_required
def actuals_import_bank_csv(pid):
    """Import monthly bank / credit-card CSV (Chase etc.) into project actuals as
    source='csv_import' Transactions. Dry-run preview by default; ?apply=1 to
    commit. Charges (negative amounts) import as expenses; refunds/returns as
    credits (is_expense=False); card-payment rows are SKIPPED (not project
    expenses). De-dupes against rows already imported with the same
    (date, vendor, |amount|, card) so overlapping months don't double up.
    (User 2026-06-02.)"""
    if current_user.role == 'viewer':
        return jsonify({"error": "Forbidden — viewers cannot import"}), 403
    ProjectSheet.query.get_or_404(pid)
    apply = (request.args.get('apply') == '1')
    include_payments = (request.args.get('include_payments') == '1')
    f = request.files.get('file')
    if not f:
        return jsonify({"error": "No file uploaded"}), 400
    _upl_err = _validate_upload_file(f, 'document') if f else None
    if _upl_err:
        return jsonify({"error": _upl_err}), 400
    try:
        content = f.read().decode('utf-8-sig')
    except UnicodeDecodeError:
        return jsonify({"error": "File must be UTF-8 encoded CSV"}), 400

    charge_sign = (request.args.get('charge_sign') or 'auto').lower()
    if charge_sign not in ('auto', 'pos', 'neg'):
        charge_sign = 'auto'
    rows, stats = _parse_bank_csv(content, charge_sign=charge_sign)
    if not stats["detected_columns"].get('date') or not (
            stats["detected_columns"].get('amount')
            or stats["detected_columns"].get('debit')
            or stats["detected_columns"].get('credit')):
        return jsonify({"error": "Could not find a date column and an amount "
                                 "(or debit/credit) column in this CSV.",
                        "detected_columns": stats["detected_columns"],
                        "header": list((csv.reader(io.StringIO(content)).__next__()
                                        if content else []))}), 400

    # De-dup by COUNT, not presence, so legitimately-identical same-day charges
    # (two $6.75 coffees on the same card) both import, while overlapping months
    # still don't double up. Skip a row only while we haven't yet matched the
    # number already in the DB for that fingerprint. (Code review 2026-06-04.)
    from collections import Counter as _Counter
    existing_counts = _Counter()
    for t in (Transaction.query
              .filter(Transaction.project_id == pid,
                      Transaction.source == 'csv_import').all()):
        existing_counts[(t.txn_date, (t.vendor or '').strip().lower(),
                         float(t.amount or 0), t.card_last4 or '')] += 1

    importable, dups, payments, transfers, zeros = [], 0, 0, 0, 0
    batch_counts = _Counter()
    for r in rows:
        if r["kind"] == 'zero':
            zeros += 1
            continue
        if r["kind"] == 'payment' and not include_payments:
            payments += 1
            continue
        if r["kind"] == 'transfer' and not include_payments:
            transfers += 1
            continue
        fp = (r["txn_date"], r["vendor"].strip().lower(), r["amount"], r["card_last4"] or '')
        batch_counts[fp] += 1
        # first existing_counts[fp] occurrences in this file are already in the DB
        if batch_counts[fp] <= existing_counts.get(fp, 0):
            dups += 1
            continue
        importable.append(r)

    dates = [r["txn_date"] for r in importable]
    by_card = {}
    for r in importable:
        by_card[r["card_last4"] or '—'] = by_card.get(r["card_last4"] or '—', 0) + 1
    report = {
        "dry": (not apply), "applied": apply, "project": pid,
        "detected_columns": stats["detected_columns"],
        "charge_polarity": stats.get("charge_polarity"),
        "polarity_source": stats.get("polarity_source"),
        "spend_sign_counts": stats.get("spend_sign_counts"),
        "rows_in_file": len(rows),
        "to_import": len(importable),
        "charges": sum(1 for r in importable if r["kind"] == 'charge'),
        "credits": sum(1 for r in importable if r["kind"] == 'credit'),
        "skipped_card_payments": payments,
        "skipped_transfers": transfers,
        "skipped_duplicates": dups,
        "skipped_zero": zeros,
        "parse_errors": stats["parse_errors"][:25],
        "parse_error_count": len(stats["parse_errors"]),
        "date_range": ([min(dates), max(dates)] if dates else None),
        "by_card": by_card,
        "sample": [{"date": r["txn_date"], "vendor": r["vendor"][:40],
                    "amount": r["amount"], "expense": r["is_expense"],
                    "card": r["card_last4"], "note": r["note"]}
                   for r in importable[:15]],
        "errors": [],
    }
    if apply and importable:
        try:
            for r in importable:
                db.session.add(Transaction(
                    project_id=pid, amount=r["amount"], is_expense=r["is_expense"],
                    vendor=r["vendor"], txn_date=r["txn_date"], note=r["note"],
                    card_last4=r["card_last4"], source='csv_import',
                    match_status='unmatched',
                    created_via_user_id=getattr(current_user, 'id', None)))
            db.session.commit()
            report["created"] = len(importable)
            # Auto-run the matcher so the freshly-imported charges get paired
            # with open receipts immediately — previously suggestions only
            # appeared after a manual ⚡ Auto-Match click. (User 2026-06-11.)
            try:
                from actuals import run_auto_match
                _am = run_auto_match(pid)
                report["auto_match"] = {"suggestions": _am.get("suggestions"),
                                        "qbo_unmatched": _am.get("qbo_unmatched"),
                                        "doc_open": _am.get("doc_open")}
            except Exception as _ame:
                report["auto_match_error"] = type(_ame).__name__
        except Exception as e:
            db.session.rollback()
            report["errors"].append(str(e))
            return jsonify(report), 500
    # Phase 3: auto-refresh the review queue after ingestion (background).
    _bg_run_all_scans(pid)
    return jsonify(report)


@app.route("/projects/<int:pid>/sync-actual-from-working", methods=["POST"])
@login_required
def sync_actual_from_working(pid):
    """Make the Actual budget MIRROR the Working budget structurally: for every
    Actual line linked to a Working line (source_line_id), copy the structural
    + planned fields from its Working counterpart — is_labor, use_schedule,
    sort_order, qty/days/rate/rate_type/fringe_type/agent_pct, line_tag — and
    remap parent_line_id through the source chain. Fixes corrupted Actual lines
    (kit fees flagged is_labor, sharing the parent's sort_order, null parent,
    wrong planned value). Does NOT touch transactions (actual spend is keyed by
    Actual line id, which is unchanged). Dry-run by default (?dry=1). Admin
    only. Prereq: run /repair-clone-links first so source_line_id is correct.
    (User 2026-06-01.)"""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    dry = (request.args.get('dry') == '1') or bool((request.get_json(silent=True) or {}).get('dry'))
    ProjectSheet.query.get_or_404(pid)
    all_b = Budget.query.filter_by(project_id=pid).all()
    wrk = (next((b for b in all_b if _budget_type(b.budget_mode) == 'working'
                 and not b.is_actual and b.version_status == 'current'), None)
           or next((b for b in all_b if _budget_type(b.budget_mode) == 'working'
                    and not b.is_actual and b.version_status != 'archived'), None))
    act = (next((b for b in all_b if b.is_actual and b.version_status == 'current'), None)
           or next((b for b in all_b if b.is_actual and b.version_status != 'archived'), None))
    if not (wrk and act):
        return jsonify({"error": "could not resolve working + actual budgets"}), 400

    _wlines = {l.id: l for l in BudgetLine.query.filter_by(budget_id=wrk.id).all()}
    _alines = BudgetLine.query.filter_by(budget_id=act.id).all()
    # Actual line keyed by the Working line it mirrors (for parent remap).
    _act_by_src = {l.source_line_id: l for l in _alines if l.source_line_id}

    def _sv(v):
        try:
            from decimal import Decimal as _D
            if isinstance(v, _D):
                return float(v)
        except Exception:
            pass
        return v
    # Opt-in writes: create-missing (the main fix — make Actual mirror Working
    # by adding lines Working has but Actual lacks) and field-edits (fringe/
    # rate/etc. on existing lines, which change computed values — held behind
    # its own flag). Dry-run still reports both.
    _do_create = (request.args.get('create') == '1')
    _do_fields = (request.args.get('fields') == '1')
    FIELDS = ['is_labor', 'use_schedule', 'sort_order', 'qty', 'days', 'rate',
              'rate_type', 'fringe_type', 'agent_pct', 'line_tag']
    report = {"dry": dry, "applied": {"create": _do_create and not dry, "fields": _do_fields and not dry},
              "working": wrk.id, "actual": act.id,
              "changed": [], "unlinked": 0, "untouched": 0}

    # ── 1) Field-edits on existing matched lines ──────────────────────
    for a in _alines:
        w = _wlines.get(a.source_line_id) if a.source_line_id else None
        if not w:
            report["unlinked"] += 1
            continue
        diffs = {}
        for f in FIELDS:
            wv, av = getattr(w, f, None), getattr(a, f, None)
            if wv != av:
                diffs[f] = [_sv(av), _sv(wv)]
                if _do_fields and not dry:
                    setattr(a, f, wv)
        new_parent = None
        if w.parent_line_id:
            ap = _act_by_src.get(w.parent_line_id)
            new_parent = ap.id if ap else None
        if a.parent_line_id != new_parent:
            diffs['parent_line_id'] = [a.parent_line_id, new_parent]
            if _do_fields and not dry:
                a.parent_line_id = new_parent
        if diffs:
            report["changed"].append({"id": a.id, "desc": (a.description or '')[:32], "diffs": diffs})
        else:
            report["untouched"] += 1

    # ── 2) Create missing Actual lines for Working lines with no mirror ──
    _skip = {'id', 'budget_id', 'source_line_id', 'parent_line_id'}
    _cols = [c for c in BudgetLine.__table__.columns.keys() if c not in _skip]
    missing = [w for w in _wlines.values() if w.id not in _act_by_src]
    report["missing_count"] = len(missing)
    report["created"] = [{"working_id": w.id, "desc": (w.description or '')[:32]} for w in missing]
    if _do_create and not dry and missing:
        for w in missing:
            nl = BudgetLine(budget_id=act.id, source_line_id=w.id)
            for c in _cols:
                setattr(nl, c, getattr(w, c))
            db.session.add(nl)
            db.session.flush()
            _act_by_src[w.id] = nl
        # second pass: remap every Actual line's parent to its Working parent's mirror
        for w in _wlines.values():
            a = _act_by_src.get(w.id)
            if not a:
                continue
            np = (_act_by_src.get(w.parent_line_id).id
                  if w.parent_line_id and _act_by_src.get(w.parent_line_id) else None)
            if a.parent_line_id != np:
                a.parent_line_id = np

    if (_do_create or _do_fields) and not dry:
        db.session.commit()
    report["changed_count"] = len(report["changed"])
    return jsonify(report)


@app.route("/projects/<int:pid>/repair-clone-links", methods=["POST"])
@login_required
def repair_clone_links(pid):
    # Destructive/one-time repair tool — super-admin only before outside
    # users arrive (tools audit 2026-07-20).
    if getattr(current_user, 'role', None) != 'super_admin':
        abort(403)
    """Repair the cross-budget clone chain so Working→Estimated and
    Actual→Working source_line_id links point at the TRUE counterpart, matched
    by (account_code, normalized description) with a positional tiebreak for
    same-named lines. Fixes the corruption behind kit fees showing a parent's
    numbers + crew bleeding onto kit rows. Dry-run first (?dry=1) returns the
    proposed relinks without writing. Admin only. (User 2026-06-01.)"""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    dry = (request.args.get('dry') == '1') or bool((request.get_json(silent=True) or {}).get('dry'))
    ProjectSheet.query.get_or_404(pid)
    all_b = Budget.query.filter_by(project_id=pid).all()
    def _pick(kind):
        # Always exclude the Actual budget — it can carry budget_mode
        # 'estimated'/'working', so it would otherwise hijack this pick. The
        # Actual is resolved separately via is_actual below.
        return (next((b for b in all_b if _budget_type(b.budget_mode) == kind
                      and not b.is_actual and b.version_status == 'current'), None)
                or next((b for b in all_b if _budget_type(b.budget_mode) == kind
                         and not b.is_actual and b.version_status != 'archived'), None))
    est = _pick('estimated')
    wrk = _pick('working')
    act = next((b for b in all_b if b.is_actual and b.version_status == 'current'), None) \
        or next((b for b in all_b if b.is_actual and b.version_status != 'archived'), None)

    def _norm(l):
        return (l.account_code, (l.description or '').strip().lower())

    def _relink(child_b, parent_b, tag):
        out = {"tag": tag, "relinked": [], "no_match": [], "already_ok": 0}
        if not (child_b and parent_b):
            return out
        p_lines = sorted(BudgetLine.query.filter_by(budget_id=parent_b.id).all(),
                         key=lambda x: (x.account_code or 0, x.sort_order or 0))
        p_idx = {}
        for pl in p_lines:
            p_idx.setdefault(_norm(pl), []).append(pl)
        used = {}
        for cl in sorted(BudgetLine.query.filter_by(budget_id=child_b.id).all(),
                         key=lambda x: (x.account_code or 0, x.sort_order or 0)):
            k = _norm(cl)
            cands = p_idx.get(k, [])
            if not cands:
                out["no_match"].append({"id": cl.id, "desc": (cl.description or '')[:34]})
                continue
            pos = used.get(k, 0)
            target = cands[pos] if pos < len(cands) else cands[-1]
            used[k] = pos + 1
            if cl.source_line_id == target.id:
                out["already_ok"] += 1
            else:
                out["relinked"].append({"id": cl.id, "desc": (cl.description or '')[:34],
                                        "old_src": cl.source_line_id, "new_src": target.id})
                if not dry:
                    cl.source_line_id = target.id
        return out

    # The estimated side has a version-pairing ambiguity (two Estimated
    # budgets); skip writing working→estimated unless explicitly enabled, to
    # avoid linking to the wrong Estimated. ?w2e=1 to include it. (2026-06-01.)
    _do_w2e = (request.args.get('w2e') == '1')
    report = {"dry": dry,
              "budgets": {"estimated": est.id if est else None,
                          "working": wrk.id if wrk else None,
                          "actual": act.id if act else None},
              "working_to_estimated": (_relink(wrk, est, "working→estimated")
                                       if _do_w2e else {"skipped": "version-pairing review pending"}),
              "actual_to_working":    _relink(act, wrk, "actual→working")}
    if not dry:
        db.session.commit()
    return jsonify(report)


# ══════════════════════════════════════════════════════════════════════════
# LINE-IDENTITY REPAIR SUITE  (owner report 2026-07: Cliburn 2000-08)
# ══════════════════════════════════════════════════════════════════════════
# THE BUG: the rendered line NUMBER ("2000-08") is POSITIONAL — section code +
# the counter of the row in render order. Estimated and Working orderings drift
# historically, so the SAME number can label DIFFERENT lines across versions.
# On top of that, the PO/crew cross-budget write-through (line_assign_po /
# assign_crew) falls back to (account_code, sort_order) matching when a line has
# no source_line_id link. Cliburn's Working budget (bid 311) predates the
# source_line_id backfill, so writes from the Estimated view landed on the
# WRONG Working line (Brenton's crew+PO stamped onto the Line Producer's line).
#
# Three ADMIN routes address this, all dry-by-default, ?pid= scoped:
#   1. /budget/repair-line-links   — BACKFILL Working→Estimated source_line_id
#      (unique-match only) so the write-through uses explicit links, killing the
#      positional fallback's future corruption.
#   2. /budget/sync-line-order     — one-time order re-sync so the SAME number
#      labels the SAME line on both sides.
#   3. /budget/crew-po-mismatch-report — read-only; flags working lines whose
#      crew/PO looks like it was misdirected by a positional write.
#
# Same safety pattern as repair_clone_links / migrate_actuals: admin-only,
# per-project isolation (one project's failure never aborts another), no
# account_code mutations except where explicitly noted (order route touches
# sort_order only).

def _repair_pick_current(all_b, kind):
    """Resolve a project's CURRENT non-actual budget of `kind`
    ('estimated'|'working'), preferring version_status='current', falling back
    to any non-archived. Mirrors repair_clone_links._pick / _resolve_sister_budget."""
    return (next((b for b in all_b if _budget_type(b.budget_mode) == kind
                  and not b.is_actual and b.version_status == 'current'), None)
            or next((b for b in all_b if _budget_type(b.budget_mode) == kind
                     and not b.is_actual and b.version_status != 'archived'), None))


def _repair_norm_key(ln):
    """The (account_code, normalized-description) pairing key — identical to
    _sister_line_for's fallback and repair_clone_links._norm."""
    return (ln.account_code, (ln.description or '').strip().lower())


def _repair_dry_flag():
    """Shared dry-run resolver: mutate ONLY when dry is EXPLICITLY false/0.
    Everything else (absent, '1', 'true', garbage) stays dry — same convention
    as migrate_actuals."""
    body = request.get_json(silent=True) or {}
    _raw = request.args.get('dry', body.get('dry', True))
    if isinstance(_raw, str):
        return _raw.strip().lower() not in ('0', 'false', 'no', 'off')
    return not (_raw is False or _raw == 0)


def _repair_scope_projects():
    """Projects in scope: a single project if ?pid= (or JSON pid) is given,
    else every ProjectSheet. Returns a list of project ids."""
    body = request.get_json(silent=True) or {}
    raw = request.args.get('pid', body.get('pid'))
    if raw not in (None, '', 'all'):
        try:
            return [int(raw)]
        except (TypeError, ValueError):
            return []
    return [p.id for p in ProjectSheet.query.order_by(ProjectSheet.id).all()]


def _repair_position_labels(budget):
    """Return {line_id: 'SECTION-NN'} for every NON-header/spacer line on
    `budget`, computed EXACTLY like the budget template's line_counter:
      • group lines by their rendered section (_section_for_code),
      • order each section with _order_lines_with_children (the same helper the
        page uses — clusters children under parents + role_group clustering),
      • number non-header/non-spacer rows sequentially from 1 within the section.
    Also returns {line_id: rendered_index} so callers can slice "first N".
    """
    lines = BudgetLine.query.filter_by(budget_id=budget.id).all()
    by_section = {}
    for ln in lines:
        by_section.setdefault(_section_for_code(ln.account_code), []).append(ln)
    labels, order_idx, section_order = {}, {}, {}
    for sec_code in sorted(by_section):
        ordered = _order_lines_with_children(by_section[sec_code])
        counter = 0
        for pos, ln in enumerate(ordered):
            order_idx[ln.id] = pos
            if getattr(ln, 'line_tag', None) in ('header', 'spacer'):
                continue
            counter += 1
            labels[ln.id] = f"{sec_code}-{counter:02d}"
            section_order.setdefault(sec_code, []).append(ln.id)
    return labels, order_idx, section_order


def _repair_crew_names(line):
    """Human-readable crew for a line: the assigned_crew name plus any
    CrewAssignment member names (deduped, order-stable)."""
    names = []
    if getattr(line, 'assigned_crew', None) and line.assigned_crew.name:
        names.append(line.assigned_crew.name)
    for ca in CrewAssignment.query.filter_by(budget_line_id=line.id).order_by(
            CrewAssignment.instance).all():
        nm = (ca.crew_member.name if ca.crew_member else None) or ca.name_override
        if nm:
            names.append(nm)
    seen, out = set(), []
    for nm in names:
        if nm not in seen:
            seen.add(nm)
            out.append(nm)
    return out


def _repair_po_number(line):
    """PO number string for a line's po_id, or None."""
    if not getattr(line, 'po_id', None):
        return None
    from models import PurchaseOrder
    po = PurchaseOrder.query.get(line.po_id)
    return po.po_number if po else None


@app.route("/budget/repair-line-links", methods=["GET", "POST"])
@login_required
def repair_line_links():
    # Destructive/one-time repair tool — super-admin only before outside
    # users arrive (tools audit 2026-07-20).
    if getattr(current_user, 'role', None) != 'super_admin':
        abort(403)
    """BACKFILL Working→Estimated source_line_id for CURRENT working budgets
    whose lines lack it. Pairing is by (account_code, normalized description);
    a link is written ONLY when the match is UNIQUE on BOTH sides — exactly one
    working line and one estimated line share that key. Ambiguous keys are
    REPORTED, never guessed (that is the whole point — a bad guess re-corrupts).

    This makes the PO/crew write-through resolve via explicit source_line_id
    links instead of the positional (account_code, sort_order) fallback, which
    is what mis-stamped Brenton's crew+PO onto the Line Producer line.

    Admin only. DRY-RUN BY DEFAULT — writes only when ?dry=0 (or {"dry":false}).
    ?pid= scopes to one project; absent = every project. Per-project isolation:
    one project's error is recorded and skipped, never aborting the batch.
    """
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    dry = _repair_dry_flag()
    out = {"ok": True, "dry": dry, "projects": []}
    for pid in _repair_scope_projects():
        rec = {"pid": pid, "linked": 0, "ambiguous": [], "already_linked": 0}
        try:
            all_b = Budget.query.filter_by(project_id=pid).all()
            est = _repair_pick_current(all_b, 'estimated')
            wrk = _repair_pick_current(all_b, 'working')
            if not (est and wrk):
                rec["skipped"] = "missing current estimated or working budget"
                out["projects"].append(rec)
                continue
            est_lines = BudgetLine.query.filter_by(budget_id=est.id).all()
            wrk_lines = BudgetLine.query.filter_by(budget_id=wrk.id).all()
            # Group both sides by pairing key.
            est_by_key, wrk_by_key = {}, {}
            for el in est_lines:
                est_by_key.setdefault(_repair_norm_key(el), []).append(el)
            for wl in wrk_lines:
                wrk_by_key.setdefault(_repair_norm_key(wl), []).append(wl)
            for key, wls in wrk_by_key.items():
                els = est_by_key.get(key, [])
                # UNIQUE on both sides required. Otherwise: report, never guess.
                if len(wls) == 1 and len(els) == 1:
                    wl, el = wls[0], els[0]
                    if wl.source_line_id == el.id:
                        rec["already_linked"] += 1
                        continue
                    rec["linked"] += 1
                    if not dry:
                        wl.source_line_id = el.id
                elif els:
                    # Ambiguous key with candidates on both sides — the risky
                    # case. (A working key with NO estimated match is just an
                    # unpaired working line, not ambiguity — skip silently.)
                    rec["ambiguous"].append({
                        "desc": key[1] or "(unnamed)",
                        "code": key[0],
                        "working_ids": [w.id for w in wls],
                        "estimated_ids": [e.id for e in els],
                    })
            if not dry:
                db.session.commit()
        except Exception as _e:
            try:
                db.session.rollback()
            except Exception:
                pass
            rec["error"] = str(_e)
        out["projects"].append(rec)
    return jsonify(out)


@app.route("/budget/sync-line-order", methods=["GET", "POST"])
@login_required
def sync_line_order():
    """ONE-TIME order re-sync between the CURRENT Estimated and CURRENT Working
    of a project so the SAME rendered number labels the SAME line on both sides.

    Param `source` is REQUIRED ('working'|'estimated'): the OTHER budget's PAIRED
    lines are resequenced to follow the source's order (same algorithm as
    _mirror_line_move — paired lines get sequential sort_order in the source's
    order; sister-only orphans keep their existing sort_order). ORDERING ONLY —
    NO account_code changes (unlike _mirror_line_move, this never moves a line
    across sections; a drifted number is a sort_order problem, not a section one).

    DRY (default) returns a human-readable BEFORE/AFTER preview: per section, the
    first ~15 rendered positions on BOTH sides (position label + desc) pre- and
    post-sync, so the owner can choose direction per project before committing.

    Admin only. Writes only when ?dry=0. ?pid= scopes (required in practice —
    direction is a per-project judgment; absent = every project, same source).
    """
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    body = request.get_json(silent=True) or {}
    source = (request.args.get('source', body.get('source')) or '').strip().lower()
    if source not in ('working', 'estimated'):
        return jsonify({"error": "source is required — 'working' or 'estimated'"}), 400
    dry = _repair_dry_flag()
    target_kind = 'estimated' if source == 'working' else 'working'
    PREVIEW_ROWS = 15
    out = {"ok": True, "dry": dry, "source": source, "target": target_kind,
           "projects": []}

    for pid in _repair_scope_projects():
        rec = {"pid": pid, "resequenced": 0, "sections": []}
        try:
            all_b = Budget.query.filter_by(project_id=pid).all()
            src_b = _repair_pick_current(all_b, source)
            tgt_b = _repair_pick_current(all_b, target_kind)
            if not (src_b and tgt_b):
                rec["skipped"] = "missing current estimated or working budget"
                out["projects"].append(rec)
                continue

            src_lines = (BudgetLine.query.filter_by(budget_id=src_b.id)
                         .order_by(BudgetLine.sort_order, BudgetLine.id).all())
            tgt_lines = BudgetLine.query.filter_by(budget_id=tgt_b.id).all()

            # BEFORE snapshot of position labels (both sides).
            src_labels_b, _, src_secorder_b = _repair_position_labels(src_b)
            tgt_labels_b, _, tgt_secorder_b = _repair_position_labels(tgt_b)
            desc_of = {ln.id: (ln.description or '').strip() or '(unnamed)'
                       for ln in src_lines + tgt_lines}

            # Pairing indexes over the TARGET (reused from _mirror_line_move).
            tgt_src_ids = {}
            for _tl in tgt_lines:
                if _tl.source_line_id is not None:
                    tgt_src_ids.setdefault(_tl.source_line_id, _tl)
            tgt_desc_index = {}
            for _tl in tgt_lines:
                tgt_desc_index.setdefault(_repair_norm_key(_tl), _tl)

            # Compute the NEW target sort_order: paired target lines follow the
            # source's full order sequentially; orphans keep their sort_order.
            new_sort = {}
            matched = set()
            seq = 0
            for sl in src_lines:
                tl = _sister_line_for(sl, tgt_lines, tgt_src_ids, tgt_desc_index)
                if tl is None or tl.id in matched:
                    continue
                matched.add(tl.id)
                new_sort[tl.id] = seq
                seq += 1
            # Orphan target lines: keep existing sort_order (shifted past the
            # paired block so paired rows lead, matching _mirror_line_move's
            # "leave orphans alone" but without them jumping ahead of paired).
            for tl in sorted(tgt_lines, key=lambda x: (x.sort_order or 0, x.id)):
                if tl.id not in new_sort:
                    new_sort[tl.id] = seq
                    seq += 1

            changed = sum(1 for tl in tgt_lines
                          if (tl.sort_order or 0) != new_sort[tl.id])
            rec["resequenced"] = changed

            if dry:
                # AFTER preview: apply new_sort IN MEMORY (no commit) and
                # recompute labels, then roll back so nothing persists.
                for tl in tgt_lines:
                    tl.sort_order = new_sort[tl.id]
                tgt_labels_a, _, tgt_secorder_a = _repair_position_labels(tgt_b)
                db.session.rollback()

                def _rows(labels, secorder, sec):
                    return [{"pos": labels[lid], "desc": desc_of.get(lid, '')}
                            for lid in secorder.get(sec, [])[:PREVIEW_ROWS]]

                all_secs = sorted(set(src_secorder_b) | set(tgt_secorder_b))
                for sec in all_secs:
                    rec["sections"].append({
                        "section": sec,
                        "source_order": _rows(src_labels_b, src_secorder_b, sec),
                        "target_before": _rows(tgt_labels_b, tgt_secorder_b, sec),
                        "target_after": _rows(tgt_labels_a, tgt_secorder_a, sec),
                    })
            else:
                for tl in tgt_lines:
                    tl.sort_order = new_sort[tl.id]
                db.session.commit()
                _touch_budget(tgt_b.id)
                db.session.commit()
        except Exception as _e:
            try:
                db.session.rollback()
            except Exception:
                pass
            rec["error"] = str(_e)
        out["projects"].append(rec)
    return jsonify(out)


@app.route("/budget/crew-po-mismatch-report", methods=["GET", "POST"])
@login_required
def crew_po_mismatch_report():
    """READ-ONLY report. For each CURRENT working line, compare its crew/PO
    against (a) its DESCRIPTION-paired estimated peer and (b) the line the
    POSITIONAL (account_code, sort_order) fallback WOULD have matched. Flag a
    working line as a suspect when BOTH hold:
      (i)  its crew/PO DIFFERS from its desc-paired estimated peer, AND
      (ii) the positionally-paired estimated line DOES carry that same crew/PO.
    That is the exact signature of a misdirected positional write — Brenton's
    crew+PO written from the Technical Producer's Estimated line landing on the
    Line Producer's Working line because they shared (account_code, sort_order).

    NO MUTATIONS. The owner reviews and fixes by hand (moving crew/PO is a
    judgment call). Admin only. ?pid= scopes; absent = every project.
    """
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    out = {"ok": True, "projects": []}
    for pid in _repair_scope_projects():
        rec = {"pid": pid, "suspects": []}
        try:
            all_b = Budget.query.filter_by(project_id=pid).all()
            est = _repair_pick_current(all_b, 'estimated')
            wrk = _repair_pick_current(all_b, 'working')
            if not (est and wrk):
                rec["skipped"] = "missing current estimated or working budget"
                out["projects"].append(rec)
                continue
            est_lines = BudgetLine.query.filter_by(budget_id=est.id).all()
            wrk_lines = BudgetLine.query.filter_by(budget_id=wrk.id).all()
            wrk_labels, _, _ = _repair_position_labels(wrk)

            # DESCRIPTION pairing: (account_code, normalized desc) → est line.
            est_desc_index = {}
            for el in est_lines:
                est_desc_index.setdefault(_repair_norm_key(el), el)
            # source_line_id links (either direction) take precedence — mirror
            # _sister_line_for so we compare against the TRUE peer.
            est_src_ids = {}
            for el in est_lines:
                if el.source_line_id is not None:
                    est_src_ids.setdefault(el.source_line_id, el)
            # POSITIONAL pairing: (account_code, sort_order) → est line — the
            # exact key line_assign_po / assign_crew fall back to.
            est_pos_index = {}
            for el in est_lines:
                est_pos_index.setdefault((el.account_code, el.sort_order), el)

            for wl in wrk_lines:
                desc_peer = _sister_line_for(wl, est_lines, est_src_ids, est_desc_index)
                pos_peer = est_pos_index.get((wl.account_code, wl.sort_order))
                if pos_peer is None or (desc_peer is not None
                                        and pos_peer.id == desc_peer.id):
                    continue  # no positional drift → nothing to flag
                wl_crew = set(_repair_crew_names(wl))
                wl_po = _repair_po_number(wl)
                peer_crew = set(_repair_crew_names(desc_peer)) if desc_peer else set()
                peer_po = _repair_po_number(desc_peer) if desc_peer else None
                pos_crew = set(_repair_crew_names(pos_peer))
                pos_po = _repair_po_number(pos_peer)

                # (i) differs from desc-paired peer AND (ii) matches the
                # positional peer — for crew OR po independently.
                crew_sig = bool(wl_crew) and wl_crew != peer_crew and wl_crew == pos_crew
                po_sig = bool(wl_po) and wl_po != peer_po and wl_po == pos_po
                if crew_sig or po_sig:
                    rec["suspects"].append({
                        "working_line_id": wl.id,
                        "desc": (wl.description or '').strip() or '(unnamed)',
                        "code": wl.account_code,
                        "position_label": wrk_labels.get(wl.id),
                        "crew_names": sorted(wl_crew),
                        "po_number": wl_po,
                        "likely_intended_line_id":
                            (desc_peer.id if desc_peer else None),
                        "likely_intended_desc":
                            ((desc_peer.description or '').strip() or '(unnamed)'
                             if desc_peer else None),
                    })
        except Exception as _e:
            rec["error"] = str(_e)
        out["projects"].append(rec)
    return jsonify(out)


# ── PHASE 2: actuals-on-Working migration ──────────────────────────────────
# Phase 1 (commit 2cc78c0) made NEW transaction coding point directly at
# Working-budget lines. This one-time migration remaps ALL remaining LEGACY
# references (txns/sub-budget/location/suggested/crew/schedule) that still
# point at "Actual"-clone lines back to their Working peers, materializes any
# orphan Actual line that carries spend into the Working budget so no coding is
# ever lost, then archives the Actual budgets. Safety-first: dry-run by default,
# per-section totals asserted IDENTICAL pre/post, all-or-nothing transaction.

# Field list copied when materializing an orphan Actual line onto Working.
# Mirrors clone_estimated_to_working's line_skip set: everything EXCEPT the
# structural/id columns is carried over (account_code, account_name,
# description, is_labor, sort_order, rate, days, estimated_total, etc.).
_MIGRATE_LINE_SKIP = {'id', 'budget_id', 'parent_line_id', 'source_line_id',
                      'orphan_from_working', 'crew_assignments', 'schedule_days',
                      'assigned_crew', 'working_total', 'manual_actual'}


def _migrate_actuals_pick_working(all_b, pid):
    """Resolve the project's CURRENT Working budget (never an Actual)."""
    return (next((b for b in all_b
                  if _budget_type(b.budget_mode) == 'working'
                  and not b.is_actual and b.version_status == 'current'), None)
            or next((b for b in all_b
                     if _budget_type(b.budget_mode) == 'working'
                     and not b.is_actual and b.version_status != 'archived'), None))


@app.route("/projects/<int:pid>/migrate-actuals", methods=["POST", "GET"])
@login_required
def migrate_actuals(pid):
    # Destructive/one-time repair tool — super-admin only before outside
    # users arrive (tools audit 2026-07-20).
    if getattr(current_user, 'role', None) != 'super_admin':
        abort(403)
    """PHASE 2 one-time migration: remap every legacy reference off the Actual
    clone lines onto Working lines, then archive the Actual budgets.

    Gated to super_admin / admin only. DRY-RUN BY DEFAULT — mutations happen
    ONLY when `dry` is explicitly false/0 (?dry=0 on GET, or {"dry": false} in
    the POST body). Any other value (missing, "1", true, garbage) → dry.

    On a live run the whole thing is a single all-or-nothing transaction: we
    remap, recompute the per-section actuals rollup, and ASSERT it is identical
    (per code, 2dp) to the pre-migration snapshot. If ANY code differs we
    rollback and return {ok:false, aborted:true} — nothing is committed unless
    the totals match exactly. Archiving (never deleting — audit trail) and the
    ActivityLog entry happen only after the assert passes.
    """
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403

    # DRY DEFAULT: mutate ONLY when dry is EXPLICITLY false/0. Everything else
    # (absent, "1", "true", anything) stays dry.
    body = request.get_json(silent=True) or {}
    _raw = request.args.get('dry', body.get('dry', True))
    if isinstance(_raw, str):
        dry = _raw.strip().lower() not in ('0', 'false', 'no', 'off')
    else:
        dry = not (_raw is False or _raw == 0)

    ProjectSheet.query.get_or_404(pid)
    all_b = Budget.query.filter_by(project_id=pid).all()

    working = _migrate_actuals_pick_working(all_b, pid)
    actual_budgets = [b for b in all_b if b.is_actual]
    if not working:
        return jsonify({"ok": False, "dry": dry, "project": pid,
                        "error": "no current Working budget to migrate onto"}), 400

    # ── 1. PRE-SNAPSHOT ────────────────────────────────────────────────────
    before = _actuals_by_section_code(pid)
    before_total = round(sum(before.values()), 2)

    actual_line_ids = [l.id for b in actual_budgets
                       for l in BudgetLine.query.filter_by(budget_id=b.id).all()]
    actual_line_ids_set = set(actual_line_ids)

    def _count_on_actual(model, col='budget_line_id'):
        if not actual_line_ids:
            return 0
        return (db.session.query(model)
                .filter(getattr(model, col).in_(actual_line_ids)).count())

    pre_counts = {
        "txns_on_actual_lines":      (Transaction.query
                                      .filter(Transaction.project_id == pid,
                                              Transaction.budget_line_id.in_(actual_line_ids)).count()
                                      if actual_line_ids else 0),
        "suggested_on_actual_lines": (Transaction.query
                                      .filter(Transaction.project_id == pid,
                                              Transaction.suggested_budget_line_id.in_(actual_line_ids)).count()
                                      if actual_line_ids else 0),
        "subbudget_on_actual_lines": _count_on_actual(SubBudgetLine),
        "location_on_actual_lines":  _count_on_actual(Location),
        "crew_on_actual_lines":      _count_on_actual(CrewAssignment),
        "schedule_line_on_actual":   _count_on_actual(ScheduleDay),
        "schedule_budget_on_actual": (ScheduleDay.query
                                      .filter(ScheduleDay.budget_id.in_([b.id for b in actual_budgets])).count()
                                      if actual_budgets else 0),
    }

    # ── 2. BUILD actual_line → working_line MAP ────────────────────────────
    # Index working lines for the materialize/validate steps.
    working_line_ids = {l.id for l in BudgetLine.query.filter_by(budget_id=working.id).all()}
    # Non-actual budget ids in THIS project (for source_line_id validation).
    non_actual_bids = {b.id for b in all_b if not b.is_actual}

    counts = {
        "txns_remapped": 0, "txns_kept_unmappable": 0, "suggested_remapped": 0,
        "suggested_nulled": 0, "subbudget": 0, "locations": 0,
        "crew_mirrors_deleted": 0, "crew_values_promoted": 0,
        "schedule_rows_deleted": 0, "schedule_budget_rows_deleted": 0,
        "orphan_lines_materialized": 0, "actual_budgets_archived": 0,
    }
    unmappable = []   # actual line ids we could not map (reported, never NULLed)

    def _has_deps(alid):
        """Does this actual line have ANY dependent ref that must be preserved?"""
        return bool(
            Transaction.query.filter(Transaction.budget_line_id == alid).first() or
            Transaction.query.filter(Transaction.suggested_budget_line_id == alid).first() or
            SubBudgetLine.query.filter(SubBudgetLine.budget_line_id == alid).first() or
            Location.query.filter(Location.budget_line_id == alid).first()
        )

    line_map = {}          # actual_line_id -> working_line_id
    for b in actual_budgets:
        for aline in BudgetLine.query.filter_by(budget_id=b.id).all():
            target = None
            # (a) source_line_id → a real line on a NON-actual budget of this project.
            if aline.source_line_id:
                peer = BudgetLine.query.get(aline.source_line_id)
                if peer and peer.budget_id in non_actual_bids:
                    target = peer
            if target is not None:
                line_map[aline.id] = target.id
                continue
            # (b) orphan / dangling. Materialize onto CURRENT Working ONLY if it
            #     has dependents; otherwise skip (nothing references it).
            if not _has_deps(aline.id):
                continue
            if dry:
                # Represent a would-be materialized line with a sentinel so the
                # remap counters below still count the dependent refs.
                line_map[aline.id] = ('NEW', aline.id)
                counts["orphan_lines_materialized"] += 1
            else:
                new_line = BudgetLine()
                for col in BudgetLine.__table__.columns:
                    if col.name in _MIGRATE_LINE_SKIP:
                        continue
                    setattr(new_line, col.name, getattr(aline, col.name))
                new_line.budget_id           = working.id
                new_line.source_line_id      = None
                new_line.parent_line_id      = None
                new_line.orphan_from_working = True
                db.session.add(new_line)
                db.session.flush()
                line_map[aline.id] = new_line.id
                counts["orphan_lines_materialized"] += 1

    def _resolve(mapped):
        """Translate a line_map value (int id or ('NEW', src) sentinel) to a
        real working line id, or None in dry mode for a not-yet-created line."""
        if isinstance(mapped, tuple):
            return None   # dry-run sentinel: line would be created live
        return mapped

    # ── 3. REMAP ───────────────────────────────────────────────────────────
    # 3a. Transaction.budget_line_id (canonical coding).
    #
    # ACCOUNT-CODE PINNING (fix after the first Cliburn live run ABORTED —
    # 9 section codes drifted both ways, grand total unchanged): the original
    # version mirrored account_code from the mapped Working line, but
    # (a) a txn whose account_code was deliberately set DIFFERENT from its
    #     line's code got overwritten → its spend jumped sections, and
    # (b) a NULL-code txn whose Actual line's code had DRIFTED from its
    #     Working peer's code shifted sections via the rollup's coalesce.
    # THE MIGRATION MUST NOT MOVE A SINGLE FIGURE. So: pin each txn's
    # EFFECTIVE HISTORICAL code — leave account_code untouched when set;
    # when NULL, stamp it with the OLD (actual) line's code before moving the
    # line link. Totals are then identical by construction, and the pinned
    # code preserves exactly what the user saw pre-migration. (2026-07.)
    aline_by_id = {l.id: l for l in (
        BudgetLine.query.filter(BudgetLine.id.in_(actual_line_ids)).all()
        if actual_line_ids else [])}
    for aline_id in list(line_map.keys()):
        mapped = line_map[aline_id]
        target_id = _resolve(mapped)
        old_line = aline_by_id.get(aline_id)
        txns = (Transaction.query
                .filter(Transaction.project_id == pid,
                        Transaction.budget_line_id == aline_id).all())
        for txn in txns:
            counts["txns_remapped"] += 1
            if not dry and target_id is not None:
                if txn.account_code is None and old_line is not None:
                    # Pin the effective section the rollup used pre-migration.
                    txn.account_code      = old_line.account_code
                    txn.account_code_name = old_line.account_name
                txn.budget_line_id = target_id
                txn.updated_at     = datetime.utcnow()

    # Any txn still pointing at an actual line with NO mapping = unmappable.
    # By construction (orphans with deps get materialized) this should be 0.
    # Never NULL it — keep it where it is and REPORT.
    for aline_id in actual_line_ids:
        if aline_id in line_map:
            continue
        stragglers = (Transaction.query
                      .filter(Transaction.project_id == pid,
                              Transaction.budget_line_id == aline_id).count())
        if stragglers:
            counts["txns_kept_unmappable"] += stragglers
            unmappable.append({"actual_line_id": aline_id, "txns": stragglers})

    # 3b. Transaction.suggested_budget_line_id → mapped working id (advisory:
    #     NULL if the actual line has no mapping — a suggestion is disposable).
    for aline_id in actual_line_ids:
        mapped = line_map.get(aline_id)
        target_id = _resolve(mapped) if mapped is not None else None
        sugg = (Transaction.query
                .filter(Transaction.project_id == pid,
                        Transaction.suggested_budget_line_id == aline_id).all())
        for txn in sugg:
            if mapped is not None:
                counts["suggested_remapped"] += 1
                if not dry and target_id is not None:
                    txn.suggested_budget_line_id = target_id
            else:
                counts["suggested_nulled"] += 1
                if not dry:
                    txn.suggested_budget_line_id = None

    # 3c. SubBudgetLine.budget_line_id / Location.budget_line_id → mapped id.
    #     Skip rows whose actual line had no mapping (no target to move to).
    for aline_id in actual_line_ids:
        mapped = line_map.get(aline_id)
        if mapped is None:
            continue
        target_id = _resolve(mapped)
        for sbl in SubBudgetLine.query.filter_by(budget_line_id=aline_id).all():
            counts["subbudget"] += 1
            if not dry and target_id is not None:
                sbl.budget_line_id = target_id
        for loc in Location.query.filter_by(budget_line_id=aline_id).all():
            counts["locations"] += 1
            if not dry and target_id is not None:
                loc.budget_line_id = target_id

    # 3d. CrewAssignment rows ON actual lines are WRITE-THROUGH MIRRORS: the
    #     canonical rows live on the Working peer (see assign_crew, app.py ~18538
    #     — Working is the canonical owner; Actual clones are mirrored copies).
    #     DELETE the mirrors, but first PROMOTE any override value the mirror
    #     carries that its Working peer's matching assignment lacks, so a
    #     rate_override / fringe_override / name_override / agent_override typed
    #     on the Actual view is never lost.
    _PROMOTE_FIELDS = ('rate_override', 'fringe_override', 'name_override',
                       'agent_override', 'omit_flags', 'role_number')
    for aline_id in actual_line_ids:
        mapped = line_map.get(aline_id)
        target_id = _resolve(mapped) if mapped is not None else None
        for ca in CrewAssignment.query.filter_by(budget_line_id=aline_id).all():
            counts["crew_mirrors_deleted"] += 1
            if target_id is not None:
                peer = (CrewAssignment.query
                        .filter_by(budget_line_id=target_id, instance=ca.instance).first())
                if peer is not None:
                    for f in _PROMOTE_FIELDS:
                        mv = getattr(ca, f)
                        if mv not in (None, '') and getattr(peer, f) in (None, ''):
                            counts["crew_values_promoted"] += 1
                            if not dry:
                                setattr(peer, f, mv)
            if not dry:
                db.session.delete(ca)

    # 3e. ScheduleDay rows attached to an Actual BUDGET (budget_id on an Actual)
    #     were never user-visible (the UI keys schedule off working/estimated
    #     modes). Verify count, then delete. Also drop any line-level schedule
    #     rows pointing at actual lines (defensive — normally none).
    _actual_bids = [b.id for b in actual_budgets]
    if _actual_bids:
        from models import TravelDetail as _TD_mig
        # Budget-level schedule rows.
        _bsd_ids = [r[0] for r in db.session.query(ScheduleDay.id)
                    .filter(ScheduleDay.budget_id.in_(_actual_bids)).all()]
        counts["schedule_budget_rows_deleted"] = len(_bsd_ids)
        # Line-level schedule rows on actual lines.
        _lsd_ids = ([r[0] for r in db.session.query(ScheduleDay.id)
                     .filter(ScheduleDay.budget_line_id.in_(actual_line_ids)).all()]
                    if actual_line_ids else [])
        counts["schedule_rows_deleted"] = len(_lsd_ids)
        if not dry:
            _all_sd = list(set(_bsd_ids) | set(_lsd_ids))
            if _all_sd:
                _TD_mig.query.filter(_TD_mig.schedule_day_id.in_(_all_sd))\
                    .delete(synchronize_session=False)
                ScheduleDay.query.filter(ScheduleDay.id.in_(_all_sd))\
                    .delete(synchronize_session=False)

    # ── 4. POST-ASSERT: per-section totals IDENTICAL (2dp) ─────────────────
    diffs = []
    codes_compared = 0
    if dry:
        # Nothing mutated — the rollup is unchanged by definition, but we still
        # report the snapshot so the operator sees what will be preserved.
        after = dict(before)
    else:
        db.session.flush()
        after = _actuals_by_section_code(pid)
    all_codes = set(before) | set(after)
    for code in all_codes:
        codes_compared += 1
        bv = round(before.get(code, 0.0), 2)
        av = round(after.get(code, 0.0), 2)
        if bv != av:
            diffs.append({"code": code, "before": bv, "after": av})
    identical = not diffs
    after_total = round(sum(after.values()), 2)

    if not dry and not identical:
        # ABORT — all-or-nothing. Nothing is committed.
        db.session.rollback()
        return jsonify({
            "ok": False, "dry": False, "aborted": True, "project": pid,
            "error": "per-section actuals totals changed — migration rolled back",
            "counts": counts,
            "totals_check": {"codes_compared": codes_compared,
                             "identical": False, "diffs": diffs},
            "before_total": before_total, "after_total": after_total,
        }), 500

    # ── 5. ARCHIVE (live only, after assert passes) ────────────────────────
    if not dry:
        for b in actual_budgets:
            if b.version_status != 'archived':
                b.version_status = 'archived'
                b.updated_at = datetime.utcnow()
                counts["actual_budgets_archived"] += 1
        db.session.commit()
        try:
            _log_activity(
                action='update', entity_type='budget_migration',
                entity_id=working.id,
                entity_label=f"Phase 2 actuals→Working migration (project {pid})",
                budget_id=working.id, project_id=pid,
                note=(f"Remapped {counts['txns_remapped']} txns, "
                      f"{counts['subbudget']} sub-budget, {counts['locations']} location refs; "
                      f"materialized {counts['orphan_lines_materialized']} orphan lines; "
                      f"deleted {counts['crew_mirrors_deleted']} crew mirrors "
                      f"({counts['crew_values_promoted']} values promoted), "
                      f"{counts['schedule_rows_deleted'] + counts['schedule_budget_rows_deleted']} schedule rows; "
                      f"archived {counts['actual_budgets_archived']} Actual budgets."),
                after={'counts': counts})
        except Exception:
            pass
    else:
        counts["actual_budgets_archived"] = len(
            [b for b in actual_budgets if b.version_status != 'archived'])

    return jsonify({
        "ok": True, "dry": dry, "project": pid,
        "pre_counts": pre_counts,
        "counts": counts,
        "totals_check": {"codes_compared": codes_compared,
                         "identical": identical, "diffs": diffs},
        "unmappable": unmappable,
        "before_total": before_total, "after_total": after_total,
    })


@app.route("/projects/migrate-actuals/scan", methods=["GET"])
@login_required
def migrate_actuals_scan():
    """Blast-radius scan (read-only, admin): every project that still has any
    Actual budget, with its Actual-budget count and how many transactions are
    still coded to Actual-clone lines. Lets us see scope before running
    /projects/<pid>/migrate-actuals anywhere."""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403

    rows = []
    actual_budgets = Budget.query.filter_by(is_actual=True).all()
    by_project = {}
    for b in actual_budgets:
        by_project.setdefault(b.project_id, []).append(b)

    for pid, bs in by_project.items():
        proj = ProjectSheet.query.get(pid)
        line_ids = [l.id for b in bs
                    for l in BudgetLine.query.filter_by(budget_id=b.id).all()]
        txns = (Transaction.query
                .filter(Transaction.project_id == pid,
                        Transaction.budget_line_id.in_(line_ids)).count()
                if line_ids else 0)
        rows.append({
            "pid": pid,
            "name": proj.name if proj else None,
            "actual_budgets": len(bs),
            "actual_budgets_current": len([b for b in bs
                                           if b.version_status == 'current']),
            "txns_on_actual_lines": txns,
        })
    rows.sort(key=lambda r: (-r["txns_on_actual_lines"], r["pid"]))
    return jsonify({"ok": True, "projects": rows,
                    "total_projects": len(rows)})


@app.route("/docs/<int:pid>/reconcile-filing", methods=["POST"])
@login_required
def docs_reconcile_filing(pid):
    """Reconcile every filed doc in a project so its Dropbox location matches
    the software's current metadata — fixes files left orphaned by edits made
    before save-time re-filing existed. Admin only. (User 2026-05-29.)

    Body/params:
      dry   : true → preview only, no Dropbox calls (processes ALL).
      limit : real runs process at most this many MOVES per call (default 12)
              and commit PER ITEM, so a worker timeout can't leave Dropbox
              and the DB out of sync. The client loops until remaining == 0.
    Returns {moved, already_ok, skipped, errors, remaining}."""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    body = request.get_json(silent=True) or {}
    dry = (request.args.get('dry') == '1') or bool(body.get('dry'))
    try:
        limit = int(request.args.get('limit') or body.get('limit') or 12)
    except (TypeError, ValueError):
        limit = 12
    # Optional category filter — lets a targeted migration touch ONLY one
    # doc type (e.g. employee_vendor_doc → per-person folders) without
    # disturbing every other filed doc in the project. (User 2026-05-30.)
    cat_filter = (request.args.get('category') or body.get('category') or '').strip()
    q = (DocUpload.query
         .filter_by(project_id=pid)
         .filter(DocUpload.status.in_(['done', 'filed'])))
    if cat_filter:
        q = q.filter(DocUpload.category == cat_filter)
    uploads = q.all()
    report = {"dry": dry, "total": len(uploads), "moved": [], "already_ok": 0,
              "skipped": 0, "errors": [], "remaining": 0}
    done_moves = 0
    for u in uploads:
        # On a real run, stop after `limit` actual moves (commit per item).
        # Remaining still-needed moves are counted (dry check) so the client
        # knows whether to loop again.
        if not dry and limit and done_moves >= limit:
            r = _refile_doc(u, dry=True)   # cheap: no Dropbox call
            if r.get("changed"):
                report["remaining"] += 1
            continue
        r = _refile_doc(u, dry=dry)
        if r.get("changed"):
            report["moved"].append({"id": u.id, "from": r["from"], "to": r["to"],
                                    "healed": r.get("healed", False)})
            if not dry:
                db.session.commit()        # durable per item
                done_moves += 1
        elif r.get("error"):
            report["errors"].append({"id": u.id, "error": r["error"]})
        elif r.get("reason") in ("not filed", "special folder", "unresolved"):
            report["skipped"] += 1
        else:
            report["already_ok"] += 1
    logging.info(f"[reconcile-filing] pid={pid} dry={dry}: "
                 f"{len(report['moved'])} {'would move' if dry else 'moved'}, "
                 f"{report['already_ok']} ok, {report['skipped']} skipped, "
                 f"{len(report['errors'])} errors, {report['remaining']} remaining")
    return jsonify(report)


@app.route("/docs/<int:pid>/backfill-card4", methods=["POST"])
@login_required
def docs_backfill_card4(pid):
    """One-off: populate card_last4 on existing docs from their stored
    Veryfi OCR JSON (veryfi_data), so the new sortable Card field isn't
    blank on historical receipts. Idempotent — only touches rows where
    card_last4 is NULL and veryfi_data is present. Also syncs the value
    onto each doc's linked Transaction(s). Admin only. (User 2026-05-30.)"""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    import json as _json
    from fp_analyzer import extract_card_last4 as _extract_card4
    rows = (DocUpload.query
            .filter_by(project_id=pid)
            .filter(DocUpload.card_last4.is_(None))
            .filter(DocUpload.veryfi_data.isnot(None))
            .all())
    updated, scanned = 0, 0
    for u in rows:
        scanned += 1
        try:
            vr = _json.loads(u.veryfi_data) if u.veryfi_data else None
        except Exception:
            vr = None
        c4 = _extract_card4(vr) if vr else None
        if not c4:
            continue
        u.card_last4 = c4
        for _t in Transaction.query.filter_by(doc_upload_id=u.id).all():
            if not _t.card_last4:
                _t.card_last4 = c4
        updated += 1
        if updated % 50 == 0:
            db.session.commit()
    db.session.commit()
    logging.info(f"[backfill-card4] pid={pid}: scanned {scanned}, set {updated}")
    return jsonify({"scanned": scanned, "updated": updated})


@app.route("/docs/<int:pid>/relabel-subtype", methods=["POST"])
@login_required
def docs_relabel_subtype(pid):
    """Bulk-relabel the sub-type (stored in `vendor`) of Employee/Vendor docs
    whose current value matches one of `match` → `to`, then re-file each in
    Dropbox so the filename/folder follow. Per-item commit + `limit` so a
    worker timeout can't desync; client loops until remaining == 0. Admin only.
    Body: {match: ["dtr", ...], to: "Tax Credit Documents", limit: 12}.
    (User 2026-06-01.)"""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    body  = request.get_json(silent=True) or {}
    match = {str(m).strip().lower() for m in (body.get("match") or []) if str(m).strip()}
    to    = (body.get("to") or "").strip()
    try:
        limit = int(body.get("limit") or 12)
    except (TypeError, ValueError):
        limit = 12
    if not match or not to:
        return jsonify({"error": "match[] and to are required"}), 400
    rows = (DocUpload.query
            .filter_by(project_id=pid, category='employee_vendor_doc')
            .filter(DocUpload.vendor.isnot(None))
            .all())
    targets = [u for u in rows if (u.vendor or '').strip().lower() in match]
    report = {"matched": len(targets), "relabeled": 0, "moved": [], "errors": [], "remaining": 0}
    done = 0
    for u in targets:
        if (u.vendor or '').strip() == to:
            continue  # already correct
        if limit and done >= limit:
            report["remaining"] += 1
            continue
        u.vendor = to
        report["relabeled"] += 1
        try:
            r = _refile_doc(u)
            if r.get("changed"):
                report["moved"].append({"id": u.id, "to": r.get("to")})
            elif r.get("error"):
                report["errors"].append({"id": u.id, "error": r.get("error")})
        except Exception as e:
            report["errors"].append({"id": u.id, "error": str(e)})
        db.session.commit()
        done += 1
    logging.info(f"[relabel-subtype] pid={pid}: matched {report['matched']}, "
                 f"relabeled {report['relabeled']}, moved {len(report['moved'])}, "
                 f"errors {len(report['errors'])}, remaining {report['remaining']}")
    return jsonify(report)


@app.route("/admin/veryfi/classify/<int:uid>")
@login_required
def admin_veryfi_classify(uid):
    """Read-only diagnostic: run Veryfi's /classify on an existing doc's file
    and return the predicted type + score. Lets us verify classify-first
    routing live without uploading. Admin only. (User 2026-06-01.)"""
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Forbidden — admin only"}), 403
    upload = DocUpload.query.get_or_404(uid)
    deny = _docs_check_row_access(upload)
    if deny:
        return deny
    path = upload.filed_dropbox_path or upload.source_archive_path
    if not path:
        return jsonify({"error": "no file on this upload"}), 404
    try:
        dbx = _dbx_client()
        _ops = (_DBX_OPS_ROOT or "").rstrip("/") if _DBX_NAMESPACE_ID else ""
        norm = path[len(_ops):] if (_ops and path.startswith(_ops + "/")) else path
        link = None
        for t in (norm, path) if norm != path else (norm,):
            try:
                link = dbx.files_get_temporary_link(t).link
                break
            except Exception:
                continue
        if not link:
            return jsonify({"error": "could not build temp link"}), 502
        from fp_analyzer import get_veryfi_client
        res = get_veryfi_client().classify_document_url(file_url=link)
        dt = (res or {}).get("document_type") if isinstance(res, dict) else None
        return jsonify({"uid": uid, "filename": upload.filed_filename,
                        "current_category": upload.category,
                        "classify": dt or res})
    except Exception as e:
        return jsonify({"error": f"{type(e).__name__}: {e}"}), 500


@app.route("/docs/upload/<int:uid>/reocr", methods=["POST"])
@login_required
def docs_upload_reocr(uid):
    """Re-run OCR (Veryfi) on ONE document on demand and RETURN the freshly
    extracted fields — vendor / amount / date / card, plus foreign-currency
    original + USD conversion — WITHOUT saving. The detail panel fills them in
    so the user can review and Save. Lets you re-read a receipt OCR got wrong
    (e.g. a foreign transaction that wasn't recognized). (User 2026-06-17.)"""
    upload = DocUpload.query.get_or_404(uid)
    deny = _docs_check_row_access(upload)
    if deny:
        return deny
    from datetime import datetime as _dt
    path = upload.source_archive_path or upload.filed_dropbox_path
    if not path:
        return jsonify({"error": "No stored file to re-read for this document."}), 400
    item = {"original_filename": upload.original_filename or '', "staged_path": path}
    try:
        item = _call_veryfi_bounded(item, secs=90)
    except Exception as e:
        logging.exception(f"[reocr] Veryfi failed for #{uid}: {e}")
        return jsonify({"error": f"OCR failed: {e}"}), 500
    vr = (item or {}).get("vr") or {}
    if item is None or item.get("error") or not vr:
        return jsonify({"error": "OCR couldn't read this file (timed out or returned nothing)."}), 502
    from fp_analyzer import extract_card_last4 as _c4
    v = vr.get("vendor") or {}
    vendor = v.get("name") or v.get("raw_name")
    try:
        total = float(vr.get("total")) if vr.get("total") is not None else None
    except (TypeError, ValueError):
        total = None
    doc_date = None
    try:
        _ds = (vr.get("date") or "")[:10]
        if _ds:
            doc_date = _dt.strptime(_ds, "%Y-%m-%d").date().isoformat()
    except Exception:
        pass
    ccy = _normalize_ccy(vr.get("currency_code"))
    orig_amt, orig_ccy, usd, fx_note = None, None, total, None
    if total is not None and ccy and ccy != 'USD':
        _usd, _rate, _ = _convert_to_usd(total, ccy, doc_date)
        orig_amt, orig_ccy = total, ccy
        if _usd is not None:
            usd = _usd
            fx_note = f"{ccy} {total:,.2f} → ${_usd:,.2f}"
        else:
            fx_note = f"Detected {ccy} {total:,.2f}, but no exchange rate was available."
    return jsonify({
        "ok": True,
        "vendor": vendor,
        "amount": (round(usd, 2) if usd is not None else None),
        "original_amount": orig_amt, "original_currency": orig_ccy,
        "doc_date": doc_date, "card_last4": _c4(vr),
        "currency": ccy, "fx_note": fx_note,
    })


@app.route("/docs/upload/<int:uid>/update", methods=["POST"])
@login_required
def docs_upload_update(uid):
    """Update the editable metadata fields on a DocUpload row from the
    detail modal: vendor, amount, doc_date, category (doc type), note.

    Only edits the DB row — does NOT re-OCR, does NOT touch the Dropbox
    file (use /rename for the filename). Filed_filename and the Dropbox
    file stay unchanged so the user can correct vendor/amount typos
    without disturbing the filed file's path.
    """
    upload = DocUpload.query.get_or_404(uid)
    deny = _docs_check_row_access(upload)
    if deny:
        return deny
    # `_dt` is used below (filed_at, txn updated_at) but was never defined in
    # this function — `_dt` is only a local alias in other functions and the
    # module imports plain `datetime`. That NameError was silently caught,
    # so a doc's amount/vendor edit never propagated to its linked Actuals
    # transaction (user 2026-05-29: "I change the amount and it doesn't take").
    from datetime import datetime as _dt

    data = request.get_json(force=True) or {}
    _act_before = {
        'vendor': upload.vendor, 'amount': float(upload.amount) if upload.amount else None,
        'doc_date': upload.doc_date.isoformat() if upload.doc_date else None,
        'category': upload.category, 'note': upload.note,
    }
    if "vendor" in data:
        v = (data.get("vendor") or "").strip()
        upload.vendor = v[:200] if v else None
    if "amount" in data:
        a = data.get("amount")
        if a in (None, "", "null"):
            upload.amount = None
        else:
            try:
                upload.amount = round(float(a), 2)
            except (TypeError, ValueError):
                return jsonify({"error": "amount must be a number"}), 400
    # Foreign-currency original figure (USD `amount` above is the
    # reconciliation value). 2026-05-29.
    if "original_amount" in data:
        oa = data.get("original_amount")
        if oa in (None, "", "null"):
            upload.original_amount = None
        else:
            try:
                upload.original_amount = round(float(oa), 2)
            except (TypeError, ValueError):
                return jsonify({"error": "original_amount must be a number"}), 400
    if "original_currency" in data:
        oc = (data.get("original_currency") or "").strip().upper()
        upload.original_currency = oc[:8] or None
    if "doc_date" in data:
        d = (data.get("doc_date") or "").strip()
        if not d:
            upload.doc_date = None
        else:
            try:
                from datetime import datetime as _dt_mod
                upload.doc_date = _dt_mod.strptime(d[:10], "%Y-%m-%d").date()
            except Exception:
                return jsonify({"error": "doc_date must be YYYY-MM-DD"}), 400
    # Capture the category change so we can move the file post-commit
    # if the type changed and the file is currently filed in Dropbox.
    _old_category = upload.category
    _category_changed = False
    if "category" in data:
        c = (data.get("category") or "").strip()
        new_cat = c[:100] if c else None
        if new_cat != upload.category:
            _category_changed = True
        upload.category = new_cat
    if "note" in data:
        n = (data.get("note") or "").strip()
        upload.note = n[:500] if n else None
    if "doc_number" in data:
        dn = (data.get("doc_number") or "").strip()
        upload.doc_number = dn[:100] if dn else None
    if "card_last4" in data:
        # Keep digits only; store the last 4 (so "****1234" or "1234" both
        # land as "1234"). Blank clears.
        c4 = re.sub(r"\D", "", str(data.get("card_last4") or ""))
        upload.card_last4 = c4[-4:] if c4 else None
    # Receipt detail (tax-credit reporting): subtotal / tax / tip + merchant
    # address / phone. Empty clears. (User 2026-07.)
    for _fld in ('subtotal', 'tax', 'tip'):
        if _fld in data:
            _v = data.get(_fld)
            if _v in (None, "", "null"):
                setattr(upload, _fld, None)
            else:
                try:
                    setattr(upload, _fld, round(float(_v), 2))
                except (TypeError, ValueError):
                    return jsonify({"error": f"{_fld} must be a number"}), 400
    if "merchant_address" in data:
        _ma = (data.get("merchant_address") or "").strip()
        upload.merchant_address = _ma[:300] if _ma else None
    if "merchant_phone" in data:
        _mp = (data.get("merchant_phone") or "").strip()
        upload.merchant_phone = _mp[:40] if _mp else None
    # Crew / location linkage. Empty / null clears.
    if "crew_member_id" in data:
        cm = data.get("crew_member_id")
        if cm in (None, "", "null", "0", 0):
            upload.crew_member_id = None
        else:
            try:
                upload.crew_member_id = int(cm)
            except (TypeError, ValueError):
                return jsonify({"error": "crew_member_id must be int"}), 400
    if "location_id" in data:
        lc = data.get("location_id")
        if lc in (None, "", "null", "0", 0):
            upload.location_id = None
        else:
            try:
                upload.location_id = int(lc)
            except (TypeError, ValueError):
                return jsonify({"error": "location_id must be int"}), 400

    # ── File on review-confirm OR re-file on type change ──────────────
    # Two cases handled by one block:
    #
    # (A) Review confirmation: status='review' means OCR happened but
    #     the doc never got filed because confidence was low. The
    #     bytes live in _SOURCE_ARCHIVE/ only. When the user picks a
    #     category in the modal and saves, COPY the archive file into
    #     the right processed folder, mirroring auto_file_high_confidence's
    #     layout (per-user, vendor subfolder for AP types). Flip the
    #     row to status='done'.
    #
    # (B) Type change on an already-filed doc: MOVE the processed file
    #     into the new type folder so the filing structure matches the
    #     user's classification.
    refile_info = None
    # Source for the copy: prefer source_archive_path (added 2026-04-30)
    # but fall back to filed_dropbox_path for older review-status rows
    # which were saved before that column existed. Either points at the
    # staged file in _SOURCE_ARCHIVE/, which is what we copy from.
    _src_for_copy = upload.source_archive_path or upload.filed_dropbox_path
    if upload.category and _src_for_copy:
        try:
            from fp_analyzer import (
                DOCUMENT_TYPES, DOC_PREFIXES,
                get_dropbox_client as _ana_dbx,
                _ops_prefix as _ana_ops,
                safe as _ana_safe,
            )
            new_type_folder = DOCUMENT_TYPES.get(upload.category)
            proj = ProjectSheet.query.get(upload.project_id)
            proj_name = (proj.dropbox_folder or '').strip('/') if proj else ''
            ops = _ana_ops()

            def _build_processed_path():
                """Compute the destination path for this row's processed
                copy, mirroring auto_file_high_confidence's layout."""
                if not (proj_name and new_type_folder):
                    return None, None
                user_name = (current_user.name
                             or (current_user.email or '').split('@')[0]
                             or f'user-{current_user.id}')
                user_folder = _ana_safe(user_name)
                # Construct a date-prefixed filename from the row's data.
                # Falls back to the existing filed_filename if we already
                # had one (review re-confirms keep the Analyzer's name).
                fname = upload.filed_filename
                if not fname:
                    date_str = (upload.doc_date.isoformat()
                                if upload.doc_date else 'Unknown')
                    vendor   = _ana_safe(upload.vendor or 'Unknown')
                    amount   = (f"{float(upload.amount):.2f}"
                                if upload.amount is not None else 'Unknown')
                    prefix   = DOC_PREFIXES.get(upload.category, 'DOC')
                    if upload.category in ('contract', 'tax_form', 'release'):
                        # No amount in the name for these (irrelevant or absent)
                        fname = f"{date_str}_{prefix}_{vendor}.pdf"
                    elif upload.category == 'invoice' or upload.category == 'purchase_order':
                        # Include any invoice/PO# from notes if present.
                        fname = f"{date_str}_{prefix}_{vendor}_{amount}.pdf"
                    else:
                        fname = f"{date_str}_{prefix}_{vendor}_{amount}.pdf"
                base = f"{ops}/{proj_name}/{new_type_folder}" if ops else f"/{proj_name}/{new_type_folder}"
                if upload.category in ('invoice', 'contract', 'purchase_order', 'insurance'):
                    vendor_folder = _ana_safe(upload.vendor or 'Unknown_Vendor')
                    return f"{base}/{user_folder}/{vendor_folder}/{fname}", fname
                # Employee/Vendor docs → per-person packet folder (crew link),
                # falling back to the uploader folder. Mirrors
                # _doc_intended_path. (User 2026-05-30.)
                if upload.category == 'employee_vendor_doc' and upload.crew_member_id:
                    _cm = CrewMember.query.get(upload.crew_member_id)
                    if _cm and (_cm.name or '').strip():
                        return f"{base}/{_ana_safe(_cm.name.strip())}/{fname}", fname
                return f"{base}/{user_folder}/{fname}", fname

            # Case A — review confirmation (file not yet processed)
            if upload.status == 'review' or not upload.filed_at:
                if new_type_folder:
                    dest_path, dest_name = _build_processed_path()
                    if dest_path:
                        try:
                            dbx = _ana_dbx()
                            meta = dbx.files_copy_v2(
                                _src_for_copy, dest_path,
                                autorename=True, allow_ownership_transfer=False,
                            )
                            upload.filed_dropbox_path = meta.metadata.path_display
                            upload.filed_filename    = os.path.basename(meta.metadata.path_display)
                            upload.filed_at          = _dt.utcnow()
                            upload.status            = 'done'
                            # Backfill source_archive_path on legacy rows so
                            # next time around we don't have to fall back.
                            if not upload.source_archive_path:
                                upload.source_archive_path = _src_for_copy
                            refile_info = {
                                'action': 'filed_from_review',
                                'from':   _src_for_copy,
                                'to':     meta.metadata.path_display,
                            }
                        except Exception as _me:
                            logging.warning(
                                f"[/update] review-confirm copy failed for upload {uid}: {_me}")
                            refile_info = {'error': str(_me)}

            # Case B — already-filed doc: re-file to match ALL current
            # fields (vendor / type / date / amount / doc-number), not just
            # the type folder. _refile_doc computes the full intended path
            # and moves only if it actually differs. (User 2026-05-29: a
            # vendor correction must move the file + its vendor subfolder,
            # not leave an orphan.)
            else:
                _r = _refile_doc(upload)
                if _r.get("changed"):
                    refile_info = {'action': 'refiled', 'from': _r.get('from'), 'to': _r.get('to')}
                elif _r.get("error"):
                    refile_info = {'error': _r.get('error')}
        except Exception as _e:
            logging.warning(f"[/update] re-file logic error for upload {uid}: {_e}")

    # ── Sync DocUpload metadata edits to linked Transaction(s) ─────────
    # The Docs tab and the Actuals tab show the same physical file from
    # different angles. Editing vendor / amount / date / note in the
    # Docs detail modal should propagate to the auto-created Transaction
    # row(s) so the two views stay in lockstep. Without this the user
    # sees one vendor in Docs and another (the original OCR value) in
    # Actuals — the exact "names don't match" symptom they reported.
    #
    # Category change to a non-ledger type (estimate / quote / PO / tax
    # form / contract / release / legal / insurance / misc) DELETES the
    # linked Transaction rows: those doc types are forecast paperwork,
    # not spend events, so they shouldn't sit on the actuals ledger.
    # 2026-05-06 — fixes "PO and estimate docs still showing up in the
    # Actuals tab after I corrected the doc type from invoice".
    _NON_LEDGER_CATS = {'tax_form', 'contract', 'release', 'legal',
                        'insurance', 'misc', 'employee_vendor_doc',
                        'estimate', 'quote', 'purchase_order'}
    try:
        if (upload.category or '') in _NON_LEDGER_CATS:
            # Pull Transaction ids first so we can clean up child FK rows
            # (qbo_account_map is fine; budget_line stays — it just
            # loses any actual_amount contribution from these txns).
            _txn_ids = [t.id for t in
                        Transaction.query.filter_by(doc_upload_id=upload.id).all()]
            if _txn_ids:
                Transaction.query.filter(Transaction.id.in_(_txn_ids)) \
                    .delete(synchronize_session=False)
                logging.info(f"[/update] doc {uid} switched to non-ledger "
                             f"category '{upload.category}' — deleted "
                             f"{len(_txn_ids)} linked Transaction row(s)")
        else:
            # NEVER sync onto invoice_split children: their amount is the
            # SUBLINE amount and their note is the subline description — the
            # doc-level metadata belongs to the container only. Syncing them
            # overwrote every itemized line with the full invoice total on any
            # doc Save (user 2026-07-20: "it doesn't hold the value of that
            # line and replaces it with the total value for the invoice").
            linked_txns = (Transaction.query
                           .filter(Transaction.doc_upload_id == upload.id,
                                   Transaction.source != 'invoice_split')
                           .all())
            for _t in linked_txns:
                _t.vendor   = upload.vendor
                _t.amount   = upload.amount
                _t.txn_date = upload.doc_date.isoformat() if upload.doc_date else None
                _t.note     = upload.note
                _t.card_last4 = upload.card_last4
                _t.updated_at = _dt.utcnow()
    except Exception as _se:
        logging.warning(f"[/update] could not sync to linked txns for upload {uid}: {_se}")

    # Person-doc duplicate guard: if this is an employee/vendor doc (W-9, ID,
    # etc.) for a person who already has the SAME sub-type, flag it for review
    # so it lands in the compare/dup workflow instead of silently duplicating.
    _dup_orig = None
    try:
        _dup_orig = _flag_person_doc_duplicate(upload)
    except Exception as _pde:
        logging.warning(f"[/update] person-doc dup check failed for upload {uid}: {_pde}")

    db.session.commit()
    try:
        _act_after = {
            'vendor': upload.vendor, 'amount': float(upload.amount) if upload.amount else None,
            'doc_date': upload.doc_date.isoformat() if upload.doc_date else None,
            'category': upload.category, 'note': upload.note,
        }
        if _act_before != _act_after:
            _label = upload.filed_filename or upload.original_filename or f'Upload #{uid}'
            _log_activity(action='update', entity_type='doc_upload',
                          entity_id=uid, entity_label=_label,
                          project_id=upload.project_id,
                          before=_act_before, after=_act_after,
                          note=f'Updated metadata on "{_label}"')
    except Exception: pass
    return jsonify({
        "ok":          True,
        "vendor":      upload.vendor,
        "amount":      float(upload.amount) if upload.amount is not None else None,
        "original_amount":   float(upload.original_amount) if upload.original_amount is not None else None,
        "original_currency": upload.original_currency,
        "doc_date":    upload.doc_date.isoformat() if upload.doc_date else None,
        "category":    upload.category,
        "note":        upload.note,
        "doc_number":  upload.doc_number,
        "card_last4":  upload.card_last4,
        "status":      upload.status,
        "filed_path":  upload.filed_dropbox_path,
        "refile":      refile_info,
    })


# ── Debug: dump a budget line + both calc paths ──────────────────────────────
# Lets us inspect why calc_line vs calc_line_from_schedule disagree on a given
# line. Super-admin-gated. Returns JSON with the raw BudgetLine row, its
# schedule rows, and the result of both calc paths so we can see exactly
# where a divergence comes from. Add to a URL like:
#   /admin/debug/line/306?account_code=3500&description=Flights
# 2026-05-08.
@app.route("/admin/debug/line/<int:bid>")
@super_admin_required
def debug_line(bid):
    from flask import jsonify, request
    from models import Budget, BudgetLine, ScheduleDay
    from budget_calc import (calc_line, calc_line_from_schedule,
                             get_fringe_configs)
    budget = Budget.query.get_or_404(bid)
    q = BudgetLine.query.filter_by(budget_id=bid)
    if request.args.get('account_code'):
        q = q.filter_by(account_code=int(request.args['account_code']))
    if request.args.get('description'):
        q = q.filter(BudgetLine.description.ilike(
            f"%{request.args['description']}%"))
    if request.args.get('line_id'):
        q = q.filter_by(id=int(request.args['line_id']))
    lines = q.all()
    fringe = get_fringe_configs(db.session, budget.project_id)
    profile = budget.payroll_profile
    pw_start = (budget.payroll_week_start
                if budget.payroll_week_start is not None
                else (profile.payroll_week_start if profile else 6))
    sched_mode = ('working'
                  if budget.budget_mode in ('working', 'actual')
                  else 'estimated')
    out = {
        "budget": {
            "id": budget.id, "name": budget.name, "mode": budget.budget_mode,
            "is_actual": bool(budget.is_actual),
        },
        "lines": [],
    }
    for ln in lines:
        # Strict working-mode rows (cross-view query)
        sched_strict = ScheduleDay.query.filter_by(
            budget_line_id=ln.id, schedule_mode=sched_mode).all()
        # working-OR-NULL rows with dedup (line_results / Working-view query)
        sched_loose_raw = ScheduleDay.query.filter(
            ScheduleDay.budget_line_id == ln.id,
            db.or_(ScheduleDay.schedule_mode == sched_mode,
                   ScheduleDay.schedule_mode == None),
        ).all()
        _dedup = {}
        for d in sched_loose_raw:
            k = (d.crew_instance or 1, d.date)
            ex = _dedup.get(k)
            if ex is None:
                _dedup[k] = d
            elif ex.schedule_mode is None and d.schedule_mode == sched_mode:
                _dedup[k] = d
        sched_loose = list(_dedup.values())

        def _do_calc(rows):
            try:
                if ln.use_schedule:
                    if rows:
                        r = calc_line_from_schedule(ln, rows, fringe,
                                                    profile, pw_start)
                    else:
                        r = calc_line(ln, fringe)
                        r["_note"] = "no schedule rows → fell back to calc_line"
                else:
                    r = calc_line(ln, fringe)
                return r
            except Exception as e:
                return {"_error": repr(e)}

        out["lines"].append({
            "id": ln.id,
            "account_code": ln.account_code,
            "sort_order": ln.sort_order,
            "source_line_id": ln.source_line_id,
            "parent_line_id": ln.parent_line_id,
            "description": ln.description,
            "is_labor": bool(ln.is_labor),
            "use_schedule": bool(ln.use_schedule),
            "rate_type": ln.rate_type,
            "fringe_type": ln.fringe_type,
            "quantity": float(ln.quantity) if ln.quantity is not None else None,
            "days": float(ln.days) if ln.days is not None else None,
            "rate": float(ln.rate) if ln.rate is not None else None,
            "agent_pct": float(ln.agent_pct) if ln.agent_pct is not None else None,
            "estimated_total": (float(ln.estimated_total)
                                if ln.estimated_total is not None else None),
            "working_total": (float(ln.working_total)
                              if ln.working_total is not None else None),
            "line_tag": ln.line_tag,
            "sync_omit": bool(getattr(ln, 'sync_omit', False)),
            "sched_strict_count": len(sched_strict),
            "sched_loose_count": len(sched_loose),
            "calc_strict": _do_calc(sched_strict),  # cross-view path
            "calc_loose":  _do_calc(sched_loose),   # Working-view path
            "schedule_strict": [
                {"id": d.id, "instance": d.crew_instance, "date": str(d.date),
                 "day_type": d.day_type, "mode": d.schedule_mode,
                 "est_ot_hours": float(getattr(d, 'est_ot_hours', None) or 0)}
                for d in sched_strict
            ],
            "schedule_loose": [
                {"id": d.id, "instance": d.crew_instance, "date": str(d.date),
                 "day_type": d.day_type, "mode": d.schedule_mode,
                 "est_ot_hours": float(getattr(d, 'est_ot_hours', None) or 0)}
                for d in sched_loose
            ],
        })
    return jsonify(out)


# ── Admin: cleanup of estimate-linked Transactions ──────────────────────────
# Both the upload and metadata-update paths already prevent estimate-type
# docs from creating Transaction rows. But pre-guard legacy data and the
# QBO-sync-then-manual-match pathway can leave stray estimate-linked
# Transactions in the DB, polluting Actual rollups. This route gives the
# super admin a way to list them (GET) and delete them (POST).
# 2026-05-14 per user report.
@app.route("/admin/cleanup-estimate-txns", methods=["GET", "POST"])
@super_admin_required
def admin_cleanup_estimate_txns():
    from flask import request, render_template_string
    # Find every Transaction whose linked doc has a non-ledger category.
    # Join via doc_upload_id so a Transaction with no doc attached is
    # never picked up — manual-entry / pure-QBO rows are always kept.
    q = (db.session.query(Transaction, DocUpload)
         .join(DocUpload, DocUpload.id == Transaction.doc_upload_id)
         .filter(DocUpload.category.in_(_NON_LEDGER_DOC_CATEGORIES))
         .order_by(Transaction.txn_date.desc().nullslast(),
                   Transaction.id.desc()))
    rows = q.all()
    if request.method == "POST" and request.form.get("confirm") == "delete":
        _ids = [t.id for (t, _d) in rows]
        if _ids:
            (Transaction.query
             .filter(Transaction.id.in_(_ids))
             .delete(synchronize_session=False))
            db.session.commit()
            logging.warning(f"[admin/cleanup] deleted {len(_ids)} estimate-linked "
                            f"Transaction rows by user={current_user.id}")
            return render_template_string(
                "<h2>Deleted {{ n }} estimate-linked Transaction rows.</h2>"
                "<p><a href=\"{{ url_for('admin_cleanup_estimate_txns') }}\">Refresh list</a> · "
                "<a href=\"{{ url_for('dashboard') }}\">Dashboard</a></p>",
                n=len(_ids))
        return redirect(url_for('admin_cleanup_estimate_txns'))

    HTML = """
<!doctype html><html><head><title>Cleanup estimate-linked Transactions</title>
<style>
 body{font-family:system-ui,sans-serif;max-width:1100px;margin:24px auto;padding:0 18px;color:#222}
 h1{font-size:18px;margin:0 0 6px} .sub{color:#6b7280;font-size:13px;margin-bottom:16px}
 table{border-collapse:collapse;width:100%;font-size:12px}
 th{background:#f3f4f6;text-align:left;padding:6px 8px;border-bottom:1px solid #e5e7eb}
 td{padding:5px 8px;border-bottom:1px solid #f3f4f6;vertical-align:top}
 .amt{text-align:right;font-variant-numeric:tabular-nums}
 .cat{background:#fef3c7;padding:1px 6px;border-radius:3px;font-size:11px}
 .empty{padding:24px;text-align:center;color:#6b7280;background:#f9fafb;border-radius:6px}
 .danger{background:#dc2626;color:#fff;border:none;padding:10px 16px;border-radius:5px;font-weight:600;cursor:pointer;font-size:14px}
 .danger:hover{background:#b91c1c}
</style></head><body>
<h1>Cleanup: estimate-linked Transactions</h1>
<div class="sub">
  Transactions whose linked DocUpload has a non-ledger category
  (estimate / quote / purchase_order / contract / tax_form / release / legal /
  insurance / misc). These shouldn't exist — they're paperwork, not spend —
  but legacy data + post-upload category edits can leave them. Deleting them
  here cleans up the Actuals view and PO Actualized totals.
</div>
{% if rows %}
<form method="post" style="margin:18px 0">
  <input type="hidden" name="confirm" value="delete">
  <button class="danger" type="submit"
    onclick="return confirm('Delete {{ rows|length }} Transaction rows? Cannot be undone.')">
    🗑 Delete all {{ rows|length }} rows
  </button>
</form>
<table>
  <thead><tr>
    <th>txn id</th><th>doc id</th><th>category</th>
    <th>txn date</th><th>vendor</th><th class="amt">amount</th>
    <th>doc filename</th>
  </tr></thead>
  <tbody>
  {% for t, d in rows %}
  <tr>
    <td>{{ t.id }}</td><td>{{ d.id }}</td>
    <td><span class="cat">{{ d.category }}</span></td>
    <td>{{ t.txn_date or '—' }}</td>
    <td>{{ t.vendor or '—' }}</td>
    <td class="amt">{{ '${:,.2f}'.format(t.amount|float) if t.amount is not none else '—' }}</td>
    <td>{{ d.filed_filename or d.original_filename or '' }}</td>
  </tr>
  {% endfor %}
  </tbody>
</table>
{% else %}
<div class="empty">✓ No estimate-linked Transactions found. All clean.</div>
{% endif %}
</body></html>
"""
    return render_template_string(HTML, rows=rows)


# ── Debug: full-budget calc trace HTML page ──────────────────────────────────
# Side-window companion view. Shows every line's stored fields + both calc
# paths' outputs in a single readable table. Auto-refreshes every 5s so
# super admin can edit the budget in another tab and watch the calc shift
# in real time. Companion to /admin/debug/line/<bid> (which returns JSON
# for a single line). 2026-05-08 (Option B of sweep). Super-admin gated.
@app.route("/admin/debug/budget/<int:bid>")
@super_admin_required
def debug_budget_calc_trace(bid):
    from flask import render_template_string
    from models import Budget, BudgetLine, ScheduleDay
    from budget_calc import (calc_line, calc_line_from_schedule,
                             get_fringe_configs)
    budget = Budget.query.get_or_404(bid)
    fringe = get_fringe_configs(db.session, budget.project_id)
    profile = budget.payroll_profile
    pw_start = (budget.payroll_week_start
                if budget.payroll_week_start is not None
                else (profile.payroll_week_start if profile else 6))
    sched_mode = ('working'
                  if budget.budget_mode in ('working', 'actual')
                  else 'estimated')
    # Pre-bucket all schedule rows in one query so per-line filters are
    # dict lookups, not N+1 queries. Same dedup pattern budget_view uses.
    _all_sd = ScheduleDay.query.filter(
        ScheduleDay.budget_id == bid,
        db.or_(ScheduleDay.schedule_mode == sched_mode,
               ScheduleDay.schedule_mode == None),
    ).all()
    bucket_loose = {}
    bucket_strict = {}
    for d in _all_sd:
        bk = (d.crew_instance or 1, d.date)
        # Strict: only mode-specific rows
        if d.schedule_mode == sched_mode:
            bucket_strict.setdefault(d.budget_line_id, {})[bk] = d
        # Loose: dedup with mode-tagged winning over NULL
        b = bucket_loose.setdefault(d.budget_line_id, {})
        ex = b.get(bk)
        if ex is None:
            b[bk] = d
        elif ex.schedule_mode is None and d.schedule_mode == sched_mode:
            b[bk] = d

    lines = (BudgetLine.query
             .filter_by(budget_id=bid)
             .order_by(BudgetLine.account_code, BudgetLine.sort_order, BudgetLine.id)
             .all())

    rows = []
    for ln in lines:
        sched_strict = list(bucket_strict.get(ln.id, {}).values())
        sched_loose  = list(bucket_loose.get(ln.id, {}).values())

        def _do_calc(rows_):
            try:
                if ln.use_schedule:
                    if rows_:
                        return calc_line_from_schedule(ln, rows_, fringe,
                                                      profile, pw_start)
                    r = calc_line(ln, fringe)
                    r["_note"] = "no sched → calc_line fallback"
                    return r
                return calc_line(ln, fringe)
            except Exception as e:
                return {"_error": repr(e)}

        rs = _do_calc(sched_strict)
        rl = _do_calc(sched_loose)

        # Highlight rows where the two calc paths disagree, or where the
        # frozen working_total snapshot disagrees with the live calc.
        live = (rl.get("est_total") if isinstance(rl, dict) else None) or 0
        snap = float(ln.working_total) if ln.working_total is not None else None
        mismatch_calc = (rs.get("est_total") if isinstance(rs, dict) else None) != \
                        (rl.get("est_total") if isinstance(rl, dict) else None)
        mismatch_snap = snap is not None and abs((snap or 0) - live) > 0.01

        rows.append({
            "ln": ln,
            "sched_strict_n": len(sched_strict),
            "sched_loose_n":  len(sched_loose),
            "rs": rs,
            "rl": rl,
            "snap": snap,
            "live": live,
            "mismatch_calc": mismatch_calc,
            "mismatch_snap": mismatch_snap,
        })

    n_calc = sum(1 for r in rows if r["mismatch_calc"])
    n_snap = sum(1 for r in rows if r["mismatch_snap"])

    HTML = """
<!doctype html>
<html><head>
<meta http-equiv="refresh" content="5">
<title>Calc trace — {{ budget.name }}</title>
<style>
 body{font-family:-apple-system,system-ui,sans-serif;margin:0;padding:14px;background:#0b0d10;color:#e5e7eb;font-size:12px}
 h1{font-size:14px;margin:0 0 8px;color:#f3f4f6}
 .meta{color:#9ca3af;margin-bottom:10px;font-size:11px}
 .meta b{color:#e5e7eb}
 .legend{display:flex;gap:14px;margin-bottom:8px;font-size:11px;color:#9ca3af}
 .legend span{display:inline-flex;align-items:center;gap:4px}
 .swatch{display:inline-block;width:10px;height:10px;border-radius:2px}
 table{border-collapse:collapse;width:100%;font-size:11px}
 th{background:#1f2937;color:#e5e7eb;text-align:left;padding:5px 6px;position:sticky;top:0;border-bottom:1px solid #374151;white-space:nowrap}
 td{padding:4px 6px;border-bottom:1px solid #1f2937;vertical-align:top}
 tr.mismatch-snap td{background:#3f1d1d}
 tr.mismatch-calc td{background:#3f2d1d}
 .num{text-align:right;font-variant-numeric:tabular-nums;font-family:ui-monospace,monospace}
 .muted{color:#6b7280}
 .ok{color:#10b981}
 .bad{color:#ef4444}
 .desc{max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
 .small{font-size:10px;color:#9ca3af}
 .err{color:#ef4444;font-family:ui-monospace,monospace;font-size:10px}
 .pill{display:inline-block;padding:1px 5px;border-radius:3px;font-size:10px;background:#374151;color:#d1d5db}
 .pill.lab{background:#312e81;color:#a5b4fc}
 .pill.sch{background:#064e3b;color:#6ee7b7}
</style>
</head><body>
<h1>Calc trace — {{ budget.name }} <span class="muted">(bid={{ budget.id }}, mode={{ budget.budget_mode }})</span></h1>
<div class="meta">
 Auto-refresh every 5s · {{ rows|length }} lines ·
 <b class="{{ 'bad' if n_calc else 'ok' }}">{{ n_calc }}</b> calc-path mismatches ·
 <b class="{{ 'bad' if n_snap else 'ok' }}">{{ n_snap }}</b> snapshot mismatches
 (live calc vs frozen working_total)
</div>
<div class="legend">
 <span><span class="swatch" style="background:#3f1d1d"></span>working_total snapshot ≠ live calc (Top Sheet bug)</span>
 <span><span class="swatch" style="background:#3f2d1d"></span>strict-mode calc ≠ loose-mode calc (NULL-mode legacy rows)</span>
</div>
<table>
<thead><tr>
 <th>code</th><th>description</th>
 <th>tags</th>
 <th class="num">qty</th><th class="num">days</th><th class="num">rate</th>
 <th class="num">agent%</th>
 <th>fringe</th><th>rate_type</th>
 <th class="num">sched (strict / loose)</th>
 <th class="num">est_total<br>strict</th>
 <th class="num">est_total<br>loose (live)</th>
 <th class="num">working_total<br>snapshot</th>
 <th class="num">subtotal<br>(loose)</th>
 <th class="num">agent$<br>(loose)</th>
 <th class="num">fringe$<br>(loose)</th>
</tr></thead>
<tbody>
{% for r in rows %}
{% set ln = r.ln %}
<tr class="{% if r.mismatch_snap %}mismatch-snap{% elif r.mismatch_calc %}mismatch-calc{% endif %}">
 <td class="muted">{{ ln.account_code }}</td>
 <td class="desc" title="{{ ln.description }}">{{ ln.description or '—' }}</td>
 <td>
  {% if ln.is_labor %}<span class="pill lab">labor</span>{% endif %}
  {% if ln.use_schedule %}<span class="pill sch">sched</span>{% endif %}
  {% if ln.line_tag %}<span class="pill">{{ ln.line_tag }}</span>{% endif %}
  {% if ln.sync_omit %}<span class="pill" style="background:#5b21b6;color:#ddd6fe">sync_omit</span>{% endif %}
 </td>
 <td class="num">{{ '%g' % ln.quantity if ln.quantity is not none else '—' }}</td>
 <td class="num">{{ '%g' % ln.days if ln.days is not none else '—' }}</td>
 <td class="num">{{ '%g' % ln.rate if ln.rate is not none else '—' }}</td>
 <td class="num">{{ '%g' % (ln.agent_pct * 100) if ln.agent_pct else '0' }}%</td>
 <td><span class="muted">{{ ln.fringe_type or '—' }}</span></td>
 <td><span class="muted">{{ ln.rate_type or '—' }}</span></td>
 <td class="num"><span class="muted">{{ r.sched_strict_n }} / {{ r.sched_loose_n }}</span></td>
 <td class="num">
  {% if r.rs._error is defined %}<span class="err">{{ r.rs._error }}</span>
  {% else %}{{ '%.2f' % (r.rs.est_total or 0) }}{% endif %}
 </td>
 <td class="num"><b>
  {% if r.rl._error is defined %}<span class="err">{{ r.rl._error }}</span>
  {% else %}{{ '%.2f' % (r.rl.est_total or 0) }}{% endif %}
 </b></td>
 <td class="num">
  {% if r.snap is none %}<span class="muted">—</span>
  {% else %}{{ '%.2f' % r.snap }}{% endif %}
 </td>
 <td class="num"><span class="muted">{{ '%.2f' % (r.rl.subtotal or 0) if r.rl.subtotal is defined else '' }}</span></td>
 <td class="num"><span class="muted">{{ '%.2f' % (r.rl.agent_amount or 0) if r.rl.agent_amount is defined else '' }}</span></td>
 <td class="num"><span class="muted">{{ '%.2f' % (r.rl.fringe_amount or 0) if r.rl.fringe_amount is defined else '' }}</span></td>
</tr>
{% if r.rl._note is defined %}
<tr><td colspan="16" class="small" style="padding-left:24px">↳ {{ r.rl._note }}</td></tr>
{% endif %}
{% endfor %}
</tbody>
</table>
</body></html>
"""
    return render_template_string(HTML, budget=budget, rows=rows,
                                  n_calc=n_calc, n_snap=n_snap)


@app.errorhandler(404)
def page_not_found(e):
    return render_template("404.html"), 404


# ── Global 500 handler — traceback + error-ref ────────────────────────────────
# Catches any unhandled exception in a view, generates a short error-ref id,
# logs the full traceback under that ref, and returns a small HTML page
# showing the ref so the user can paste it back. Lets us find the exact
# traceback in Render logs by grepping `ERR-<ref>`. Without this, Flask's
# default 500 page reveals nothing and Render's log window is too narrow
# to scroll back through hours of socket.io noise.
#
# Static assets and socket.io polling errors are excluded — those generate
# enough log noise on their own and are handled by the LB / client retry.
# 2026-05-08.
@app.errorhandler(Exception)
def _unhandled_exception(e):
    # Let HTTP exceptions (404, 403, 401 etc.) pass through to their own
    # handlers / Flask's default rendering. Only trap actual 500s.
    from werkzeug.exceptions import HTTPException
    if isinstance(e, HTTPException):
        return e
    import uuid as _uuid
    import traceback as _tb
    ref = _uuid.uuid4().hex[:8].upper()
    _trace = _tb.format_exc()
    try:
        _path = request.path
        _method = request.method
        _user_id = getattr(getattr(request, '_login_user', None), 'id', None)
    except Exception:
        _path = '?'
        _method = '?'
        _user_id = None
    logging.error(
        f"[ERR-{ref}] {_method} {_path} user={_user_id}\n{_trace}"
    )
    # If the exception was a DB error the session is now in an aborted state,
    # and ANY further query (current_user reload, the error page itself) would
    # raise too — which is how a traceback can vanish from every surface at
    # once. Roll back first so the rest of this handler works. (2026-07-22,
    # Van Cliburn crash debugging.)
    try:
        db.session.rollback()
    except Exception:
        pass
    # Persist the traceback to a small on-disk ring so it's readable at
    # /admin/errors even when Sentry misses the event and Render's log window
    # has scrolled past. /tmp is per-instance and shared across gunicorn
    # workers, which is exactly the scope we need. (2026-07-22.)
    try:
        import glob as _glob
        import time as _time
        _edir = '/tmp/fpb-errors'
        os.makedirs(_edir, exist_ok=True)
        with open(os.path.join(_edir, f"{int(_time.time())}-ERR-{ref}.txt"), 'w') as _f:
            _f.write(f"{_method} {_path} user={_user_id}\n\n{_trace}")
        _old = sorted(_glob.glob(os.path.join(_edir, '*.txt')))[:-40]
        for _p in _old:
            os.unlink(_p)
    except Exception:
        pass
    # Explicit Sentry capture: with a custom errorhandler the exception counts
    # as "handled", so the SDK's automatic hook may not fire. No-op if the SDK
    # isn't initialized (no SENTRY_DSN). The ERR ref rides along as a tag so a
    # user-reported "ERR-XXXX" finds its Sentry event. (2026-07-20.)
    try:
        import sentry_sdk as _ssdk
        with _ssdk.push_scope() as _scope:
            _scope.set_tag("err_ref", ref)
            _ssdk.capture_exception(e)
    except Exception:
        pass
    # API clients need machine-readable errors: the mobile app can't parse
    # the HTML page, so users saw a bare "Request failed (500)" with no ref
    # to report (live debugging 2026-08-18). JSON + the ERR ref instead.
    try:
        if (request.path or '').startswith('/api/'):
            return jsonify({"error": f"Server error — reference ERR-{ref}",
                            "err_ref": ref}), 500
    except Exception:
        pass
    # Alerting: Sentry (captured below) is the alert channel — email on new
    # issues + optional mobile push. The old ntfy phone ping was removed
    # 2026-07-20 at the owner's request (delivery was unreliable).
    # Show the traceback inline to super-admins only — so production errors are
    # debuggable without server-log access. Everyone else gets the generic page.
    _admin_trace = ''
    try:
        from flask_login import current_user as _cu
        if getattr(_cu, 'is_authenticated', False) and getattr(_cu, 'role', None) == 'super_admin':
            import html as _html
            _admin_trace = ('<hr><p style="color:#888;font-size:.85em">super-admin debug:</p>'
                            '<pre style="white-space:pre-wrap;font-size:12px;background:#f8f8f8;'
                            'padding:12px;border-radius:6px;overflow:auto">'
                            + _html.escape(_trace) + '</pre>')
    except Exception:
        pass
    body = (
        '<!doctype html><html><head>'
        '<title>Internal error</title>'
        '<style>body{font-family:system-ui,sans-serif;max-width:560px;'
        'margin:80px auto;padding:0 20px;color:#222}'
        'code{background:#f3f4f6;padding:2px 8px;border-radius:4px;'
        'font-size:1.1em}</style>'
        '</head><body>'
        '<h1>Something broke.</h1>'
        '<p>We hit an unexpected error. Send this reference to support '
        'so we can find the exact traceback:</p>'
        f'<p><code>ERR-{ref}</code></p>'
        '<p><a href="/">Back to dashboard</a></p>'
        + _admin_trace +
        '</body></html>'
    )
    return body, 500


